"use client";

import {
  useEffect,
  useLayoutEffect,
  useRef,
  useState,
  type KeyboardEvent as ReactKeyboardEvent,
  type RefObject,
} from "react";
import { createPortal } from "react-dom";
import type { AraHit, AraLog, AraTurn } from "@/lib/voice/ara-history";
import { searchAraLog } from "@/lib/voice/ara-history";

const MENU_ID = "ara-history-actions";

function when(at: number): string {
  const date = new Date(at);
  const now = new Date();
  const sameDay = date.toDateString() === now.toDateString();
  return sameDay
    ? date.toLocaleTimeString([], { hour: "numeric", minute: "2-digit" })
    : date.toLocaleDateString([], { month: "short", day: "numeric" });
}

function Mark({ text, query }: { text: string; query: string }) {
  const terms = query.trim().toLowerCase().split(/\s+/).filter(Boolean);
  if (!terms.length) return <>{text}</>;
  const re = new RegExp(
    `(${terms.map((t) => t.replace(/[.*+?^${}()|[\]\\]/g, "\\$&")).join("|")})`,
    "ig",
  );
  const parts = text.split(re);
  return (
    <>
      {parts.map((part, i) =>
        terms.some((term) => part.toLowerCase() === term) ? (
          <mark key={i}>{part}</mark>
        ) : (
          <span key={i}>{part}</span>
        ),
      )}
    </>
  );
}

function speaker(role: AraTurn["role"]): string {
  return role === "you" ? "You" : "Ara";
}

function messageKey(threadId: string, turnId: string): string {
  return `message:${threadId}:${turnId}`;
}

function threadKey(threadId: string): string {
  return `thread:${threadId}`;
}

function findTurn(log: AraLog, threadId: string, turnId: string): AraTurn | null {
  return (
    log.threads
      .find((thread) => thread.id === threadId)
      ?.turns.find((turn) => turn.id === turnId) ?? null
  );
}

function selectionInside(node: HTMLElement): boolean {
  const selection = window.getSelection();
  if (!selection || selection.isCollapsed) return false;
  const anchor = selection.anchorNode;
  return !!anchor && node.contains(anchor);
}

type MessageMenu = {
  kind: "message";
  key: string;
  threadId: string;
  turnId: string;
  text: string;
  role: AraTurn["role"];
  fromSearch: boolean;
};

type ThreadMenu = {
  kind: "thread";
  key: string;
  threadId: string;
  title: string;
};

type OpenMenu = (MessageMenu | ThreadMenu) & { top: number; left: number };

type MenuAction = {
  id: string;
  label: string;
  danger?: boolean;
  run: () => void;
};

function guessHeight(target: { kind: OpenMenu["kind"]; fromSearch?: boolean }): number {
  const count = target.kind === "message" && target.fromSearch ? 4 : 3;
  return count * 36 + 16;
}

function placeMenu(
  anchor: HTMLElement,
  width: number,
  height: number,
): { top: number; left: number } {
  const box = anchor.getBoundingClientRect();
  const gap = 6;
  const margin = 8;
  let left = anchor.hasAttribute("data-ara-menu-trigger") ? box.right - width : box.left;
  left = Math.min(left, window.innerWidth - width - margin);
  left = Math.max(margin, left);
  let top = box.bottom + gap;
  if (top + height > window.innerHeight - margin) {
    const above = box.top - height - gap;
    top = above >= margin ? above : Math.max(margin, window.innerHeight - height - margin);
  }
  return { top, left };
}

function anchorInView(anchor: HTMLElement, bounds: HTMLElement | null): boolean {
  const box = anchor.getBoundingClientRect();
  if (box.bottom < 0 || box.top > window.innerHeight) return false;
  if (!bounds) return true;
  const frame = bounds.getBoundingClientRect();
  return box.bottom > frame.top + 2 && box.top < frame.bottom - 2;
}

function AraLogMenu({
  menu,
  actions,
  flash,
  failed,
  anchorRef,
  scrollerRef,
  onClose,
}: {
  menu: OpenMenu;
  actions: MenuAction[];
  flash: string | null;
  failed: boolean;
  anchorRef: RefObject<HTMLElement | null>;
  scrollerRef: RefObject<HTMLElement | null>;
  onClose: (restoreFocus: boolean) => void;
}) {
  const menuRef = useRef<HTMLDivElement>(null);
  const onCloseRef = useRef(onClose);
  onCloseRef.current = onClose;

  useLayoutEffect(() => {
    function place(fromScroll: boolean) {
      const anchor = anchorRef.current;
      const node = menuRef.current;
      if (!anchor || !node) return;
      if (fromScroll && !anchorInView(anchor, scrollerRef.current)) {
        onCloseRef.current(false);
        return;
      }
      const next = placeMenu(anchor, node.offsetWidth, node.offsetHeight);
      node.style.top = `${next.top}px`;
      node.style.left = `${next.left}px`;
    }
    place(false);
    function onScroll() {
      place(true);
    }
    function onResize() {
      place(false);
    }
    window.addEventListener("scroll", onScroll, true);
    window.addEventListener("resize", onResize);
    return () => {
      window.removeEventListener("scroll", onScroll, true);
      window.removeEventListener("resize", onResize);
    };
  }, [anchorRef, scrollerRef, menu.key]);

  useEffect(() => {
    menuRef.current?.querySelector<HTMLButtonElement>('[role="menuitem"]')?.focus();
  }, [menu.key]);

  useEffect(() => {
    function onPointerDown(event: PointerEvent) {
      const target = event.target;
      if (!(target instanceof Node)) return;
      if (menuRef.current?.contains(target)) return;
      if (target instanceof Element) {
        if (target.closest("[data-ara-menu-trigger]")) return;
        const owner = target.closest("[data-menu-key]");
        if (owner?.getAttribute("data-menu-key") === menu.key) return;
      }
      onCloseRef.current(false);
    }
    function onKey(event: globalThis.KeyboardEvent) {
      if (event.key !== "Escape") return;
      event.preventDefault();
      onCloseRef.current(true);
    }
    document.addEventListener("pointerdown", onPointerDown);
    document.addEventListener("keydown", onKey);
    return () => {
      document.removeEventListener("pointerdown", onPointerDown);
      document.removeEventListener("keydown", onKey);
    };
  }, [menu.key]);

  function onMenuKeyDown(event: ReactKeyboardEvent<HTMLDivElement>) {
    const list = Array.from(
      event.currentTarget.querySelectorAll<HTMLButtonElement>('[role="menuitem"]'),
    );
    const index = list.indexOf(document.activeElement as HTMLButtonElement);
    if (event.key === "ArrowDown") {
      event.preventDefault();
      list[(index < 0 ? 0 : index + 1) % list.length]?.focus();
    } else if (event.key === "ArrowUp") {
      event.preventDefault();
      list[index < 0 ? list.length - 1 : (index - 1 + list.length) % list.length]?.focus();
    } else if (event.key === "Home") {
      event.preventDefault();
      list[0]?.focus();
    } else if (event.key === "End") {
      event.preventDefault();
      list[list.length - 1]?.focus();
    } else if (event.key === "Escape") {
      event.preventDefault();
      event.stopPropagation();
      onClose(true);
    } else if (event.key === "Tab") {
      event.preventDefault();
      onClose(true);
    }
  }

  if (typeof document === "undefined") return null;

  return createPortal(
    <div
      ref={menuRef}
      id={MENU_ID}
      role="menu"
      aria-label={menu.kind === "thread" ? "Conversation actions" : "Message actions"}
      className="la-ara-log-menu"
      style={{ top: menu.top, left: menu.left }}
      onKeyDown={onMenuKeyDown}
    >
      {actions.map((action) => {
        const copied = flash === action.id;
        const label = copied ? (failed ? "Couldn't copy" : "Copied") : action.label;
        return (
          <button
            key={action.id}
            type="button"
            role="menuitem"
            className="la-btn la-ara-log-menu-item"
            data-danger={action.danger ? "1" : "0"}
            data-copied={copied && !failed ? "1" : "0"}
            onClick={() => action.run()}
          >
            {label}
          </button>
        );
      })}
    </div>,
    document.body,
  );
}

function MenuTrigger({
  label,
  open,
  onToggle,
}: {
  label: string;
  open: boolean;
  onToggle: (anchor: HTMLButtonElement, keepOpen: boolean) => void;
}) {
  return (
    <button
      type="button"
      className="la-btn la-btn-quiet la-ara-log-more"
      data-ara-menu-trigger="1"
      aria-haspopup="menu"
      aria-expanded={open}
      aria-controls={open ? MENU_ID : undefined}
      aria-label={label}
      onClick={(event) => {
        event.stopPropagation();
        onToggle(event.currentTarget, false);
      }}
      onKeyDown={(event) => {
        if (event.key !== "ArrowDown") return;
        event.preventDefault();
        onToggle(event.currentTarget, true);
      }}
    >
      <span aria-hidden="true">⋯</span>
    </button>
  );
}

export function AraHistoryRail({
  log,
  onSelect,
  onNew,
  onDeleteMessage,
  onDeleteThread,
  focusTurnId,
}: {
  log: AraLog;
  onSelect: (threadId: string, turnId?: string) => void;
  onNew: () => void;
  onDeleteMessage: (threadId: string, turnId: string) => void;
  onDeleteThread: (threadId: string) => void;
  focusTurnId: string | null;
}) {
  const [query, setQuery] = useState("");
  const [browsing, setBrowsing] = useState(true);
  const [menu, setMenu] = useState<OpenMenu | null>(null);
  const [flash, setFlash] = useState<string | null>(null);
  const [failed, setFailed] = useState(false);
  const [status, setStatus] = useState("");
  const scroller = useRef<HTMLDivElement>(null);
  const anchorRef = useRef<HTMLElement | null>(null);
  const triggerRef = useRef<HTMLElement | null>(null);
  const menuKeyRef = useRef<string | null>(null);
  const flashTimer = useRef<ReturnType<typeof setTimeout> | null>(null);
  menuKeyRef.current = menu?.key ?? null;
  const hits = searchAraLog(log, query);
  const active = log.threads.find((t) => t.id === log.activeId) || log.threads[0] || null;
  const turnCount = active?.turns.length || 0;
  const seenTurns = useRef(turnCount);

  useEffect(() => {
    if (turnCount > seenTurns.current) setBrowsing(false);
    seenTurns.current = turnCount;
  }, [turnCount, active?.id]);

  useEffect(() => {
    if (!focusTurnId || !scroller.current) return;
    const node = scroller.current.querySelector(`[data-turn="${focusTurnId}"]`);
    if (node instanceof HTMLElement) node.scrollIntoView({ block: "nearest" });
  }, [focusTurnId, active?.id, query]);

  useEffect(() => {
    if (!menu) return;
    const gone =
      menu.kind === "message"
        ? !findTurn(log, menu.threadId, menu.turnId)
        : !log.threads.some((thread) => thread.id === menu.threadId);
    if (gone) setMenu(null);
  }, [log, menu]);

  useEffect(
    () => () => {
      if (flashTimer.current) clearTimeout(flashTimer.current);
    },
    [],
  );

  function clearFlashTimer() {
    if (!flashTimer.current) return;
    clearTimeout(flashTimer.current);
    flashTimer.current = null;
  }

  function closeMenu(restoreFocus: boolean) {
    const back = triggerRef.current;
    clearFlashTimer();
    setFlash(null);
    setFailed(false);
    setMenu(null);
    if (restoreFocus) back?.focus();
  }

  function toggleMenu(
    next: MessageMenu | ThreadMenu,
    anchor: HTMLElement,
    trigger: HTMLElement,
    keepOpen = false,
  ) {
    if (menu?.key === next.key) {
      if (keepOpen) {
        document
          .getElementById(MENU_ID)
          ?.querySelector<HTMLButtonElement>('[role="menuitem"]')
          ?.focus();
        return;
      }
      closeMenu(false);
      return;
    }
    clearFlashTimer();
    setFlash(null);
    setFailed(false);
    setStatus("");
    anchorRef.current = anchor;
    triggerRef.current = trigger;
    setMenu({ ...next, ...placeMenu(anchor, 208, guessHeight(next)) });
  }

  function openHit(hit: AraHit) {
    onSelect(hit.threadId, hit.turnId);
    setQuery("");
    setBrowsing(false);
    closeMenu(false);
  }

  async function copyValue(text: string, actionId: string) {
    const key = menuKeyRef.current;
    if (!key) return;
    clearFlashTimer();
    let ok = false;
    try {
      await navigator.clipboard.writeText(text);
      ok = true;
    } catch {
      ok = false;
    }
    if (menuKeyRef.current !== key) return;
    setFlash(actionId);
    setFailed(!ok);
    setStatus(ok ? "Copied to clipboard" : "Couldn't copy");
    if (!ok) return;
    clearFlashTimer();
    flashTimer.current = setTimeout(() => {
      if (menuKeyRef.current !== key) return;
      closeMenu(false);
    }, 900);
  }

  function messageTarget(
    threadId: string,
    turnId: string,
    role: AraTurn["role"],
    text: string,
    fromSearch: boolean,
  ): MessageMenu {
    const turn = findTurn(log, threadId, turnId);
    return {
      kind: "message",
      key: messageKey(threadId, turnId),
      threadId,
      turnId,
      role: turn?.role ?? role,
      text: turn?.text ?? text,
      fromSearch,
    };
  }

  const actions: MenuAction[] = !menu
    ? []
    : menu.kind === "thread"
      ? [
          {
            id: "open",
            label: "Open",
            run: () => {
              onSelect(menu.threadId);
              setBrowsing(false);
              closeMenu(false);
            },
          },
          {
            id: "copy-title",
            label: "Copy title",
            run: () => void copyValue(menu.title, "copy-title"),
          },
          {
            id: "delete",
            label: "Delete conversation",
            danger: true,
            run: () => {
              onDeleteThread(menu.threadId);
              closeMenu(false);
            },
          },
        ]
      : [
          ...(menu.fromSearch
            ? [
                {
                  id: "open",
                  label: "Open",
                  run: () => {
                    onSelect(menu.threadId, menu.turnId);
                    setQuery("");
                    setBrowsing(false);
                    closeMenu(false);
                  },
                },
              ]
            : []),
          { id: "copy", label: "Copy", run: () => void copyValue(menu.text, "copy") },
          {
            id: "copy-as",
            label: `Copy as ${speaker(menu.role)}`,
            run: () => void copyValue(`${speaker(menu.role)}: ${menu.text}`, "copy-as"),
          },
          {
            id: "delete",
            label: "Delete",
            danger: true,
            run: () => {
              onDeleteMessage(menu.threadId, menu.turnId);
              closeMenu(false);
            },
          },
        ];

  return (
    <aside className="la-ara-log" data-ara-history="1" aria-label="Ara conversations">
      <p className="sr-only" aria-live="polite">
        {status}
      </p>
      <div className="la-ara-log-head">
        <div>
          <p className="la-kicker">Ara</p>
          <h2 className="font-display">Conversations</h2>
        </div>
        <button
          type="button"
          className="la-btn la-btn-ghost"
          onClick={() => {
            setBrowsing(false);
            setQuery("");
            closeMenu(false);
            onNew();
          }}
        >
          New
        </button>
      </div>
      <div className="la-ara-log-search">
        <input
          className="la-field"
          value={query}
          aria-label="Search messages"
          placeholder="Search messages"
          onChange={(e) => {
            setQuery(e.target.value);
            closeMenu(false);
          }}
        />
      </div>
      <div className="la-ara-log-scroll" ref={scroller}>
        {query.trim() ? (
          hits.length ? (
            hits.map((hit, index) => {
              const key = messageKey(hit.threadId, hit.turnId);
              return (
                <div
                  key={`${hit.threadId}:${hit.turnId}:${hit.at}:${index}:${hit.snippet}`}
                  className="la-ara-log-hit"
                  data-turn={hit.turnId}
                >
                  <button type="button" className="la-ara-log-open" onClick={() => openHit(hit)}>
                    <span className="la-ara-log-meta">
                      {speaker(hit.role)} · {when(hit.at)}
                    </span>
                    <span className="la-ara-log-title">{hit.title}</span>
                    <span className="la-ara-log-snippet">
                      <Mark text={hit.snippet} query={query} />
                    </span>
                  </button>
                  <MenuTrigger
                    label={`Actions for ${speaker(hit.role)} message`}
                    open={menu?.key === key}
                    onToggle={(anchor, keepOpen) =>
                      toggleMenu(
                        messageTarget(hit.threadId, hit.turnId, hit.role, hit.snippet, true),
                        anchor,
                        anchor,
                        keepOpen,
                      )
                    }
                  />
                </div>
              );
            })
          ) : (
            <p className="la-ara-log-empty">No messages match that.</p>
          )
        ) : browsing || !active ? (
          log.threads.length ? (
            log.threads.map((thread) => {
              const key = threadKey(thread.id);
              return (
                <div
                  key={thread.id}
                  className="la-ara-log-item"
                  data-on={thread.id === log.activeId ? "1" : "0"}
                >
                  <button
                    type="button"
                    className="la-ara-log-open"
                    onClick={() => {
                      onSelect(thread.id);
                      setBrowsing(false);
                      closeMenu(false);
                    }}
                  >
                    <span className="la-ara-log-title">{thread.title}</span>
                    <span className="la-ara-log-meta">
                      {when(thread.updatedAt)} · {thread.turns.length}
                    </span>
                  </button>
                  <MenuTrigger
                    label={`Actions for ${thread.title}`}
                    open={menu?.key === key}
                    onToggle={(anchor, keepOpen) =>
                      toggleMenu(
                        { kind: "thread", key, threadId: thread.id, title: thread.title },
                        anchor,
                        anchor,
                        keepOpen,
                      )
                    }
                  />
                </div>
              );
            })
          ) : (
            <p className="la-ara-log-empty">Nothing saved yet. Talk to Ara and it stays here.</p>
          )
        ) : (
          <>
            <button
              type="button"
              className="la-btn la-btn-quiet"
              onClick={() => {
                setBrowsing(true);
                closeMenu(false);
              }}
            >
              All conversations
            </button>
            <p className="la-ara-log-current">{active.title}</p>
            {active.turns.length ? (
              active.turns.map((turn) => {
                const key = messageKey(active.id, turn.id);
                return (
                  <article
                    key={turn.id}
                    className="la-ara-log-turn"
                    data-turn={turn.id}
                    data-on={focusTurnId === turn.id ? "1" : "0"}
                    data-menu-key={key}
                    data-menu={menu?.key === key ? "1" : "0"}
                    onClick={(event) => {
                      if (selectionInside(event.currentTarget)) return;
                      const trigger =
                        event.currentTarget.querySelector<HTMLButtonElement>(
                          "[data-ara-menu-trigger]",
                        );
                      if (!trigger || trigger.contains(event.target as Node)) return;
                      toggleMenu(
                        messageTarget(active.id, turn.id, turn.role, turn.text, false),
                        event.currentTarget,
                        trigger,
                      );
                    }}
                  >
                    <div className="la-ara-log-meta-row">
                      <p className="la-ara-log-meta">
                        {speaker(turn.role)} · {when(turn.at)}
                      </p>
                      <MenuTrigger
                        label={`Actions for ${speaker(turn.role)} message`}
                        open={menu?.key === key}
                        onToggle={(anchor, keepOpen) =>
                          toggleMenu(
                            messageTarget(active.id, turn.id, turn.role, turn.text, false),
                            anchor,
                            anchor,
                            keepOpen,
                          )
                        }
                      />
                    </div>
                    <p className={turn.role === "ara" ? "la-ara-log-ara" : "la-ara-log-you"}>
                      {turn.text}
                    </p>
                  </article>
                );
              })
            ) : (
              <p className="la-ara-log-empty">This conversation is empty.</p>
            )}
          </>
        )}
      </div>
      {menu ? (
        <AraLogMenu
          menu={menu}
          actions={actions}
          flash={flash}
          failed={failed}
          anchorRef={anchorRef}
          scrollerRef={scroller}
          onClose={closeMenu}
        />
      ) : null}
    </aside>
  );
}

import { useEffect, useState } from "react";
import { autopilotStatusFn, recordOutcomeFn, setAutopilotFn } from "@/lib/autonomy/actions";
import { dailySummary } from "@/lib/autonomy/daily";
import { knownRevenue, lifecycle, type OutcomeProspect } from "@/lib/autonomy/outcomes";

type Row = OutcomeProspect & {
  uid?: string;
  discovered_at?: string;
  vertical?: string;
  website?: string;
  history?: { at?: string; action?: string; detail?: string }[];
};

export function BookingLinkField() {
  return (
    <section className="la-card mb-4" data-booking-link="1">
      <p className="la-kicker">Booking</p>
      <p className="mt-1 text-sm text-muted">Each interested company gets its own private booking link. There is nothing to paste here.</p>
    </section>
  );
}

export function AutonomyHome({
  rows,
  testMode,
  onUpdated,
}: {
  rows: Row[];
  testMode: boolean;
  onUpdated?: (row: Row) => void;
}) {
  const [busy, setBusy] = useState("");
  const [value, setValue] = useState("");
  const [billing, setBilling] = useState<"" | "one-time" | "monthly">("");
  const [autopilot, setAutopilot] = useState(false);
  const [phrase, setPhrase] = useState("");
  const [pilotMsg, setPilotMsg] = useState("");
  useEffect(() => {
    void autopilotStatusFn().then((r) => { if (r.ok) setAutopilot(r.autopilot); }).catch(() => setAutopilot(false));
  }, []);
  const calendarDown = rows.some((r) => (r.history || []).some((h) => h.action === "calendar_unavailable"));
  const day = new Date().toISOString().slice(0, 10);
  const today = dailySummary(rows, day);
  const now = new Date();
  const upcoming = rows.filter((r) => lifecycle(r) === "BOOKED");
  const needOutcome = upcoming.filter((r) => !r.meeting_at || new Date(r.meeting_at).getTime() <= now.getTime());
  const needDecision = rows.filter((r) => lifecycle(r) === "FOLLOW_UP_NEEDED" || lifecycle(r) === "SHOWED");
  const showed = rows.filter((r) => lifecycle(r) === "SHOWED").length;
  const won = rows.filter((r) => lifecycle(r) === "WON").length;
  const lost = rows.filter((r) => lifecycle(r) === "LOST").length;
  const money = knownRevenue(rows);

  async function mark(row: Row, kind: "SHOWED" | "NO_SHOW" | "RESCHEDULE" | "WON" | "LOST" | "FOLLOW_UP_NEEDED", extra?: { lostReason?: string }) {
    if (!row.uid) return;
    setBusy(row.uid + kind);
    const result = await recordOutcomeFn({
      data: {
        uid: row.uid,
        kind,
        clientValue: value.trim() ? Number(value) : null,
        billing,
        lostReason: extra?.lostReason,
      },
    });
    setBusy("");
    if (result.ok) onUpdated?.(result.prospect as Row);
  }

  return (
    <section className="la-card mb-5" data-autonomy="1">
      <p className="la-kicker">Today</p>
      <p className="mt-1 text-sm">Acquisition Autopilot: {autopilot ? "ON" : "OFF"}</p>
      <p className="text-sm">Test Mode: {testMode ? "ON" : "OFF"}</p>
      <p className="mt-1 text-sm text-muted">{testMode ? "The allowlist still blocks real companies. Autopilot does not turn on when Test Mode changes." : "Live send rules apply. Autopilot stays off unless you enable it separately."}</p>
      <div className="mt-2 flex flex-wrap gap-2">
        <input className="la-field" value={phrase} placeholder={autopilot ? "DISABLE AUTOPILOT" : "ENABLE AUTOPILOT"} onChange={(e) => setPhrase(e.target.value)} />
        <button
          type="button"
          className="la-btn la-btn-quiet"
          onClick={() => {
            void setAutopilotFn({ data: { command: phrase } }).then((r) => {
              if (!r.ok) setPilotMsg(r.reason);
              else {
                setAutopilot(r.autopilot);
                setPhrase("");
                setPilotMsg(r.autopilot ? "Acquisition Autopilot is on." : "Acquisition Autopilot is off.");
              }
            }).catch(() => setPilotMsg("Could not change Autopilot."));
          }}
        >
          {autopilot ? "Turn Autopilot off" : "Enable Autopilot"}
        </button>
      </div>
      {pilotMsg ? <p className="mt-1 text-sm">{pilotMsg}</p> : null}
      {calendarDown ? <p className="mt-2 text-sm">Google Calendar is not connected. Interested replies will not include a booking link until it is.</p> : null}
      <div className="mt-3 grid grid-cols-2 gap-2 text-sm sm:grid-cols-4">
        <p><b>{today.found}</b> found</p>
        <p><b>{today.researched}</b> researched</p>
        <p><b>{today.qualified}</b> qualified</p>
        <p><b>{today.contacted}</b> contacted</p>
        <p><b>{today.replies}</b> replies</p>
        <p><b>{today.interested}</b> interested</p>
        <p><b>{upcoming.length}</b> booked</p>
        <p><b>{money.amount === null ? "UNKNOWN" : `$${money.amount.toLocaleString()}`}</b> revenue</p>
      </div>
      <div className="mt-3 text-sm">
        <p className="la-kicker">Upcoming calls</p>
        {upcoming.length ? upcoming.slice(0, 3).map((row) => (
          <p key={row.uid || row.name} className="mt-1">{row.name}{row.meeting_at ? ` — ${new Date(row.meeting_at).toLocaleString()}` : " — time not on file"}</p>
        )) : <p className="mt-1 text-muted">No calls booked.</p>}
      </div>
      <div className="mt-3 text-sm">
        <p className="la-kicker">Needs you</p>
        {!needOutcome.length && !needDecision.length && !today.needsYou.length ? <p className="mt-1 text-muted">Nothing needs you right now.</p> : null}
        {today.needsYou.slice(0, 3).map((item) => <p key={item} className="mt-1">{item}</p>)}
        {needOutcome.map((row) => (
          <div key={row.uid} className="mt-2">
            <p>{row.name} needs a call result.</p>
            <div className="mt-1 flex flex-wrap gap-2">
              <button type="button" className="la-btn la-btn-quiet" disabled={busy === (row.uid || "") + "SHOWED"} onClick={() => void mark(row, "SHOWED")}>Showed</button>
              <button type="button" className="la-btn la-btn-quiet" disabled={busy === (row.uid || "") + "NO_SHOW"} onClick={() => void mark(row, "NO_SHOW")}>No-show</button>
            </div>
          </div>
        ))}
        {rows.filter((r) => lifecycle(r) === "NO_SHOW").slice(0, 2).map((row) => (
          <div key={row.uid} className="mt-2">
            <p>{row.name} missed the call. No new cold email.</p>
            <button type="button" className="la-btn la-btn-quiet mt-1" onClick={() => void mark(row, "RESCHEDULE")}>Waiting for them to rebook</button>
          </div>
        ))}
        {needDecision.map((row) => (
          <div key={row.uid} className="mt-2">
            <p>{row.name} showed. What happened?</p>
            <div className="mt-1 flex flex-wrap gap-2">
              <input className="la-field w-28" inputMode="decimal" placeholder="Value" value={value} onChange={(e) => setValue(e.target.value)} />
              <button type="button" className="la-btn la-btn-quiet" onClick={() => setBilling("monthly")}>Monthly</button>
              <button type="button" className="la-btn la-btn-quiet" onClick={() => setBilling("one-time")}>One-time</button>
              <button type="button" className="la-btn la-btn-primary" onClick={() => void mark(row, "WON")}>Won</button>
              <button type="button" className="la-btn la-btn-quiet" onClick={() => void mark(row, "LOST", { lostReason: "No decision" })}>Lost</button>
              <button type="button" className="la-btn la-btn-quiet" onClick={() => void mark(row, "FOLLOW_UP_NEEDED")}>Follow up later</button>
            </div>
            <p className="mt-1 text-muted">{billing ? `Billing: ${billing}. ` : ""}Leave value blank and revenue stays UNKNOWN.</p>
          </div>
        ))}
      </div>
      <p className="mt-3 text-sm text-muted">Pipeline: {upcoming.length} booked, {showed} showed, {won} won, {lost} lost.</p>
    </section>
  );
}

"use client";

import { useEffect, useState } from "react";
import { ChevronLeft, ChevronRight } from "lucide-react";
import type { AgendaEvent } from "@/lib/mail/actions";
import { formatLong, formatShort, formatTime, rangeFor, ymdInTz, type CalView } from "@/lib/calendar/range";
import type { ConnectionHealth } from "@/lib/mail/integration-status";

export function CalendarDesk({
  calView,
  calAnchor,
  events,
  selectedId,
  health,
  reason,
  loading,
  onToday,
  onPrev,
  onNext,
  onView,
  onSelect,
  onOpenProspect,
  onPrep,
  onDelete,
  onSettings,
}: {
  calView: CalView;
  calAnchor: string;
  events: AgendaEvent[];
  selectedId: string | null;
  health: ConnectionHealth;
  reason: string;
  loading: boolean;
  onToday: () => void;
  onPrev: () => void;
  onNext: () => void;
  onView: (v: CalView) => void;
  onSelect: (id: string) => void;
  onOpenProspect: (uid: string) => void;
  onPrep: (uid: string) => void;
  onDelete: (event: AgendaEvent) => Promise<string>;
  onSettings: () => void;
}) {
  const range = rangeFor(calView, calAnchor);
  const selected = events.find((e) => e.id === selectedId) || null;
  const todayKey = ymdInTz();
  const now = Date.now();
  const todayCalls = events.filter((e) => e.kind === "sales_call" && ymdInTz(new Date(e.start)) === todayKey);
  const upcoming = events
    .filter((e) => e.kind === "sales_call" && new Date(e.start).getTime() >= now)
    .slice(0, 5);
  const connected = health === "connected";
  const unknown = health === "unknown";
  const [armedId, setArmedId] = useState<string | null>(null);
  const [deleting, setDeleting] = useState(false);
  const [deleteErr, setDeleteErr] = useState("");

  useEffect(() => {
    setArmedId(null);
    setDeleteErr("");
    setDeleting(false);
  }, [selectedId]);

  return (
    <section className="space-y-4" data-owner-calendar="1" data-cal-view={calView} data-cal-range={range.label} data-cal-health={health}>
      <div className="flex flex-wrap items-end justify-between gap-3">
        <div>
          <p className="la-kicker">Schedule</p>
          <h1 className="font-display mt-1 text-3xl">Calendar</h1>
          <p className="mt-1 text-sm text-muted">{range.label}</p>
        </div>
        <div className="flex flex-wrap items-center gap-2">
          <button className="la-btn la-btn-ghost" onClick={onToday}>Today</button>
          <button className="la-btn la-btn-ghost" onClick={onPrev} aria-label="Previous"><ChevronLeft size={18} /></button>
          <button className="la-btn la-btn-ghost" onClick={onNext} aria-label="Next"><ChevronRight size={18} /></button>
        </div>
      </div>
      <div className="la-tabs">
        {(["day", "week", "month"] as const).map((v) => (
          <button
            key={v}
            className="la-tab capitalize"
            data-on={calView === v ? "1" : "0"}
            onClick={() => onView(v)}
          >
            {v}
          </button>
        ))}
      </div>

      {unknown ? (
        <div className="la-card">
          <p>Checking Calendar…</p>
          <p className="mt-2 text-sm text-muted">I’m not treating Calendar as disconnected until the server status loads.</p>
        </div>
      ) : !connected ? (
        <div className="la-card la-card-accent">
          <p>Calendar isn’t connected yet.</p>
          <p className="mt-2 text-sm text-muted">I will not guess what’s on your calendar. Gmail can stay connected on its own.</p>
          <button className="la-btn la-btn-primary mt-4" onClick={onSettings}>
            Connect in Settings
          </button>
        </div>
      ) : reason ? (
        <div className="la-card">
          <div className="la-ribbon la-ribbon-bad">{reason}</div>
          <p className="mt-3 text-sm text-muted">This is not an empty calendar. Nothing was assumed.</p>
          <button className="la-btn la-btn-ghost mt-4" onClick={onSettings}>Open Settings</button>
        </div>
      ) : loading ? (
        <p className="text-sm text-muted">Reading your Google Calendar…</p>
      ) : (
        <>
          <div className="grid gap-3 sm:grid-cols-2">
            <div className="la-card">
              <p className="la-kicker">Today’s calls</p>
              {todayCalls.length ? todayCalls.map((e) => (
                <button key={e.id} className="mt-2 block w-full text-left" onClick={() => onSelect(e.id)}>
                  <span className="font-semibold">{formatTime(e.start)}</span>
                  <span className="mt-0.5 block text-sm">{e.companyName || e.title}</span>
                </button>
              )) : <p className="mt-2 text-sm text-muted">No sales calls today.</p>}
            </div>
            <div className="la-card">
              <p className="la-kicker">Upcoming sales calls</p>
              {upcoming.length ? upcoming.map((e) => (
                <button key={e.id} className="mt-2 block w-full text-left" onClick={() => onSelect(e.id)}>
                  <span className="font-semibold">{formatTime(e.start)}</span>
                  <span className="mt-0.5 block text-sm">{e.companyName || e.title}</span>
                </button>
              )) : <p className="mt-2 text-sm text-muted">None coming up in this range.</p>}
            </div>
          </div>
          {calView === "week" ? (
            <div className="grid grid-cols-1 gap-2 sm:grid-cols-7">
              {range.days.map((day) => {
                const dayEvents = events.filter((e) => ymdInTz(new Date(e.start)) === day);
                return (
                  <div key={day} className="la-cal-day">
                    <p className="text-xs text-muted">{formatLong(day).split(",")[0]} {formatShort(day)}</p>
                    {dayEvents.length ? dayEvents.map((e) => (
                      <button
                        key={e.id}
                        className="la-cal-event"
                        data-on={selectedId === e.id ? "1" : "0"}
                        onClick={() => onSelect(e.id)}
                      >
                        <span className="block font-semibold">{formatTime(e.start)}</span>
                        {e.companyName || e.title}
                      </button>
                    )) : <p className="mt-3 text-xs text-muted">—</p>}
                  </div>
                );
              })}
            </div>
          ) : (
            <div className="space-y-2">
              {events.length ? events.map((e) => (
                <button
                  key={e.id}
                  className={`la-card block w-full text-left ${selectedId === e.id ? "la-card-accent" : ""}`}
                  onClick={() => onSelect(e.id)}
                >
                  <p className="la-kicker">{formatTime(e.start)} · {e.kind === "sales_call" ? "Sales call" : "Calendar"}</p>
                  <p className="font-display mt-1 text-lg">{e.companyName || e.title}</p>
                  {e.companyName && e.title !== e.companyName ? <p className="text-sm text-muted">{e.title}</p> : null}
                </button>
              )) : (
                <p className="la-card la-empty">No events in this range.</p>
              )}
            </div>
          )}
        </>
      )}

      {selected ? (
        <div className="la-card la-card-accent" data-cal-selected={selected.id}>
          <p className="la-kicker">{selected.kind === "sales_call" ? "Sales Call" : "Calendar event"}</p>
          <h2 className="font-display mt-1 text-2xl">{selected.companyName || selected.title}</h2>
          <p className="mt-1">{formatTime(selected.start)}</p>
          {selected.companyName && selected.title !== selected.companyName ? <p className="text-sm text-muted">{selected.title}</p> : null}
          <p className="mt-2 text-sm text-muted">Status: {selected.status}</p>
          <div className="mt-4 flex flex-wrap gap-2">
            {selected.prospectUid ? (
              <>
                <button className="la-btn la-btn-primary" onClick={() => onOpenProspect(selected.prospectUid!)}>Open Prospect</button>
                <button className="la-btn la-btn-ghost" onClick={() => onPrep(selected.prospectUid!)}>Call Prep</button>
              </>
            ) : (
              <p className="text-sm text-muted">This isn’t linked to a Lamb Ascension prospect.</p>
            )}
            {armedId === selected.id ? (
              <>
                <button
                  className="la-btn la-btn-danger"
                  disabled={deleting}
                  onClick={() => {
                    setDeleting(true);
                    setDeleteErr("");
                    void onDelete(selected)
                      .then((message) => {
                        if (message) setDeleteErr(message);
                      })
                      .catch(() => setDeleteErr("I couldn't delete that event, so nothing changed."))
                      .finally(() => setDeleting(false));
                  }}
                >
                  {deleting ? "Deleting…" : "Delete event"}
                </button>
                <button className="la-btn la-btn-ghost" disabled={deleting} onClick={() => setArmedId(null)}>Keep</button>
              </>
            ) : (
              <button className="la-btn la-btn-danger" onClick={() => { setDeleteErr(""); setArmedId(selected.id); }}>Delete</button>
            )}
          </div>
          {deleteErr ? <p className="la-quiet-status is-bad mt-2">{deleteErr}</p> : null}
        </div>
      ) : null}
    </section>
  );
}

import { useState } from "react";
import { recordOutcomeFn, saveCallSupportFn, sendApprovedFollowupFn } from "@/lib/autonomy/actions";
import { lifecycle } from "@/lib/autonomy/outcomes";
import { callGuide, discoveryQuestions, type CallNotes } from "@/lib/autonomy/sales";
import { opportunities, type Prospect } from "@/lib/review-brief";

const FIELDS: { key: keyof CallNotes; label: string }[] = [
  { key: "problem", label: "Main problem" },
  { key: "leadSource", label: "Current lead source" },
  { key: "leadVolume", label: "Qualified lead volume" },
  { key: "customerValue", label: "Customer value" },
  { key: "tried", label: "What they have tried" },
  { key: "frustration", label: "Biggest frustration" },
  { key: "desired", label: "Desired outcome" },
  { key: "timeline", label: "Timeline" },
  { key: "budget", label: "Budget discussed" },
  { key: "decisionMaker", label: "Decision maker" },
  { key: "objections", label: "Objections" },
  { key: "nextStep", label: "Next step" },
  { key: "notes", label: "Additional notes" },
];

export function CallSupport({ rows, onUpdated }: { rows: Prospect[]; onUpdated?: (row: Prospect) => void }) {
  const [open, setOpen] = useState<string | null>(null);
  const [notes, setNotes] = useState<CallNotes>({});
  const [price, setPrice] = useState("");
  const [when, setWhen] = useState("");
  const [draft, setDraft] = useState("");
  const today = new Date().toISOString().slice(0, 10);
  const calls = rows.filter((r) => lifecycle(r) === "BOOKED" || lifecycle(r) === "SHOWED");
  const due = rows.filter((r) => lifecycle(r) === "FOLLOW_UP_NEEDED" && (!r.follow_up_at || r.follow_up_at.slice(0, 10) <= today));
  const proposals = rows.filter((r) => r.proposal_draft && lifecycle(r) !== "WON" && lifecycle(r) !== "LOST");
  const clients = rows.filter((r) => r.client_record?.company);
  const active = rows.find((r) => r.uid === open);

  async function save(kind: "notes" | "draft" | "proposal") {
    if (!active?.uid) return;
    const result = await saveCallSupportFn({
      data: {
        uid: active.uid,
        notes,
        makeDraft: kind === "draft",
        makeProposal: kind === "proposal",
        price: price.trim() ? Number(price) : null,
        billing: "monthly",
      },
    });
    if (!result.ok) {
      setMsg(result.reason);
      return;
    }
    setMsg(kind === "draft" ? "Follow-up draft is ready. It was not sent." : kind === "proposal" ? "Proposal draft is ready. It was not sent." : "Notes saved.");
    if (result.draft) setDraft(result.draft);
    onUpdated?.(result.prospect as Prospect);
  }

  return (
    <section className="la-card mb-5" data-call-support="1">
      <p className="la-kicker">Sales</p>
      <div className="mt-2 grid grid-cols-2 gap-2 text-sm">
        <p><b>{calls.length}</b> calls to prep</p>
        <p><b>{due.length}</b> need follow-up</p>
        <p><b>{proposals.length}</b> proposals to review</p>
        <p><b>{clients.length}</b> new clients</p>
      </div>
      {due.slice(0, 3).map((row) => (
        <div key={row.uid} className="mt-2 text-sm">
          <p>Follow up with {row.name}. {row.follow_up_at ? `Due ${row.follow_up_at.slice(0, 10)}.` : "Due when you can."} No cold email.</p>
          <div className="mt-1 flex flex-wrap gap-2">
            <button type="button" className="la-btn la-btn-quiet" onClick={() => { setOpen(row.uid || null); setNotes(row.call_notes || {}); setDraft(row.followup_draft || ""); }}>Open</button>
            <button type="button" className="la-btn la-btn-quiet" onClick={() => { setOpen(row.uid || null); setNotes(row.call_notes || {}); setDraft(row.followup_draft || ""); }}>Draft follow-up</button>
            {row.phone && row.phone !== "UNKNOWN" ? <a className="la-btn la-btn-quiet" href={`tel:${row.phone}`}>Call</a> : <span className="text-muted">No phone on file.</span>}
          </div>
        </div>
      ))}
      {calls.slice(0, 3).map((row) => (
        <button key={row.uid} type="button" className="la-btn la-btn-quiet mt-2" onClick={() => { setOpen(row.uid || null); setNotes(row.call_notes || {}); setDraft(row.followup_draft || ""); setMsg(""); }}>
          {row.name} brief
        </button>
      ))}
      {active ? (
        <div className="mt-3 text-sm">
          <p className="font-display text-xl">{active.name}</p>
          <p className="mt-2">{active.vertical || "Category unknown"}{active.city ? ` in ${active.city}` : ""}. {active.website && active.website !== "UNKNOWN" ? active.website : "Website unknown."}</p>
          <p className="mt-2">Questions</p>
          <ul className="mt-1 list-disc pl-4">
            {discoveryQuestions({
              company: active.name || "",
              gaps: opportunities(active).map((o) => o.code),
              vertical: active.vertical,
            }).map((q) => <li key={q}>{q}</li>)}
          </ul>
          <p className="mt-2">Call shape</p>
          {callGuide({ company: active.name || "", gaps: opportunities(active).map((o) => o.code) }).slice(0, 4).map((line) => <p key={line} className="mt-1">{line}</p>)}
          <div className="mt-3 grid gap-2">
            {FIELDS.slice(0, 6).map((field) => (
              <label key={field.key} className="text-sm">{field.label}
                <input className="la-field mt-1" value={notes[field.key] || ""} onChange={(e) => setNotes({ ...notes, [field.key]: e.target.value })} />
              </label>
            ))}
          </div>
          <div className="mt-3 flex flex-wrap gap-2">
            <button type="button" className="la-btn la-btn-primary" onClick={() => void save("notes")}>Save notes</button>
            <button type="button" className="la-btn la-btn-quiet" onClick={() => void save("draft")}>Draft follow-up</button>
            <input className="la-field w-28" placeholder="Your price" value={price} onChange={(e) => setPrice(e.target.value)} />
            <button type="button" className="la-btn la-btn-quiet" onClick={() => void save("proposal")}>Create proposal</button>
          </div>
          <div className="mt-3 flex flex-wrap gap-2">
            <input className="la-field" type="date" value={when} onChange={(e) => setWhen(e.target.value)} />
            <button type="button" className="la-btn la-btn-quiet" onClick={() => {
              if (!active.uid) return;
              void recordOutcomeFn({ data: { uid: active.uid, kind: "FOLLOW_UP_NEEDED", followUpAt: when, followUpReason: notes.nextStep || notes.problem || "" } }).then((r) => {
                if (r.ok) onUpdated?.(r.prospect as Prospect);
                else setMsg(r.reason);
              });
            }}>Follow up later</button>
          </div>
          {active.followup_draft || draft ? (
            <label className="mt-3 block text-sm">Follow-up. Edit it, then send it yourself.
              <textarea className="la-field mt-1 min-h-28" value={draft || active.followup_draft || ""} onChange={(e) => setDraft(e.target.value)} />
            </label>
          ) : null}
          <button type="button" className="la-btn la-btn-primary mt-2" onClick={() => {
            if (!active.uid) return;
            void sendApprovedFollowupFn({ data: { uid: active.uid, body: draft || active.followup_draft || "" } }).then((r) => {
              setMsg(r.ok ? `Sent to ${r.prospect.followup_sent_to || "them"}.` : r.reason);
              if (r.ok) onUpdated?.(r.prospect as Prospect);
            });
          }}>Approve & send</button>
          {active.proposal_draft ? <pre className="mt-3 whitespace-pre-wrap text-sm">{active.proposal_draft}</pre> : null}
          {active.handoff_summary ? <pre className="mt-3 whitespace-pre-wrap text-sm">{active.handoff_summary}</pre> : null}
          {active.onboarding?.length ? <p className="mt-2">Onboarding: {active.onboarding.map((item) => item.label).join(", ")}</p> : null}
          {msg ? <p className="mt-2">{msg}</p> : null}
          <p className="mt-2 text-muted">Nothing here is sent. You still decide the price and whether it goes out.</p>
        </div>
      ) : null}
    </section>
  );
}

"use client";

import { useEffect, useState } from "react";
import type { DesignDirectorStatus } from "@/lib/design/types";

export function DesignDirectorBar({
  status,
  paused,
  spoken,
  preview,
  busy,
  onSend,
  onPause,
  onUndo,
  onKeep,
  onDiscard,
  onTryAnother,
  onOpenSettings,
}: {
  status: DesignDirectorStatus;
  paused: boolean;
  spoken: string;
  preview: boolean;
  busy: boolean;
  onSend: (prompt: string) => void;
  onPause: (paused: boolean) => void;
  onUndo: () => void;
  onKeep: () => void;
  onDiscard: () => void;
  onTryAnother: () => void;
  onOpenSettings: () => void;
}) {
  const [text, setText] = useState("");
  const [open, setOpen] = useState(false);

  useEffect(() => {
    if (preview || status === "designing" || status === "waiting") setOpen(true);
  }, [preview, status]);

  const label =
    status === "disconnected" ? "Disconnected"
      : paused || status === "paused" ? "Paused"
        : status === "designing" ? "Designing"
          : status === "waiting" ? "Waiting"
            : "Connected";

  function submit() {
    const t = text.trim();
    if (!t || busy) return;
    onSend(t);
    setText("");
  }

  return (
    <div className="la-dd" data-dd-status={status} data-dd-preview={preview ? "1" : "0"}>
      <div className="la-dd-row">
        <p className="la-dd-status">
          <span className={`la-dot la-dot-inline ${status === "connected" || status === "designing" ? "la-dot-good" : status === "paused" || paused ? "la-dot-warn" : "la-dot-bad"}`} />
          ChatGPT Design Director · {label}
        </p>
        <div className="la-dd-actions">
          {status === "disconnected" ? (
            <button type="button" className="la-btn la-btn-quiet" onClick={onOpenSettings}>Connect</button>
          ) : (
            <>
              <button type="button" className="la-btn la-btn-quiet" onClick={() => onPause(!(paused || status === "paused"))}>
                {paused || status === "paused" ? "Resume" : "Pause"}
              </button>
              <button type="button" className="la-btn la-btn-quiet" onClick={onUndo}>Undo</button>
              <button type="button" className="la-btn la-btn-quiet" onClick={() => setOpen((v) => !v)}>
                {open ? "Hide" : "Ask"}
              </button>
            </>
          )}
        </div>
      </div>
      {preview ? (
        <div className="la-dd-preview">
          <p className="la-dd-note">{spoken || "Preview on screen. Keep it, undo, or try another."}</p>
          <div className="la-dd-actions">
            <button type="button" className="la-btn la-btn-primary" onClick={onKeep}>Keep design</button>
            <button type="button" className="la-btn la-btn-ghost" onClick={onDiscard}>Undo</button>
            <button type="button" className="la-btn la-btn-ghost" onClick={onTryAnother}>Try another</button>
          </div>
        </div>
      ) : null}
      {open && status !== "disconnected" ? (
        <form
          className="la-dd-form"
          onSubmit={(e) => {
            e.preventDefault();
            submit();
          }}
        >
          <input
            className="la-field"
            value={text}
            placeholder={busy ? "Designing…" : "Make Home more luxurious…"}
            disabled={busy}
            onChange={(e) => setText(e.target.value)}
            aria-label="Design Director request"
          />
          <button className="la-btn la-btn-primary" type="submit" disabled={busy || !text.trim()}>
            {busy ? "…" : "Send"}
          </button>
        </form>
      ) : null}
      {spoken && !preview ? <p className="la-dd-note">{spoken}</p> : null}
    </div>
  );
}

/**
 * Owner Desk — Email Campaigns card.
 * Create → members → Arm (authorize) → Pause / results.
 * Test Mode ribbon when campaign.testModeOnly.
 */
import { useCallback, useEffect, useState } from "react";
import {
  armEmailCampaignFn,
  cancelEmailCampaignFn,
  createEmailCampaignFn,
  enableLiveEmailCampaignFn,
  getEmailCampaignFn,
  listEmailCampaignsFn,
  pauseEmailCampaignFn,
  resumeEmailCampaignFn,
} from "@/lib/campaigns/actions";
import type { CampaignMember, CampaignReport, EmailCampaign } from "@/lib/campaigns/types";

type Props = {
  onBack: () => void;
  globalTestMode: boolean;
};

export function EmailCampaignsPanel({ onBack, globalTestMode }: Props) {
  const [campaigns, setCampaigns] = useState<EmailCampaign[]>([]);
  const [selectedId, setSelectedId] = useState<string | null>(null);
  const [members, setMembers] = useState<CampaignMember[]>([]);
  const [report, setReport] = useState<CampaignReport | null>(null);
  const [busy, setBusy] = useState(false);
  const [msg, setMsg] = useState("");
  const [name, setName] = useState("");
  const [verticals, setVerticals] = useState("");
  const [locations, setLocations] = useState("");
  const [liveConfirm, setLiveConfirm] = useState("");

  const refreshList = useCallback(async () => {
    const r = await listEmailCampaignsFn();
    if (r.ok) setCampaigns(r.campaigns);
  }, []);

  const openCampaign = useCallback(async (id: string) => {
    setSelectedId(id);
    setBusy(true);
    setMsg("");
    try {
      const r = await getEmailCampaignFn({ data: { id } });
      if (!r.ok) {
        setMsg(r.reason);
        return;
      }
      setMembers(r.members);
      setReport(r.report);
    } finally {
      setBusy(false);
    }
  }, []);

  useEffect(() => {
    void refreshList();
  }, [refreshList]);

  const selected = campaigns.find((c) => c.id === selectedId) || null;
  const showTestRibbon = Boolean(
    globalTestMode || selected?.testModeOnly || (selected && !selected.liveEnabled),
  );

  async function onCreate() {
    setBusy(true);
    setMsg("");
    try {
      const r = await createEmailCampaignFn({
        data: {
          name: name.trim() || "Untitled campaign",
          verticals: verticals.split(/[,;]/).map((s) => s.trim()).filter(Boolean),
          locations: locations.split(/[,;]/).map((s) => s.trim()).filter(Boolean),
        },
      });
      if (!r.ok) return;
      setName("");
      await refreshList();
      await openCampaign(r.campaign.id);
      const m = r.membership;
      if (m && m.ok) {
        setMsg(`Draft created. Eligible ${m.eligible}, skipped ${m.skipped}. Nothing sent.`);
      }
    } finally {
      setBusy(false);
    }
  }

  async function onArm() {
    if (!selectedId) return;
    setBusy(true);
    setMsg("");
    try {
      const r = await armEmailCampaignFn({ data: { id: selectedId } });
      if (!r.ok) {
        setMsg(r.reason);
        return;
      }
      setMsg(
        `Armed: ${r.authorized} authorized, ${r.skipped} skipped. ` +
          `Worker sends under caps` +
          (r.testModeOnly || !r.liveEnabled ? " + Test Mode allowlist" : "") +
          ". Arm does not send by itself.",
      );
      await refreshList();
      await openCampaign(selectedId);
    } finally {
      setBusy(false);
    }
  }

  async function onPause() {
    if (!selectedId) return;
    setBusy(true);
    try {
      const r = await pauseEmailCampaignFn({ data: { id: selectedId } });
      setMsg(r.ok ? "Paused. New first contacts stop; reply sync continues." : r.reason);
      await refreshList();
      await openCampaign(selectedId);
    } finally {
      setBusy(false);
    }
  }

  async function onResume() {
    if (!selectedId) return;
    setBusy(true);
    try {
      const r = await resumeEmailCampaignFn({ data: { id: selectedId } });
      setMsg(r.ok ? `Resumed (${r.status}).` : r.reason);
      await refreshList();
      await openCampaign(selectedId);
    } finally {
      setBusy(false);
    }
  }

  async function onCancel() {
    if (!selectedId) return;
    setBusy(true);
    try {
      const r = await cancelEmailCampaignFn({ data: { id: selectedId } });
      setMsg(r.ok ? "Cancelled." : r.reason);
      await refreshList();
      setSelectedId(null);
      setMembers([]);
      setReport(null);
    } finally {
      setBusy(false);
    }
  }

  async function onEnableLive() {
    if (!selectedId) return;
    setBusy(true);
    try {
      const r = await enableLiveEmailCampaignFn({ data: { id: selectedId, confirm: liveConfirm } });
      setMsg(r.ok ? "Live enabled for this campaign. Global Test Mode may still apply." : r.reason);
      setLiveConfirm("");
      await refreshList();
      await openCampaign(selectedId);
    } finally {
      setBusy(false);
    }
  }

  return (
    <section className="la-card la-campaigns" data-testid="email-campaigns-panel">
      <header className="la-row" style={{ justifyContent: "space-between", gap: 12, flexWrap: "wrap" }}>
        <div>
          <h2 style={{ margin: 0 }}>Campaigns</h2>
          <p className="la-muted" style={{ margin: "4px 0 0" }}>
            Create → select eligible (email-only) → Arm once → worker sends under caps. Not per-lead Confirm forever.
          </p>
        </div>
        <button className="la-btn la-btn-ghost" type="button" onClick={onBack}>Back</button>
      </header>

      {showTestRibbon ? (
        <div className="la-chip" data-testid="campaign-test-mode-ribbon" style={{ marginTop: 12 }}>
          TEST MODE — allowlist required until you enable live for this campaign
        </div>
      ) : null}

      {msg ? <p className="la-muted" style={{ marginTop: 12 }}>{msg}</p> : null}

      <div className="la-card" style={{ marginTop: 16, padding: 12 }}>
        <h3 style={{ marginTop: 0 }}>New campaign</h3>
        <label className="la-field">
          Name
          <input value={name} onChange={(e) => setName(e.target.value)} placeholder="Dallas dental — week 1" />
        </label>
        <label className="la-field">
          Verticals (comma-separated)
          <input value={verticals} onChange={(e) => setVerticals(e.target.value)} placeholder="dental, med spa" />
        </label>
        <label className="la-field">
          Locations (comma-separated)
          <input value={locations} onChange={(e) => setLocations(e.target.value)} placeholder="Dallas, Fort Worth" />
        </label>
        <button className="la-btn" type="button" disabled={busy} onClick={() => void onCreate()}>
          Create (Test Mode)
        </button>
      </div>

      <div style={{ marginTop: 16 }}>
        <h3>Your campaigns</h3>
        {!campaigns.length ? <p className="la-muted">No campaigns yet.</p> : null}
        <ul style={{ listStyle: "none", padding: 0, margin: 0 }}>
          {campaigns.map((c) => (
            <li key={c.id} style={{ marginBottom: 8 }}>
              <button
                className="la-btn la-btn-quiet"
                type="button"
                data-on={selectedId === c.id ? "1" : "0"}
                onClick={() => void openCampaign(c.id)}
              >
                {c.name} · {c.status}
                {c.testModeOnly || !c.liveEnabled ? " · TEST" : " · LIVE"}
              </button>
            </li>
          ))}
        </ul>
      </div>

      {selected && report ? (
        <div className="la-card" style={{ marginTop: 16, padding: 12 }} data-testid="campaign-results-strip">
          <h3 style={{ marginTop: 0 }}>{selected.name}</h3>
          <p className="la-muted">
            Status <strong>{report.status}</strong>
            {" · "}
            eligible/authorized {report.counts.eligible + report.counts.authorized}
            {" · "}
            sent {report.counts.sent}
            {" · "}
            skipped {report.counts.skipped}
            {" · "}
            replied {report.counts.replied}
            {" · "}
            failed {report.counts.failed}
          </p>
          <div className="la-row" style={{ gap: 8, flexWrap: "wrap" }}>
            <button className="la-btn" type="button" disabled={busy || selected.status === "cancelled"} onClick={() => void onArm()}>
              Arm (authorize)
            </button>
            <button className="la-btn la-btn-quiet" type="button" disabled={busy} onClick={() => void onPause()}>
              Pause
            </button>
            <button className="la-btn la-btn-quiet" type="button" disabled={busy} onClick={() => void onResume()}>
              Resume
            </button>
            <button className="la-btn la-btn-ghost" type="button" disabled={busy} onClick={() => void onCancel()}>
              Cancel
            </button>
          </div>
          {!selected.liveEnabled ? (
            <div style={{ marginTop: 12 }}>
              <label className="la-field">
                Enable live (type ENABLE LIVE)
                <input value={liveConfirm} onChange={(e) => setLiveConfirm(e.target.value)} placeholder="ENABLE LIVE" />
              </label>
              <button className="la-btn la-btn-quiet" type="button" disabled={busy} onClick={() => void onEnableLive()}>
                Enable live for this campaign
              </button>
            </div>
          ) : null}
          <h4>Members</h4>
          <div style={{ maxHeight: 280, overflow: "auto" }}>
            <table className="la-table" style={{ width: "100%", fontSize: 13 }}>
              <thead>
                <tr>
                  <th>Prospect</th>
                  <th>Status</th>
                  <th>Recipient</th>
                  <th>Skip / error</th>
                </tr>
              </thead>
              <tbody>
                {members.slice(0, 200).map((m) => (
                  <tr key={m.prospectUid}>
                    <td>{m.prospectUid}</td>
                    <td>{m.status}</td>
                    <td>{m.recipient || "—"}</td>
                    <td>{m.skipReason || m.lastError || "—"}</td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </div>
      ) : null}
    </section>
  );
}

