"use client";

const VERTICALS = [
  "Roofing",
  "HVAC",
  "Plumbing / sewer",
  "Foundation repair",
  "Solar",
  "Med spa / cosmetic",
  "Dental",
  "Law / personal injury",
  "B2B consulting",
  "SaaS / software",
  "Other",
] as const;

/** Native <select> for Find Clients — datalist fails on mobile Chrome. */
export function FindVerticalField({
  value,
  onChange,
}: {
  value: string;
  onChange: (next: string) => void;
}) {
  const known = (VERTICALS as readonly string[]).includes(value);
  const selectValue = known ? value : value ? "Other" : "Roofing";
  return (
    <>
      <label className="la-label">What kind of company?</label>
      <select
        className="la-field mb-3"
        value={selectValue}
        onChange={(e) => onChange(e.target.value === "Other" ? "" : e.target.value)}
      >
        {VERTICALS.map((x) => (
          <option key={x} value={x}>
            {x}
          </option>
        ))}
      </select>
      {selectValue === "Other" ? (
        <input
          className="la-field mb-3"
          value={value}
          onChange={(e) => onChange(e.target.value)}
          placeholder="Type the kind of company…"
          aria-label="Custom company type"
        />
      ) : null}
    </>
  );
}

"use client";

import { originLabel, type GalleryItem, type GalleryState } from "@/lib/visual/gallery";
import { safetyLabel } from "@/lib/visual/safety";

function labelForStatus(item: GalleryItem): string {
  if (item.safetyStatus) return safetyLabel(item.safetyStatus);
  if (item.nsfw) return "Owner-private";
  if (item.kind === "ad") return "Brand-safe";
  return safetyLabel("brand_safe");
}

export function ImageDock({
  gallery,
  compact,
  onToggle,
  onSelect,
  onUseHome,
  onDelete,
}: {
  gallery: GalleryState;
  compact?: boolean;
  onToggle: () => void;
  onSelect: (id: string) => void;
  onUseHome: (id: string) => void;
  onDelete: (id: string) => void;
}) {
  const generated = gallery.items.filter((i) => i.source === "generated");
  const current = generated.find((i) => i.id === gallery.currentId) || generated[0];
  const status = gallery.status === "creating"
    ? "Creating image…"
    : gallery.status === "failed"
      ? (gallery.error || "Generation failed")
      : gallery.status === "ready"
        ? "Image ready"
        : "";
  const open = Boolean(gallery.libraryOpen);

  return (
    <div className={`la-images ${compact ? "is-compact" : ""}`} data-image-dock="1" data-open={open ? "1" : "0"}>
      <div className="la-images-bar">
        <button type="button" className="la-btn la-btn-quiet" onClick={onToggle}>
          Images{generated.length ? ` · ${generated.length}` : ""}
        </button>
        {status ? (
          <span className={`la-images-status ${gallery.status === "failed" ? "is-bad" : gallery.status === "creating" ? "is-live" : ""}`} data-image-status={gallery.status || "idle"}>
            {status}
          </span>
        ) : null}
      </div>
      {open ? (
        <div className="la-images-panel" data-image-library="1">
          {!generated.length ? (
            <p className="text-sm text-muted">No AI-generated images yet. Presets live in Settings. Ask Ara to generate something new.</p>
          ) : (
            <ul className="la-images-list">
              {generated.map((item) => (
                <li key={item.id} className={item.id === current?.id ? "is-current" : ""}>
                  <button type="button" className="la-images-thumb" onClick={() => onSelect(item.id)}>
                    <img src={item.url} alt="" />
                  </button>
                  <div className="min-w-0">
                    <p className="la-images-name">{item.label}</p>
                    <p className="text-xs text-muted">{originLabel(item)} · {labelForStatus(item)}</p>
                  </div>
                  <div className="la-images-actions">
                    <button type="button" className="la-btn la-btn-quiet" onClick={() => onUseHome(item.id)}>Use as Home</button>
                    <button type="button" className="la-btn la-btn-quiet" onClick={() => onDelete(item.id)}>Delete</button>
                  </div>
                </li>
              ))}
            </ul>
          )}
        </div>
      ) : current && !compact ? (
        <div className="la-images-latest" data-latest-generated="1">
          <img src={current.url} alt="" />
          <p className="text-xs text-muted">{originLabel(current)} · {current.label}</p>
        </div>
      ) : null}
    </div>
  );
}

"use client";

import "@/styles-linkedin-agent.css";

import { useCallback, useEffect, useRef, useState, type FormEvent } from "react";
import {
  createLinkedInAgentOrderFn,
  fillHighTicketLeadsFn,
  listLinkedInAgentMessagesFn,
  listLinkedInAgentOrdersFn,
  postLinkedInAgentMessageFn,
} from "@/lib/linkedin-agent/actions";
import type { LinkedInAgentMessage, LinkedInAgentOrder } from "@/lib/linkedin-agent/types";

/**
 * In-app LinkedIn agent chat dock (not an iframe of Grok Bot).
 * Stores messages + queues orders for the external LinkedIn agent to poll.
 */
export function LinkedInAgentChat() {
  const [expanded, setExpanded] = useState(false);
  const [busy, setBusy] = useState(false);
  const [draft, setDraft] = useState("");
  const [err, setErr] = useState("");
  const [messages, setMessages] = useState<LinkedInAgentMessage[]>([]);
  const [pending, setPending] = useState<LinkedInAgentOrder[]>([]);
  const bottomRef = useRef<HTMLDivElement | null>(null);

  const refresh = useCallback(async () => {
    try {
      const [msgs, ords] = await Promise.all([
        listLinkedInAgentMessagesFn(),
        listLinkedInAgentOrdersFn(),
      ]);
      if (msgs.ok) setMessages(msgs.messages);
      if (ords.ok) setPending(ords.pending);
      setErr("");
    } catch {
      setErr("Could not load LinkedIn agent chat.");
    }
  }, []);

  useEffect(() => {
    void refresh();
  }, [refresh]);

  useEffect(() => {
    if (expanded) bottomRef.current?.scrollIntoView({ behavior: "smooth", block: "end" });
  }, [messages, expanded]);

  async function send(e?: FormEvent) {
    e?.preventDefault();
    const body = draft.trim();
    if (!body || busy) return;
    setBusy(true);
    setDraft("");
    try {
      const posted = await postLinkedInAgentMessageFn({ data: { body, role: "user" } });
      if (!posted.ok) {
        setErr(posted.reason);
        setDraft(body);
        return;
      }
      await createLinkedInAgentOrderFn({
        data: {
          kind: "chat_reply",
          payload: { message_id: posted.message.id, body },
          note: body.slice(0, 500),
        },
      });
      await refresh();
    } catch {
      setErr("Message failed to send.");
      setDraft(body);
    } finally {
      setBusy(false);
    }
  }

  async function queueFill() {
    if (busy) return;
    setBusy(true);
    try {
      await createLinkedInAgentOrderFn({
        data: {
          kind: "fill_leads",
          payload: { source: "chat_ui" },
          note: "Fill high-ticket TX leads via Places",
        },
      });
      const fill = await fillHighTicketLeadsFn({ data: { maxSearches: 3, perSearchLimit: 5 } });
      await postLinkedInAgentMessageFn({
        data: {
          role: "system",
          body: fill.ok
            ? fill.reason
            : ("reason" in fill ? fill.reason : "High-ticket fill failed."),
        },
      });
      await refresh();
    } catch {
      setErr("Could not queue high-ticket fill.");
    } finally {
      setBusy(false);
    }
  }

  async function queueEnrichNeedsContact() {
    if (busy) return;
    setBusy(true);
    try {
      await createLinkedInAgentOrderFn({
        data: {
          kind: "enrich",
          payload: {
            focus: "NEEDS_CONTACT_INFORMATION",
            contactability: "email_only",
            soft_cap: true,
            do_not_invent_email: true,
            gmail_auto_send: false,
          },
          note: "Find a usable email for Needs Contact Information. Do not invent emails.",
        },
      });
      await postLinkedInAgentMessageFn({
        data: {
          role: "system",
          body: "Queued email search for Needs Contact Information. The Grok Bot must not invent emails or send mail.",
        },
      });
      await refresh();
    } catch {
      setErr("Could not queue enrich order.");
    } finally {
      setBusy(false);
    }
  }

  async function queueOutreachDraft() {
    if (busy) return;
    setBusy(true);
    try {
      await createLinkedInAgentOrderFn({
        data: {
          kind: "outreach",
          payload: {
            safety_note: "draft/request LinkedIn connects under soft caps",
            auto_send: false,
            gmail_auto_send: false,
          },
          note: "Draft LinkedIn connects under soft caps (no auto-send)",
        },
      });
      await refresh();
    } catch {
      setErr("Could not queue outreach order.");
    } finally {
      setBusy(false);
    }
  }

  return (
    <div className={`la-li-chat ${expanded ? "is-expanded" : "is-compact"}`} data-linkedin-agent="1">
      <button
        type="button"
        className="la-li-chat-toggle"
        aria-expanded={expanded}
        onClick={() => setExpanded((v) => !v)}
      >
        <span className={`la-li-orb ${busy ? "is-busy" : "is-ready"}`} aria-hidden="true" />
        <span className="la-li-chat-title">
          <b>LinkedIn Agent</b>
          <span className="la-li-chat-sub">
            {pending.length ? `${pending.length} pending order${pending.length === 1 ? "" : "s"}` : "Orders + chat"}
          </span>
        </span>
        <span className="la-li-chat-chev">{expanded ? "Collapse" : "Open"}</span>
      </button>

      {expanded ? (
        <div className="la-li-chat-panel">
          <p className="la-li-chat-hint">
            In-app thread for the LinkedIn Grok Bot. Orders stay queued until the bot claims them.
            Lamb Ascension does not scrape LinkedIn and does not send those emails.
          </p>

          <div className="la-li-thread" role="log" aria-live="polite">
            {messages.length === 0 ? (
              <p className="la-empty">No messages yet. Ask for leads, enrich, or LinkedIn drafts.</p>
            ) : (
              messages.map((m) => (
                <div key={m.id} className={`la-li-msg la-li-msg-${m.role}`}>
                  <span className="la-li-msg-role">{m.role}</span>
                  <p className="la-li-msg-body">{m.body}</p>
                </div>
              ))
            )}
            <div ref={bottomRef} />
          </div>

          {pending.length ? (
            <div className="la-li-orders">
              <p className="la-li-orders-label">Pending orders</p>
              <ul>
                {pending.slice(0, 6).map((o) => (
                  <li key={o.id}>
                    <b>{o.kind}</b> · {o.status}
                    {o.kind === "outreach" ? " · soft-capped drafts only" : ""}
                  </li>
                ))}
              </ul>
            </div>
          ) : null}

          {err ? <p className="la-li-err">{err}</p> : null}

          <div className="la-li-quick">
            <button type="button" className="la-btn la-btn-ghost" disabled={busy} onClick={() => void queueFill()}>
              Fill high-ticket leads
            </button>
            <button type="button" className="la-btn la-btn-ghost" disabled={busy} onClick={() => void queueEnrichNeedsContact()}>
              Enrich missing emails
            </button>
            <button type="button" className="la-btn la-btn-ghost" disabled={busy} onClick={() => void queueOutreachDraft()}>
              Queue LinkedIn drafts
            </button>
          </div>

          <form className="la-li-compose" onSubmit={(e) => void send(e)}>
            <input
              className="la-field"
              value={draft}
              onChange={(e) => setDraft(e.target.value)}
              placeholder="Message the LinkedIn agent…"
              disabled={busy}
              maxLength={4000}
            />
            <button className="la-btn la-btn-primary" type="submit" disabled={busy || !draft.trim()}>
              Send
            </button>
          </form>
        </div>
      ) : null}
    </div>
  );
}

"use client";

import { useMemo } from "react";
import type { FilterableProspect, ProspectViewFilter } from "@/lib/prospects/view-filter";

export type NextMovesProps = {
  prospects: FilterableProspect[];
  onFilter: (filter: ProspectViewFilter) => void;
  onFindHighTicket?: () => void;
  onOrderLinkedInEnrich?: () => void;
};

function countReach(rows: FilterableProspect[], reach: FilterableProspect["reach"]) {
  return rows.filter((r) => r.reach === reach).length;
}

export function NextMoves({
  prospects,
  onFilter,
  onFindHighTicket,
  onOrderLinkedInEnrich,
}: NextMovesProps) {
  const counts = useMemo(() => {
    const ready = countReach(prospects, "READY_TO_CONTACT");
    const contact = countReach(prospects, "NEEDS_CONTACT_INFO");
    const research = countReach(prospects, "NEEDS_RESEARCH");
    const linkedin = prospects.filter((p) => /linkedin/i.test(p.source || "")).length;
    return { ready, contact, research, linkedin };
  }, [prospects]);

  const chips: {
    key: string;
    label: string;
    hint: string;
    filter: ProspectViewFilter;
    show: boolean;
  }[] = [
    {
      key: "ready",
      label: `Ready to send (${counts.ready})`,
      hint: "You have enough to draft a note. Nothing sends until you confirm.",
      filter: { replace: true, reach: ["READY_TO_CONTACT"], sort: "needs_attention" },
      show: true,
    },
    {
      key: "contact",
      label: `Needs contact (${counts.contact})`,
      hint: "Find a real email or decision-maker before outreach.",
      filter: { replace: true, reach: ["NEEDS_CONTACT_INFO"], sort: "needs_attention" },
      show: true,
    },
    {
      key: "research",
      label: `Needs research (${counts.research})`,
      hint: "Look them up so you know who you’re pitching.",
      filter: { replace: true, reach: ["NEEDS_RESEARCH"], sort: "needs_attention" },
      show: true,
    },
    {
      key: "linkedin",
      label: `LinkedIn leads (${counts.linkedin})`,
      hint: "Prospects that came from LinkedIn research — your warmest Texas list.",
      filter: { replace: true, source: ["linkedin"], sort: "needs_attention" },
      show: true,
    },
    {
      key: "attn",
      label: "Your move first",
      hint: "Sort the whole Pipeline so research and contact gaps float to the top.",
      filter: { replace: true, sort: "needs_attention" },
      show: true,
    },
  ];

  return (
    <div className="mb-4">
      <p className="la-kicker">Next moves</p>
      <p className="mt-1 mb-2 text-sm text-muted">
        Cut through the noise. Tap a chip to see who can become a client next.
      </p>
      <div className="flex flex-wrap gap-2">
        {chips.filter((c) => c.show).map((c) => (
          <button
            key={c.key}
            type="button"
            className="la-btn la-btn-ghost"
            title={c.hint}
            onClick={() => onFilter(c.filter)}
          >
            {c.label}
          </button>
        ))}
        {onFindHighTicket ? (
          <button type="button" className="la-btn la-btn-quiet" onClick={onFindHighTicket}>
            Find high-ticket
          </button>
        ) : null}
        {onOrderLinkedInEnrich ? (
          <button type="button" className="la-btn la-btn-quiet" onClick={onOrderLinkedInEnrich}>
            Order LinkedIn enrich
          </button>
        ) : null}
      </div>
    </div>
  );
}

"use client";

import { useState } from "react";
import { approveSequenceFn } from "@/lib/mail/actions";
import type { Prospect } from "@/lib/review-brief";
