"use client";

import { useState } from "react";
import type { HealthLight, SentinelBug, SentinelSnapshot } from "@/lib/sentinel/types";
import { featureLabel } from "@/lib/sentinel/health";
import { ownerLabel } from "@/lib/sentinel/codes";
import { canonicalHealth } from "@/lib/sentinel/system-health";

function lightClass(light: HealthLight): string {
  if (light === "green") return "la-dot-good";
  if (light === "red") return "la-dot-bad";
  if (light === "yellow") return "la-dot-warn";
  return "la-dot-warn";
}

function formatWhen(iso: string | null): string {
  if (!iso) return "Not yet";
  const d = new Date(iso);
  if (!Number.isFinite(d.getTime())) return "Not yet";
  return d.toLocaleString("en-US", { timeZone: "America/Chicago", hour: "numeric", minute: "2-digit" });
}

function shortSha(sha: string): string {
  return (sha || "").slice(0, 7) || "unknown";
}

function isBookingMismatch(errorCode: string | undefined): boolean {
  const code = (errorCode || "").toUpperCase();
  return code.includes("PIPELINE_STATE_MISMATCH") || (code.includes("BOOKING") && code.includes("MISMATCH"));
}

function affectedLine(bug: { affected_records?: Array<Record<string, string>>; evidence?: Record<string, unknown> }): string {
  const rows = bug.affected_records || [];
  const bits: string[] = [];
  for (const row of rows.slice(0, 3)) {
    const uid = row.prospectUid || row.uid || "";
    const gid = row.googleEventId || "";
    if (uid && gid) bits.push(`prospect ${uid} · googleEventId ${gid}`);
    else if (uid) bits.push(`prospect ${uid}${gid === "" ? " · googleEventId (empty)" : ""}`);
    else if (gid) bits.push(`googleEventId ${gid}`);
  }
  if (!bits.length && bug.evidence) {
    const uid = String(bug.evidence.prospectUid || bug.evidence.uid || "");
    const gid = String(bug.evidence.googleEventId ?? "");
    if (uid) bits.push(`prospect ${uid}${gid ? ` · googleEventId ${gid}` : " · googleEventId (empty)"}`);
  }
  return bits.join("; ");
}

export function SystemHealthAlert({
  snapshot,
  onOpen,
  onRepair,
  repairing,
  result,
}: {
  snapshot: SentinelSnapshot | null;
  onOpen: () => void;
  onRepair?: (alert: SentinelBug) => void;
  repairing?: boolean;
  result?: string;
}) {
  const alerts = (snapshot?.alerts || []).slice(0, 3);
  if (!snapshot || !alerts.length) return null;
  return (
    <div className="la-ribbon la-ribbon-bad mb-3">
      {alerts.map((alert) => (
        <span key={alert.bug_id} className="block">
          <b>{alert.summary}</b>
          <span className="mt-1 block text-sm">
            {ownerLabel(alert.error_code)}. First seen {formatWhen(alert.first_seen_at)}.
            Production SHA {shortSha(alert.production_sha)}.
          </span>
          <span className="mt-2 flex flex-wrap gap-2">
            {onRepair ? (
              <button type="button" className="la-btn la-btn-primary" disabled={Boolean(repairing)} onClick={() => onRepair(alert)}>
                {repairing ? "Fixing…" : `Fix: ${ownerLabel(alert.error_code)}`}
              </button>
            ) : null}
          </span>
        </span>
      ))}
      {result ? <span className="mt-2 block text-sm">{result}</span> : null}
      <span className="mt-2 flex flex-wrap gap-2">
        <button type="button" className="la-btn la-btn-quiet" onClick={onOpen}>Open System Health</button>
      </span>
    </div>
  );
}

export function SystemHealthStrip({
