import type { Prospect } from "../review-brief.ts";
import { hypothesesFor } from "./hypotheses.ts";
import type { OpportunityCode, PriorityResult, ProspectPriority } from "./types.ts";

const UNKNOWN_DEFAULT = [
  "Average customer / case value",
  "Close rate",
  "Advertising budget",
  "Whether a meaningful retainer makes sense",
];

export function unknownEconomics(p: Prospect): string[] {
  const extra: string[] = [];
  const d = p.discovery || {};
  const out = UNKNOWN_DEFAULT.filter((label) => {
    if (label.startsWith("Average") && d.customer_value) return false;
    if (label.startsWith("Close") && d.close_rate) return false;
    if (label.startsWith("Advertising") && d.monthly_ad_budget) return false;
    return true;
  });
  if (!p.website || p.website === "UNKNOWN") extra.push("Whether they have a working website");
  return [...out, ...extra];
}

/** Explainable priority. No opaque AI score. */
export function priorityFor(p: Prospect): PriorityResult {
  if (p.suppressed || p.stage === "Do Not Contact") {
    return { priority: "DO NOT CONTACT", why: ["Already marked Do Not Contact."] };
  }
  if (p.stage === "Lost") {
    return { priority: "DO NOT CONTACT", why: ["Marked Lost. Do not reopen outreach from Get Clients."] };
  }

  const why: string[] = [];
  const researched = p.research_status === "complete" || p.research_status === "partial";
  const hy = hypothesesFor(p);
  const useful = hy.filter((h) => h.code !== "NO CLEAR OPPORTUNITY YET");
  const named = (p.contacts || []).filter((c) => c.name && c.name !== "UNKNOWN");
  const adsOn = (p.ads || []).some((a) => a.label === "ADVERTISING DETECTED");

  if (p.vertical) why.push(`${p.name} is a ${p.vertical} company${p.city ? ` in ${p.city}` : ""}.`);
  if (p.website && p.website !== "UNKNOWN") why.push("Public website is on file.");
  if (adsOn) why.push("Public advertising observation is on file (not proof of spend or waste).");
  if (useful.length) why.push(`${useful.length} evidence-grounded opportunit${useful.length === 1 ? "y" : "ies"} from pages we actually checked.`);
  if (named.length) why.push(`A named contact is on file: ${named[0].name}.`);
  if (p.review_count > 0) why.push(`${p.review_count} public reviews — a demand signal, not a requirement and not revenue.`);

  if (!researched && p.research_status !== "blocked" && p.research_status !== "failed") {
    return {
      priority: "NEEDS MORE RESEARCH",
      why: why.length ? why.concat(["We have not finished a website review."]) : ["We have not opened their website yet."],
    };
  }

  if (p.readiness === "LOW PRIORITY") {
    return { priority: "LOW PRIORITY", why: why.concat(p.readiness_why || ["Research classed this as low priority."]) };
  }

  if (p.research_status === "blocked" || p.research_status === "failed") {
    return {
      priority: "NEEDS MORE RESEARCH",
      why: why.concat(["Website research did not finish. We did not invent findings."]),
    };
  }

  const strongReadiness = p.readiness === "STRONG CANDIDATE FOR FURTHER QUALIFICATION";
  const hasPitch = useful.length >= 1 && useful[0].code !== "NO CLEAR OPPORTUNITY YET";
  const mature = Boolean(p.website && p.website !== "UNKNOWN") && (adsOn || named.length || p.review_count >= 20 || strongReadiness);

  if ((strongReadiness && hasPitch) || (hasPitch && mature && named.length)) {
    return {
      priority: "STRONG CANDIDATE FOR OUTREACH",
      why: why.slice(0, 4),
    };
  }

  if (hasPitch || strongReadiness || p.readiness === "POSSIBLE CANDIDATE") {
    return {
      priority: "WORTH REVIEWING",
      why: why.slice(0, 4),
    };
  }

  if (p.readiness === "NOT ENOUGH INFORMATION" || !researched) {
    return { priority: "NEEDS MORE RESEARCH", why: why.concat(["Not enough verified public facts yet."]) };
  }

  return { priority: "LOW PRIORITY", why: why.concat(["No clear public opportunity, and we will not invent one."]) };
}

export function applyAttackFields(p: Prospect): Prospect {
  const hy = hypothesesFor(p);
  const pri = priorityFor(p);
  return {
    ...p,
    opportunity_codes: hy.map((h) => h.code) as OpportunityCode[],
    priority: pri.priority,
    priority_why: pri.why,
  };
}

import { whyConsider, type Prospect } from "../review-brief.ts";
import { hypothesesFor } from "./hypotheses.ts";
import type { IndustryAttack, ProposalDoc } from "./types.ts";

const AD_SPEND = "Advertising spend is separate from the management fee. We do not set or claim a spend number until you and the client agree.";

export function buildProposal(p: Prospect, opts: { monthlyFee: number | null; attack?: IndustryAttack | null }): ProposalDoc {
  const hy = hypothesesFor(p);
  const named = (p.contacts || []).filter((c) => c.name && c.name !== "UNKNOWN");
  const fee = opts.monthlyFee != null && Number.isFinite(opts.monthlyFee) && opts.monthlyFee > 0
    ? opts.monthlyFee
    : null;
  const feeLine = fee == null
    ? "Management fee: UNKNOWN — you still need to enter a monthly fee. Lamb Ascension will not invent one."
    : `Management fee: $${Math.round(fee).toLocaleString("en-US")} / month.`;

  const opps = hy.filter((h) => h.code !== "NO CLEAR OPPORTUNITY YET");
  const sit = whyConsider(p);
  const oppLines = opps.length
    ? opps.map((h) => `- ${h.title}: ${h.plain}`).join("\n")
    : "- No clear public opportunity was verified. We will not invent one in this proposal.";

  const unknowns: string[] = [];
  const d = p.discovery || {};
  if (!d.customer_value) unknowns.push("average customer value");
  if (!d.close_rate) unknowns.push("close rate");
  if (!d.monthly_ad_budget) unknowns.push("current advertising budget");
  const unknownLine = unknowns.length
    ? `Still unknown (must be confirmed with the client): ${unknowns.join(", ")}.`
    : "Client-provided economics are on file for this draft.";

  const body = [
    `Proposal — ${p.name}`,
    "",
    "Current situation",
    sit,
    "",
    "Opportunity (hypotheses from public pages — not guaranteed revenue)",
    oppLines,
    "",
    "Lamb Ascension acquisition system",
    opts.attack?.offer
      || "We help you get more of the right customers. We will not promise a revenue number we have not measured.",
    "",
    "What we will manage",
    "- Research, tracking hygiene, and campaign direction you approve",
    "- Creative and landing-page drafts from verified facts only",
    "- Reporting on spend, leads, and outcomes we can actually see",
    "",
    "What the client needs to provide",
    "- Offer, service area, and brand assets",
    "- Ad account / analytics access",
    "- Honest economics (customer value, close rate, capacity)",
    named.length ? `- Primary contact: ${named[0].name}` : "- A named decision-maker (UNKNOWN until they tell us)",
    "",
    "Tracking / measurement",
    "We do not launch paid media until conversion measurement is checked. Platform-attributed numbers are labeled separately from CRM-verified numbers.",
    "",
    feeLine,
    AD_SPEND,
    "",
    unknownLine,
    "",
    "Next steps",
    "1. You review this draft.",
    "2. Nothing is sent until you approve.",
    "3. After they sign, onboarding starts — that is a later phase, not this proposal.",
    "",
    "This document does not guarantee revenue, ROAS, or a specific number of customers.",
  ].join("\n");

  return {
    status: "draft",
    monthly_fee: fee,
    ad_spend_note: AD_SPEND,
    body,
    generated_at: new Date().toISOString(),
  };
}

import type { Prospect } from "../review-brief.ts";
import { applyAttackFields, priorityFor, unknownEconomics } from "./priority.ts";
import { hypothesesFor } from "./hypotheses.ts";
import type { GetClientsBriefing, GetClientsItem, ProspectPriority } from "./types.ts";

const SKIP_STAGES = new Set(["Do Not Contact", "Won", "Lost"]);

function rank(priority: ProspectPriority, stage: string, research: string): number {
  if (stage === "Replied") return 0;
  if (stage === "Call Booked") return 1;
  if (stage === "Proposal Sent" || stage === "Negotiation") return 2;
  if (stage === "Approved for Outreach") return 3;
  if (priority === "STRONG CANDIDATE FOR OUTREACH") return 4;
  if (priority === "WORTH REVIEWING") return 5;
  if (priority === "NEEDS MORE RESEARCH" || research === "none" || research === "queued") return 6;
  if (priority === "LOW PRIORITY") return 7;
  return 8;
}

export function inAttack(p: Prospect, attackId: string | null | undefined): boolean {
  if (!attackId) return true;
  return p.attack_id === attackId;
}

export function queueProspects(rows: Prospect[], attackId?: string | null): Prospect[] {
  return rows
    .filter((p) => !p.suppressed && !SKIP_STAGES.has(p.stage) && !p.get_clients_skipped)
    .filter((p) => inAttack(p, attackId))
    .map(applyAttackFields)
    .sort((a, b) => {
      const pa = priorityFor(a).priority;
      const pb = priorityFor(b).priority;
      const d = rank(pa, a.stage, a.research_status) - rank(pb, b.stage, b.research_status);
      if (d !== 0) return d;
      return (b.score || 0) - (a.score || 0);
    });
}

export function toQueueItem(p: Prospect): GetClientsItem {
  const enriched = applyAttackFields(p);
  const pri = priorityFor(enriched);
  return {
    uid: enriched.uid || "",
    name: enriched.name,
    priority: pri.priority,
    why: (enriched.priority_why || pri.why).slice(0, 4),
    codes: hypothesesFor(enriched).map((h) => h.code),
    unknown: unknownEconomics(enriched),
    stage: enriched.stage,
    research_status: enriched.research_status,
  };
}

export function briefingFor(rows: Prospect[], attackId?: string | null): GetClientsBriefing {
  const scoped = attackId ? rows.filter((p) => inAttack(p, attackId)) : rows;
  const live = scoped.filter((p) => !p.suppressed && p.stage !== "Do Not Contact");
  const items = queueProspects(rows, attackId).map(toQueueItem);
  const researched = live.filter((p) => ["complete", "partial", "blocked", "failed"].includes(p.research_status)).length;
  const attention = items.filter((i) => i.priority === "STRONG CANDIDATE FOR OUTREACH" || i.priority === "WORTH REVIEWING").length;
  const outreachReady = live.filter((p) => p.stage === "Approved for Outreach").length;
  const replies = live.filter((p) => p.stage === "Replied").length;
  const calls = live.filter((p) => p.stage === "Call Booked").length;
  const found = live.length;
  const spoken = found
    ? `I found ${found} compan${found === 1 ? "y" : "ies"}. I researched ${researched}. ${attention} look worth your attention. ${outreachReady} already have outreach ready.`
    : "No companies in this attack yet. Build a target list, or add a company you already know.";
  return { found, researched, attention, outreachReady, replies, calls, spoken, items };
}

export function recommendContact(p: Prospect): string {
  const hy = hypothesesFor(p);
  const pitch = hy.find((h) => h.code !== "NO CLEAR OPPORTUNITY YET");
  if (p.research_status !== "complete" && p.research_status !== "partial") {
    return "Research them before you contact. We do not have a verified public observation yet.";
  }
  if (!pitch) {
    return "No clear public gap. You can still contact them, but do not invent a compliment or a problem.";
  }
  return `Contact them and use the ${pitch.title.toLowerCase()} angle — only what we actually saw.`;
}

import type { Prospect } from "../review-brief.ts";
import type { OwnerGoal, RevenueLane, RevenueSnapshot } from "./types.ts";
import { isTestWorkflowUid } from "../mail/test-loop.ts";

export function revenueLane(stage: string): RevenueLane | null {
  if (stage === "New" || stage === "Researching") return "researching";
  if (stage === "Qualified" || stage === "Ready for Review" || stage === "Approved for Outreach") return "ready";
  if (stage === "Contacted") return "contacted";
  if (stage === "Replied") return "replied";
  if (stage === "Call Booked") return "calls";
  if (stage === "Proposal Sent" || stage === "Negotiation") return "proposals";
  if (stage === "Won") return "won";
  if (stage === "Lost") return "lost";
  return null;
}

export function isQualified(p: Prospect): boolean {
  const d = p.discovery || {};
  return Boolean(d.customer_value || d.monthly_ad_budget || d.close_rate);
}

/** VERIFIED MRR = Won clients with an owner-entered monthly fee. Never inferred. */
export function verifiedMrr(rows: Prospect[]): number {
  let sum = 0;
  for (const p of rows) {
    if (p.stage !== "Won") continue;
    const fee = p.monthly_fee;
    if (typeof fee === "number" && Number.isFinite(fee) && fee > 0) sum += fee;
  }
  return sum;
}

export function clientsNeeded(goal: OwnerGoal): number | null {
  const m = goal.monthly_mrr_target;
  const a = goal.average_retainer_target;
  if (!m || !a || m <= 0 || a <= 0) return null;
  return Math.ceil(m / a);
}

export function revenueSnapshot(rows: Prospect[], goal: OwnerGoal = { monthly_mrr_target: null, average_retainer_target: null }): RevenueSnapshot {
  const live = rows.filter((p) => !p.suppressed && !p.is_demo && !isTestWorkflowUid(p.uid));
  const counts: Omit<RevenueSnapshot, "verified_mrr" | "clients_needed" | "goal"> = {
    researching: 0,
    ready: 0,
    contacted: 0,
    replied: 0,
    qualified: 0,
    calls: 0,
    proposals: 0,
    won: 0,
    lost: 0,
  };
  for (const p of live) {
    const lane = revenueLane(p.stage);
    if (lane && lane in counts) counts[lane] += 1;
    if (isQualified(p) && p.stage !== "Won" && p.stage !== "Lost" && p.stage !== "Do Not Contact") {
      counts.qualified += 1;
    }
  }
  return {
    ...counts,
    verified_mrr: verifiedMrr(live),
    clients_needed: clientsNeeded(goal),
    goal,
  };
}

