import type { InboundClass } from "./replies.ts";

const PROD = "https://lamb-ascension-engine.vercel.app";

export function publicBookingOrigin(): string {
  const auth = (process.env.BETTER_AUTH_URL || "").trim().replace(/\/$/, "");
  if (/^https:\/\//i.test(auth)) return auth;
  const vercel = (process.env.VERCEL_URL || "").replace(/^https?:\/\//, "").trim();
  if (vercel) return `https://${vercel}`;
  return PROD;
}

export function trackedBookingUrl(origin: string, token: string): string {
  const base = (origin || PROD).replace(/\/$/, "");
  return `${base}/book/${token}`;
}

export function replyWantsBooking(cls: InboundClass): boolean {
  return cls === "INTERESTED" || cls === "BOOKING_REQUEST" || cls === "WANTS_AUDIT" || cls === "WANTS_MORE_INFORMATION" || cls === "PRICING_QUESTION";
}

export function shouldReuseBookingToken(link: { status: string; expiresAt?: string | null } | null, now = Date.now()): boolean {
  if (!link || link.status !== "open") return false;
  if (!link.expiresAt) return true;
  const exp = new Date(link.expiresAt).getTime();
  return Number.isFinite(exp) && exp > now;
}

export function applyImmediateBooking<T extends {
  stage?: string;
  stage_plain?: string;
  meeting_at?: string;
  meeting_event_id?: string;
  history?: { at?: string; action?: string; detail?: string }[];
}>(prospect: T, opts: { at: string; startIso: string; eventId: string; brief: string }): T {
  const stage = prospect.stage || "";
  const locked = stage === "Won" || stage === "Lost" || stage === "Do Not Contact";
  const history = [...(prospect.history || [])];
  if (!history.some((h) => h.action === "call_prep")) {
    history.push({ at: opts.at, action: "call_prep", detail: opts.brief });
  }
  history.push({ at: opts.at, action: "meeting_booked", detail: `Booked ${opts.startIso}. Event ${opts.eventId}. Outreach stopped.` });
  return {
    ...prospect,
    stage: locked ? stage : "Call Booked",
    stage_plain: locked ? prospect.stage_plain : "Call is on the calendar",
    meeting_at: opts.startIso,
    meeting_event_id: opts.eventId,
    history,
  };
}

export function callPrep(opts: {
  company: string;
  contact: string;
  when: string;
  vertical: string;
  city: string;
  finding: string;
  emailsSent: number;
  replySummary: string;
  bookingUrl: string;
  website?: string;
  angle?: string;
  offer?: string;
}): string {
  const finding = opts.finding.trim() || "No single verified website gap was stored. Do not invent one on the call.";
  return [
    `${opts.company}`,
    opts.contact ? `With ${opts.contact}` : "Contact not named on file",
    opts.when ? `When: ${opts.when}` : "",
    opts.website && opts.website !== "UNKNOWN" ? `Website: ${opts.website}` : "",
    "",
    `What they do: ${opts.vertical || "Unknown category"}${opts.city ? ` in ${opts.city}` : ""}.`,
    `Why they were targeted: ${finding}`,
    opts.angle ? `Original angle: ${opts.angle}` : "",
    opts.offer ? `Possible offer from what we stored: ${opts.offer}` : "No packaged offer was stored. Do not invent one.",
    `Emails sent: ${opts.emailsSent}.`,
    opts.replySummary ? `What they said: ${opts.replySummary}` : "No reply text stored.",
    "",
    "Ask: How are you getting customers today, and what happens after someone visits the site?",
    "Likely objection: they may say they already get enough calls. Ask what happens to people who are not ready to call.",
    "Do not invent testimonials, prices, or results. Do not claim their revenue, ad spend, or that they already want to buy.",
    opts.bookingUrl ? `Booking link on file: ${opts.bookingUrl}` : "No booking link saved.",
    "Best next step: agree on one acquisition gap and whether a short engagement is worth a proposal.",
  ].filter((line) => line !== "").join("\n");
}

export type DayRow = {
  stage?: string;
  discovered_at?: string;
  history?: { at?: string; action?: string; detail?: string }[];
};

export type DaySummary = {
  found: number;
  researched: number;
  qualified: number;
  contacted: number;
  replies: number;
  interested: number;
  callsBooked: number;
  needsYou: string[];
  revenue: "UNKNOWN";
  paused: boolean;
};

function onDay(at: string | undefined, day: string): boolean {
  return Boolean(at && at.slice(0, 10) === day);
}

export function dailySummary(rows: DayRow[], day: string): DaySummary {
  const summary: DaySummary = {
    found: 0,
    researched: 0,
    qualified: 0,
    contacted: 0,
    replies: 0,
    interested: 0,
    callsBooked: 0,
    needsYou: [],
    revenue: "UNKNOWN",
    paused: false,
  };
  for (const row of rows) {
    if (onDay(row.discovered_at, day)) summary.found += 1;
    const history = row.history || [];
    if (history.some((h) => h.action === "research_completed" && onDay(h.at, day))) summary.researched += 1;
    if (history.some((h) => h.action === "outreach_generated" && onDay(h.at, day))) summary.qualified += 1;
    if (history.some((h) => (h.action === "autonomy_sent" || h.action === "email_sent") && onDay(h.at, day))) summary.contacted += 1;
    if (history.some((h) => (h.action === "reply" || h.action === "autonomy_replied" || h.action === "autonomy_escalate") && onDay(h.at, day))) summary.replies += 1;
    if (history.some((h) => onDay(h.at, day) && /INTERESTED|WANTS_AUDIT|BOOKING_REQUEST/.test(h.detail || ""))) summary.interested += 1;
    if (history.some((h) => h.action === "meeting_booked" && onDay(h.at, day)) || (row.stage === "Call Booked" && history.some((h) => h.action === "call_prep" && onDay(h.at, day)))) {
      summary.callsBooked += 1;
    }
    if (history.some((h) => h.action === "autonomy_paused" && onDay(h.at, day))) summary.paused = true;
    const openReview = history.some((h) => h.action === "autonomy_escalate") && !history.some((h) => h.action === "owner_reviewed");
    if (openReview) summary.needsYou.push("Unclear reply needs a look");
  }
  if (summary.paused) summary.needsYou.unshift("Sending is paused to protect the inbox");
  if (summary.callsBooked) summary.needsYou.push(`${summary.callsBooked} upcoming call${summary.callsBooked === 1 ? "" : "s"}`);
  return summary;
}

