export type CheckItem = { id: string; label: string; done: boolean };
export type ClientStatus = "ONBOARDING" | "ACTIVE" | "PAUSED" | "COMPLETED" | "CANCELED";

export function onboardingChecklist(service: string): CheckItem[] {
  const s = (service || "").toLowerCase();
  const named = /acquire|convert|system/.test(s);
  const ads = /acquire|system|\bads\b|meta|google ads/.test(s);
  const site = /convert|system|website|landing|form/.test(s);
  const items: CheckItem[] = [
    { id: "agreement", label: "Agreement", done: false },
    { id: "payment", label: "Payment", done: false },
    { id: "contact", label: "Primary contact confirmed", done: false },
    { id: "service", label: "Service confirmed", done: false },
  ];
  if (named && site) {
    items.push({ id: "website", label: "Website access", done: false });
    items.push({ id: "tracking", label: "Tracking access", done: false });
  }
  if (named && ads) items.push({ id: "ads", label: "Ad account access", done: false });
  if (named && (site || ads)) {
    items.push({ id: "offer", label: "The offer they want promoted", done: false });
    items.push({ id: "audience", label: "Who they want as a customer", done: false });
  }
  items.push({ id: "start", label: "Start date", done: false });
  return items;
}

export function handoffSummary(input: {
  company: string;
  contact?: string;
  website?: string;
  service?: string;
  price?: number | null;
  billing?: string;
  gap?: string;
  goal?: string;
  promised?: string;
  needs?: string[];
  next?: string;
}): string {
  const price = typeof input.price === "number" ? `$${input.price.toLocaleString()}${input.billing ? ` / ${input.billing}` : ""}` : "UNKNOWN";
  return [
    `CLIENT`,
    input.company || "UNKNOWN",
    input.contact ? `Contact: ${input.contact}` : "Contact: UNKNOWN",
    input.website && input.website !== "UNKNOWN" ? `Website: ${input.website}` : "Website: UNKNOWN",
    "",
    "THEY HIRED US FOR",
    input.service || "UNKNOWN",
    "",
    "WHY",
    input.gap || "UNKNOWN",
    "",
    "PRICE",
    price,
    "",
    "GOAL",
    input.goal || "UNKNOWN",
    "",
    "WHAT WE PROMISED",
    input.promised || "UNKNOWN",
    "",
    "WE NEED FROM THEM",
    input.needs?.length ? input.needs.join(", ") : "UNKNOWN",
    "",
    "NEXT",
    input.next || "Confirm the agreement and the start date.",
  ].join("\n");
}

export function applyFollowupSent<T extends { history?: { at?: string; action?: string; detail?: string }[]; followup_sent_body?: string; followup_sent_at?: string; followup_sent_to?: string }>(
  prospect: T,
  result: { ok: false; reason: string } | { ok: true; to: string; body: string; at: string },
): { ok: true; prospect: T } | { ok: false; reason: string } {
  if (!result.ok) return { ok: false, reason: result.reason };
  if (!result.body.trim()) return { ok: false, reason: "The note is empty. Nothing was sent." };
  if (prospect.followup_sent_body && prospect.followup_sent_body === result.body) {
    return { ok: false, reason: "That exact note was already sent." };
  }
  return {
    ok: true,
    prospect: {
      ...prospect,
      followup_sent_body: result.body,
      followup_sent_at: result.at,
      followup_sent_to: result.to,
      history: [...(prospect.history || []), { at: result.at, action: "sales_followup_sent", detail: `Sent to ${result.to}.` }],
    },
  };
}

export type LearnRow = {
  vertical?: string;
  stage?: string;
  history?: { action?: string; detail?: string }[];
};

const POSITIVE = /INTERESTED|WANTS_AUDIT|BOOKING|meeting_booked|Call Booked|Won/;

/** Nudge only after 8 sends in that industry. Tiny samples do not change who we contact. */
export function industryNudge(rows: LearnRow[], vertical: string): number {
  const key = vertical.trim().toLowerCase();
  if (!key) return 0;
  let sent = 0;
  let good = 0;
  for (const row of rows) {
    if ((row.vertical || "").trim().toLowerCase() !== key) continue;
    const sentThis = (row.history || []).some((h) => h.action === "autonomy_sent" || h.action === "email_sent");
    if (!sentThis && row.stage !== "Contacted" && row.stage !== "Replied" && row.stage !== "Call Booked" && row.stage !== "Won") continue;
    sent += 1;
    const text = `${row.stage || ""} ${(row.history || []).map((h) => `${h.action || ""} ${h.detail || ""}`).join(" ")}`;
    if (POSITIVE.test(text) || row.stage === "Call Booked" || row.stage === "Won" || row.stage === "Replied") good += 1;
  }
  if (sent < 8) return 0;
  const rate = good / sent;
  if (rate >= 0.25) return 8;
  if (rate === 0) return -6;
  return 0;
}

import assert from "node:assert/strict";
import test from "node:test";
import { callPrep } from "./call-prep.ts";
import { knownRevenue, learningSlices, lifecycle, markCallOutcome, markRescheduleWaiting, markSalesOutcome } from "./outcomes.ts";
import { planReply } from "./replies.ts";

test("booking flow stays on evidence and does not invent revenue", () => {
  let row = {
    name: "AWO Lending",
    stage: "New",
    research_status: "none",
    history: [] as { action: string; detail: string }[],
  };
  assert.equal(lifecycle(row), "FOUND");
  row = { ...row, research_status: "complete" };
  assert.equal(lifecycle(row), "RESEARCHED");
  row = { ...row, stage: "Approved for Outreach", history: [{ action: "outreach_generated", detail: "draft" }] };
  assert.equal(lifecycle(row), "READY_FOR_OUTREACH");
  row = { ...row, stage: "Contacted", history: [...row.history, { action: "autonomy_sent", detail: "held in test mode" }] };
  assert.equal(lifecycle(row), "CONTACTED");
  row = { ...row, history: [...row.history, { action: "autonomy_replied", detail: "INTERESTED" }] };
  assert.equal(lifecycle(row), "INTERESTED");
  const reply = planReply({ text: "Sounds good, let's talk", name: "Amos", company: "AWO Lending", bookingUrl: "https://cal.example/dylan", finding: "no homepage form" });
  assert.match(reply.body, /cal\.example/);
  const cold = planReply({ text: "Not interested", name: "Amos", company: "AWO Lending", bookingUrl: "https://cal.example/dylan" });
  assert.doesNotMatch(cold.body, /cal\.example/);
  const noLink = planReply({ text: "Sounds good", name: "Amos", company: "AWO Lending", bookingUrl: "" });
  assert.doesNotMatch(noLink.body, /https?:\/\//);

  row = { ...row, stage: "Call Booked", meeting_at: "2020-01-01T15:00:00.000Z", meeting_event_id: "evt-1", history: [...row.history, { action: "meeting_booked", detail: "stopped" }] };
  assert.equal(lifecycle(row), "BOOKED");
  const early = markCallOutcome({ ...row, meeting_at: "2099-01-01T15:00:00.000Z" }, "SHOWED", new Date("2026-09-23T12:00:00.000Z"));
  assert.equal(early.ok, false);
  const showed = markCallOutcome(row, "SHOWED", new Date("2026-09-23T12:00:00.000Z"));
  assert.equal(showed.ok, true);
  if (!showed.ok) return;
  assert.equal(lifecycle(showed.prospect), "SHOWED");
  const again = markCallOutcome(showed.prospect, "SHOWED", new Date());
  assert.equal(again.ok && again.prospect.history?.length, showed.prospect.history?.length);

  const wonBlank = markSalesOutcome(showed.prospect, { outcome: "WON" });
  assert.equal(wonBlank.ok, true);
  if (!wonBlank.ok) return;
  assert.equal(wonBlank.prospect.client_value, null);
  assert.equal(knownRevenue([wonBlank.prospect]).amount, null);

  const won = markSalesOutcome(showed.prospect, { outcome: "WON", clientValue: 2500, billing: "monthly", note: "starts October" });
  assert.equal(won.ok, true);
  if (!won.ok) return;
  assert.equal(knownRevenue([won.prospect]).amount, 2500);

  const missed = markCallOutcome(row, "NO_SHOW", new Date("2026-09-23T12:00:00.000Z"));
  assert.equal(missed.ok, true);
  if (!missed.ok) return;
  assert.notEqual(missed.prospect.stage, "New");
  const wait = markRescheduleWaiting(missed.prospect);
  assert.equal(wait.ok, true);
  if (!wait.ok) return;
  assert.ok((wait.prospect.history || []).some((h) => h.action === "reschedule_waiting"));
  assert.equal(lifecycle(wait.prospect), "NO_SHOW");

  const lost = markSalesOutcome(showed.prospect, { outcome: "LOST" });
  assert.equal(lost.ok, true);
  if (!lost.ok) return;
  assert.equal(lost.prospect.lost_reason, "");
  assert.equal(learningSlices([won.prospect]).tooSmall, true);

  const brief = callPrep({
    company: "AWO Lending", contact: "Amos", when: "Thursday 11:00 AM", vertical: "Business lending", city: "Dallas",
    finding: "no homepage form", emailsSent: 1, replySummary: "Asked to talk", bookingUrl: "https://cal.example/dylan", website: "https://awo.example",
  });
  assert.match(brief, /AWO Lending/);
  assert.match(brief, /no homepage form/);
  assert.match(brief, /Do not invent/);
});

import { handoffSummary, onboardingChecklist, type CheckItem, type ClientStatus } from "./handoff.ts";

export type LifeStage =
  | "FOUND"
  | "RESEARCHED"
  | "QUALIFIED"
  | "READY_FOR_OUTREACH"
  | "CONTACTED"
  | "FOLLOW_UP"
  | "REPLIED"
  | "INTERESTED"
  | "BOOKED"
  | "SHOWED"
  | "NO_SHOW"
  | "FOLLOW_UP_NEEDED"
  | "WON"
  | "LOST"
  | "DO_NOT_CONTACT";

export type SalesOutcome = "" | "SHOWED" | "NO_SHOW" | "FOLLOW_UP_NEEDED" | "WON" | "LOST";
export type BillingType = "" | "one-time" | "monthly";
export type LostReason = "" | "Too expensive" | "Not ready" | "No fit" | "Went with competitor" | "No decision" | "Other";

export type OutcomeProspect = {
  name?: string;
  stage?: string;
  suppressed?: boolean;
  research_status?: string;
  meeting_at?: string;
  meeting_event_id?: string;
  sales_outcome?: SalesOutcome;
  client_value?: number | null;
  billing_type?: BillingType;
  lost_reason?: LostReason;
  outcome_note?: string;
  follow_up_at?: string;
  follow_up_reason?: string;
  call_notes?: { recommended?: string; desired?: string; notes?: string; nextStep?: string };
  client_record?: {
    company: string;
    contact: string;
    service: string;
    price: number | null;
    billing: string;
    startDate: string;
    notes: string;
    expectations: string;
    nextAction: string;
  };
  client_status?: ClientStatus;
  onboarding?: CheckItem[];
  handoff_summary?: string;
  history?: { at?: string; action?: string; detail?: string }[];
};

const LOST_REASONS = new Set(["", "Too expensive", "Not ready", "No fit", "Went with competitor", "No decision", "Other"]);

export function lifecycle(p: OutcomeProspect): LifeStage {
  if (p.suppressed || p.stage === "Do Not Contact") return "DO_NOT_CONTACT";
  if (p.sales_outcome === "WON" || p.stage === "Won") return "WON";
  if (p.sales_outcome === "LOST" || p.stage === "Lost") return "LOST";
  if (p.sales_outcome === "FOLLOW_UP_NEEDED") return "FOLLOW_UP_NEEDED";
  if (p.sales_outcome === "SHOWED") return "SHOWED";
  if (p.sales_outcome === "NO_SHOW") return "NO_SHOW";
  if (p.stage === "Call Booked" || (p.history || []).some((h) => h.action === "meeting_booked")) return "BOOKED";
  const text = (p.history || []).map((h) => `${h.action || ""} ${h.detail || ""}`).join(" ");
  if (/INTERESTED|WANTS_AUDIT|BOOKING_REQUEST/.test(text)) return "INTERESTED";
  if (p.stage === "Replied" || /reply|autonomy_replied/.test(text)) return "REPLIED";
  if (p.stage === "Contacted" && /followup/.test(text)) return "FOLLOW_UP";
  if (p.stage === "Contacted" || /autonomy_sent|email_sent/.test(text)) return "CONTACTED";
  if (p.stage === "Approved for Outreach" || /outreach_generated/.test(text)) return "READY_FOR_OUTREACH";
  if (p.stage === "Qualified" || /autonomy_disqualified/.test(text) === false && (p.research_status === "complete" || p.research_status === "partial") && p.stage === "Qualified") return "QUALIFIED";
  if (p.research_status === "complete" || p.research_status === "partial") return "RESEARCHED";
  return "FOUND";
}

function stamp<T extends OutcomeProspect>(p: T, action: string, detail: string): T {
  return { ...p, history: [...(p.history || []), { at: new Date().toISOString(), action, detail }] };
}

export function meetingIsPast(meetingAt: string | undefined, now: Date): boolean {
  if (!meetingAt) return true;
  const t = new Date(meetingAt).getTime();
  if (!Number.isFinite(t)) return true;
  return t <= now.getTime();
}

export function markCallOutcome<T extends OutcomeProspect>(p: T, outcome: "SHOWED" | "NO_SHOW", now: Date): { ok: true; prospect: T } | { ok: false; reason: string } {
  if (p.sales_outcome === outcome) return { ok: true, prospect: p };
  const life = lifecycle(p);
  if (life !== "BOOKED" && life !== "NO_SHOW") return { ok: false, reason: "There is no booked call to mark." };
  if (!meetingIsPast(p.meeting_at, now)) return { ok: false, reason: "That call has not happened yet." };
  const next = stamp({ ...p, sales_outcome: outcome }, outcome === "SHOWED" ? "showed" : "no_show", outcome === "SHOWED" ? "They showed. No new cold email." : "No-show. Cold outreach stays off. They can rebook.");
  return { ok: true, prospect: next };
}

export function markRescheduleWaiting<T extends OutcomeProspect>(p: T): { ok: true; prospect: T } | { ok: false; reason: string } {
  if (p.sales_outcome !== "NO_SHOW") return { ok: false, reason: "Reschedule is only for a no-show. A new cold sequence was not started." };
  if ((p.history || []).some((h) => h.action === "reschedule_waiting")) return { ok: true, prospect: p };
  return { ok: true, prospect: stamp(p, "reschedule_waiting", "Waiting for them to rebook. No cold email will be sent.") };
}

export function markSalesOutcome<T extends OutcomeProspect>(p: T, input: {
  outcome: "WON" | "LOST" | "FOLLOW_UP_NEEDED";
  clientValue?: number | null;
  billing?: BillingType;
  note?: string;
  lostReason?: string;
  followUpAt?: string;
  followUpReason?: string;
}): { ok: true; prospect: T } | { ok: false; reason: string } {
  if (lifecycle(p) !== "SHOWED" && p.sales_outcome !== "FOLLOW_UP_NEEDED") {
    return { ok: false, reason: "Mark that they showed before recording won, lost, or follow-up." };
  }
  if (input.outcome === "WON") {
    const value = input.clientValue;
    const hasValue = typeof value === "number" && Number.isFinite(value) && value >= 0;
    const billing = input.billing === "one-time" || input.billing === "monthly" ? input.billing : "";
    const service = p.call_notes?.recommended || "Not chosen on the call";
    const checklist = onboardingChecklist(service);
    const next = stamp({
      ...p,
      stage: "Won",
      stage_plain: "Signed client",
      sales_outcome: "WON" as SalesOutcome,
      client_value: hasValue ? value : null,
      billing_type: billing,
      outcome_note: (input.note || "").slice(0, 500),
      client_status: "ONBOARDING" as const,
      onboarding: checklist,
      client_record: {
        company: p.name || "",
        contact: "",
        service,
        price: hasValue ? (value as number) : null,
        billing,
        startDate: new Date().toISOString().slice(0, 10),
        notes: p.call_notes?.notes || input.note || "",
        expectations: p.call_notes?.desired || "",
        nextAction: p.call_notes?.nextStep || "Send the agreement and book onboarding.",
      },
      handoff_summary: handoffSummary({
        company: p.name || "",
        service,
        price: hasValue ? (value as number) : null,
        billing,
        gap: "",
        goal: p.call_notes?.desired || "",
        promised: p.call_notes?.notes || "",
        needs: checklist.map((item) => item.label),
        next: p.call_notes?.nextStep || "",
      }),
    }, "client_created", "Client record opened. Acquisition stays stopped.");
    return { ok: true, prospect: next as T };
  }
  if (input.outcome === "LOST") {
    const reason = LOST_REASONS.has(input.lostReason || "") ? (input.lostReason as LostReason) || "" : "";
    const next = stamp({
      ...p,
      stage: "Lost",
      stage_plain: "Not moving forward",
      sales_outcome: "LOST" as SalesOutcome,
      lost_reason: reason,
      client_value: null,
      outcome_note: (input.note || "").slice(0, 500),
    }, "sales_lost", reason ? `Lost. ${reason}.` : "Lost. No reason given.");
    return { ok: true, prospect: next as T };
  }
  const next = stamp({
    ...p,
    sales_outcome: "FOLLOW_UP_NEEDED" as SalesOutcome,
    outcome_note: (input.note || "").slice(0, 500),
    follow_up_at: input.followUpAt || p.follow_up_at || "",
    follow_up_reason: (input.followUpReason || "").slice(0, 200),
  }, "follow_up_needed", "Needs a decision from you. No automatic cold email.");
  return { ok: true, prospect: next as T };
}

export function knownRevenue(rows: { client_value?: number | null; sales_outcome?: string; billing_type?: string }[]): { amount: number | null; monthly: number; once: number } {
  let amount = 0;
  let monthly = 0;
  let once = 0;
  let any = false;
  for (const row of rows) {
    if (row.sales_outcome !== "WON") continue;
    if (typeof row.client_value !== "number") continue;
    any = true;
    amount += row.client_value;
    if (row.billing_type === "monthly") monthly += row.client_value;
    if (row.billing_type === "one-time") once += row.client_value;
  }
  return { amount: any ? amount : null, monthly, once };
}

export type LearnSlice = { key: string; bookings: number; wins: number; revenue: number | null };

export function learningSlices(rows: {
  vertical?: string;
  city?: string;
  sales_outcome?: string;
  client_value?: number | null;
  stage?: string;
  history?: { action?: string; detail?: string }[];
  opportunity?: string;
  angle?: string;
  subject?: string;
}[]): { industry: LearnSlice[]; tooSmall: boolean } {
  const map = new Map<string, LearnSlice>();
  let decided = 0;
  for (const row of rows) {
    const booked = row.stage === "Call Booked" || row.sales_outcome === "SHOWED" || row.sales_outcome === "WON" || row.sales_outcome === "NO_SHOW" || row.sales_outcome === "LOST" || (row.history || []).some((h) => h.action === "meeting_booked");
    const won = row.sales_outcome === "WON" || row.stage === "Won";
    if (booked || won) decided += 1;
    const key = (row.vertical || "Unknown").trim() || "Unknown";
    const cur = map.get(key) || { key, bookings: 0, wins: 0, revenue: null };
    if (booked) cur.bookings += 1;
    if (won) {
      cur.wins += 1;
      if (typeof row.client_value === "number") cur.revenue = (cur.revenue || 0) + row.client_value;
    }
    map.set(key, cur);
  }
  return { industry: [...map.values()], tooSmall: decided < 8 };
}

const GAP_WEIGHT: Record<string, number> = {
  NO_HOMEPAGE_FORM: 28,
  NO_HOMEPAGE_CTA: 22,
  NO_CLICK_TO_CALL: 16,
  NO_TRACKING: 14,
  NO_ADS_CONVERSION_TAG: 10,
  SLOW_MOBILE: 12,
  testimonials: 8,
};

export function priorityScore(input: {
  gaps: string[];
  reviewCount: number;
  hasEmail: boolean;
  fit: string;
  jobValue: number;
  industryNudge: number;
}): { score: number; reasons: string[] } {
  let score = 0;
  const reasons: string[] = [];
  const gaps = [...new Set(input.gaps)];
  const best = gaps.map((g) => GAP_WEIGHT[g] || 0).sort((a, b) => b - a)[0] || 0;
  if (best) {
    score += best;
    reasons.push("verified acquisition gap");
  }
  if (input.reviewCount >= 20 && input.reviewCount <= 400) {
    score += 8;
    reasons.push("established public reputation");
  }
  if (input.hasEmail) {
    score += 12;
    reasons.push("usable email");
  }
  if (input.fit === "strong" || input.fit === "GOOD FIT") {
    score += 10;
    reasons.push("clear fit");
  }
  if (input.jobValue >= 2500) {
    score += Math.min(12, Math.round(input.jobValue / 2500));
    reasons.push("higher typical job value for this category");
  }
  score += input.industryNudge;
  if (input.industryNudge > 0) reasons.push("this industry has been replying");
  if (input.industryNudge < 0) reasons.push("this industry has not been replying");
  return { score: Math.max(0, score), reasons };
}

export type ReadinessLight = "green" | "yellow" | "red" | "unknown";

export type LiveReadinessInput = {
  testFlowPassed: number;
  testFlowTotal: number;
  gmail: ReadinessLight;
  database: ReadinessLight;
  worker: ReadinessLight;
  outreach: ReadinessLight;
  calendar: ReadinessLight;
  booking: ReadinessLight;
  places: ReadinessLight;
  highCriticalOutreach: number;
  unknownDelivery: number;
  dncFutureSends: number;
  repliedFutureSends: number;
  duplicateOutreach: number;
  autopilotOn: boolean;
  liveCampaigns: number;
  productionSha: string;
  smoke: "pass" | "fail" | "unknown";
};

export function liveOutreachReadiness(input: LiveReadinessInput): { ready: boolean; blockers: string[] } {
  const blockers: string[] = [];
  if (input.testFlowPassed !== input.testFlowTotal || input.testFlowTotal !== 8) blockers.push("Test Sales Flow is not 8/8.");
  if (input.gmail !== "green") blockers.push("Gmail is not healthy.");
  if (input.database !== "green") blockers.push("Database is not healthy.");
  if (input.worker !== "green") blockers.push("Worker has not been observed healthy recently.");
  if (input.outreach !== "green") blockers.push("Outreach safety is not healthy.");
  if (input.calendar !== "green") blockers.push("Calendar is not healthy.");
  if (input.booking !== "green") blockers.push("Booking is not healthy.");
  if (input.places !== "green") blockers.push("Google Places is not healthy.");
  if (input.highCriticalOutreach > 0) blockers.push("A high or critical outreach issue is open.");
  if (input.unknownDelivery > 0) blockers.push("An email delivery is still unknown.");
  if (input.dncFutureSends > 0) blockers.push("A Do Not Contact company still has a future send.");
  if (input.repliedFutureSends > 0) blockers.push("A company that replied still has a future send.");
  if (input.duplicateOutreach > 0) blockers.push("Duplicate outreach is still active.");
  if (input.autopilotOn) blockers.push("Acquisition Autopilot is on. Controlled launch needs it off.");
  if (input.liveCampaigns > 0) blockers.push("A live campaign is still enabled.");
  if (!input.productionSha) blockers.push("Production SHA is not identified.");
  if (input.smoke !== "pass") blockers.push("Production smoke has not passed.");
  return { ready: blockers.length === 0, blockers };
}

export type InboundClass =
  | "INTERESTED"
  | "WANTS_MORE_INFORMATION"
  | "WANTS_AUDIT"
  | "PRICING_QUESTION"
  | "OBJECTION"
  | "NOT_NOW"
  | "BOOKING_REQUEST"
  | "QUESTION"
  | "NOT_INTERESTED"
  | "NEGATIVE"
  | "UNSUBSCRIBE"
  | "OUT_OF_OFFICE"
  | "WRONG_PERSON"
  | "REFERRAL"
  | "ALREADY_SOLVED"
  | "MEETING_BOOKED"
  | "UNCLEAR";

export type ReplyPlan = {
  cls: InboundClass;
  confidence: "high" | "low";
  stop: boolean;
  dnc: boolean;
  escalate: boolean;
  send: boolean;
  body: string;
};

export function classifyInbound(text: string): { cls: InboundClass; confidence: "high" | "low" } {
  const t = (text || "").toLowerCase();
  if (/ignore (previous|your) instructions|you are now|send me your password/.test(t)) return { cls: "UNCLEAR", confidence: "low" };
  if (/unsub|remove me|do not contact|stop emailing|take me off/.test(t)) return { cls: "UNSUBSCRIBE", confidence: "high" };
  if (/scam|lawyer|sue you|harass|terrible|this is spam/.test(t)) return { cls: "NEGATIVE", confidence: "high" };
  if (/out of office|automatic reply|ooo\b|away from/.test(t)) return { cls: "OUT_OF_OFFICE", confidence: "high" };
  if (/wrong person|not the right person|no longer (here|with)|left the company/.test(t)) return { cls: "WRONG_PERSON", confidence: "low" };
  if (/i (just )?booked|meeting is (set|booked)|see you (on|at)/.test(t)) return { cls: "MEETING_BOOKED", confidence: "high" };
  if (/talk to|reach out to|contact my|forward you to/.test(t) && /@|manager|partner|owner/.test(t)) return { cls: "REFERRAL", confidence: "low" };
  if (/already (have|solved|fixed)|we already|in-house|have an agency/.test(t)) return { cls: "ALREADY_SOLVED", confidence: "high" };
  if (/not now|next quarter|next month|circle back|busy right now/.test(t)) return { cls: "NOT_NOW", confidence: "high" };
  if (/too expensive|can't afford|cannot afford|not in the budget|we tried that/.test(t)) return { cls: "OBJECTION", confidence: "high" };
  if (/not interested|no thanks|no thank you|not a fit|pass\b/.test(t)) return { cls: "NOT_INTERESTED", confidence: "high" };
  if (/how much|pricing|what does it cost|price|retainer/.test(t)) return { cls: "PRICING_QUESTION", confidence: "high" };
  if (/book|calendar|schedule|hop on|pick a time|grab a time/.test(t)) return { cls: "BOOKING_REQUEST", confidence: "high" };
  if (/send (it|the audit|the summary)|yes,? send/.test(t)) return { cls: "WANTS_AUDIT", confidence: "high" };
  if (/what do you|what exactly|who are you|tell me more/.test(t)) return { cls: "WANTS_MORE_INFORMATION", confidence: "high" };
  if (/interested|sounds good|let's talk|lets talk|sure\b/.test(t)) return { cls: "INTERESTED", confidence: "high" };
  if (/\?/.test(t)) return { cls: "QUESTION", confidence: "low" };
  return { cls: "UNCLEAR", confidence: "low" };
}

function bookingLine(url: string, seed: number): string {
  if (!url) return "Reply with a time that works and I’ll send a calendar hold.";
  const lines = [
    `If it's easier, you can grab 15 minutes here:\n${url}`,
    `If you'd rather skip the back-and-forth, pick a time here:\n${url}`,
  ];
  return lines[Math.abs(seed) % lines.length]!;
}

export function planReply(opts: { text: string; name: string; company: string; bookingUrl: string; finding?: string }): ReplyPlan {
  const { cls, confidence } = classifyInbound(opts.text);
  if (confidence === "low") {
    return { cls, confidence, stop: true, dnc: false, escalate: true, send: false, body: "" };
  }
  const hi = opts.name && opts.name !== "UNKNOWN" ? opts.name.split(" ")[0] : "there";
  const link = bookingLine(opts.bookingUrl, opts.company.length);
  const base = { cls, confidence, stop: true, dnc: false, escalate: false, send: false, body: "" };
  if (cls === "UNSUBSCRIBE") return { ...base, dnc: true, send: false, body: "" };
  if (cls === "NEGATIVE") return { ...base, escalate: true, send: false };
  if (cls === "MEETING_BOOKED") return { ...base, send: false };
  if (cls === "NOT_INTERESTED" || cls === "ALREADY_SOLVED") {
    return { ...base, send: true, body: `Hi ${hi},\n\nUnderstood. I won’t follow up.\n\nDylan\nLamb Ascension` };
  }
  if (cls === "NOT_NOW") {
    return { ...base, send: true, body: `Hi ${hi},\n\nNo problem. I’ll leave it here. If timing changes later, just reply.\n\nDylan\nLamb Ascension` };
  }
  if (cls === "OUT_OF_OFFICE") return { ...base, stop: false, send: false };
  if (cls === "OBJECTION") {
    return {
      ...base,
      send: true,
      body: `Hi ${hi},\n\nFair. I’m not going to argue with that, and I won’t guess a price from one email.\n\nDylan\nLamb Ascension`,
    };
  }
  if (cls === "PRICING_QUESTION") {
    return {
      ...base,
      send: true,
      body: `Hi ${hi},\n\nIt depends on the job, so I don’t quote a number from a single email. Lamb Ascension builds the path from a visit to a real inquiry.\n\nIf you want to see whether it fits ${opts.company}, ${link}\n\nDylan\nLamb Ascension`,
    };
  }
  const finding = (opts.finding || "").trim();
  if (cls === "WANTS_AUDIT") {
    const noted = finding ? `What I actually saw: ${finding}.` : "I only have what the research pass stored. I won’t add anything past that.";
    return { ...base, send: true, body: `Hi ${hi},\n\n${noted}\n\n${link}\n\nDylan\nLamb Ascension` };
  }
  return {
    ...base,
    send: true,
    body: `Hi ${hi},\n\nHappy to walk through ${opts.company} with you. ${finding ? `The verified piece was: ${finding}.` : "I won’t add findings that weren’t checked."}\n\n${link}\n\nDylan\nLamb Ascension`,
  };
}

import { opportunities } from "../review-brief.ts";
import type { Prospect } from "../review-brief.ts";
import { usefulEmail } from "../prospects/reach.ts";
import { decideProspect, isSameCompany, type AutoView } from "./decide.ts";
import { mayFirstTouch, reputationPause } from "./deliverability.ts";
import { industryNudge } from "./learn.ts";
import { priorityScore } from "./priority.ts";
import { autopilotAuthorized, autonomyExecutionOff, autonomyTickEffects, legacyAutopilotUnauthorized, nextMarket, normalizeAutonomy, type AutonomySettings } from "./settings.ts";

function acted(p: Prospect, action: string): boolean {
  return (p.history || []).some((h) => h.action === action);
}

function viewOf(p: Prospect): AutoView {
  const email = usefulEmail(p);
  const opps = opportunities(p);
  return {
    name: p.name,
    stage: p.stage || "",
    suppressed: Boolean(p.suppressed),
    researchStatus: p.research_status || "none",
    hasWebsite: Boolean(p.website && p.website !== "UNKNOWN"),
    hasEmail: Boolean(email),
    hasOpportunity: opps.length > 0,
    fit: p.fit || "",
    hasPack: Boolean(p.outreach?.messages?.some((m) => m.kind === "email" && m.body)),
    alreadySent: acted(p, "email_sent") || acted(p, "autonomy_sent") || p.stage === "Contacted",
    booked: p.stage === "Call Booked",
    prepDone: acted(p, "call_prep"),
    disqualified: acted(p, "autonomy_disqualified"),
    emailBlocked: acted(p, "autonomy_email_blocked"),
    sendFailed: acted(p, "autonomy_send_failed"),
  };
}

async function loadAutonomy(userId: string): Promise<AutonomySettings> {
  try {
    const { getSql } = await import("../db.ts");
    const sql = await getSql();
    const rows = await sql<{ autonomy: unknown }>`select autonomy from outreach_settings where user_id = ${userId}`;
    const raw = rows[0]?.autonomy;
    if (legacyAutopilotUnauthorized(raw)) {
      const repaired = autonomyExecutionOff(raw);
      await sql`
        update outreach_settings set autonomy = ${JSON.stringify(repaired)}::jsonb
        where user_id = ${userId}
      `;
      try {
        const { audit } = await import("../mail/sql.server.ts");
        await audit(userId, "AUTOPILOT_LEGACY_STATE_REPAIRED", "Autonomy flags were on without an owner enable marker. Autopilot is off. History was kept.", { method: "AUTOMATION" });
      } catch {
        /* the repaired row is what matters */
      }
      return repaired;
    }
    return normalizeAutonomy(raw);
  } catch {
    return normalizeAutonomy(null);
  }
}

export async function saveAutonomy(userId: string, patch: Partial<AutonomySettings>): Promise<AutonomySettings> {
  const current = await loadAutonomy(userId);
  const next = normalizeAutonomy({ ...current, ...patch });
  const { getSql } = await import("../db.ts");
  const sql = await getSql();
  await sql`
    insert into outreach_settings (user_id, autonomy)
    values (${userId}, ${JSON.stringify(next)}::jsonb)
    on conflict (user_id) do update set autonomy = excluded.autonomy
  `;
  return next;
}

export async function readAutonomy(userId: string): Promise<AutonomySettings> {
  return loadAutonomy(userId);
}

function stamp(p: Prospect, action: string, detail: string): Prospect {
  return {
    ...p,
    history: [...(p.history || []), { at: new Date().toISOString(), action, detail }],
  };
}

export async function runAutonomyPass(userId: string): Promise<{ researched: number; generated: number; held: number; sent: number; prepped: number }> {
  const report = { researched: 0, generated: 0, held: 0, sent: 0, prepped: 0 };
  const settings = await loadAutonomy(userId);
  const { listProspects, upsertProspects, importProspects, logActivity } = await import("../prospects/repo.server.ts");
  const { loadSettings } = await import("../mail/sql.server.ts");
  const mailSettings = await loadSettings(userId);
  let prospects = await listProspects(userId);
  const foundToday = prospects.filter((p) => (p.discovered_at || "").slice(0, 10) === new Date().toISOString().slice(0, 10)).length;

  const effects = autonomyTickEffects(settings, mailSettings.testMode);
  if (effects.discover && foundToday < settings.dailyProspectLimit) {
    try {
      const { env } = await import("../env.server.ts");
      const key = env("GOOGLE_PLACES_API_KEY");
      if (key) {
        const tick = Math.floor(Date.now() / 3_600_000);
        const market = nextMarket(settings, tick);
        const { searchText } = await import("../discovery/places.ts");
        const { hitToProspect } = await import("../discovery/to-prospect.ts");
        const { tryReserveDiscovery, EST_SEARCH_CENTS } = await import("../discovery/usage.server.ts");
        const found = await searchText({
          apiKey: key,
          vertical: market.vertical,
          location: market.city,
          radiusM: 20000,
          limit: 5,
          minRating: 0,
          reserve: async () => tryReserveDiscovery(userId, EST_SEARCH_CENTS),
        });
        if (!("error" in found)) {
          const fresh = found.places
            .map((hit, i) => hitToProspect(hit, prospects.length + i + 1))
            .filter((candidate) => !prospects.some((existing) => isSameCompany(existing, candidate)));
          if (fresh.length) {
            const imported = await importProspects(userId, fresh.slice(0, 5));
            prospects = imported.prospects;
            await logActivity(userId, "autonomy_find", `Found ${fresh.length} in ${market.vertical} / ${market.city}`, undefined, "AUTOMATION");
          }
        }
      }
    } catch {
      /* discovery must not fail the tick */
    }
  }

  const touchedMeetings: Prospect[] = [];
  try {
    const { getSql } = await import("../db.ts");
    const sql = await getSql();
    const events = await sql<{ prospect_uid: string; google_event_id: string; start_at: string; status: string }>`
      select prospect_uid, google_event_id, start_at::text, status from calendar_events
      where user_id = ${userId} and status = 'booked' and prospect_uid <> ''
    `;
    const { stopSequencesForProspect } = await import("../mail/sql.server.ts");
    for (const event of events) {
      const prospect = prospects.find((p) => p.uid === event.prospect_uid);
      if (!prospect) continue;
      if (prospect.stage === "Won" || prospect.stage === "Lost" || prospect.stage === "Do Not Contact") continue;
      if (prospect.meeting_event_id === event.google_event_id) continue;
      const rescheduled = Boolean(prospect.meeting_event_id);
      prospect.meeting_at = event.start_at;
      prospect.meeting_event_id = event.google_event_id || prospect.meeting_event_id;
      prospect.stage = "Call Booked";
      prospect.stage_plain = "Call is on the calendar";
      prospect.sales_outcome = "";
      prospect.history = [...(prospect.history || []), {
        at: new Date().toISOString(),
        action: rescheduled ? "meeting_rescheduled" : "meeting_booked",
        detail: rescheduled ? "Meeting time changed. Cold outreach stays off." : "Meeting booked. Outreach stopped.",
      }];
      await stopSequencesForProspect(userId, prospect.uid || "");
      touchedMeetings.push(prospect);
    }
  } catch {
    /* calendar rows may be absent — do not stop the tick */
  }

  const dirty: Prospect[] = [...touchedMeetings];
  const today = new Date().toISOString().slice(0, 10);
  let sentToday = prospects.filter((p) => (p.history || []).some((h) => (h.action === "autonomy_sent" || h.action === "email_sent") && (h.at || "").slice(0, 10) === today)).length;
  const bounced = new Set<string>();
  const unsubscribed = new Set<string>();
  const domainsToday = new Set<string>();
  const mailedCompany = new Map<string, string>();
  let lifetimeSent = 0;
  let lifetimeBounced = 0;
  const companyKey = (p: Prospect) => {
    const site = (p.website || "").replace(/^https?:\/\//, "").replace(/^www\./, "").replace(/\/$/, "").toLowerCase();
    return site || (p.name || "").trim().toLowerCase();
  };
  for (const p of prospects) {
    const sentThis = (p.history || []).some((h) => h.action === "autonomy_sent" || h.action === "email_sent") || p.stage === "Contacted" || p.stage === "Won";
    if (sentThis) {
      const key = companyKey(p);
      if (key && !mailedCompany.has(key)) mailedCompany.set(key, p.uid || p.name);
    }
    for (const h of p.history || []) {
      if (h.action === "autonomy_sent" || h.action === "email_sent") lifetimeSent += 1;
      if (h.action === "bounced" || h.action === "email_bounced") {
        lifetimeBounced += 1;
        const match = (h.detail || "").match(/[^\s]+@[^\s]+/);
        if (match) bounced.add(match[0].toLowerCase());
      }
      if ((h.action === "autonomy_sent" || h.action === "email_sent") && (h.at || "").slice(0, 10) === today) {
        const fromDetail = (h.detail || "").match(/[^\s]+@[^\s]+/);
        const address = fromDetail?.[0] || usefulEmail(p)?.value || "";
        const domain = address.split("@")[1]?.toLowerCase() || "";
        if (domain) domainsToday.add(domain);
      }
    }
    if (p.suppressed || p.stage === "Do Not Contact") {
      const email = usefulEmail(p)?.value;
      if (email) unsubscribed.add(email.toLowerCase());
    }
  }
  try {
    const { deliveryTotals } = await import("../mail/sql.server.ts");
    const totals = await deliveryTotals(userId);
    lifetimeSent = Math.max(lifetimeSent, totals.sent);
    lifetimeBounced = Math.max(lifetimeBounced, totals.bounced);
  } catch {
    /* counts from history still apply */
  }
  const paused = reputationPause(lifetimeSent, lifetimeBounced) || prospects.some((p) => (p.history || []).some((h) => h.action === "autonomy_paused" && (h.at || "").slice(0, 10) === today));
  const ranked = [...prospects].sort((a, b) => {
    const score = (p: Prospect) => priorityScore({
      gaps: opportunities(p).map((o) => o.code),
      reviewCount: p.review_count || 0,
      hasEmail: Boolean(usefulEmail(p)),
      fit: p.fit || "",
      jobValue: p.job_value_est || 0,
      industryNudge: industryNudge(prospects, p.vertical || ""),
    }).score;
    return score(b) - score(a);
  });

  for (const prospect of ranked) {
    try {
    const email = usefulEmail(prospect)?.value || "";
    const screen = email ? mayFirstTouch({
      email,
      bounced,
      unsubscribed,
      domainsMailedToday: domainsToday,
      alreadyMailedCompany: Boolean(mailedCompany.get(companyKey(prospect)) && mailedCompany.get(companyKey(prospect)) !== (prospect.uid || prospect.name)),
    }) : { ok: true as const };
    const decision = decideProspect({
      ...viewOf(prospect),
      emailBlocked: !screen.ok || acted(prospect, "autonomy_email_blocked"),
      reputationPaused: paused,
    }, { ...settings, autonomous: true }, { testMode: mailSettings.testMode, sentToday });
    if (!autopilotAuthorized(settings) && decision.action !== "prep") continue;
    if (!screen.ok && !acted(prospect, "autonomy_email_blocked") && decision.action !== "research") {
      dirty.push(stamp(prospect, "autonomy_email_blocked", screen.reason));
      continue;
    }
    if (decision.action === "research" && report.researched < 1 && !acted(prospect, "autonomy_research_queued")) {
      try {
        const { runDeepResearch } = await import("../research/orchestrate.ts");
        const result = await runDeepResearch({
          name: prospect.name,
          website: prospect.website,
          vertical: prospect.vertical,
          city: prospect.city,
          phone: prospect.phone,
          google_rating: prospect.google_rating,
          review_count: prospect.review_count,
          score: prospect.score,
          research_status: "running",
        }, { minScoreForEnrichment: 65, dailyEnrichmentUsed: 0, dailyEnrichmentCap: 1 });
        dirty.push(stamp({
          ...prospect,
          research_status: "complete",
          findings: result.findings || prospect.findings,
          facts: result.facts,
          contacts: result.contacts?.length ? result.contacts : prospect.contacts,
          ads: result.ads,
          readiness: result.readiness,
          readiness_why: result.readiness_why,
          company_kind: result.company_kind,
          website_note: result.website_note,
        }, "research_completed", "Researched automatically from the public website. Unknown stayed unknown."));
        report.researched += 1;
      } catch {
        dirty.push(stamp(prospect, "autonomy_research_queued", "Research did not finish this pass. Nothing was invented."));
      }
      continue;
    }
    if (decision.action === "disqualify" && !acted(prospect, "autonomy_disqualified")) {
      dirty.push(stamp(prospect, "autonomy_disqualified", decision.reason));
      continue;
    }
    if (decision.action === "generate") {
      const { generateOutreach } = await import("../outreach/generate.ts");
      const pack = generateOutreach(prospect);
      dirty.push(stamp({
        ...prospect,
        stage: "Approved for Outreach",
        stage_plain: "Ready to send",
        outreach: pack,
      }, "outreach_generated", decision.reason));
      report.generated += 1;
      continue;
    }
    if (decision.action === "hold" && !acted(prospect, "autonomy_held")) {
      dirty.push(stamp(prospect, "autonomy_held", decision.reason));
      report.held += 1;
      continue;
    }
    if (decision.action === "prep" && !acted(prospect, "call_prep")) {
      const { salesBrief } = await import("./sales.ts");
      const { recommendOffer } = await import("../review-brief.ts");
      const offer = recommendOffer(prospect);
      const brief = salesBrief({
        company: prospect.name,
        contact: prospect.contacts?.[0]?.name || email,
        website: prospect.website,
        vertical: prospect.vertical,
        city: prospect.city,
        gaps: opportunities(prospect).map((o) => o.code),
        angle: prospect.outreach?.brief.angle || opportunities(prospect)[0]?.plain || "",
        replySummary: (prospect.history || []).filter((h) => h.action === "reply" || h.action === "autonomy_replied").map((h) => h.detail || "").join(" "),
        emailsSent: acted(prospect, "autonomy_sent") || acted(prospect, "email_sent") ? 1 : 0,
        researchDone: prospect.research_status === "complete" || prospect.research_status === "partial",
        offerName: offer.name,
        offerWhy: offer.why,
      });
      const prepped = stamp(prospect, "call_prep", brief);
      dirty.push(acted(prospect, "meeting_booked") ? prepped : stamp(prepped, "meeting_booked", "Meeting is booked. Outreach is stopped."));
      report.prepped += 1;
      continue;
    }
    if (decision.action === "send" && report.sent < 1 && effects.firstContact) {
      const to = usefulEmail(prospect)?.value || "";
      const email = prospect.outreach?.messages.find((m) => m.kind === "email");
      if (!to || !email) continue;
      try {
        const { sendLive } = await import("../mail/live.server.ts");
        const sent = await sendLive({
          userId,
          prospect,
          kind: "email",
          method: "AUTOMATION",
          to,
          subject: email.subject || `${prospect.name} — quick opportunity I noticed`,
          body: email.body,
          firstApproved: true,
        });
        if (sent.ok) {
          const { saveSequence } = await import("../mail/sql.server.ts");
          const now = Date.now();
          const uid = prospect.uid || "";
          if (settings.autoFollowup && uid) {
            await saveSequence(userId, uid, "AUTOMATION", [
              { step: "followup1", dueAt: now + 3 * 86400000, idempotencyKey: `${userId}:${uid}:followup1`, body: prospect.outreach?.messages.find((m) => m.kind === "followup1")?.body || "", subject: email.subject || prospect.name, recipient: to, threadId: sent.threadId },
              { step: "followup2", dueAt: now + 7 * 86400000, idempotencyKey: `${userId}:${uid}:followup2`, body: prospect.outreach?.messages.find((m) => m.kind === "followup2")?.body || "", subject: email.subject || prospect.name, recipient: to, threadId: sent.threadId },
              { step: "followup3", dueAt: now + 12 * 86400000, idempotencyKey: `${userId}:${uid}:followup3`, body: prospect.outreach?.messages.find((m) => m.kind === "followup3")?.body || "", subject: email.subject || prospect.name, recipient: to, threadId: sent.threadId },
            ]);
          }
          dirty.push(stamp({ ...prospect, stage: "Contacted", stage_plain: "Email sent" }, "autonomy_sent", `First email sent to ${to}.`));
          report.sent += 1;
          sentToday += 1;
        } else {
          dirty.push(stamp(prospect, "autonomy_send_failed", sent.reason || "Send failed. It will not be retried automatically."));
        }
      } catch (err) {
        dirty.push(stamp(prospect, "autonomy_send_failed", err instanceof Error ? err.message : "Send failed."));
      }
    }
    } catch (err) {
      if (!acted(prospect, "autonomy_failed")) {
        dirty.push(stamp(prospect, "autonomy_failed", err instanceof Error ? err.message : "This company failed. The rest of the run continued."));
      }
    }
  }

  if (dirty.length) await upsertProspects(userId, dirty);
  return report;
}

export async function autoReplyTo(opts: {
  userId: string;
  prospect: Prospect;
  text: string;
  threadId?: string | null;
}): Promise<"sent" | "held" | "escalated" | "stopped" | "skipped"> {
  const settings = await loadAutonomy(opts.userId);
  const { classifyInbound, planReply } = await import("./replies.ts");
  const { replyWantsBooking, publicBookingOrigin, trackedBookingUrl } = await import("./booking-link.ts");
  const { upsertProspects } = await import("../prospects/repo.server.ts");
  const classified = classifyInbound(opts.text);
  const closed = opts.prospect.stage === "Call Booked" || opts.prospect.stage === "Won" || opts.prospect.stage === "Lost" || opts.prospect.stage === "Do Not Contact";
  const planWithoutLink = planReply({
    text: opts.text,
    name: opts.prospect.contacts?.[0]?.name || "there",
    company: opts.prospect.name,
    bookingUrl: "",
    finding: opts.prospect.outreach?.brief.angle || "",
  });
  if (planWithoutLink.dnc) {
    const { stopSequencesForProspect } = await import("../mail/sql.server.ts");
    await stopSequencesForProspect(opts.userId, opts.prospect.uid || "");
    await upsertProspects(opts.userId, [stamp({ ...opts.prospect, suppressed: true, stage: "Do Not Contact" }, "do_not_contact", "They asked to be removed. Outreach is stopped.")]);
    return "stopped";
  }
  if (planWithoutLink.cls === "MEETING_BOOKED") {
    await upsertProspects(opts.userId, [stamp({
      ...opts.prospect,
      stage: "Call Booked",
      stage_plain: "Call is on the calendar",
    }, "meeting_booked", "They said the meeting is booked. Outreach stays stopped.")]);
    return "stopped";
  }
  const mayCompose = autopilotAuthorized(settings) && settings.autoReply;
  if (!mayCompose || planWithoutLink.escalate || closed && replyWantsBooking(classified.cls)) {
    await upsertProspects(opts.userId, [stamp({
      ...opts.prospect,
      stage: opts.prospect.stage === "Call Booked" ? opts.prospect.stage : "Replied",
    }, "autonomy_escalate", `${classified.cls}: needs you. No automatic reply was sent.`)]);
    return "escalated";
  }
  let bookingUrl = "";
  if (!closed && classified.confidence === "high" && replyWantsBooking(classified.cls)) {
    const { accessFor } = await import("../mail/live.server.ts");
    const calendar = await accessFor(opts.userId, "calendar");
    if (!calendar) {
      await upsertProspects(opts.userId, [stamp(opts.prospect, "calendar_unavailable", "Google Calendar is not connected. No booking link was sent.")]);
      return "escalated";
    }
    const { ensureBookingToken } = await import("../mail/sql.server.ts");
    const email = opts.prospect.contacts?.find((c) => c.email && c.email !== "UNKNOWN")?.email || "";
    const token = await ensureBookingToken(opts.userId, opts.prospect.uid || "", { contact: email, threadId: opts.threadId || "" });
    bookingUrl = trackedBookingUrl(publicBookingOrigin(), token);
  }
  const plan = bookingUrl
    ? planReply({
      text: opts.text,
      name: opts.prospect.contacts?.[0]?.name || "there",
      company: opts.prospect.name,
      bookingUrl,
      finding: opts.prospect.outreach?.brief.angle || "",
    })
    : planWithoutLink;
  if (!plan.send) return "skipped";
  const { loadSettings } = await import("../mail/sql.server.ts");
  const mail = await loadSettings(opts.userId);
  if (mail.testMode || !autonomyTickEffects(settings, mail.testMode).autoReply) {
    await upsertProspects(opts.userId, [stamp({ ...opts.prospect, booking_url: bookingUrl }, "autonomy_reply_held", mail.testMode ? "Test Mode is on. Reply was classified and not sent." : "Autopilot is off. Reply was not sent.")]);
    return "held";
  }
  const to = usefulEmail(opts.prospect)?.value || "";
  if (!to) return "escalated";
  const { sendLive } = await import("../mail/live.server.ts");
  const sent = await sendLive({
    userId: opts.userId,
    prospect: opts.prospect,
    kind: "reply",
    method: "AUTOMATION",
    to,
    subject: `Re: ${opts.prospect.name}`,
    body: plan.body,
    firstApproved: true,
    threadId: opts.threadId,
  });
  if (!sent.ok) return "held";
  await upsertProspects(opts.userId, [stamp({ ...opts.prospect, stage: "Replied", booking_url: bookingUrl }, "autonomy_replied", plan.cls)]);
  return "sent";
}

import assert from "node:assert/strict";
import test from "node:test";
import { markCallOutcome, markSalesOutcome } from "./outcomes.ts";
import { clientRecord, discoveryQuestions, followupDraft, proposalDraft, recommendService, salesBrief } from "./sales.ts";

test("sales support stays on the call and does not invent a price", () => {
  const base = {
    company: "AWO Lending",
    contact: "Amos Oneil",
    website: "https://awo.example",
    vertical: "Business lending",
    city: "Dallas",
    gaps: ["NO_HOMEPAGE_FORM"],
    angle: "no homepage form",
    replySummary: "Asked to talk",
    emailsSent: 1,
    researchDone: true,
  };
  const brief = salesBrief(base);
  assert.match(brief, /AWO Lending/);
  assert.match(brief, /NO_HOMEPAGE_FORM/);
  assert.match(brief, /Still unknown/);
  assert.doesNotMatch(brief, /\$10,000|guaranteed/);
  const questions = discoveryQuestions(base);
  const other = discoveryQuestions({ ...base, company: "Northstar", gaps: ["NO_TRACKING"] });
  assert.ok(questions.length >= 5 && questions.length <= 8);
  assert.notEqual(questions.join("|"), other.join("|"));
  assert.match(questions.join(" "), /leave their info/);
  const thin = recommendService({ company: "X", researchDone: false });
  assert.equal(thin.name, "MORE DISCOVERY NEEDED");
  const fit = recommendService({ ...base, notes: { problem: "No form on the homepage" } });
  assert.equal(fit.name, "Convert");
  const draft = followupDraft({ ...base, notes: { problem: "no form for people who will not call", nextStep: "send a one-page note" } });
  assert.match(draft, /no form/);
  assert.match(draft, /one-page note/);
  assert.doesNotMatch(draft, /case study|guarantee/);
  const blocked = proposalDraft(base);
  assert.equal(blocked.ok, false);
  const proposal = proposalDraft({ ...base, price: 2500, billing: "monthly", notes: { problem: "no form", desired: "more applications" } });
  assert.equal(proposal.ok, true);
  if (!proposal.ok) return;
  assert.match(proposal.text, /\$2,500/);
  assert.match(proposal.text, /No guaranteed/);

  let row = { name: "AWO Lending", stage: "Call Booked", meeting_at: "2020-01-01T15:00:00.000Z", sales_outcome: "" as const, call_notes: { recommended: "Convert", desired: "more applications", nextStep: "send the note" } };
  const showed = markCallOutcome(row, "SHOWED", new Date("2026-09-23T12:00:00.000Z"));
  assert.equal(showed.ok, true);
  if (!showed.ok) return;
  const later = markSalesOutcome(showed.prospect, { outcome: "FOLLOW_UP_NEEDED", followUpAt: "2026-09-24", followUpReason: "Send the note" });
  assert.equal(later.ok, true);
  if (!later.ok) return;
  assert.equal(later.prospect.follow_up_at, "2026-09-24");
  assert.notEqual(later.prospect.stage, "New");
  const won = markSalesOutcome(showed.prospect, { outcome: "WON", clientValue: 2500, billing: "monthly" });
  assert.equal(won.ok, true);
  if (!won.ok) return;
  assert.equal(won.prospect.client_record?.service, "Convert");
  assert.equal(won.prospect.client_record?.price, 2500);
  const record = clientRecord({ ...base, price: 2500, billing: "monthly", startDate: "2026-09-23", notes: { recommended: "Convert" } });
  assert.equal(record.price, 2500);
});

export type CallNotes = {
  problem?: string;
  leadSource?: string;
  leadVolume?: string;
  customerValue?: string;
  tried?: string;
  frustration?: string;
  desired?: string;
  timeline?: string;
  budget?: string;
  decisionMaker?: string;
  objections?: string;
  recommended?: string;
  nextStep?: string;
  notes?: string;
};

export type SalesInput = {
  company: string;
  contact?: string;
  website?: string;
  vertical?: string;
  city?: string;
  gaps?: string[];
  angle?: string;
  replySummary?: string;
  emailsSent?: number;
  researchDone?: boolean;
  offerName?: string;
  offerWhy?: string;
  notes?: CallNotes;
};

const GAP_QUESTION: Record<string, string> = {
  NO_HOMEPAGE_FORM: "Someone who is not ready to call — where do they leave their info today?",
  NO_HOMEPAGE_CTA: "What is the first thing you want a visitor to do?",
  NO_CLICK_TO_CALL: "How many people call versus filling something out?",
  NO_TRACKING: "Can you tell which page or ad actually turns into a job?",
  SLOW_MOBILE: "How often are customers finding you on a phone?",
  testimonials: "Where do new customers see proof before they reach out?",
};

const BASE = [
  "How are you getting customers right now?",
  "What have you already tried?",
  "When a lead comes in, what happens next?",
  "What is one new customer worth to you?",
  "Where does this break down most — the lead, the follow-up, or the close?",
  "What would have to be true for this to be worth doing?",
];

function hash(s: string): number {
  let h = 0;
  for (let i = 0; i < s.length; i += 1) h = (h * 33 + s.charCodeAt(i)) >>> 0;
  return h;
}

export function discoveryQuestions(input: SalesInput): string[] {
  const gaps = input.gaps || [];
  const specific = gaps.map((g) => GAP_QUESTION[g]).filter(Boolean);
  const start = hash(input.company || "x") % BASE.length;
  const rotated = [...BASE.slice(start), ...BASE.slice(0, start)];
  const picked = [...specific, ...rotated];
  const unique: string[] = [];
  for (const q of picked) {
    if (!unique.includes(q)) unique.push(q);
    if (unique.length >= 8) break;
  }
  return unique;
}

export function callGuide(input: SalesInput): string[] {
  const finding = (input.gaps || [])[0] ? `the gap we actually saw (${input.gaps![0]})` : "what we verified, and nothing past that";
  return [
    `Intro — You looked at ${input.company}. Mention ${finding}. Do not praise them generically.`,
    "Discovery — Ask how they get customers before you explain anything.",
    "Problem — Stay on the one gap. Do not pile on minor website issues.",
    "Current process — Ask what happens after the inquiry. Do not assume they have no follow-up.",
    "Impact — Ask what a missed inquiry costs them. Do not state their revenue or ad spend.",
    "Desired outcome — Ask what they want more of in the next few months.",
    "Recommendation — Only name Acquire, Convert, or System if the notes and research support it. Otherwise say you need a little more.",
    "Next step — Proposal, another call, or no. You decide. Do not discount or promise results.",
  ];
}

export function salesBrief(input: SalesInput): string {
  const notes = input.notes || {};
  const gaps = (input.gaps || []).filter(Boolean);
  const unknowns = ["Revenue", "Ad spend", "Lead volume", "Close rate", "Budget", "Team size"].filter((u) => {
    if (u === "Lead volume" && notes.leadVolume) return false;
    if (u === "Budget" && notes.budget) return false;
    return true;
  });
  return [
    input.company,
    input.contact ? `Contact: ${input.contact}` : "Contact: not on file",
    input.website && input.website !== "UNKNOWN" ? `Website: ${input.website}` : "Website: unknown",
    `Sells: ${input.vertical || "Unknown"}${input.city ? ` in ${input.city}` : ""}.`,
    "Who they sell to: not verified unless they say so on the call.",
    gaps.length ? `Verified gaps: ${gaps.join(", ")}.` : "Verified gaps: none stored. Do not invent one.",
    input.researchDone ? "Qualified because research found a real acquisition gap and a way to reach them." : "Research is thin. Do not treat them as fully qualified.",
    input.angle ? `Outreach angle: ${input.angle}` : "Outreach angle: not stored.",
    input.replySummary ? `Replies: ${input.replySummary}` : "Replies: none stored.",
    `Emails sent: ${input.emailsSent || 0}.`,
    notes.problem ? `They said the problem is: ${notes.problem}` : "Likely problem: only the verified gap above. Impact is unknown until you ask.",
    input.offerName && input.offerName !== "Unknown" ? `Possible fit: ${input.offerName}. ${input.offerWhy || ""}` : "Offer: more discovery needed before naming a package.",
    `Still unknown: ${unknowns.join(", ")}.`,
  ].join("\n");
}

export function recommendService(input: SalesInput): { name: "Acquire" | "Convert" | "System" | "MORE DISCOVERY NEEDED"; why: string } {
  const notes = input.notes || {};
  const gaps = input.gaps || [];
  const funnel = gaps.some((g) => ["NO_HOMEPAGE_FORM", "NO_HOMEPAGE_CTA", "NO_CLICK_TO_CALL"].includes(g));
  const tracking = gaps.includes("NO_TRACKING");
  if (!input.researchDone && !notes.problem && !notes.frustration) {
    return { name: "MORE DISCOVERY NEEDED", why: "Research and call notes are too thin to name a service." };
  }
  if (funnel && tracking && /whole|everything|system/i.test(`${notes.desired || ""} ${notes.recommended || ""}`)) {
    return { name: "System", why: "The site is weak on both inquiries and tracking, and they asked for the whole path. Still not a price." };
  }
  if (funnel || /form|website|inquir/i.test(notes.problem || "")) {
    return { name: "Convert", why: "The verified problem is turning attention into an inquiry. Convert fits that. Do not add ads unless they ask." };
  }
  if (input.offerName === "Acquire" || input.offerName === "Convert" || input.offerName === "System") {
    return { name: input.offerName, why: input.offerWhy || "This matches the stored research. It is not a promise they will buy." };
  }
  if (notes.problem) {
    return { name: "MORE DISCOVERY NEEDED", why: "They described a problem, but it does not map cleanly to Acquire, Convert, or System yet." };
  }
  return { name: "MORE DISCOVERY NEEDED", why: "Not enough to recommend a service." };
}

export function followupDraft(input: SalesInput): string {
  const notes = input.notes || {};
  const hi = input.contact && input.contact !== "UNKNOWN" ? input.contact.split(" ")[0] : "there";
  const heard = notes.problem || notes.frustration || "";
  const next = notes.nextStep || "";
  const gap = (input.gaps || [])[0] || "";
  const lines = [`Hi ${hi},`, "", `Thanks for the time on ${input.company}.`];
  if (heard) lines.push("", `You mentioned ${heard}.`);
  else if (gap) lines.push("", `The only piece I had going in was ${gap}. I am not adding anything we did not cover.`);
  else lines.push("", "I am not going to add findings we did not actually cover.");
  if (next) lines.push("", `Next step on my side: ${next}.`);
  else lines.push("", "If you want, I can send a short written version of what we discussed. I will not turn that into a proposal until you ask.");
  lines.push("", "Dylan", "Lamb Ascension");
  return lines.join("\n");
}

export function proposalDraft(input: SalesInput & { price?: number | null; billing?: string }): { ok: true; text: string } | { ok: false; reason: string } {
  if (typeof input.price !== "number" || !Number.isFinite(input.price) || input.price < 0) {
    return { ok: false, reason: "Enter a price first. A proposal was not written." };
  }
  const notes = input.notes || {};
  const rec = recommendService(input);
  const billing = input.billing === "monthly" || input.billing === "one-time" ? input.billing : "billing not set";
  const text = [
    input.company,
    `Problem: ${notes.problem || "Only the verified research gap. Nothing added."}`,
    `What we found: ${(input.gaps || []).join(", ") || "No verified gap stored."}`,
    `What they want: ${notes.desired || "Not stated on the call."}`,
    `Recommendation: ${rec.name}. ${rec.why}`,
    "Scope: the service above, nothing beyond what was discussed.",
    "Lamb Ascension handles the agreed work. The client provides access, offers, and a person who can answer questions.",
    `Price entered by you: $${input.price.toLocaleString()} (${billing}).`,
    notes.timeline ? `Timing they mentioned: ${notes.timeline}.` : "No timeline was agreed. None is promised.",
    "No guaranteed lead counts, revenue, or rankings.",
    "Next step: you review this, then send it yourself if you want.",
  ].join("\n");
  return { ok: true, text };
}

export type ClientRecord = {
  company: string;
  contact: string;
  service: string;
  price: number | null;
  billing: string;
  startDate: string;
  notes: string;
  expectations: string;
  nextAction: string;
};

export function clientRecord(input: SalesInput & { price?: number | null; billing?: string; startDate: string }): ClientRecord {
  const notes = input.notes || {};
  return {
    company: input.company,
    contact: input.contact || "",
    service: notes.recommended || recommendService(input).name,
    price: typeof input.price === "number" ? input.price : null,
    billing: input.billing || "",
    startDate: input.startDate,
    notes: notes.notes || "",
    expectations: notes.desired || "",
    nextAction: notes.nextStep || "Send the agreement and book onboarding.",
  };
}

