  if (filter === "sales") return events.filter((e) => e.sales || /\blamb ascension\b/i.test(e.title));
  if (filter === "personal") return events.filter((e) => !e.sales && !/\blamb ascension\b/i.test(e.title));
  if (filter === "test") return events.filter((e) => /\btest\b/i.test(e.title));
  return events;
}

export type CalView = "day" | "week" | "month";

const TZ = "America/Chicago";

function partsOf(d: Date) {
  const parts = new Intl.DateTimeFormat("en-US", {
    timeZone: TZ,
    year: "numeric",
    month: "2-digit",
    day: "2-digit",
    weekday: "short",
  }).formatToParts(d);
  const grab = (t: string) => parts.find((p) => p.type === t)?.value || "";
  return { y: grab("year"), m: grab("month"), d: grab("day"), w: grab("weekday") };
}

export function ymdInTz(d = new Date()): string {
  const p = partsOf(d);
  return `${p.y}-${p.m}-${p.d}`;
}

export function parseYmd(s: string): Date {
  const [y, m, d] = (s || "").split("-").map((n) => parseInt(n, 10));
  if (!y || !m || !d) return new Date();
  return new Date(y, m - 1, d, 12, 0, 0);
}

export function addDays(anchor: string, n: number): string {
  const d = parseYmd(anchor);
  d.setDate(d.getDate() + n);
  return ymdInTz(d);
}

export function addMonths(anchor: string, n: number): string {
  const d = parseYmd(anchor);
  d.setMonth(d.getMonth() + n);
  return ymdInTz(d);
}

export function startOfWeek(anchor: string): string {
  const d = parseYmd(anchor);
  d.setDate(d.getDate() - d.getDay());
  return ymdInTz(d);
}

export function shiftAnchor(view: CalView, anchor: string, dir: 1 | -1): string {
  if (view === "day") return addDays(anchor, dir);
  if (view === "month") return addMonths(anchor, dir);
  return addDays(startOfWeek(anchor), dir * 7);
}

export function rangeFor(view: CalView, anchor: string): { from: Date; to: Date; label: string; days: string[] } {
  if (view === "day") {
    const from = parseYmd(anchor);
    const to = new Date(from);
    to.setDate(to.getDate() + 1);
    return { from, to, label: formatLong(anchor), days: [anchor] };
  }
  if (view === "month") {
    const d = parseYmd(anchor);
    const from = new Date(d.getFullYear(), d.getMonth(), 1, 12);
    const to = new Date(d.getFullYear(), d.getMonth() + 1, 1, 12);
    const label = from.toLocaleDateString("en-US", { month: "long", year: "numeric" });
    const days: string[] = [];
    for (let x = new Date(from); x < to; x.setDate(x.getDate() + 1)) days.push(ymdInTz(x));
    return { from, to, label, days };
  }
  const start = startOfWeek(anchor);
  const from = parseYmd(start);
  const to = parseYmd(addDays(start, 7));
  const days = Array.from({ length: 7 }, (_, i) => addDays(start, i));
  const label = `${formatShort(days[0])} – ${formatShort(days[6])}`;
  return { from, to, label, days };
}

export function formatShort(anchor: string): string {
  const d = parseYmd(anchor);
  return d.toLocaleDateString("en-US", { month: "short", day: "numeric" });
}

export function formatLong(anchor: string): string {
  const d = parseYmd(anchor);
  return d.toLocaleDateString("en-US", { weekday: "long", month: "long", day: "numeric" });
}

export function formatTime(iso: string): string {
  const d = new Date(iso);
  if (Number.isNaN(d.getTime())) return "UNKNOWN";
  return d.toLocaleTimeString("en-US", { hour: "numeric", minute: "2-digit", timeZone: TZ });
}

export function hourOf(iso: string): number {
  const d = new Date(iso);
  if (Number.isNaN(d.getTime())) return -1;
  const h = new Intl.DateTimeFormat("en-US", { hour: "numeric", hour12: false, timeZone: TZ }).format(d);
  return parseInt(h, 10);
}

export function parseSpokenHour(raw: string): number | null {
  const t = (raw || "").toLowerCase();
  const m = t.match(/\b(\d{1,2})(?::(\d{2}))?\s*(a\.?m\.?|p\.?m\.?)?\b/);
  if (!m) return null;
  let h = parseInt(m[1], 10);
  if (h > 23) return null;
  const ap = (m[3] || "").replace(/\./g, "");
  if (ap.startsWith("p") && h < 12) h += 12;
  if (ap.startsWith("a") && h === 12) h = 0;
  if (!ap && h < 7) h += 12;
  return h;
}

export type Busy = { start: Date; end: Date };

function overlaps(a: Busy, b: Busy): boolean {
  return a.start < b.end && b.start < a.end;
}

export function labelSlot(start: Date, timezone = "America/Chicago"): string {
  try {
    const when = new Intl.DateTimeFormat("en-US", {
      timeZone: timezone,
      weekday: "long",
      hour: "numeric",
      minute: "2-digit",
    }).format(start);
    const zone = timezone === "America/Chicago" ? "CT" : timezone;
    return `${when} ${zone}`;
  } catch {
    return start.toUTCString();
  }
}

function zonedClock(date: Date, timeZone: string): { hour: number; weekday: number } {
  const parts = new Intl.DateTimeFormat("en-US", {
    timeZone,
    weekday: "short",
    hour: "2-digit",
    hourCycle: "h23",
  }).formatToParts(date);
  const hour = Number(parts.find((p) => p.type === "hour")?.value || "0");
  const name = parts.find((p) => p.type === "weekday")?.value || "Sun";
  const weekday = { Sun: 0, Mon: 1, Tue: 2, Wed: 3, Thu: 4, Fri: 5, Sat: 6 }[name] ?? date.getUTCDay();
  return { hour, weekday };
}

export function openSlots(opts: {
  from: Date;
  busy: Busy[];
  count?: number;
  durationMin?: number;
  timezone?: string;
  workStart?: number;
  workEnd?: number;
}): { start: Date; end: Date; label: string }[] {
  const duration = (opts.durationMin || 30) * 60 * 1000;
  const out: { start: Date; end: Date; label: string }[] = [];
  const cursor = new Date(opts.from);
  cursor.setMinutes(0, 0, 0);
  if (cursor.getMinutes() !== 0) cursor.setHours(cursor.getHours() + 1);
  for (let i = 0; i < 14 * 24 && out.length < (opts.count || 3); i += 1) {
    const start = new Date(cursor);
    const end = new Date(cursor.getTime() + duration);
    const zoned = opts.timezone ? zonedClock(start, opts.timezone) : null;
    const hour = zoned ? zoned.hour : cursor.getHours();
    const day = zoned ? zoned.weekday : cursor.getDay();
    const workStart = opts.workStart ?? 8;
    const workEnd = opts.workEnd ?? 17;
    const weekday = day >= 1 && day <= 5;
    const inHours = hour >= workStart && hour < workEnd;
    const conflict = opts.busy.some((b) => overlaps({ start, end }, b));
    if (weekday && inHours && !conflict && start > opts.from) {
      out.push({ start, end, label: labelSlot(start, opts.timezone) });
    }
    cursor.setTime(cursor.getTime() + 30 * 60 * 1000);
  }
  return out;
}

/**
 * Server actions for Email Campaigns UI + Ara tools.
 * Keep .server imports behind dynamic import so client bundles stay clean.
 */
import { createServerFn } from "@tanstack/react-start";
import { authMiddleware } from "@/lib/auth/middleware";

export const listEmailCampaignsFn = createServerFn({ method: "GET" })
  .middleware([authMiddleware])
  .handler(async ({ context }) => {
    const { listCampaigns } = await import("./service.server");
    const campaigns = await listCampaigns(context.userId);
