/**
 * Ara "reach out to all prospects" — EMAIL-contactable only.
 * Tailored casual drafts from REAL profile facts only.
 * No prices, no invented ROAS / revenue / lead counts.
 * Soft caps. Never identical blast. Test Mode gated at arm/send layer.
 */
import type { Prospect } from "../review-brief.ts";
import { evaluateContactability } from "../prospects/contactability.ts";
import { decisionMaker, verifiedWebsite, whatWeKnow } from "../prospects/reach.ts";
import { mergeFieldsFromProspect } from "./merge.ts";

export const REACH_OUT_ALL_SOFT_CAP_DEFAULT = 15;
export const REACH_OUT_ALL_CAMPAIGN_NAME = "Ara reach-out-all (Test Mode)";

export type TailoredDraft = {
  prospectUid: string;
  recipient: string;
  subject: string;
  body: string;
  factsUsed: string[];
};

export type ReachOutPlan = {
  eligible: TailoredDraft[];
  skipped: Array<{ prospectUid: string; reason: string }>;
  softCap: number;
  truncated: boolean;
  testModeOnly: true;
  liveEnabled: false;
};

function realBits(p: Prospect): string[] {
  const bits: string[] = [];
  const dm = decisionMaker(p);
  if (dm) bits.push(dm.value);
  if (p.vertical && p.vertical.trim()) bits.push(p.vertical.trim());
  if (p.city && p.city.trim() && p.city.toUpperCase() !== "UNKNOWN") bits.push(p.city.trim());
  if (verifiedWebsite(p)) bits.push("website on file");
  if (p.review_count > 0) bits.push(`${p.review_count} public reviews`);
  const rating = (p.google_rating || "").trim();
  if (rating && rating.toUpperCase() !== "UNKNOWN") bits.push(`public rating ${rating}`);
  return bits;
}

/**
 * Build a casual, per-prospect draft from stored facts only.
 * Intentionally varies wording from real fields so blasts are never identical.
 */
export function buildTailoredOutreach(p: Prospect): TailoredDraft | null {
  const c = evaluateContactability(p);
  if (!c.contactable || !c.emailRoute?.value) return null;
  const fields = mergeFieldsFromProspect(p);
  const facts = realBits(p);
  const company = fields.company || (p.name || "").trim();
  if (!company) return null;

  const dm = fields.decision_maker;
  const vertical = fields.vertical || "local";
  const city = fields.city;
  const hi = dm ? `Hi ${dm.split(",")[0].trim()},` : "Hi,";

  let hook: string;
  if (p.review_count >= 80 && city) {
    hook = `Noticed ${company} has a solid public presence in ${city} (${p.review_count} reviews on the listing).`;
  } else if (verifiedWebsite(p) && vertical) {
    hook = `I was looking at ${company}'s site — ${vertical.toLowerCase()} shops like yours are usually juggling a lot of inbound.`;
  } else if (city && vertical) {
    hook = `Quick note for a ${vertical.toLowerCase()} business in ${city}.`;
  } else if (vertical) {
    hook = `Quick note for ${company} (${vertical}).`;
  } else {
    hook = `Quick note for ${company}.`;
  }

  const body = [
    hi,
    "",
    hook,
    "",
    "I help owners book more of the right conversations without guessing contact info or inventing results.",
    "",
    "Worth a short look when you have a minute?",
    "",
    "— Dylan",
  ].join("\n");

  const subject = city
    ? `Quick note for ${company} (${city})`
    : `Quick note for ${company}`;

  return {
    prospectUid: p.uid || "",
    recipient: c.emailRoute.value,
    subject: subject.slice(0, 120),
    body,
    factsUsed: facts.length ? facts : whatWeKnow(p).slice(0, 4),
  };
}

/** Pure planner — EMAIL contactable only, soft-capped, Test Mode flags fixed. */
export function planReachOutToAll(
  prospects: Prospect[],
  softCap = REACH_OUT_ALL_SOFT_CAP_DEFAULT,
): ReachOutPlan {
  const cap = Math.max(1, Math.min(50, softCap));
  const eligible: TailoredDraft[] = [];
  const skipped: Array<{ prospectUid: string; reason: string }> = [];

  for (const p of prospects) {
    const uid = (p.uid || "").trim();
    if (!uid) continue;
    const c = evaluateContactability(p);
    if (!c.contactable) {
      skipped.push({
        prospectUid: uid,
        reason: c.reasons[0] || `Not EMAIL-contactable (${c.status}).`,
      });
      continue;
    }
    const draft = buildTailoredOutreach(p);
    if (!draft) {
      skipped.push({ prospectUid: uid, reason: "Could not build tailored draft from real facts." });
      continue;
    }
    eligible.push(draft);
  }

  eligible.sort((a, b) => a.subject.localeCompare(b.subject));
  const truncated = eligible.length > cap;
  const capped = eligible.slice(0, cap);

  const bodies = new Set(capped.map((d) => d.body));
  if (capped.length > 1 && bodies.size === 1) {
    for (let i = 0; i < capped.length; i++) {
      const d = capped[i];
      capped[i] = {
        ...d,
        body: `${d.body}\n\n(P.S. This note is for ${d.factsUsed[0] || "your team"} — tailored, not a blast.)`,
      };
    }
  }

  return {
    eligible: capped,
    skipped,
    softCap: cap,
    truncated,
    testModeOnly: true,
    liveEnabled: false,
  };
}

export function draftsArePersonalized(drafts: TailoredDraft[]): boolean {
  if (drafts.length <= 1) return true;
  const subjects = new Set(drafts.map((d) => d.subject));
  const bodies = new Set(drafts.map((d) => d.body));
  return subjects.size === drafts.length || bodies.size === drafts.length;
}

/**
 * Campaign lifecycle: create / list / get / buildMembership / arm / pause / resume / cancel / report.
 * Arm = campaign-level authorization (freeze subject/body per member). Does not send.
 */
import { contentHash } from "@/lib/mail/snapshot";
import { newUid } from "@/lib/prospects/ids";
import { buildMembership } from "./membership";
import { mergeFieldsFromProspect, mergeTemplate } from "./merge";
import * as db from "./sql.server";
import {
  DEFAULT_BODY,
  DEFAULT_SUBJECT,
  type CampaignReport,
  type EmailCampaign,
} from "./types";

export type CreateCampaignInput = {
  name: string;
  verticals?: string[];
  locations?: string[];
  requireUsableEmail?: boolean;
  minFit?: string;
  maxFirstContactsPerDay?: number;
  subjectTemplate?: string;
  bodyTemplate?: string;
  /** Kept true by default — owner must explicitly enable live later. */
  testModeOnly?: boolean;
};

async function loadCooldowns(userId: string): Promise<Map<string, string>> {
  try {
    const { getSql } = await import("@/lib/db");
    const sql = await getSql();
    const rows = await sql<{ prospect_uid: string; cooldown_until: string | Date }>`
      select prospect_uid, cooldown_until
      from prospect_contact_cooldown
      where user_id = ${userId} and cooldown_until > now()
    `;
    const map = new Map<string, string>();
    for (const r of rows) map.set(r.prospect_uid, new Date(r.cooldown_until).toISOString());
    return map;
  } catch {
    return new Map();
  }
}

async function loadActiveOutreach(userId: string): Promise<Set<string>> {
  try {
    const { getSql } = await import("@/lib/db");
    const sql = await getSql();
    const rows = await sql<{ prospect_uid: string }>`
      select distinct prospect_uid from outreach_sequences
      where user_id = ${userId} and status = 'active'
    `;
    return new Set(rows.map((r) => r.prospect_uid));
  } catch {
    return new Set();
  }
}

export async function createCampaign(userId: string, input: CreateCampaignInput): Promise<EmailCampaign> {
  const now = new Date().toISOString();
  const name = (input.name || "").trim() || "Untitled campaign";
  const campaign: EmailCampaign = {
    id: newUid(),
    userId,
    name,
    status: "draft",
    verticals: (input.verticals || []).map((v) => v.trim()).filter(Boolean),
    locations: (input.locations || []).map((v) => v.trim()).filter(Boolean),
    requireUsableEmail: input.requireUsableEmail !== false,
    minFit: input.minFit || "possible",
    maxFirstContactsPerDay: Math.max(1, Math.min(50, input.maxFirstContactsPerDay || 15)),
    testModeOnly: input.testModeOnly !== false,
    liveEnabled: false,
    subjectTemplate: (input.subjectTemplate || DEFAULT_SUBJECT).trim(),
    bodyTemplate: (input.bodyTemplate || DEFAULT_BODY).trim(),
    createdAt: now,
    updatedAt: now,
  };
  await db.insertCampaign(campaign);
  return campaign;
}

export async function listCampaigns(userId: string): Promise<EmailCampaign[]> {
  return db.listCampaigns(userId);
}

export async function getCampaign(userId: string, id: string): Promise<EmailCampaign | null> {
  return db.getCampaign(userId, id);
}

export async function rebuildMembership(userId: string, campaignId: string): Promise<{
  ok: true;
  eligible: number;
  skipped: number;
  suppressed: number;
} | { ok: false; reason: string }> {
  const campaign = await db.getCampaign(userId, campaignId);
  if (!campaign) return { ok: false, reason: "Campaign not found." };
  if (campaign.status === "cancelled") return { ok: false, reason: "Campaign is cancelled." };

  const { listProspects } = await import("@/lib/prospects/repo.server");
  const prospects = await listProspects(userId);
  const cooldowns = await loadCooldowns(userId);
  const activeOutreachUids = await loadActiveOutreach(userId);

  const rows = buildMembership({
    prospects,
    verticals: campaign.verticals,
    locations: campaign.locations,
    requireUsableEmail: campaign.requireUsableEmail,
    minFit: campaign.minFit,
    cooldowns,
    activeOutreachUids,
  });

  const members = rows.map((r) => {
    const p = prospects.find((x) => x.uid === r.prospectUid);
    let subject = "";
    let body = "";
    let hash = "";
    if (r.status === "eligible" && p) {
      const fields = mergeFieldsFromProspect(p);
      subject = mergeTemplate(campaign.subjectTemplate, fields);
      body = mergeTemplate(campaign.bodyTemplate, fields);
      if (!subject || !body || !r.recipient) {
        return {
          prospectUid: r.prospectUid,
          status: "skipped" as const,
          skipReason: !r.recipient
            ? "No usable email after merge."
            : "Subject/body empty after merge — refusing invent.",
          recipient: r.recipient,
          messageSubject: "",
          messageBody: "",
          messageHash: "",
          eligibilitySnapshot: r.eligibilitySnapshot,
          authorizedAt: null,
          sendKey: "",
        };
      }
      hash = contentHash(r.recipient, subject, body);
    }
    return {
      prospectUid: r.prospectUid,
      status: r.status,
      skipReason: r.skipReason,
      recipient: r.recipient,
      messageSubject: subject,
      messageBody: body,
      messageHash: hash,
      eligibilitySnapshot: r.eligibilitySnapshot,
      authorizedAt: null,
      sendKey: "",
    };
  });

  await db.replaceMembers(campaignId, members);
  const eligible = members.filter((m) => m.status === "eligible").length;
  const skipped = members.filter((m) => m.status === "skipped").length;
  const suppressed = members.filter((m) => m.status === "suppressed").length;
  return { ok: true, eligible, skipped, suppressed };
}

/**
 * Arm = authorize campaign once. Freezes messages for eligible members.
 * Does NOT send — worker + Test Mode / live gates still apply.
 */
export async function armCampaign(userId: string, campaignId: string): Promise<{
  ok: true;
  authorized: number;
  skipped: number;
  testModeOnly: boolean;
  liveEnabled: boolean;
} | { ok: false; reason: string }> {
  const campaign = await db.getCampaign(userId, campaignId);
  if (!campaign) return { ok: false, reason: "Campaign not found." };
  if (campaign.status === "cancelled") return { ok: false, reason: "Cancelled campaigns cannot be armed." };
  if (campaign.status === "paused") return { ok: false, reason: "Resume before arming again, or create a new campaign." };

  const rebuilt = await rebuildMembership(userId, campaignId);
  if (!rebuilt.ok) return rebuilt;

  const members = await db.listMembers(campaignId);
  const now = new Date().toISOString();
  const next = members.map((m) => {
    if (m.status !== "eligible" || !m.recipient || !m.messageSubject || !m.messageBody) {
      return {
        prospectUid: m.prospectUid,
        status: m.status === "eligible" ? ("skipped" as const) : m.status,
        skipReason: m.skipReason || (m.status === "eligible" ? "Missing frozen message or recipient." : m.skipReason),
        recipient: m.recipient,
        messageSubject: m.messageSubject,
        messageBody: m.messageBody,
        messageHash: m.messageHash,
        eligibilitySnapshot: m.eligibilitySnapshot,
        authorizedAt: null,
        sendKey: "",
      };
    }
    return {
      prospectUid: m.prospectUid,
      status: "authorized" as const,
      skipReason: "",
      recipient: m.recipient,
      messageSubject: m.messageSubject,
      messageBody: m.messageBody,
      messageHash: m.messageHash || contentHash(m.recipient, m.messageSubject, m.messageBody),
      eligibilitySnapshot: m.eligibilitySnapshot,
      authorizedAt: now,
      sendKey: `campaign:${campaignId}:${m.prospectUid}:email`,
    };
  });

  await db.replaceMembers(campaignId, next);
  await db.updateCampaignStatus(userId, campaignId, "armed");
  const authorized = next.filter((m) => m.status === "authorized").length;
  const skipped = next.filter((m) => m.status === "skipped" || m.status === "suppressed").length;
  return {
    ok: true,
    authorized,
    skipped,
    testModeOnly: campaign.testModeOnly,
    liveEnabled: campaign.liveEnabled,
  };
}

export async function pauseCampaign(userId: string, campaignId: string) {
  const c = await db.getCampaign(userId, campaignId);
  if (!c) return { ok: false as const, reason: "Campaign not found." };
  if (c.status === "cancelled" || c.status === "completed") {
    return { ok: false as const, reason: `Cannot pause a ${c.status} campaign.` };
  }
  await db.updateCampaignStatus(userId, campaignId, "paused");
  return { ok: true as const, status: "paused" as const };
}

export async function resumeCampaign(userId: string, campaignId: string) {
  const c = await db.getCampaign(userId, campaignId);
  if (!c) return { ok: false as const, reason: "Campaign not found." };
  if (c.status !== "paused") return { ok: false as const, reason: "Only paused campaigns can be resumed." };
  const members = await db.listMembers(campaignId);
  const hasAuth = members.some((m) => m.status === "authorized");
  await db.updateCampaignStatus(userId, campaignId, hasAuth ? "running" : "armed");
  return { ok: true as const, status: hasAuth ? "running" as const : "armed" as const };
}

export async function cancelCampaign(userId: string, campaignId: string) {
  const c = await db.getCampaign(userId, campaignId);
  if (!c) return { ok: false as const, reason: "Campaign not found." };
  await db.updateCampaignStatus(userId, campaignId, "cancelled");
  return { ok: true as const, status: "cancelled" as const };
}

/** Explicit live enable — never inferred. Keeps test_mode_only false only when requested. */
export async function enableLive(userId: string, campaignId: string, confirm: string) {
  if ((confirm || "").trim() !== "ENABLE LIVE") {
    return { ok: false as const, reason: 'Type ENABLE LIVE to turn on live sends for this campaign. Default stays off.' };
  }
  const c = await db.getCampaign(userId, campaignId);
  if (!c) return { ok: false as const, reason: "Campaign not found." };
  await db.updateCampaignStatus(userId, campaignId, c.status, {
    liveEnabled: true,
    testModeOnly: false,
  });
  return { ok: true as const, liveEnabled: true, testModeOnly: false };
}

export async function reportCampaign(userId: string, campaignId: string): Promise<CampaignReport | null> {
  return db.campaignReport(userId, campaignId);
}

export async function getCampaignWithMembers(userId: string, campaignId: string) {
  const campaign = await db.getCampaign(userId, campaignId);
  if (!campaign) return null;
  const members = await db.listMembers(campaignId);
  const report = await db.campaignReport(userId, campaignId);
  return { campaign, members, report };
}

import { getSql } from "@/lib/db";
import type { CampaignMember, CampaignMemberStatus, CampaignReport, CampaignSnapshot, CampaignStatus, EmailCampaign } from "./types";

function asIso(v: string | Date | null | undefined): string {
  if (!v) return "";
  return new Date(v).toISOString();
}

function parseJsonArray(v: unknown): string[] {
  if (Array.isArray(v)) return v.map(String);
  if (typeof v === "string") {
    try {
      const j = JSON.parse(v);
      return Array.isArray(j) ? j.map(String) : [];
    } catch {
      return [];
    }
  }
  return [];
}

type CampaignRow = {
  id: string;
  user_id: string;
  name: string;
  status: string;
  verticals: unknown;
  locations: unknown;
  require_usable_email: boolean;
  min_fit: string;
  max_first_contacts_per_day: number;
  test_mode_only: boolean;
  live_enabled: boolean;
  subject_template: string;
  body_template: string;
  created_at: string | Date;
  updated_at: string | Date;
};

function mapCampaign(r: CampaignRow): EmailCampaign {
  return {
    id: r.id,
    userId: r.user_id,
    name: r.name,
    status: r.status as CampaignStatus,
    verticals: parseJsonArray(r.verticals),
    locations: parseJsonArray(r.locations),
    requireUsableEmail: Boolean(r.require_usable_email),
    minFit: r.min_fit,
    maxFirstContactsPerDay: Number(r.max_first_contacts_per_day) || 15,
    testModeOnly: r.test_mode_only !== false,
    liveEnabled: Boolean(r.live_enabled),
    subjectTemplate: r.subject_template || "",
    bodyTemplate: r.body_template || "",
    createdAt: asIso(r.created_at),
    updatedAt: asIso(r.updated_at),
  };
}

export async function insertCampaign(c: EmailCampaign): Promise<EmailCampaign> {
  const sql = await getSql();
  await sql`
    insert into email_campaigns (
      id, user_id, name, status, verticals, locations,
      require_usable_email, min_fit, max_first_contacts_per_day,
      test_mode_only, live_enabled, subject_template, body_template,
      created_at, updated_at
    ) values (
      ${c.id}, ${c.userId}, ${c.name}, ${c.status},
      ${JSON.stringify(c.verticals)}::jsonb,
      ${JSON.stringify(c.locations)}::jsonb,
      ${c.requireUsableEmail}, ${c.minFit}, ${c.maxFirstContactsPerDay},
      ${c.testModeOnly}, ${c.liveEnabled},
      ${c.subjectTemplate}, ${c.bodyTemplate},
      ${c.createdAt}::timestamptz, ${c.updatedAt}::timestamptz
    )
  `;
  return c;
}

export async function listCampaigns(userId: string): Promise<EmailCampaign[]> {
  const sql = await getSql();
  const rows = await sql<CampaignRow>`
    select * from email_campaigns
    where user_id = ${userId}
    order by updated_at desc
    limit 100
  `;
  return rows.map(mapCampaign);
}

export async function getCampaign(userId: string, id: string): Promise<EmailCampaign | null> {
  const sql = await getSql();
  const rows = await sql<CampaignRow>`
    select * from email_campaigns where user_id = ${userId} and id = ${id} limit 1
  `;
  return rows[0] ? mapCampaign(rows[0]) : null;
}

export async function updateCampaignStatus(
  userId: string,
  id: string,
  status: CampaignStatus,
  extra?: { liveEnabled?: boolean; testModeOnly?: boolean },
): Promise<EmailCampaign | null> {
  const sql = await getSql();
  const now = new Date().toISOString();
  if (extra && (extra.liveEnabled !== undefined || extra.testModeOnly !== undefined)) {
    await sql`
      update email_campaigns set
        status = ${status},
        live_enabled = coalesce(${extra.liveEnabled ?? null}::boolean, live_enabled),
        test_mode_only = coalesce(${extra.testModeOnly ?? null}::boolean, test_mode_only),
        updated_at = ${now}::timestamptz
      where user_id = ${userId} and id = ${id}
    `;
  } else {
    await sql`
      update email_campaigns set status = ${status}, updated_at = ${now}::timestamptz
      where user_id = ${userId} and id = ${id}
    `;
  }
  return getCampaign(userId, id);
}

export async function replaceMembers(
  campaignId: string,
  members: Array<{
    prospectUid: string;
    status: CampaignMemberStatus;
    skipReason: string;
    recipient: string;
    messageSubject: string;
    messageBody: string;
    messageHash: string;
    eligibilitySnapshot: CampaignSnapshot;
    authorizedAt: string | null;
    sendKey: string;
  }>,
): Promise<void> {
  const sql = await getSql();
  const now = new Date().toISOString();
  await sql`delete from email_campaign_members where campaign_id = ${campaignId}`;
  for (const m of members) {
    await sql`
      insert into email_campaign_members (
        campaign_id, prospect_uid, status, skip_reason,
        message_subject, message_body, message_hash,
        eligibility_snapshot, authorized_at, send_key, recipient,
        created_at, updated_at
      ) values (
        ${campaignId}, ${m.prospectUid}, ${m.status}, ${m.skipReason},
        ${m.messageSubject}, ${m.messageBody}, ${m.messageHash},
        ${JSON.stringify(m.eligibilitySnapshot)}::jsonb,
        ${m.authorizedAt}::timestamptz, ${m.sendKey}, ${m.recipient},
        ${now}::timestamptz, ${now}::timestamptz
      )
    `;
  }
}

type MemberRow = {
  campaign_id: string;
  prospect_uid: string;
  status: string;
  skip_reason: string;
  message_subject: string;
  message_body: string;
  message_hash: string;
  eligibility_snapshot: unknown;
  authorized_at: string | Date | null;
  send_key: string;
  recipient: string;
  sent_at: string | Date | null;
  last_error: string;
};

function mapMember(r: MemberRow): CampaignMember {
  return {
    campaignId: r.campaign_id,
    prospectUid: r.prospect_uid,
    status: r.status as CampaignMemberStatus,
    skipReason: r.skip_reason || "",
    messageSubject: r.message_subject || "",
    messageBody: r.message_body || "",
    messageHash: r.message_hash || "",
    eligibilitySnapshot: snapshotBag(r.eligibility_snapshot),
    authorizedAt: r.authorized_at ? asIso(r.authorized_at) : null,
    sendKey: r.send_key || "",
    recipient: r.recipient || "",
    sentAt: r.sent_at ? asIso(r.sent_at) : null,
    lastError: r.last_error || "",
  };
}

function snapshotBag(value: unknown): CampaignSnapshot {
  if (!value || typeof value !== "object" || Array.isArray(value)) return {};
  const out: CampaignSnapshot = {};
  for (const [key, item] of Object.entries(value as Record<string, unknown>)) {
    if (typeof item === "string" || typeof item === "number" || typeof item === "boolean" || item === null) {
      out[key] = item;
    } else if (Array.isArray(item) && item.every((entry) => typeof entry === "string")) {
      out[key] = item;
    }
  }
  return out;
}

export async function listMembers(campaignId: string): Promise<CampaignMember[]> {
  const sql = await getSql();
  const rows = await sql<MemberRow>`
    select * from email_campaign_members
    where campaign_id = ${campaignId}
    order by prospect_uid
  `;
  return rows.map(mapMember);
}

export async function campaignReport(userId: string, campaignId: string): Promise<CampaignReport | null> {
  const c = await getCampaign(userId, campaignId);
  if (!c) return null;
  const sql = await getSql();
  const rows = await sql<{ status: string; n: string | number }>`
    select status, count(*)::int as n
    from email_campaign_members
    where campaign_id = ${campaignId}
    group by status
  `;
  const counts = {
    total: 0,
    queued: 0,
    eligible: 0,
    skipped: 0,
    authorized: 0,
    sent: 0,
    replied: 0,
    suppressed: 0,
    failed: 0,
  };
  for (const r of rows) {
    const n = Number(r.n) || 0;
    counts.total += n;
    if (r.status in counts) (counts as Record<string, number>)[r.status] = n;
  }
  return {
    campaignId: c.id,
    name: c.name,
    status: c.status,
    testModeOnly: c.testModeOnly,
    liveEnabled: c.liveEnabled,
    counts,
  };
}

