import { VERTICAL_QUERY, cacheKey, mapSpokenVertical, type PlaceHit } from "./places.ts";

const IN_SPLIT = /\s+in\s+/i;

export type ParsedFindQuery = {
  vertical: string;
  location: string;
  textQuery: string;
  industryRaw: string;
};

/** Turn owner language into a Places text query. Never invent a market. */
export function parseFindQuery(opts: { vertical?: string; location?: string }): ParsedFindQuery {
  let industry = (opts.vertical || "").trim();
  let location = (opts.location || "").trim();
  if (IN_SPLIT.test(industry)) {
    const parts = industry.split(IN_SPLIT).map((p) => p.trim()).filter(Boolean);
    if (parts.length >= 2) {
      industry = parts[0];
      if (!location) location = parts.slice(1).join(" in ");
    }
  }
  const vertical = mapSpokenVertical(industry || "Other");
  const spec = VERTICAL_QUERY[vertical];
  const phrase = vertical === "Other" && industry
    ? industry.replace(/\s+companies?$/i, "").trim() || industry
    : spec?.query || industry || "company";
  const textQuery = location ? `${phrase} in ${location}` : phrase;
  return { vertical, location, textQuery, industryRaw: industry };
}

export function normalizeMarket(location: string): string {
  return location.trim().toLowerCase().replace(/\s+/g, " ");
}

/** Statewide / country queries should not get a tight circle bias. */
export function useLocationBias(location: string): boolean {
  const t = normalizeMarket(location);
  if (!t) return false;
  if (/^(texas|tx|california|ca|united states|usa|us|oklahoma|ok)$/.test(t)) return false;
  return true;
}

export function radiusMeters(location: string, requested?: number): number {
  const cap = 50_000;
  if (requested && requested > 0) return Math.min(cap, Math.max(1_000, Math.floor(requested)));
  if (/\bdfw\b|dallas[- ]fort worth|metroplex/.test(normalizeMarket(location))) return cap;
  return 40_000;
}

export function discoveryCacheKey(opts: {
  vertical: string;
  location: string;
  limit: number;
  radiusM: number;
  minRating: number;
  textQuery: string;
}): string {
  return cacheKey({
    v: mapSpokenVertical(opts.vertical),
    loc: normalizeMarket(opts.location),
    q: opts.textQuery.trim().toLowerCase(),
    n: opts.limit,
    r: opts.radiusM,
    min: opts.minRating,
    p: "places_v2",
  });
}

export function dropClosedPlaces(hits: PlaceHit[]): PlaceHit[] {
  return hits.filter((h) => {
    const st = (h.business_status || "").toUpperCase();
    return st !== "CLOSED_PERMANENTLY";
  });
}

/** Usefulness rank. Reviews are a signal, never a hard gate. */
export function usefulnessScore(hit: PlaceHit): number {
  let n = 0;
  const st = (hit.business_status || "").toUpperCase();
  if (st === "OPERATIONAL") n += 20;
  else if (st === "CLOSED_TEMPORARILY") n += 4;
  if (hit.website && hit.website !== "UNKNOWN") n += 16;
  if (hit.phone && hit.phone !== "UNKNOWN") n += 8;
  if (hit.review_count >= 50) n += 10;
  else if (hit.review_count >= 15) n += 6;
  else if (hit.review_count > 0) n += 2;
  const rating = hit.google_rating === "UNKNOWN" ? 0 : Number(hit.google_rating);
  if (rating >= 4.5) n += 6;
  else if (rating >= 4) n += 3;
  return n;
}

export function rankPlaceHits(hits: PlaceHit[]): PlaceHit[] {
  return [...hits].sort((a, b) => {
    const d = usefulnessScore(b) - usefulnessScore(a);
    if (d) return d;
    return (b.review_count || 0) - (a.review_count || 0);
  });
}

import { createServerFn } from "@tanstack/react-start";
import { authMiddleware } from "@/lib/auth/middleware";
import type { Prospect } from "@/lib/review-brief";
import { hitToProspect } from "./to-prospect";
import type { PlaceHit } from "./places";

export type FindInput = {
  vertical: string;
  location: string;
  limit: number;
  radiusM?: number;
  minRating?: number;
  minReviews?: number;
  query?: string;
};

export { hitToProspect };

export const findClientsFn = createServerFn({ method: "POST" })
  .middleware([authMiddleware])
  .validator((data: FindInput) => data)
  .handler(async ({ data, context }) => {
    const { env } = await import("@/lib/env.server");
    const { searchText } = await import("./places");
    const {
      parseFindQuery,
      discoveryCacheKey,
      dropClosedPlaces,
      rankPlaceHits,
      radiusMeters,
      useLocationBias,
    } = await import("./query");
    const { tryReserveDiscovery, cacheGet, cacheSet, EST_SEARCH_CENTS, EST_GEOCODE_CENTS } = await import("./usage.server");
    const { listProspects, importProspects, logActivity } = await import("@/lib/prospects/repo.server");
    const { nextClientId } = await import("@/lib/prospects/ids");

    const key = env("GOOGLE_PLACES_API_KEY");
    if (!key) {
      return {
        ok: false as const,
        reason: "Live Find Clients is off. Add GOOGLE_PLACES_API_KEY on the server (Places API New + Geocoding API), or use Add Client for a company you already know. We will not invent businesses.",
        prospects: [] as Prospect[],
        imported: 0,
        merged: 0,
      };
    }

    const parsed = parseFindQuery({
      vertical: (data.query || data.vertical || "").trim() || "Other",
      location: (data.location || "").trim(),
    });
    const vertical = parsed.vertical;
    const location = parsed.location;
    const limit = Math.min(20, Math.max(1, Math.floor(Number(data.limit) || 8)));
    if (!location) {
      return {
        ok: false as const,
        reason: "I need a city or market. Type Dallas, Fort Worth, or similar.",
        prospects: [] as Prospect[],
        imported: 0,
        merged: 0,
      };
    }

    const radiusM = radiusMeters(location, data.radiusM);
    const skipGeocode = !useLocationBias(location);
    const ck = discoveryCacheKey({
      vertical,
      location,
      limit,
      radiusM: skipGeocode ? 0 : radiusM,
      minRating: data.minRating || 0,
      textQuery: parsed.textQuery,
    });
    const cached = await cacheGet(ck);
    const { cacheSatisfiesSearch } = await import("./places");
    let hits: PlaceHit[] = cacheSatisfiesSearch(cached) ? cached : [];

    if (!hits.length) {
      const found = await searchText({
        apiKey: key,
        vertical,
        location,
        radiusM,
        limit,
        minRating: data.minRating || 0,
        textQuery: parsed.textQuery,
        skipGeocode,
        collect: Math.min(20, Math.max(limit, 10)),
        reserve: async (kind) => {
          const cents = kind === "geocode" ? EST_GEOCODE_CENTS : EST_SEARCH_CENTS;
          return tryReserveDiscovery(context.userId, cents);
        },
      });
      if ("error" in found) {
        return {
          ok: false as const,
          reason: found.error.message,
          prospects: [] as Prospect[],
          imported: 0,
          merged: 0,
        };
      }
      hits = found.places;
      await cacheSet(ck, hits, 7);
    }

    const minReviews = Math.max(0, data.minReviews || 0);
    const filtered = rankPlaceHits(
      dropClosedPlaces(hits).filter((h) => h.review_count >= minReviews),
    ).slice(0, limit);
    if (!filtered.length) {
      return {
        ok: false as const,
        reason: "No real businesses came back for that search. We did not invent any.",
        prospects: [] as Prospect[],
        imported: 0,
        merged: 0,
      };
    }
    const existing = await listProspects(context.userId);
    let nextId = nextClientId(existing);
    const incoming: Prospect[] = [];
    for (const hit of filtered) {
      incoming.push(hitToProspect(hit, nextId));
      nextId += 1;
    }
    const imported = await importProspects(context.userId, incoming);
    const prospects = imported.prospects;
    const placeIds = incoming.map((p) => p.provider_place_id).filter((id): id is string => Boolean(id));
    const matched = prospects.filter((p) => p.provider_place_id && placeIds.includes(p.provider_place_id));
    const lastDiscovery = {
      query: `${vertical} in ${location}`,
      vertical,
      location,
      requested: limit,
      matched: matched.length,
      prospectUids: matched.map((p) => p.uid || "").filter(Boolean),
      placeIds,
      timestamp: new Date().toISOString(),
    };
    const reason = imported.imported === 0 && imported.merged > 0
      ? `Those ${matched.length} ${vertical} companies in ${location} are already on your list. Showing them on Pipeline.`
      : `Saved ${imported.imported} new companies${imported.merged ? `, ${imported.merged} already on your list` : ""}. Showing them on Pipeline.`;
    await logActivity(context.userId, "find_clients", `${filtered.length} from Places (${vertical} / ${location}); imported ${imported.imported}, merged ${imported.merged}`);
    return { ok: true as const, reason, prospects, imported: imported.imported, merged: imported.merged, lastDiscovery };
  });

