import type { GmailPort, GmailSendInput, GmailSendResult } from "../mail/types.ts";

function rfc822(input: GmailSendInput): string {
  const headers = [
    `To: ${input.to}`,
    `Subject: ${input.subject}`,
    "Content-Type: text/plain; charset=utf-8",
  ];
  return `${headers.join("\r\n")}\r\n\r\n${input.body}`;
}

export function liveGmail(accessToken: string, fetchImpl: typeof fetch = fetch): GmailPort {
  return {
    async send(input: GmailSendInput): Promise<GmailSendResult> {
      const raw = Buffer.from(rfc822(input)).toString("base64url");
      const body: Record<string, unknown> = { raw };
      if (input.threadId) body.threadId = input.threadId;
      let res: Response;
      try {
        res = await fetchImpl("https://gmail.googleapis.com/gmail/v1/users/me/messages/send", {
          method: "POST",
          headers: {
            Authorization: `Bearer ${accessToken}`,
            "Content-Type": "application/json",
          },
          body: JSON.stringify(body),
        });
      } catch {
        return { ok: false, error: "timeout", timeout: true };
      }
      if (res.status === 401 || res.status === 403) return { ok: false, error: "disconnected", disconnected: true };
      const json = (await res.json()) as { id?: string; threadId?: string; error?: { message?: string } };
      if (!res.ok || !json.id) {
        const msg = json.error?.message || `Gmail HTTP ${res.status}`;
        const bounced = /bounce|invalid recipient|failed recipient/i.test(msg);
        return { ok: false, error: msg, bounced };
      }
      return { ok: true, messageId: json.id, threadId: json.threadId || json.id };
    },
    async listNewReplies(threadId: string) {
      const res = await fetchImpl(`https://gmail.googleapis.com/gmail/v1/users/me/threads/${encodeURIComponent(threadId)}?format=full`, {
        headers: { Authorization: `Bearer ${accessToken}` },
      });
      if (!res.ok) return [];
      const json = (await res.json()) as {
        messages?: {
          id?: string;
          labelIds?: string[];
          payload?: { headers?: { name: string; value: string }[]; body?: { data?: string }; parts?: { body?: { data?: string } }[] };
        }[];
      };
      const out: { id: string; from: string; body: string; labelIds?: string[] }[] = [];
      for (const m of json.messages || []) {
        const headers = m.payload?.headers || [];
        const from = headers.find((h) => h.name.toLowerCase() === "from")?.value || "";
        const b64 = m.payload?.body?.data || m.payload?.parts?.[0]?.body?.data || "";
        let body = "";
        try {
          body = Buffer.from(b64, "base64url").toString("utf8");
        } catch {
          body = "";
        }
        if (m.id) out.push({ id: m.id, from, body, labelIds: m.labelIds });
      }
      return out;
    },
  };
}

export async function gmailProfile(
  accessToken: string,
  fetchImpl: typeof fetch = fetch,
): Promise<{ ok: true; email: string } | { ok: false; reason: string }> {
  try {
    const res = await fetchImpl("https://gmail.googleapis.com/gmail/v1/users/me/profile", {
      headers: { Authorization: `Bearer ${accessToken}` },
    });
    if (res.status === 401 || res.status === 403) {
      return { ok: false, reason: "Gmail needs to be reconnected." };
    }
    if (!res.ok) return { ok: false, reason: "Could not read the Gmail account." };
    const json = (await res.json()) as { emailAddress?: string };
    if (!json.emailAddress) return { ok: false, reason: "Gmail did not return an account email." };
    return { ok: true, email: json.emailAddress };
  } catch {
    return { ok: false, reason: "Could not reach Gmail." };
  }
}

export type OauthMissing = { name: string; ready: boolean };

export type GoogleConnectResult = {
  ok: boolean;
  reason: string;
  missing: OauthMissing[];
  next: string;
  launched: boolean;
  url?: string;
};

const POPUP_NAME = "lascengine-google";

function openOauthWindow(): Window | null {
  try {
    // Open synchronously in the click turn so the browser counts it as a user gesture.
    // Do not pass noopener — Chrome then returns null and we cannot set the URL after the server round-trip.
    return window.open("about:blank", POPUP_NAME, "width=520,height=720");
  } catch {
    return null;
  }
}

export async function startGoogleOAuth(kind: "gmail" | "calendar", opts?: { allowPopup?: boolean; force?: boolean }): Promise<GoogleConnectResult> {
  const wantPopup = opts?.allowPopup !== false;
  const popup = wantPopup ? openOauthWindow() : null;
  const { googleStartFn } = await import("@/lib/mail/actions");
  let res: Awaited<ReturnType<typeof googleStartFn>>;
  try {
    res = await googleStartFn({ data: { kind, origin: window.location.origin, force: opts?.force } });
  } catch {
    try { popup?.close(); } catch { /* ignore */ }
    return {
      ok: false,
      reason: kind === "calendar"
        ? "Could not start Google Calendar sign-in. The existing Calendar connection was not changed."
        : "Could not start Google sign-in. Nothing was connected.",
      missing: [],
      next: kind === "calendar"
        ? "The stored Calendar connection was left as-is."
        : "Try Connect Gmail again. We will not ask for your Gmail password.",
      launched: false,
    };
  }
  if ("alreadyConnected" in res && res.alreadyConnected) {
    try { popup?.close(); } catch { /* ignore */ }
    return {
      ok: true,
      reason: res.reason || "Google Calendar is already connected. The existing connection was not changed.",
      missing: res.missing || [],
      next: res.next || "Use Reconnect only if Calendar actually needs a new Google sign-in.",
      launched: false,
    };
  }
  if (!res.ok) {
    try { popup?.close(); } catch { /* ignore */ }
    return {
      ok: false,
      reason: res.reason,
      missing: res.missing || [],
      next: res.next || "Add the missing Google OAuth values on the server, then press Connect Gmail again. We will not ask for your Gmail password.",
      launched: false,
    };
  }
  if (!res.url) {
    try { popup?.close(); } catch { /* ignore */ }
    return {
      ok: false,
      reason: kind === "calendar"
        ? "Could not start Google Calendar sign-in. The existing Calendar connection was not changed."
        : "Could not start Google sign-in. Nothing was connected.",
      missing: res.missing || [],
      next: kind === "calendar" ? "The stored Calendar connection was left as-is." : "Try Connect Gmail again.",
      launched: false,
    };
  }
  if (popup && !popup.closed) {
    try {
      popup.location.replace(res.url);
      popup.focus();
      return {
        ok: true,
        reason: kind === "gmail"
          ? "Opening Google so you can authorize Gmail. We will not ask for your Gmail password."
          : "Opening Google so you can authorize Calendar.",
        missing: [],
        next: "Finish sign-in in the Google window. This page will update when it comes back.",
        launched: true,
        url: res.url,
      };
    } catch {
      /* fall through to a visible link */
    }
  }
  try { popup?.close(); } catch { /* ignore */ }
  return {
    ok: false,
    reason: "Google sign-in couldn’t open a window. Allow pop-ups for this page, or use Continue with Google below.",
    missing: [],
    next: "If pop-ups are blocked, allow them and try once more. We will not ask for your Gmail password.",
    launched: false,
    url: res.url,
  };
}

export function isGoogleOauthMessage(data: unknown): data is { source: "lascengine-google"; status: string } {
  if (!data || typeof data !== "object") return false;
  const rec = data as { source?: unknown; status?: unknown };
  return rec.source === "lascengine-google" && typeof rec.status === "string";
}

import assert from "node:assert/strict";
