import { env } from "../env.server.ts";
import type { OauthKind } from "../mail/oauth-state.ts";

export const GMAIL_SCOPES = [
  "openid",
  "email",
  "https://www.googleapis.com/auth/gmail.send",
  "https://www.googleapis.com/auth/gmail.readonly",
];

export const CALENDAR_SCOPES = [
  "openid",
  "email",
  "https://www.googleapis.com/auth/calendar.events",
  "https://www.googleapis.com/auth/calendar.freebusy",
];

export function googleOAuthConfigured(): boolean {
  return Boolean(env("GOOGLE_OAUTH_CLIENT_ID") && env("GOOGLE_OAUTH_CLIENT_SECRET"));
}

function present(key: string, forbidden: string[] = []): boolean {
  const v = env(key);
  if (!v) return false;
  return !forbidden.includes(v);
}

export function googleOAuthSetup(): { name: string; ready: boolean }[] {
  return [
    { name: "Google OAuth Client ID", ready: present("GOOGLE_OAUTH_CLIENT_ID") },
    { name: "Google OAuth Client Secret", ready: present("GOOGLE_OAUTH_CLIENT_SECRET") },
    { name: "APP_SECRET", ready: present("APP_SECRET", ["dev-preview-only-not-for-production", "changeme"]) },
  ];
}

export function redirectUri(requestUrl: string): string {
  const explicit = env("GOOGLE_OAUTH_REDIRECT_URI");
  if (explicit) return explicit;
  const u = new URL(requestUrl);
  return `${u.origin}/api/google/callback`;
}

export function scopesFor(kind: OauthKind): string[] {
  return kind === "calendar" ? [...CALENDAR_SCOPES] : [...GMAIL_SCOPES];
}

export function authorizeUrl(opts: { state: string; kind: OauthKind; requestUrl: string; loginHint?: string }): string {
  const clientId = env("GOOGLE_OAUTH_CLIENT_ID") || "";
  const unique = [...new Set(scopesFor(opts.kind))];
  const p = new URLSearchParams({
    client_id: clientId,
    redirect_uri: redirectUri(opts.requestUrl),
    response_type: "code",
    scope: unique.join(" "),
    access_type: "offline",
    prompt: "consent",
    include_granted_scopes: "false",
    state: opts.state,
  });
  if (opts.loginHint) p.set("login_hint", opts.loginHint);
  return `https://accounts.google.com/o/oauth2/v2/auth?${p.toString()}`;
}

export type GoogleTokens = {
  access_token: string;
  refresh_token?: string;
  expires_in?: number;
  token_type?: string;
  scope?: string;
  expiry: number;
  email?: string;
  sub?: string;
};

export async function exchangeCode(code: string, requestUrl: string, fetchImpl: typeof fetch = fetch): Promise<GoogleTokens> {
  const body = new URLSearchParams({
    code,
    client_id: env("GOOGLE_OAUTH_CLIENT_ID") || "",
    client_secret: env("GOOGLE_OAUTH_CLIENT_SECRET") || "",
    redirect_uri: redirectUri(requestUrl),
    grant_type: "authorization_code",
  });
  const res = await fetchImpl("https://oauth2.googleapis.com/token", {
    method: "POST",
    headers: { "Content-Type": "application/x-www-form-urlencoded" },
    body,
  });
  const json = (await res.json()) as Record<string, unknown>;
  if (!res.ok || !json.access_token) {
    throw new Error("Google did not finish sign-in. Nothing was connected.");
  }
  const tokens: GoogleTokens = {
    access_token: String(json.access_token),
    refresh_token: json.refresh_token ? String(json.refresh_token) : undefined,
    expires_in: Number(json.expires_in || 3600),
    token_type: json.token_type ? String(json.token_type) : "Bearer",
    scope: json.scope ? String(json.scope) : "",
    expiry: Date.now() + Number(json.expires_in || 3600) * 1000,
  };
  try {
    const infoRes = await fetchImpl("https://openidconnect.googleapis.com/v1/userinfo", {
      headers: { Authorization: `Bearer ${tokens.access_token}` },
    });
    const info = (await infoRes.json()) as { email?: string; sub?: string };
    tokens.email = info.email;
    tokens.sub = info.sub;
  } catch {
    /* email optional */
  }
  return tokens;
}

export async function refreshAccess(refreshToken: string, fetchImpl: typeof fetch = fetch): Promise<GoogleTokens> {
  const body = new URLSearchParams({
    refresh_token: refreshToken,
    client_id: env("GOOGLE_OAUTH_CLIENT_ID") || "",
    client_secret: env("GOOGLE_OAUTH_CLIENT_SECRET") || "",
    grant_type: "refresh_token",
  });
  const res = await fetchImpl("https://oauth2.googleapis.com/token", {
    method: "POST",
    headers: { "Content-Type": "application/x-www-form-urlencoded" },
    body,
  });
  const json = (await res.json()) as Record<string, unknown>;
  if (!res.ok || !json.access_token) {
    throw new Error("Gmail needs to be reconnected.");
  }
  return {
    access_token: String(json.access_token),
    refresh_token: refreshToken,
    expiry: Date.now() + Number(json.expires_in || 3600) * 1000,
    scope: json.scope ? String(json.scope) : "",
  };
}

export async function ensureFreshAccess(
  tokens: GoogleTokens,
  refreshFn: (rt: string) => Promise<GoogleTokens> = (rt) => refreshAccess(rt),
  now = Date.now(),
): Promise<{ ok: true; tokens: GoogleTokens; refreshed: boolean } | { ok: false; error: string }> {
  if (!tokens.expiry || tokens.expiry >= now + 30_000) return { ok: true, tokens, refreshed: false };
  if (!tokens.refresh_token) return { ok: false, error: "Calendar needs to be reconnected." };
  try {
    const next = await refreshFn(tokens.refresh_token);
    next.refresh_token = tokens.refresh_token;
    next.email = tokens.email;
    next.sub = tokens.sub;
    next.scope = next.scope || tokens.scope || "";
    return { ok: true, tokens: next, refreshed: true };
  } catch {
    return { ok: false, error: "Calendar needs to be reconnected." };
  }
}

import { createServerFn } from "@tanstack/react-start";
import { authMiddleware } from "@/lib/auth/middleware";
import {
  HIGH_TICKET_CITIES,
  HIGH_TICKET_VERTICALS,
  isAgentRole,
  isOrderKind,
  LINKEDIN_OUTREACH_SOFT_CAP_NOTE,
  type LinkedInAgentOrderKind,
  type LinkedInAgentRole,
  type JsonValue,
} from "./types";

export const listLinkedInAgentMessagesFn = createServerFn({ method: "GET" })
  .middleware([authMiddleware])
  .handler(async ({ context }) => {
    const { listMessages } = await import("./repo.server");
    const messages = await listMessages(context.userId);
    return { ok: true as const, messages };
  });

export const postLinkedInAgentMessageFn = createServerFn({ method: "POST" })
  .middleware([authMiddleware])
  .validator((data: { body: string; role?: LinkedInAgentRole; meta?: { [key: string]: JsonValue } }) => data)
  .handler(async ({ data, context }) => {
    const { postMessage } = await import("./repo.server");
    const role: LinkedInAgentRole = data.role && isAgentRole(data.role) ? data.role : "user";
    const body = String(data.body || "").trim();
    if (!body) return { ok: false as const, reason: "Message is empty." };
    const message = await postMessage(context.userId, role, body, data.meta || {});
    return { ok: true as const, message };
  });

export const listLinkedInAgentOrdersFn = createServerFn({ method: "GET" })
  .middleware([authMiddleware])
  .handler(async ({ context }) => {
    const { listOrders } = await import("./repo.server");
    const orders = await listOrders(context.userId, { limit: 30 });
    const pending = orders.filter((o) => o.status === "queued" || o.status === "claimed");
    return { ok: true as const, orders, pending };
  });

export const createLinkedInAgentOrderFn = createServerFn({ method: "POST" })
  .middleware([authMiddleware])
  .validator((data: {
    kind: LinkedInAgentOrderKind | string;
    payload?: { [key: string]: JsonValue };
    note?: string;
  }) => data)
  .handler(async ({ data, context }) => {
    const kindRaw = String(data.kind || "").trim();
    if (!isOrderKind(kindRaw)) {
      return { ok: false as const, reason: "Unknown order kind." };
    }
    const payload: { [key: string]: JsonValue } = { ...(data.payload || {}) };
    if (data.note) payload.note = String(data.note).slice(0, 2000);
    if (kindRaw === "outreach") {
      payload.safety_note = LINKEDIN_OUTREACH_SOFT_CAP_NOTE;
      payload.auto_send = false;
      payload.gmail_auto_send = false;
    }
    if (kindRaw === "enrich") {
      payload.contactability = "email_only";
      payload.do_not_invent_email = true;
      payload.gmail_auto_send = false;
      if (!payload.focus) payload.focus = "NEEDS_CONTACT_INFORMATION";
    }
    if (kindRaw === "fill_leads" && !payload.verticals) {
      payload.verticals = [...HIGH_TICKET_VERTICALS];
      payload.cities = [...HIGH_TICKET_CITIES];
      payload.source = "owner_or_ara";
    }
    const { createOrder, postMessage } = await import("./repo.server");
    const order = await createOrder(context.userId, kindRaw, payload);
    await postMessage(
      context.userId,
      "system",
      `Order queued: ${kindRaw} (${order.id.slice(0, 8)}…). LinkedIn Grok Bot will pick it up under soft caps. Nothing is sent.`,
      { order_id: order.id, kind: kindRaw },
    );
    return { ok: true as const, order };
  });

export const completeLinkedInAgentOrderFn = createServerFn({ method: "POST" })
  .middleware([authMiddleware])
  .validator((data: {
    orderId: string;
    status?: "done" | "failed" | "cancelled";
    result?: { [key: string]: JsonValue };
  }) => data)
  .handler(async ({ data, context }) => {
    const { completeOrder } = await import("./repo.server");
    const order = await completeOrder(context.userId, String(data.orderId || ""), {
      status: data.status || "done",
      result: data.result || {},
    });
    if (!order) return { ok: false as const, reason: "Order not found." };
    return { ok: true as const, order };
  });

