/**
 * PIPELINE_STATE_MISMATCH repair — booking-reconcile ONLY.
 *
 * Rules:
 * - Set stage to Call Booked ONLY when a booked calendar row already has googleEventId + prospect uid
 *   and the pipeline is still behind Call Booked (Proposal Sent, Negotiation, Won, Lost, and Do Not Contact stay put).
 * - Do NOT create new Google Calendar events.
 * - Do NOT invent bookings.
 * - BOOKING_PERSISTENCE_FAILED_AFTER_CALENDAR_CREATE is audited elsewhere (persistConfirmedBooking);
 *   this module only reconciles pipeline stage to proven calendar evidence.
 */
import { isTestWorkflowUid } from "./test-loop.ts";
import { promotedStageForBooking } from "./booking-stage.ts";
import type { InvariantSnapshot } from "../sentinel/types.ts";

export const BOOKING_INVARIANT_RECONCILED = "BOOKING_INVARIANT_RECONCILED";

/** Explicit: repair path never mutates Calendar / never creates events. */
export const BOOKING_REPAIR_MUTATES_CALENDAR = false as const;

export type BookingMismatchRow = {
  calendarId: string;
  googleEventId: string;
  prospectUid: string;
  title: string;
  calendarStatus: string;
  pipelineStage: string;
  isTest: boolean;
};

/** Proven association: booked calendar row + Google event id + existing prospect uid. */
export function shouldRepairPipelineMismatch(row: {
  googleEventId: string;
  prospectUid: string;
  calendarStatus: string;
  pipelineStage: string;
}): boolean {
  return Boolean(row.googleEventId && row.googleEventId.trim())
    && Boolean(row.prospectUid && row.prospectUid.trim())
    && row.calendarStatus === "booked"
    && promotedStageForBooking(row.pipelineStage) !== null;
}

/**
 * Harden note for BOOKING_PERSISTENCE_FAILED_AFTER_CALENDAR_CREATE:
 * when Calendar create succeeded but pipeline save failed, repair uses the
 * already-persisted googleEventId — never invents a second event.
 */
export function persistenceFailedRepairNote(googleEventId: string, prospectUid: string): string {
  const eid = (googleEventId || "").trim();
  const uid = (prospectUid || "").trim();
  if (!eid || !uid) {
    return "BOOKING_PERSISTENCE_FAILED_AFTER_CALENDAR_CREATE: missing proven googleEventId or prospect uid — will not invent a Calendar event.";
  }
  return `BOOKING_PERSISTENCE_FAILED_AFTER_CALENDAR_CREATE: reconciling pipeline to existing google_event_id=${eid} for uid=${uid}. No new Calendar event.`;
}

export function bookingLightFromInvariant(inv: Pick<InvariantSnapshot, "bookedMissingPipeline" | "bookedMissingEventId">): "green" | "red" {
  if (inv.bookedMissingPipeline.length || inv.bookedMissingEventId.length) return "red";
  return "green";
}

export async function loadBookingMismatchRows(userId: string): Promise<BookingMismatchRow[]> {
  const { getSql } = await import("@/lib/db");
  const sql = await getSql();
  const rows = await sql<{
    id: string;
    google_event_id: string;
    prospect_uid: string;
    title: string;
    status: string;
    stage: string;
  }>`
    select ce.id, ce.google_event_id, ce.prospect_uid, ce.title, ce.status, p.stage
    from calendar_events ce
    join prospects p on p.user_id = ce.user_id and p.uid = ce.prospect_uid
    where ce.user_id = ${userId}
      and ce.status = 'booked'
      and ce.google_event_id is not null and ce.google_event_id <> ''
      and coalesce(p.stage, '') not in ('Call Booked', 'Proposal Sent', 'Negotiation', 'Won', 'Lost', 'Do Not Contact')
  `;
  return rows.map((r) => ({
    calendarId: r.id,
    googleEventId: r.google_event_id,
    prospectUid: r.prospect_uid,
    title: r.title || "",
    calendarStatus: r.status,
    pipelineStage: r.stage || "",
    isTest: isTestWorkflowUid(r.prospect_uid),
  }));
}

export async function repairPipelineBookingMismatches(userId: string, sha = ""): Promise<{
  inspected: number;
  repaired: number;
  skipped: number;
  remaining: number;
  spoken: string;
  mutatedCalendar: typeof BOOKING_REPAIR_MUTATES_CALENDAR;
  rows: Array<{
    googleEventId: string;
    prospectUid: string;
    calendarId: string;
    fromStage: string;
    toStage: string;
    isTest: boolean;
    repaired: boolean;
    note: string;
    name: string;
  }>;
}> {
  const mismatches = await loadBookingMismatchRows(userId);
  const { applyExistingBookingToTestState } = await import("./booking-confirm.server");
  const { audit } = await import("./sql.server");
  const out: Array<{
    googleEventId: string;
    prospectUid: string;
    calendarId: string;
    fromStage: string;
    toStage: string;
    isTest: boolean;
    repaired: boolean;
    note: string;
    name: string;
  }> = [];
  let repaired = 0;
  let skipped = 0;
  for (const row of mismatches) {
    if (!shouldRepairPipelineMismatch(row)) {
      skipped += 1;
      out.push({
        googleEventId: row.googleEventId,
        prospectUid: row.prospectUid,
        calendarId: row.calendarId,
        fromStage: row.pipelineStage,
        toStage: row.pipelineStage,
        isTest: row.isTest,
        repaired: false,
        note: "Skipped — association not proven, or stage is already at or past Call Booked.",
        name: row.title || "A prospect",
      });
      continue;
    }
    // applyExistingBookingToTestState updates prospect stage + may upsert the EXISTING
    // calendar row metadata — it does not call Google Calendar create.
    await applyExistingBookingToTestState(userId, row.prospectUid, row.googleEventId, null, null, row.title);
    const note = persistenceFailedRepairNote(row.googleEventId, row.prospectUid);
    await audit(userId, BOOKING_INVARIANT_RECONCILED, `google_event_id=${row.googleEventId} uid=${row.prospectUid} ${row.pipelineStage}->Call Booked sha=${sha}`, {
      prospectUid: row.prospectUid,
      method: "MANUAL",
      providerIds: row.googleEventId,
    });
    repaired += 1;
    out.push({
      googleEventId: row.googleEventId,
      prospectUid: row.prospectUid,
      calendarId: row.calendarId,
      fromStage: row.pipelineStage,
      toStage: "Call Booked",
      isTest: row.isTest,
      repaired: true,
      note,
      name: row.title || "A prospect",
    });
  }
  const { getSql } = await import("@/lib/db");
  const sql = await getSql();
  const orphans = await sql<{ uid: string; name: string }>`
    select p.uid, p.name
    from prospects p
    where p.user_id = ${userId}
      and p.stage = 'Call Booked'
      and not exists (
        select 1 from calendar_events ce
        where ce.user_id = p.user_id and ce.prospect_uid = p.uid
          and ce.status = 'booked'
          and ce.google_event_id is not null and ce.google_event_id <> ''
      )
  `;
  const { getProspectByUid, upsertProspects } = await import("@/lib/prospects/repo.server");
  for (const orphan of orphans) {
    const prospect = await getProspectByUid(userId, orphan.uid);
    if (!prospect || prospect.stage !== "Call Booked") {
      skipped += 1;
      continue;
    }
    prospect.stage = "Approved for Outreach";
    prospect.stage_plain = "No calendar event — not Call Booked";
    await upsertProspects(userId, [prospect]);
    if (isTestWorkflowUid(orphan.uid)) {
      const { saveTestState } = await import("./sql.server");
      await saveTestState(userId, { pipeline_stage: "Approved for Outreach", event_id: "" });
    }
    await audit(userId, BOOKING_INVARIANT_RECONCILED, `uid=${orphan.uid} Call Booked->Approved for Outreach (no booked event) sha=${sha}`, {
      prospectUid: orphan.uid,
      method: "MANUAL",
    });
    repaired += 1;
    out.push({
      googleEventId: "",
      prospectUid: orphan.uid,
      calendarId: "",
      fromStage: "Call Booked",
      toStage: "Approved for Outreach",
      isTest: isTestWorkflowUid(orphan.uid),
      repaired: true,
      note: "Call Booked with no booked Google event. Moved back. No calendar event was created.",
      name: orphan.name || "A prospect",
    });
  }
  const remaining = (await loadBookingMismatchRows(userId)).length
    + (await sql<{ n: number }>`
      select count(*)::int as n from prospects p
      where p.user_id = ${userId} and p.stage = 'Call Booked'
        and not exists (
          select 1 from calendar_events ce
          where ce.user_id = p.user_id and ce.prospect_uid = p.uid
            and ce.status = 'booked'
            and ce.google_event_id is not null and ce.google_event_id <> ''
        )
    `)[0]?.n || 0;
  const spoken = repairSpeech({ repaired, remaining, rows: out });
  return {
    inspected: mismatches.length + orphans.length,
    repaired,
    skipped,
    remaining,
    spoken,
    mutatedCalendar: BOOKING_REPAIR_MUTATES_CALENDAR,
    rows: out,
  };
}

export function repairSpeech(result: {
  repaired: number;
  remaining: number;
  rows: Array<{ name?: string; repaired: boolean; toStage: string }>;
}): string {
  const fixed = result.rows.filter((row) => row.repaired);
  if (!fixed.length) {
    return "Pipeline and Calendar disagree, but I could not find a saved booking to correct. Nothing was changed, and no calendar event was created.";
  }
  const lines = fixed.map((row) => {
    const who = row.name || "A prospect";
    if (row.toStage === "Call Booked") return `${who} is now Call Booked, matching the calendar event.`;
    return `${who} said Call Booked, but there is no calendar event. I moved it back to Approved for Outreach.`;
  });
  return `${lines.join(" ")}${result.remaining ? ` ${result.remaining} still open.` : " That problem is fixed."}`;
}

/** Stages that already satisfy a booked Google Calendar event. Do not downgrade these. */
export const BOOKING_SATISFIED_STAGES = [
  "Call Booked",
  "Proposal Sent",
  "Negotiation",
  "Won",
] as const;

const SATISFIED = new Set<string>(BOOKING_SATISFIED_STAGES);

/** Non-canonical labels that mean the same as Call Booked and should be rewritten. */
const BOOKED_ALIASES = new Set(["Booked", "booked", "Call booked", "call booked"]);

export function isBookedStageAlias(stage: string | null | undefined): boolean {
  return BOOKED_ALIASES.has((stage || "").trim());
}

export function normalizeBookingStage(stage: string | null | undefined): string {
  const current = (stage || "").trim();
  if (!current) return "";
  if (BOOKED_ALIASES.has(current)) return "Call Booked";
  return current;
}

export function bookingSatisfied(stage: string | null | undefined): boolean {
  return SATISFIED.has(normalizeBookingStage(stage));
}

/**
 * Promote only when a booked event exists and the pipeline is still behind Call Booked.
 * Empty / blank stage counts as behind (Prospect UI hardcodes Status: Booked from calendar
 * evidence while prospects.stage may never have been set to Call Booked).
 * Alias "Booked" is rewritten to canonical Call Booked.
 */
export function promotedStageForBooking(stage: string | null | undefined): "Call Booked" | null {
  const raw = (stage || "").trim();
  if (!raw || isBookedStageAlias(raw)) return "Call Booked";
  if (bookingSatisfied(raw)) return null;
  if (raw === "Lost" || raw === "Do Not Contact") return null;
  return "Call Booked";
}

export type OfferedSlot = { start: Date; end: Date };

const SLOT_MS = 30 * 60 * 1000;
const MATCH_MS = 60 * 1000;

export function slotIsOffered(requested: OfferedSlot, offered: OfferedSlot[], now: Date): { ok: true } | { ok: false; reason: string } {
  if (Number.isNaN(requested.start.getTime()) || Number.isNaN(requested.end.getTime())) {
    return { ok: false, reason: "Pick a listed time." };
  }
  if (requested.start.getTime() <= now.getTime()) {
    return { ok: false, reason: "That time has already passed." };
  }
  const duration = requested.end.getTime() - requested.start.getTime();
  if (duration < SLOT_MS - MATCH_MS || duration > SLOT_MS + MATCH_MS) {
    return { ok: false, reason: "Meetings are 30 minutes. That time was not offered." };
  }
  const hit = offered.some(
    (s) =>
      Math.abs(s.start.getTime() - requested.start.getTime()) <= MATCH_MS &&
      Math.abs(s.end.getTime() - requested.end.getTime()) <= MATCH_MS,
  );
  if (!hit) return { ok: false, reason: "That time was not offered. Pick one of the listed times." };
  return { ok: true };
}

export type BookingLink = { token: string; status: "open" | "booking" | "used" | "expired"; expiresAt: number };

export function claimBooking(link: BookingLink, now: number): "won" | "used" | "expired" {
  if (now > link.expiresAt) return "expired";
  if (link.status !== "open") return "used";
  link.status = "booking";
  return "won";
}

export function makeBookingClaim(): (link: BookingLink, now: number) => Promise<"won" | "used" | "expired"> {
  let chain = Promise.resolve();
  return (link, now) => {
    let result: "won" | "used" | "expired" = "used";
    const next = chain.then(() => {
      result = claimBooking(link, now);
    });
    chain = next.then(() => undefined, () => undefined);
    return next.then(() => result);
  };
}

import { createCipheriv, createDecipheriv, createHash, randomBytes } from "node:crypto";

function keyBytes(): Buffer {
  const secret =
    process.env.APP_SECRET?.trim() ||
    process.env.BETTER_AUTH_SECRET?.trim() ||
    "dev-preview-only-not-for-production";
  return createHash("sha256").update(secret).digest();
}

export function encryptSecret(plain: string): { ciphertext: string; iv: string; tag: string } {
  const iv = randomBytes(12);
  const cipher = createCipheriv("aes-256-gcm", keyBytes(), iv);
  const enc = Buffer.concat([cipher.update(plain, "utf8"), cipher.final()]);
  const tag = cipher.getAuthTag();
  return {
    ciphertext: enc.toString("base64"),
    iv: iv.toString("base64"),
    tag: tag.toString("base64"),
  };
}

export function decryptSecret(parts: { ciphertext: string; iv: string; tag: string }): string {
  const decipher = createDecipheriv("aes-256-gcm", keyBytes(), Buffer.from(parts.iv, "base64"));
  decipher.setAuthTag(Buffer.from(parts.tag, "base64"));
  const dec = Buffer.concat([
    decipher.update(Buffer.from(parts.ciphertext, "base64")),
    decipher.final(),
  ]);
  return dec.toString("utf8");
}

import { DEFAULT_HOURS, type HoursConfig, withinWorkingHours } from "./hours.ts";
import type { InputMethod, ProspectMailView } from "./types.ts";
import { allowSendRecipient } from "./test-mode.ts";

export type GuardFail =
  | "DNC"
  | "UNSUBSCRIBED"
  | "BOUNCED"
  | "DISCONNECTED"
  | "NO_RECIPIENT"
  | "RATE_LIMIT"
  | "OUTSIDE_HOURS"
  | "NOT_APPROVED"
  | "NO_THREAD"
  | "SUPPRESSED"
  | "NOT_ALLOWLISTED";

export type Usage = { first: number; followups: number };
export type Caps = { maxFirst: number; maxFollowups: number };

export function reasonFor(code: GuardFail): string {
  switch (code) {
    case "DNC":
    case "SUPPRESSED":
      return "This company is on Do Not Contact. Nothing was sent.";
    case "UNSUBSCRIBED":
      return "They asked not to be contacted. Follow-ups are stopped. Nothing was sent.";
    case "BOUNCED":
      return "The last email bounced. We will not keep sending to this address.";
    case "DISCONNECTED":
      return "Gmail needs to be reconnected. No emails were sent while it was disconnected.";
    case "NO_RECIPIENT":
      return "We do not have a verified email address. We will not guess one.";
    case "RATE_LIMIT":
      return "Daily send limit reached. Try again tomorrow. Nothing extra was sent.";
    case "OUTSIDE_HOURS":
      return "Outside working hours. This follow-up is waiting until morning.";
    case "NOT_APPROVED":
      return "The first email still needs your approval. Nothing was sent.";
    case "NO_THREAD":
      return "We are not sure which Gmail thread to use. Check this prospect instead of guessing.";
    case "NOT_ALLOWLISTED":
      return "Test Mode is on. That address is not on your test list. Nothing was sent.";
  }
}

export function canSend(opts: {
  prospect: ProspectMailView;
  gmailConnected: boolean;
  recipient: string;
  kind: "email" | "followup1" | "followup2" | "followup3" | "reply";
  method: InputMethod;
  firstApproved: boolean;
  sequenceActive: boolean;
  bounced: boolean;
  unsubscribed: boolean;
  usage: Usage;
  caps: Caps;
  now: Date;
  hours?: HoursConfig;
  threadId?: string | null;
  skipHours?: boolean;
  testMode?: boolean;
  allowlist?: string[];
}): { ok: true } | { ok: false; code: GuardFail } {
  const p = opts.prospect;
  if (p.suppressed || p.stage === "Do Not Contact") return { ok: false, code: "DNC" };
  if (opts.unsubscribed) return { ok: false, code: "UNSUBSCRIBED" };
  if (opts.bounced) return { ok: false, code: "BOUNCED" };
  if (!opts.gmailConnected) return { ok: false, code: "DISCONNECTED" };
  if (!opts.recipient || opts.recipient === "UNKNOWN") return { ok: false, code: "NO_RECIPIENT" };
  const allow = allowSendRecipient({
    testMode: Boolean(opts.testMode),
    allowlist: opts.allowlist || [],
    recipient: opts.recipient,
  });
  if (!allow.ok) return { ok: false, code: "NOT_ALLOWLISTED" };
  if (opts.kind === "email" && !opts.firstApproved && opts.method !== "MANUAL" && opts.method !== "VOICE") {
    return { ok: false, code: "NOT_APPROVED" };
  }
  if (opts.kind !== "email" && opts.kind !== "reply") {
    if (!opts.sequenceActive) return { ok: false, code: "NOT_APPROVED" };
    if (!opts.threadId) return { ok: false, code: "NO_THREAD" };
  }
  const hours = opts.hours || DEFAULT_HOURS;
  if (opts.method === "AUTOMATION" && !opts.skipHours && !withinWorkingHours(opts.now, hours)) {
    return { ok: false, code: "OUTSIDE_HOURS" };
  }
  if (opts.kind === "email" && opts.usage.first >= opts.caps.maxFirst) return { ok: false, code: "RATE_LIMIT" };
  if (opts.kind.startsWith("follow") && opts.usage.followups >= opts.caps.maxFollowups) return { ok: false, code: "RATE_LIMIT" };
  return { ok: true };
}

/** GitHub's five-minute worker often lands 15–25 minutes apart. Alert only after a real stall. */
export const WORKER_STALE_MS = 45 * 60 * 1000;

export type WorkerLightState = "running" | "configured" | "missing";

export function minutesAgo(from: number, now: number): number {
  return Math.max(0, Math.floor((now - from) / 60000));
}

export function workerLight(opts: {
  secretPresent: boolean;
  lastCompletedAt: number | null;
  now: number;
  staleMs?: number;
  lastResult?: string;
}): { state: WorkerLightState; detail: string } {
  if (!opts.secretPresent && opts.lastCompletedAt == null) {
    return { state: "missing", detail: "🔴 Worker not configured" };
  }
  if ((opts.lastResult || "").startsWith("error")) {
    return { state: "configured", detail: "🔴 Worker last run failed" };
  }
  if (opts.lastCompletedAt == null) {
    return { state: "configured", detail: "🟡 Worker configured but no run observed yet" };
  }
  const staleMs = opts.staleMs ?? WORKER_STALE_MS;
  const mins = minutesAgo(opts.lastCompletedAt, opts.now);
  if (opts.now - opts.lastCompletedAt > staleMs) {
    return {
      state: "configured",
      detail: `🟡 Worker configured but last run was ${mins} minute${mins === 1 ? "" : "s"} ago`,
    };
  }
  return {
    state: "running",
    detail: `🟢 Worker running — last successful run ${mins} minute${mins === 1 ? "" : "s"} ago`,
  };
}

/** Scheduler ✅ needs a real tick that saw the test workflow. A secret or a sequence is not enough. */
export function schedulerEvidenceOk(opts: {
  secretPresent?: boolean;
  sequenceId?: string | null;
  followupsScheduled?: number;
  workerRunId?: string | null;
  workerSeenAt?: string | number | null;
}): boolean {
  void opts.secretPresent;
  void opts.sequenceId;
  void opts.followupsScheduled;
  return Boolean(opts.workerRunId) && Boolean(opts.workerSeenAt);
}

export type HoursConfig = {
  workStart: number;
  workEnd: number;
  workDays: number[];
  timezone: string;
};

export const DEFAULT_HOURS: HoursConfig = {
  workStart: 8,
  workEnd: 17,
  workDays: [1, 2, 3, 4, 5],
  timezone: "America/Chicago",
};

export function withinWorkingHours(now: Date, hours: HoursConfig): boolean {
  try {
    const parts = new Intl.DateTimeFormat("en-US", {
      timeZone: hours.timezone || DEFAULT_HOURS.timezone,
      weekday: "short",
      hour: "numeric",
      hour12: false,
    }).formatToParts(now);
    const weekday = parts.find((p) => p.type === "weekday")?.value || "";
    const hour = Number(parts.find((p) => p.type === "hour")?.value);
    const dayMap: Record<string, number> = { Sun: 0, Mon: 1, Tue: 2, Wed: 3, Thu: 4, Fri: 5, Sat: 6 };
    const day = dayMap[weekday.slice(0, 3)] ?? now.getDay();
    if (!hours.workDays.includes(day)) return false;
    if (!Number.isFinite(hour)) return false;
    return hour >= hours.workStart && hour < hours.workEnd;
  } catch {
    const day = now.getDay();
    const hour = now.getHours();
    return hours.workDays.includes(day) && hour >= hours.workStart && hour < hours.workEnd;
  }
}

export function weekdayMorning(hours: HoursConfig = DEFAULT_HOURS): Date {
  // Tuesday 10:00 in America/Chicago (CDT = UTC-5 in September).
  return new Date("2026-09-15T15:00:00.000Z");
}

export function weekdayNight(hours: HoursConfig = DEFAULT_HOURS): Date {
  return new Date("2026-09-15T03:30:00.000Z"); // Monday 22:30 Chicago
}

export function nextWorkingInstant(now: Date, hours: HoursConfig = DEFAULT_HOURS): Date {
  const cursor = new Date(now.getTime());
  if (withinWorkingHours(cursor, hours)) {
    cursor.setTime(cursor.getTime() + 30 * 60 * 1000);
  }
  for (let i = 0; i < 7 * 48; i += 1) {
    if (withinWorkingHours(cursor, hours)) return cursor;
    cursor.setTime(cursor.getTime() + 30 * 60 * 1000);
  }
  return new Date(now.getTime() + 24 * 60 * 60 * 1000);
}

export type ThreadMessage = {
  id: string;
  from: string;
  body: string;
  labelIds?: string[];
};

export function extractEmail(from: string): string {
  const m = (from || "").match(/<([^>]+)>/);
  return (m ? m[1] : from || "").trim().toLowerCase();
}

export function isOwnOutbound(msg: ThreadMessage, opts: { outboundIds: Set<string>; ownerEmail?: string }): boolean {
  if (opts.outboundIds.has(msg.id)) return true;
  const labels = (msg.labelIds || []).map((l) => l.toUpperCase());
  if (labels.includes("SENT")) return true;
  const owner = (opts.ownerEmail || "").trim().toLowerCase();
  if (owner && extractEmail(msg.from) === owner) return true;
  return false;
}

/** Only genuinely inbound messages. Our own sent mail is never a reply. */
export function inboundReplies(messages: ThreadMessage[], opts: { outboundIds: Set<string>; ownerEmail?: string }): ThreadMessage[] {
  return messages.filter((m) => !isOwnOutbound(m, opts));
}

import { env } from "@/lib/env.server";
import { googleOAuthConfigured } from "@/lib/google/oauth";
import { gmailProfile } from "@/lib/google/gmail";
import { probeFreeBusy } from "@/lib/google/calendar";
import { accessFor } from "./live.server";
import { googleStatus, loadSettings, loadWorkerHeartbeat } from "./sql.server";
import { secretPresent } from "./test-mode";
import { workerLight } from "./heartbeat";
import type { IntegrationStatus } from "./integration-status";

export async function loadIntegrationStatus(
  userId: string,
  opts?: { probeLive?: boolean },
): Promise<IntegrationStatus> {
  const settings = await loadSettings(userId);
  const accounts = await googleStatus(userId);
  const beat = await loadWorkerHeartbeat();
  const worker = workerLight({
    secretPresent: secretPresent(env("OUTREACH_JOB_SECRET") || env("CRON_SECRET")),
    lastCompletedAt: beat.lastCompletedAt,
    lastResult: beat.lastResult,
    now: Date.now(),
  });

  let gmail_token_valid = false;
  let gmail_identity = accounts.gmailEmail || "";
  if (accounts.gmail === "connected") {
    const tokens = await accessFor(userId, "gmail");
    gmail_token_valid = Boolean(tokens);
    if (tokens?.email) gmail_identity = tokens.email;
    if (opts?.probeLive && tokens) {
      const prof = await gmailProfile(tokens.access_token);
      if (prof.ok) gmail_identity = prof.email;
      else gmail_token_valid = false;
    }
  }

  let calendar_freebusy_valid = false;
  let calendar_token_valid = false;
  let calendar_identity = accounts.calendarEmail || "";
  let calendar_freebusy_code = "";
  let calendar_freebusy_detail = "";
  if (accounts.calendar === "connected" || accounts.calendar === "attention") {
    const tokens = await accessFor(userId, "calendar");
    calendar_token_valid = Boolean(tokens);
    if (tokens?.email) calendar_identity = tokens.email;
    if (tokens && opts?.probeLive) {
      const probe = await probeFreeBusy(tokens.access_token, fetch, calendar_identity || tokens.email, tokens.scope);
      calendar_freebusy_valid = probe.ok;
      if (!probe.ok) {
        calendar_freebusy_code = probe.code;
        calendar_freebusy_detail = probe.reason;
        calendar_token_valid = probe.code !== "CALENDAR_TOKEN_INVALID" && probe.code !== "TOKEN_INVALID" && probe.code !== "CALENDAR_TOKEN_REFRESH_FAILED";
      }
    }
  }

  return {
    google_oauth_configured: googleOAuthConfigured(),
    gmail_connected: accounts.gmail === "connected" || accounts.gmail === "attention",
    gmail_identity,
    gmail_token_valid,
    calendar_connected: accounts.calendar === "connected" || accounts.calendar === "attention",
    calendar_identity,
    calendar_token_valid,
    calendar_freebusy_valid,
    calendar_freebusy_code,
    calendar_freebusy_detail,
    worker_configured: worker.state !== "missing",
    worker_last_success: beat.lastCompletedAt ? new Date(beat.lastCompletedAt).toISOString() : null,
    worker_state: worker.state,
    worker_detail: worker.detail,
    test_mode: settings.testMode,
  };
}

