import { classifyReply } from "../outreach/reply.ts";
import { emailCannotBecomeCommand, looksLikeInjection } from "./untrusted.ts";
import { stopSequence } from "./sequence.ts";
import type { FollowupRecord, SequenceRecord } from "./types.ts";
import type { ReplyClass } from "../outreach/types.ts";

export type InboundMail = {
  id: string;
  from: string;
  body: string;
};

export function ingestReply(opts: {
  inbound: InboundMail;
  sequence: SequenceRecord;
  followups: FollowupRecord[];
  alreadySeen: Set<string>;
}): {
  classification: ReplyClass;
  sequence: SequenceRecord;
  followups: FollowupRecord[];
  unsubscribed: boolean;
  treatedAsCommand: boolean;
  duplicate: boolean;
} {
  if (opts.alreadySeen.has(opts.inbound.id)) {
    return {
      classification: "OTHER" as ReplyClass,
      sequence: opts.sequence,
      followups: opts.followups,
      unsubscribed: false,
      treatedAsCommand: false,
      duplicate: true,
    };
  }
  opts.alreadySeen.add(opts.inbound.id);
  const treatedAsCommand = false;
  emailCannotBecomeCommand(opts.inbound.body);
  void looksLikeInjection(opts.inbound.body);
  const classification = classifyReply(opts.inbound.body) as ReplyClass;
  const unsubscribed = classification === "UNSUBSCRIBE";
  const stopped = stopSequence(opts.followups, opts.sequence, unsubscribed ? "unsubscribe" : "reply");
  return {
    classification,
    sequence: stopped.sequence,
    followups: stopped.followups,
    unsubscribed,
    treatedAsCommand,
    duplicate: false,
  };
}

export type ReserveResult = "won" | "lost";

export type CapState = { first: number; followups: number; lastSentAt: number | null };

export type Caps = { maxFirst: number; maxFollowups: number; minDelayMinutes: number };

/** Mutex-friendly in-memory reservation used by tests and mirrored in SQL. */
export function makeKeyReserver(): (key: string) => Promise<ReserveResult> {
  let chain = Promise.resolve();
  const keys = new Set<string>();
  return (key: string) => {
    const run = chain.then((): ReserveResult => {
      if (keys.has(key)) return "lost";
      keys.add(key);
      return "won";
    });
    chain = run.then(() => undefined, () => undefined);
    return run;
  };
}

export function reserveCap(state: CapState, caps: Caps, kind: "first" | "followup", now: number): boolean {
  if (state.lastSentAt != null && now - state.lastSentAt < caps.minDelayMinutes * 60 * 1000) return false;
  if (kind === "first") {
    if (state.first >= caps.maxFirst) return false;
    state.first += 1;
  } else {
    if (state.followups >= caps.maxFollowups) return false;
    state.followups += 1;
  }
  state.lastSentAt = now;
  return true;
}

export function makeCapReserver(state: CapState, caps: Caps): (kind: "first" | "followup", now: number) => Promise<boolean> {
  let chain = Promise.resolve();
  return (kind, now) => {
    const run = chain.then(() => reserveCap(state, caps, kind, now));
    chain = run.then(() => undefined, () => undefined);
    return run;
  };
}

import { canSend, reasonFor, type Caps, type Usage } from "./guard.ts";
import { DEFAULT_HOURS, type HoursConfig } from "./hours.ts";
import type { EmailRecord, GmailPort, InputMethod, MailKind, ProspectMailView } from "./types.ts";
import type { ReserveResult } from "./reserve.ts";

export type SendDeps = {
  gmail: GmailPort | null;
  gmailConnected: boolean;
  usage: Usage;
  caps: Caps;
  hours?: HoursConfig;
  firstApproved: boolean;
  sequenceActive: boolean;
  bounced: boolean;
  unsubscribed: boolean;
  now?: Date;
  existingKeys: Set<string>;
  reserveKey?: (key: string) => Promise<ReserveResult>;
  reserveCap?: (kind: "first" | "followup") => Promise<boolean>;
  testMode?: boolean;
  allowlist?: string[];
  skipHours?: boolean;
};

export function idempotencyKey(userId: string, prospectUid: string, kind: string, sequenceId?: string): string {
  return `${userId}:${prospectUid}:${kind}:${sequenceId || "first"}`;
}

export async function sendMail(opts: {
  userId: string;
  prospect: ProspectMailView;
  kind: MailKind;
  method: InputMethod;
  to: string;
  subject: string;
  body: string;
  threadId?: string | null;
  sequenceId?: string | null;
  deps: SendDeps;
}): Promise<
  | { ok: true; record: EmailRecord }
  | { ok: false; reason: string; code: string; record?: EmailRecord }
> {
  const now = opts.deps.now || new Date();
  const key = idempotencyKey(opts.userId, opts.prospect.uid, opts.kind, opts.sequenceId || undefined);

  const gate = canSend({
    prospect: opts.prospect,
    gmailConnected: opts.deps.gmailConnected,
    recipient: opts.to,
    kind: opts.kind === "reply" ? "reply" : opts.kind,
    method: opts.method,
    firstApproved: opts.deps.firstApproved,
    sequenceActive: opts.deps.sequenceActive,
    bounced: opts.deps.bounced,
    unsubscribed: opts.deps.unsubscribed,
    usage: opts.deps.usage,
    caps: opts.deps.caps,
    now,
    hours: opts.deps.hours || DEFAULT_HOURS,
    threadId: opts.threadId,
    testMode: opts.deps.testMode,
    allowlist: opts.deps.allowlist,
    skipHours: opts.deps.skipHours,
  });
  if (!gate.ok) {
    return { ok: false, reason: reasonFor(gate.code), code: gate.code };
  }
  if (!opts.deps.gmail) {
    return { ok: false, reason: reasonFor("DISCONNECTED"), code: "DISCONNECTED" };
  }

  if (opts.deps.reserveKey) {
    const reserved = await opts.deps.reserveKey(key);
    if (reserved !== "won") {
      return { ok: false, reason: "This message is already being sent or was already sent.", code: "DUPLICATE" };
    }
  } else {
    if (opts.deps.existingKeys.has(key)) {
      return { ok: false, reason: "This message is already being sent or was already sent.", code: "DUPLICATE" };
    }
    opts.deps.existingKeys.add(key);
  }

  if (opts.deps.reserveCap) {
    const kind = opts.kind === "email" ? "first" : "followup";
    const capOk = await opts.deps.reserveCap(kind);
    if (!capOk) return { ok: false, reason: reasonFor("RATE_LIMIT"), code: "RATE_LIMIT" };
  }

  const sending: EmailRecord = {
    id: key,
    userId: opts.userId,
    prospectUid: opts.prospect.uid,
    direction: "out",
    recipient: opts.to,
    subject: opts.subject,
    body: opts.body,
    status: "SENDING",
    kind: opts.kind,
    idempotencyKey: key,
    inputMethod: opts.method,
    sequenceId: opts.sequenceId,
    threadId: opts.threadId,
    gmailThreadId: opts.threadId,
  };

  const result = await opts.deps.gmail.send({
    to: opts.to,
    subject: opts.subject,
    body: opts.body,
    threadId: opts.threadId,
  });

  if (!result.ok) {
    if (result.timeout || result.error === "timeout") {
      sending.status = "UNKNOWN_DELIVERY";
      return {
        ok: false,
        reason: "Gmail may have accepted this, but we did not get confirmation. It was NOT retried. Check Gmail, then mark it sent or try a new message.",
        code: "UNKNOWN_DELIVERY",
        record: sending,
      };
    }
    sending.status = result.bounced ? "BOUNCED" : "FAILED";
    return {
      ok: false,
      reason: result.disconnected
        ? reasonFor("DISCONNECTED")
        : "Lamb Ascension could not send this email. It has NOT been marked sent.",
      code: result.bounced ? "BOUNCED" : result.disconnected ? "DISCONNECTED" : "FAILED",
      record: sending,
    };
  }

  sending.status = "SENT";
  sending.gmailMessageId = result.messageId;
  sending.gmailThreadId = result.threadId;
  sending.threadId = result.threadId;
  sending.sentAt = now.toISOString();
  if (opts.kind === "email") opts.deps.usage.first += 1;
  else if (opts.kind.startsWith("follow")) opts.deps.usage.followups += 1;
  return { ok: true, record: sending };
}

import type { FollowupRecord, InputMethod, SequenceRecord } from "./types.ts";
import { contentHash } from "./snapshot.ts";
import { idempotencyKey } from "./send.ts";

const GAPS_MS = {
  followup1: 3 * 24 * 60 * 60 * 1000,
  followup2: 7 * 24 * 60 * 60 * 1000,
  followup3: 12 * 24 * 60 * 60 * 1000,
};

export function buildSequence(opts: {
  userId: string;
  prospectUid: string;
  method: InputMethod;
  now?: Date;
  recipient: string;
  subject: string;
  bodies: { followup1: string; followup2: string; followup3: string };
  threadId?: string | null;
}): { sequence: SequenceRecord; followups: FollowupRecord[] } {
  const now = opts.now || new Date();
  const sequence: SequenceRecord = {
    id: `${opts.userId}:${opts.prospectUid}:seq`,
    userId: opts.userId,
    prospectUid: opts.prospectUid,
    status: "active",
    approvedMethod: opts.method,
  };
  const steps = ["followup1", "followup2", "followup3"] as const;
  const followups: FollowupRecord[] = steps.map((step) => ({
    id: `${sequence.id}:${step}`,
    userId: opts.userId,
    prospectUid: opts.prospectUid,
    sequenceId: sequence.id,
    step,
    dueAt: now.getTime() + GAPS_MS[step],
    status: "scheduled",
    attemptCount: 0,
    idempotencyKey: idempotencyKey(opts.userId, opts.prospectUid, step, sequence.id),
    gmailThreadId: opts.threadId,
    body: opts.bodies[step],
    subject: opts.subject.startsWith("Re:") ? opts.subject : `Re: ${opts.subject}`,
    recipient: opts.recipient,
    approvedAt: now.toISOString(),
    contentHash: contentHash(opts.recipient, opts.subject.startsWith("Re:") ? opts.subject : `Re: ${opts.subject}`, opts.bodies[step]),
  }));
  return { sequence, followups };
}

export function stopSequence(followups: FollowupRecord[], sequence: SequenceRecord, why: string): { followups: FollowupRecord[]; sequence: SequenceRecord; why: string } {
  return {
    why,
    sequence: { ...sequence, status: "stopped" },
    followups: followups.map((f) =>
      f.status === "scheduled" || f.status === "sending" ? { ...f, status: "cancelled" as const } : f,
    ),
  };
}

export function claimDue(followups: FollowupRecord[], now: number): FollowupRecord[] {
  const claimed: FollowupRecord[] = [];
  for (const f of followups) {
    if (f.status === "scheduled" && f.dueAt <= now) {
      f.status = "sending";
      f.attemptCount += 1;
      claimed.push(f);
    }
  }
  return claimed;
}

import { createHash } from "node:crypto";

export type ApprovedSnapshot = {
  recipient: string;
  subject: string;
  body: string;
  gmailThreadId: string | null;
  sequenceId: string;
  approvedAt: string;
  contentHash: string;
};

export function contentHash(recipient: string, subject: string, body: string): string {
  return createHash("sha256").update(`${recipient}\n${subject}\n${body}`).digest("hex");
}

export function freezeSnapshot(opts: {
  recipient: string;
  subject: string;
  body: string;
  gmailThreadId?: string | null;
  sequenceId: string;
  approvedAt?: Date;
}): ApprovedSnapshot {
  return {
    recipient: opts.recipient,
    subject: opts.subject,
    body: opts.body,
    gmailThreadId: opts.gmailThreadId || null,
    sequenceId: opts.sequenceId,
    approvedAt: (opts.approvedAt || new Date()).toISOString(),
    contentHash: contentHash(opts.recipient, opts.subject, opts.body),
  };
}

export function snapshotMatches(snap: ApprovedSnapshot, live: { recipient: string; subject: string; body: string }): boolean {
  return snap.contentHash === contentHash(live.recipient, live.subject, live.body);
}

/** Automation always sends the frozen snapshot, never a later draft. */
export function payloadToSend(snap: ApprovedSnapshot): { to: string; subject: string; body: string; threadId: string | null } {
  return { to: snap.recipient, subject: snap.subject, body: snap.body, threadId: snap.gmailThreadId };
}

