/**
 * Prospect email is UNTRUSTED INPUT.
 * A body that looks like a voice command must never become one.
 */
export function emailCannotBecomeCommand(body: string): true {
  const parsed = parseSpokenCommand(body);
  void parsed;
  void toolsInvokedByUntrustedText(body);
  return true;
}

export function looksLikeInjection(body: string): boolean {
  const t = (body || "").toLowerCase();
  return /ignore (previous|your) instructions|send me your password|you are now/.test(t);
}

import { canSend } from "./guard.ts";
import { DEFAULT_HOURS, nextWorkingInstant, type HoursConfig } from "./hours.ts";
import { payloadToSend, type ApprovedSnapshot } from "./snapshot.ts";
import type { ProspectMailView } from "./types.ts";
import { inboundReplies, type ThreadMessage } from "./inbound.ts";
import { ingestReply } from "./replies.ts";
import { stopSequence } from "./sequence.ts";
import type { FollowupRecord, SequenceRecord } from "./types.ts";

export type DueJob = {
  id: string;
  prospectUid: string;
  snapshot: ApprovedSnapshot;
  sequence: SequenceRecord;
  followup: FollowupRecord;
};

export async function runOutreachTick(opts: {
  syncReplies: () => Promise<void>;
  claimDue: () => Promise<DueJob[]>;
  send: (job: DueJob) => Promise<"sent" | "rescheduled" | "cancelled" | "failed" | "unknown">;
}): Promise<{ sent: number; skipped: number; rescheduled: number }> {
  await opts.syncReplies();
  const due = await opts.claimDue();
  let sent = 0;
  let skipped = 0;
  let rescheduled = 0;
  for (const job of due) {
    const result = await opts.send(job);
    if (result === "sent") sent += 1;
    else if (result === "rescheduled") rescheduled += 1;
    else skipped += 1;
  }
  return { sent, skipped, rescheduled };
}

export function decideFollowupSend(opts: {
  prospect: ProspectMailView;
  sequenceActive: boolean;
  snapshot: ApprovedSnapshot;
  now: Date;
  hours: HoursConfig;
  gmailConnected: boolean;
  testMode?: boolean;
  allowlist?: string[];
  skipHours?: boolean;
  bounced?: boolean;
}): { action: "send" | "reschedule" | "cancel"; dueAt?: Date; reason: string } {
  const stage = opts.prospect.stage || "";
  if (
    !opts.sequenceActive
    || opts.prospect.suppressed
    || stage === "Do Not Contact"
    || stage === "Won"
    || stage === "Lost"
    || stage === "Call Booked"
  ) {
    return { action: "cancel", reason: "Sequence stopped. Follow-up was not sent." };
  }
  const gate = canSend({
    prospect: opts.prospect,
    gmailConnected: opts.gmailConnected,
    recipient: opts.snapshot.recipient,
    kind: "followup1",
    method: "AUTOMATION",
    firstApproved: true,
    sequenceActive: true,
    bounced: Boolean(opts.bounced),
    unsubscribed: false,
    usage: { first: 0, followups: 0 },
    caps: { maxFirst: 999, maxFollowups: 999 },
    now: opts.now,
    hours: opts.hours || DEFAULT_HOURS,
    threadId: opts.snapshot.gmailThreadId,
    testMode: opts.testMode,
    allowlist: opts.allowlist,
    skipHours: opts.skipHours,
  });
  if (!gate.ok && gate.code === "OUTSIDE_HOURS") {
    return { action: "reschedule", dueAt: nextWorkingInstant(opts.now, opts.hours || DEFAULT_HOURS), reason: "Outside working hours. Waiting until the next work window." };
  }
  if (!gate.ok) return { action: "cancel", reason: gate.code };
  return { action: "send", reason: "ok" };
}

export function processThread(opts: {
  messages: ThreadMessage[];
  outboundIds: Set<string>;
  ownerEmail: string;
  sequence: SequenceRecord;
  followups: FollowupRecord[];
  alreadySeen: Set<string>;
}): { replies: number; sequence: SequenceRecord; followups: FollowupRecord[] } {
  const inbound = inboundReplies(opts.messages, { outboundIds: opts.outboundIds, ownerEmail: opts.ownerEmail });
  let sequence = opts.sequence;
  let followups = opts.followups;
  let replies = 0;
  for (const m of inbound) {
    const r = ingestReply({
      inbound: { id: m.id, from: m.from, body: m.body },
      sequence,
      followups,
      alreadySeen: opts.alreadySeen,
    });
    if (r.duplicate) continue;
    replies += 1;
    sequence = r.sequence;
    followups = r.followups;
  }
  if (replies === 0) return { replies: 0, sequence, followups };
  const stopped = stopSequence(followups, sequence, "reply");
  return { replies, sequence: stopped.sequence, followups: stopped.followups };
}

export { payloadToSend };

export { P2PRoom, defaultIceServers } from "./p2p";
export type {
  PeerInfo,
  P2PRoomOptions,
  SignalKind,
  PeerRow,
  SignalRow,
  RtcPollResponse,
} from "./p2p";

/**
 * Full-mesh WebRTC rooms: one RTCPeerConnection per remote peer, signaled
 * through /api/rtc (see signaling.server.ts), game data flowing directly
 * browser-to-browser afterwards. Client-authoritative by construction — see
 * the multiplayer-p2p skill for when NOT to use this.
 *
 * Negotiation follows the "perfect negotiation" pattern: on a glare (both
 * sides offering at once) the polite peer — the lexicographically smaller id —
 * rolls back and accepts, so pairs converge without wedging.
 */

export type SignalKind = "offer" | "answer" | "ice";

/**
 * Wire contract between this client and the signaling relay the app provides
 * at /api/rtc (see the multiplayer-p2p skill for a reference implementation).
 * The client only needs these shapes — the relay's storage is the app's choice.
 */
export interface PeerRow {
  id: string;
  name: string;
}
export interface SignalRow {
  id: number;
  from: string;
  kind: SignalKind;
  payload: unknown;
}
export interface RtcPollResponse {
  peers: PeerRow[];
  signals: SignalRow[];
}

export interface PeerInfo {
  id: string;
  name: string;
  connectionState: RTCPeerConnectionState;
  /** Selected local ICE candidate type: host | srflx | prflx | relay. */
  candidateType: string | null;
  /** Data-channel ping RTT (ms), measured every 2s once connected. */
  rttMs: number | null;
}

export interface P2PRoomOptions {
  room: string;
  selfId: string;
  name?: string;
  /** Defaults to VITE_STUN_URLS (comma-separated) or Google public STUN. */
  iceServers?: RTCIceServer[];
  onPeersChanged?: (peers: PeerInfo[]) => void;
  /** Fires for both the unreliable "state" and reliable "reliable" channels. */
  onMessage?: (from: string, data: unknown, channel: "state" | "reliable") => void;
  /** Fires once, on the first successful signaling poll (registration). */
  onConnected?: () => void;
}

interface PeerSlot {
  pc: RTCPeerConnection;
  state?: RTCDataChannel;
  reliable?: RTCDataChannel;
  makingOffer: boolean;
  ignoreOffer: boolean;
  /** ICE candidates that arrived before the remote description (buffered). */
  pendingCandidates: RTCIceCandidateInit[];
  /** Last time this pair made observable progress toward connected. */
  lastProgressAt: number;
  /** Watchdog recreations (dialer) / stall windows (receiver) so far. */
  recoveryAttempts: number;
  /** Gave up after MAX_RECOVERY_ATTEMPTS — excluded from fast-poll pressure. */
  terminal?: boolean;
  /** One-shot: pc was already recreated to absorb a failing remote offer. */
  recreatedForOffer?: boolean;
  info: PeerInfo;
  pingSentAt?: number;
}

const FAST_POLL_MS = 400;
const IDLE_POLL_MS = 2000;
const PING_INTERVAL_MS = 2000;
const STALL_MS = 10_000;
const MAX_RECOVERY_ATTEMPTS = 3;
const SIGNAL_RETRY_DELAYS_MS = [250, 750];

export function defaultIceServers(): RTCIceServer[] {
  const urls = (import.meta.env.VITE_STUN_URLS as string | undefined)
    ?.split(",")
    .map((u) => u.trim())
    .filter(Boolean);
  // Two independent providers: ICE queries all of them in parallel during
  // gathering, so either one being unreachable costs nothing.
  return [
    {
      urls: urls?.length ? urls : ["stun:stun.l.google.com:19302", "stun:stun.cloudflare.com:3478"],
    },
  ];
}

export class P2PRoom {
  private readonly opts: P2PRoomOptions;
  private readonly peers = new Map<string, PeerSlot>();
  /** Per-remote-peer signal delivery chains (order-preserving). */
  private readonly signalQueues = new Map<string, Promise<void>>();
  private cursor = 0;
  private pollTimer: ReturnType<typeof setTimeout> | null = null;
  private pingTimer: ReturnType<typeof setInterval> | null = null;
  private closed = false;
  private everPolled = false;
  private lastPeersFingerprint = "";

  constructor(opts: P2PRoomOptions) {
    this.opts = opts;
  }

  /**
   * The first poll IS the join: it registers this peer and returns the
   * roster. A failed first poll (cold DB, offline tab) must not strand the
   * room: the loop and timers start regardless and the next poll retries.
   */
  async join(): Promise<void> {
    try {
      await this.pollOnce();
    } catch {
      // First poll can fail transiently; the scheduled loop below retries.
    }
    if (this.closed) return;
    this.schedulePoll(this.anyPairConnecting() ? FAST_POLL_MS : IDLE_POLL_MS);
    this.pingTimer = setInterval(() => {
      this.pingAll();
      this.watchdog();
    }, PING_INTERVAL_MS);
  }

  close(): void {
    this.closed = true;
    if (this.pollTimer) clearTimeout(this.pollTimer);
    if (this.pingTimer) clearInterval(this.pingTimer);
    for (const slot of this.peers.values()) slot.pc.close();
    this.peers.clear();
    // Leaving the roster is the teardown broadcast: everyone's next poll
    // drops this peer and closes their side of the pair.
    void fetch("/api/rtc", {
      method: "POST",
      headers: { "content-type": "application/json" },
      body: JSON.stringify({ op: "leave", room: this.opts.room, peer: this.opts.selfId }),
      keepalive: true,
    }).catch(() => {});
  }

  /** Send on the unreliable game-state channel (drops stale packets). */
  broadcast(data: unknown): void {
    const wire = JSON.stringify({ t: "d", d: data });
    for (const slot of this.peers.values()) {
      if (slot.state?.readyState === "open") slot.state.send(wire);
    }
  }

  /** Send reliably (ordered) to one peer, or to all when peerId is omitted. */
  send(data: unknown, peerId?: string): void {
    const wire = JSON.stringify({ t: "d", d: data });
    const targets = peerId ? [this.peers.get(peerId)] : [...this.peers.values()];
    for (const slot of targets) {
      if (slot?.reliable?.readyState === "open") slot.reliable.send(wire);
    }
  }

  peerList(): PeerInfo[] {
    return [...this.peers.values()].map((s) => ({ ...s.info }));
  }

  // ── signaling loop ─────────────────────────────────────────────────────────

  private schedulePoll(delay: number): void {
    if (this.closed) return;
    if (this.pollTimer) clearTimeout(this.pollTimer);
    this.pollTimer = setTimeout(() => void this.poll(), delay);
  }

  private anyPairConnecting(): boolean {
    for (const s of this.peers.values()) {
      // Terminal pairs (NAT-blocked after all recovery attempts) must not pin
      // the session at the 400ms fast-poll rate.
      if (s.terminal) continue;
      if (s.info.connectionState !== "connected") return true;
    }
    return false;
  }

  private async pollOnce(): Promise<void> {
    const params = new URLSearchParams({
      room: this.opts.room,
      peer: this.opts.selfId,
      name: this.opts.name ?? "",
      since: String(this.cursor),
    });
    const res = await fetch(`/api/rtc?${params}`);
    if (this.closed) return;
    if (!res.ok) throw new Error(`signaling poll failed: ${res.status}`);
    const body = (await res.json()) as RtcPollResponse;
    if (this.closed) return;
    if (!this.everPolled) {
      this.everPolled = true;
      this.opts.onConnected?.();
    }
    this.reconcileRoster(body.peers);
    const roster = new Set(body.peers.map((p) => p.id));
    for (const sig of body.signals) {
      this.cursor = Math.max(this.cursor, sig.id);
      await this.onSignal(sig.from, sig.kind, sig.payload, roster);
      if (this.closed) return;
    }
  }

  private async poll(): Promise<void> {
    if (this.closed) return;
    try {
      await this.pollOnce();
    } catch {
      // Transient poll failures are expected (tab sleep, deploy roll); retry.
    }
    this.schedulePoll(this.anyPairConnecting() ? FAST_POLL_MS : IDLE_POLL_MS);
  }

  private reconcileRoster(peers: { id: string; name: string }[]): void {
    const alive = new Set(peers.map((p) => p.id));
    for (const p of peers) {
      if (p.id === this.opts.selfId) continue;
      const existing = this.peers.get(p.id);
      if (existing) {
        existing.info.name = p.name;
      } else {
        // Exactly one side dials each pair; the other waits for the offer.
        this.connectTo(p.id, p.name, this.opts.selfId > p.id);
      }
    }
    for (const [id, slot] of this.peers) {
      if (!alive.has(id)) {
        slot.pc.close();
        this.peers.delete(id);
      }
    }
    this.emitPeers();
  }

  // ── per-pair connection ────────────────────────────────────────────────────

  private connectTo(peerId: string, name: string, initiator: boolean): PeerSlot | null {
    if (this.closed) return null;
    const pc = new RTCPeerConnection({
      iceServers: this.opts.iceServers ?? defaultIceServers(),
    });
    const slot: PeerSlot = {
      pc,
      makingOffer: false,
      ignoreOffer: false,
      pendingCandidates: [],
      lastProgressAt: Date.now(),
      recoveryAttempts: 0,
      info: {
        id: peerId,
        name,
        connectionState: pc.connectionState,
        candidateType: null,
        rttMs: null,
      },
    };
    this.peers.set(peerId, slot);

    pc.onicecandidate = (e) => {
      if (e.candidate) void this.sendSignal(peerId, "ice", e.candidate.toJSON());
    };
    pc.onconnectionstatechange = () => {
      slot.info.connectionState = pc.connectionState;
      if (pc.connectionState === "connecting" || pc.connectionState === "connected") {
        slot.lastProgressAt = Date.now();
      }
      if (pc.connectionState === "connected") {
        slot.recoveryAttempts = 0;
        slot.terminal = false;
        void this.readCandidateType(slot);
      }
      this.emitPeers();
      if (pc.connectionState === "failed") {
        // Refires negotiationneeded → a fresh offer through signaling, so a
        // lost offer or dead path cannot wedge the pair (glare-safe).
        pc.restartIce();
      }
      if (pc.connectionState === "failed" || pc.connectionState === "disconnected") {
        this.schedulePoll(FAST_POLL_MS);
      }
    };
    pc.onnegotiationneeded = async () => {
      try {
        slot.makingOffer = true;
        await pc.setLocalDescription();
        await this.sendSignal(peerId, "offer", pc.localDescription!.toJSON());
      } catch {
        // A failed offer is retried on the next negotiationneeded.
      } finally {
        slot.makingOffer = false;
      }
    };
    pc.ondatachannel = (e) => this.attachChannel(slot, e.channel);

    if (initiator) {
      // Creating the channels triggers negotiationneeded → the offer.
      this.attachChannel(
        slot,
        pc.createDataChannel("state", { ordered: false, maxRetransmits: 0 }),
      );
      this.attachChannel(slot, pc.createDataChannel("reliable", { ordered: true }));
    }
    return slot;
  }

  private attachChannel(slot: PeerSlot, channel: RTCDataChannel): void {
    if (channel.label === "state") slot.state = channel;
    else slot.reliable = channel;
    channel.onopen = () => {
      slot.lastProgressAt = Date.now();
    };
    channel.onmessage = (e) => {
      let msg: { t: string; d?: unknown };
      try {
        msg = JSON.parse(e.data as string) as { t: string; d?: unknown };
      } catch {
        return;
      }
      if (msg.t === "ping") {
        if (slot.state?.readyState === "open") {
          slot.state.send(JSON.stringify({ t: "pong" }));
        }
      } else if (msg.t === "pong") {
        if (slot.pingSentAt) {
          slot.info.rttMs = Math.round(performance.now() - slot.pingSentAt);
          slot.pingSentAt = undefined;
          this.emitPeers();
        }
      } else {
        this.opts.onMessage?.(
          slot.info.id,
          msg.d,
          channel.label === "state" ? "state" : "reliable",
        );
      }
    };
  }

  /** Apply buffered ICE candidates once a remote description is in place. */
  private async flushPendingCandidates(slot: PeerSlot): Promise<void> {
    while (slot.pendingCandidates.length > 0) {
      const candidate = slot.pendingCandidates.shift()!;
      try {
        await slot.pc.addIceCandidate(candidate);
      } catch (err) {
        if (!slot.ignoreOffer) console.warn("[p2p] addIceCandidate failed:", err);
      }
      if (this.closed) return;
    }
  }

  private async onSignal(
    from: string,
    kind: SignalKind,
    payload: unknown,
    roster: Set<string>,
  ): Promise<void> {
    if (this.closed) return;
    let slot = this.peers.get(from);
    if (!slot) {
      // New peers dial us in the same poll that adds them to the roster.
      // Signals outlive membership, so drop senders the roster doesn't vouch for.
      if (!roster.has(from)) return;
      const created = this.connectTo(from, "", false);
      if (!created) return;
      slot = created;
    }
    const polite = this.opts.selfId < from;

    try {
      if (kind === "offer" || kind === "answer") {
        const description = payload as RTCSessionDescriptionInit;
        const collision =
          kind === "offer" && (slot.makingOffer || slot.pc.signalingState !== "stable");
        slot.ignoreOffer = !polite && collision;
        if (slot.ignoreOffer) return;
        try {
          await slot.pc.setRemoteDescription(description); // implicit rollback when polite
        } catch (err) {
          // A pc resumed from suspend can be unable to take any new remote
          // offer (stale DTLS fingerprint). Rebuild the pair once and apply
          // the same offer to the fresh pc before giving up.
          if (kind !== "offer" || slot.recreatedForOffer) throw err;
          const attempts = slot.recoveryAttempts;
          const name = slot.info.name;
          slot.pc.close();
          this.peers.delete(from);
          const fresh = this.connectTo(from, name, false);
          if (!fresh) return;
          fresh.recoveryAttempts = attempts;
          fresh.recreatedForOffer = true;
          slot = fresh;
          await slot.pc.setRemoteDescription(description);
        }
        if (this.closed) return;
        await this.flushPendingCandidates(slot);
        if (this.closed) return;
        if (kind === "offer") {
          await slot.pc.setLocalDescription();
          if (this.closed) return;
          await this.sendSignal(from, "answer", slot.pc.localDescription!.toJSON());
        }
      } else if (kind === "ice") {
        const candidate = payload as RTCIceCandidateInit;
        if (!slot.pc.remoteDescription) {
          // Candidate raced ahead of its SDP — hold it until the description
          // lands (flushed after every successful setRemoteDescription).
          slot.pendingCandidates.push(candidate);
          return;
        }
        try {
          await slot.pc.addIceCandidate(candidate);
        } catch (err) {
          // The enclosing catch would swallow a rethrow; log the real signal.
          if (!slot.ignoreOffer) console.warn("[p2p] addIceCandidate failed:", err);
        }
      }
    } catch {
      // Negotiation errors resolve on the next offer cycle; state is visible
      // to the app via connectionState.
    }
  }

  /**
   * Signals are serialized per remote peer (a candidate must never overtake
   * its SDP into the DB) and retried on failure with short backoff.
   */
  private sendSignal(to: string, kind: SignalKind, payload: unknown): Promise<void> {
    const prev = this.signalQueues.get(to) ?? Promise.resolve();
    const next = prev.then(() => this.postSignal(to, kind, payload));
    this.signalQueues.set(
      to,
      next.catch(() => {}),
    );
    return next;
  }

  private async postSignal(to: string, kind: SignalKind, payload: unknown): Promise<void> {
    for (let attempt = 0; ; attempt++) {
      if (this.closed) return;
      try {
        const res = await fetch("/api/rtc", {
          method: "POST",
          headers: { "content-type": "application/json" },
          body: JSON.stringify({
            op: "signal",
            room: this.opts.room,
            from: this.opts.selfId,
            to,
            kind,
            payload,
          }),
        });
        if (res.ok) return;
        throw new Error(`signal POST failed: ${res.status}`);
      } catch (err) {
        if (attempt >= SIGNAL_RETRY_DELAYS_MS.length) {
          // Delivery gave up; the pair converges on the next offer cycle (or
          // the watchdog rebuilds it). Logged once so failures are visible.
          console.warn(`[p2p] signal ${kind} to ${to} failed after retries`, err);
          return;
        }
        await new Promise((r) => setTimeout(r, SIGNAL_RETRY_DELAYS_MS[attempt]));
      }
    }
  }

  // ── diagnostics + recovery ─────────────────────────────────────────────────

  private pingAll(): void {
    const wire = JSON.stringify({ t: "ping" });
    for (const slot of this.peers.values()) {
      if (slot.state?.readyState !== "open") continue;
      const stale =
        slot.pingSentAt !== undefined && performance.now() - slot.pingSentAt > 2 * PING_INTERVAL_MS;
      if (slot.pingSentAt === undefined || stale) {
        // A lost pong must not freeze rttMs forever: expire and re-ping.
        slot.pingSentAt = performance.now();
        slot.state.send(wire);
      }
    }
  }

  /**
   * Stuck-pair recovery, piggybacked on the ping interval. A pair that has
   * made no progress for STALL_MS gets rebuilt by the dialer with a FRESH
   * RTCPeerConnection (new DTLS identity — fixes the suspend/resume
   * fingerprint wedge). After MAX_RECOVERY_ATTEMPTS the pair is terminal:
   * visible to the app as its last connectionState, ignored by fast-poll.
   */
  private watchdog(): void {
    if (this.closed) return;
    const now = Date.now();
    for (const [peerId, slot] of this.peers) {
      // pc.close() and some suspend/resume wedges never fire
      // connectionstatechange — read the LIVE state so a silently-dead pc
      // still trips the stall timer instead of hiding behind a cached
      // "connected". Only live progress states refresh the stall clock.
      const live = slot.pc.connectionState;
      if (live !== slot.info.connectionState) {
        slot.info.connectionState = live;
        if (live === "connecting" || live === "connected") slot.lastProgressAt = now;
        this.emitPeers();
      }
      if (slot.terminal || live === "connected") continue;
      if (now - slot.lastProgressAt <= STALL_MS) continue;
      if (slot.recoveryAttempts >= MAX_RECOVERY_ATTEMPTS) {
        slot.terminal = true;
        this.emitPeers();
        continue;
      }
      slot.recoveryAttempts += 1;
      slot.lastProgressAt = now; // re-arm the stall window
      if (this.opts.selfId > peerId) {
        // We are the dialer: rebuild the pair from scratch.
        const { name } = slot.info;
        const attempts = slot.recoveryAttempts;
        slot.pc.close();
        this.peers.delete(peerId);
        const fresh = this.connectTo(peerId, name, true);
        if (fresh) fresh.recoveryAttempts = attempts;
        this.schedulePoll(FAST_POLL_MS);
      }
      // Receiver side: count the stall window and wait for the dialer's
      // fresh offer (onSignal absorbs it, recreating our pc if needed).
    }
  }

  private async readCandidateType(slot: PeerSlot): Promise<void> {
    // relay = TURN (none configured by default); srflx/host = direct path.
    try {
      const stats = await slot.pc.getStats();
      let selected: RTCIceCandidatePairStats | undefined;
      stats.forEach((s) => {
        if (s.type === "candidate-pair" && (s as RTCIceCandidatePairStats).nominated) {
          selected = s as RTCIceCandidatePairStats;
        }
      });
      const localId = selected?.localCandidateId;
      if (localId) {
        const local = stats.get(localId) as { candidateType?: string } | undefined;
        slot.info.candidateType = local?.candidateType ?? null;
        this.emitPeers();
      }
    } catch {
      // getStats is best-effort diagnostics only.
    }
  }

  private emitPeers(): void {
    // Only notify when something observable actually changed — React state
    // setters otherwise re-render consumers on every poll/ping.
    const list = this.peerList();
    const fingerprint = JSON.stringify(
      list.map((p) => [p.id, p.name, p.connectionState, p.candidateType, p.rttMs]),
    );
    if (fingerprint === this.lastPeersFingerprint) return;
    this.lastPeersFingerprint = fingerprint;
    this.opts.onPeersChanged?.(list);
  }
}

import type { PackedContext } from "./pack.ts";
import type { OutreachPack, OutreachMessage } from "./types.ts";
import { composeOutreachEmail } from "./email-copy.ts";

function has(ctx: PackedContext, code: string): boolean {
  return ctx.opportunities.some((o) => o.code === code) || ctx.facts.some((f) => f.key === code);
}

function greeting(ctx: PackedContext): string {
  if (ctx.contact_name !== "UNKNOWN") return ctx.contact_name.split(" ")[0] || ctx.contact_name;
  return "there";
}

function observation(ctx: PackedContext): { text: string; evidence: string[]; angle: string; why: string } {
  if (has(ctx, "NO_HOMEPAGE_FORM") && has(ctx, "contact_form_inner")) {
    return {
      text: `I opened ${ctx.name}'s homepage and didn’t see a contact form there — a form did show up on an inside page.`,
      evidence: ["NO_HOMEPAGE_FORM", "contact_form_inner"],
      angle: "Homepage makes it harder to inquire than it needs to",
      why: "We verified no homepage form, and a form on an inner page. That’s a specific, checkable reason to talk — not a guess about their revenue.",
    };
  }
  if (has(ctx, "NO_HOMEPAGE_FORM")) {
    return {
      text: `I opened ${ctx.name}'s homepage and did not find a contact form on that page.`,
      evidence: ["NO_HOMEPAGE_FORM"],
      angle: "Homepage inquire path is weak",
      why: "Verified: no contact form on the homepage.",
    };
  }
  if (has(ctx, "NO_HOMEPAGE_CTA")) {
    return {
      text: `On ${ctx.name}'s homepage I didn’t see a clear “get a quote” / estimate ask near the top.`,
      evidence: ["NO_HOMEPAGE_CTA"],
      angle: "Next step isn’t obvious on the first screen",
      why: "Verified: no common quote/estimate CTA in the first content.",
    };
  }
  if (has(ctx, "case_studies") || ctx.facts.some((f) => /case-study/i.test(f.text))) {
    return {
      text: `${ctx.name} publishes case-study / client-story language, which is a different conversation than a local service ad.`,
      evidence: ["case_studies"],
      angle: "Demand-gen for a firm that already shows client work",
      why: "Observed case-study wording on a page we opened. That is wording, not verified contract value.",
    };
  }
  if (has(ctx, "enterprise_language") || ctx.facts.some((f) => /enterprise \/ b2b/i.test(f.text))) {
    return {
      text: `${ctx.name}’s site is written for businesses, not just local consumers.`,
      evidence: ["enterprise_language"],
      angle: "B2B / software acquisition, not a generic local-lead pitch",
      why: "Observed enterprise/B2B wording on a page we opened.",
    };
  }
  if (ctx.research_status === "blocked" || ctx.research_status === "failed") {
    const bits = [`${ctx.name} is a ${ctx.vertical.toLowerCase()} company in ${ctx.city}`];
    if (ctx.reviews) bits.push(`with ${ctx.reviews} public reviews`);
    if (ctx.rating !== "UNKNOWN") bits.push(`and a ${ctx.rating} public rating`);
    return {
      text: bits.join(" ") + ". We could not inspect the website, so I’m not going to pretend I audited the funnel.",
      evidence: ["reviews", "listing"],
      angle: "Public demand signal, website still unknown",
      why: "Website research did not finish. We only use listing facts we already have. We do not invent site problems.",
    };
  }
  if (ctx.reviews >= 80) {
    return {
      text: `${ctx.name} already has ${ctx.reviews} public reviews in ${ctx.city}.`,
      evidence: ["reviews"],
      angle: "Known local brand — conversation about the next customer, not “you need reviews”",
      why: "Verified public review count. That is not revenue and not an ad-budget claim.",
    };
  }
  return {
    text: `${ctx.name} is a ${ctx.vertical.toLowerCase()} company in ${ctx.city || "your market"}.`,
    evidence: ["identity"],
    angle: "Category + market only — keep the ask light",
    why: "We don’t have a stronger verified hook yet, so the note stays factual and short.",
  };
}

function helpLine(ctx: PackedContext): string {
  if (ctx.offer === "Convert") return "Lamb Ascension helps companies turn existing attention into inquiries — landing path, tracking hygiene, and ads that match the page — without guessing your numbers.";
  if (ctx.offer === "Acquire") return "Lamb Ascension runs Google and Meta customer-acquisition for companies where one new customer is worth a serious conversation.";
  if (ctx.offer === "System") return "Lamb Ascension builds the full acquire + convert path when the evidence says traffic and the follow-through are both in play.";
  return "Lamb Ascension helps high-ticket companies get customers through Google and Meta. I won’t pitch a package until a short call confirms it fits.";
}

export function buildOutreach(ctx: PackedContext): OutreachPack {
  const obs = observation(ctx);
  const hi = greeting(ctx);
  const help = helpLine(ctx);
  const who = `${ctx.name} — ${ctx.vertical}${ctx.city ? ` in ${ctx.city}` : ""}${ctx.is_demo ? " (DEMO record)" : ""}`;
  const dm = ctx.contact_name === "UNKNOWN"
    ? "UNKNOWN — we do not have a verified person. Do not guess an email."
    : `${ctx.contact_name}${ctx.contact_title !== "UNKNOWN" ? `, ${ctx.contact_title}` : ""}`;

  const mk = (kind: OutreachMessage["kind"], body: string, subject?: string): OutreachMessage => ({
    kind, body, subject, state: "READY FOR REVIEW", angle: obs.angle, angle_why: obs.why, evidence_used: obs.evidence,
  });

  const letter = composeOutreachEmail(ctx);
  const messages: OutreachMessage[] = [
    {
      kind: "email",
      body: letter.body,
      subject: letter.subject,
      state: "READY FOR REVIEW",
      angle: letter.angle,
      angle_why: letter.why,
      evidence_used: letter.evidence,
    },
    mk("followup1", `Hi ${hi},\n\nQuick add: ${letter.sentence} If useful, I can send the 1-page version of what we actually checked — nothing invented.\n\nDylan`),
    mk("followup2", `Hi ${hi},\n\nSeparate thought: ${help}\nIf now’s not the time, a one-word “later” is enough.\n\nDylan`),
    mk("followup3", `Hi ${hi},\n\nI’ll close this thread so I’m not another “just following up.” If you ever want the short audit, reply “send it.”\n\nDylan`),
  ];

  if (ctx.contact_name !== "UNKNOWN" || ctx.contact_profile) {
    messages.push(mk(
      "linkedin",
      `Hi ${hi} — I was looking at ${ctx.name} (${ctx.vertical.toLowerCase()}${ctx.city ? `, ${ctx.city}` : ""}). ${obs.text.replace(/^I opened /, "I looked at ").split(".")[0]}. If it’s useful I can send a short, evidence-based note — no pitch deck. Open to that?`,
    ));
  }

  messages.push(mk(
    "call_opener",
    `Calling ${dm}. Reason: ${obs.angle}.\n\nOpener:\n“Hi ${hi}, this is Dylan with Lamb Ascension. I’ll be brief — ${obs.text} I wanted to ask if you’d be open to a short audit based on that, not a generic sales dump.”\n\nLikely next question: “How are you getting most customers today?”\n\nDo not claim revenue, ad spend, or that they need us.`,
  ));

  return {
    fingerprint: ctx.fingerprint,
    generated_at: new Date().toISOString(),
    generator: "evidence",
    estimated_cents: 0,
    brief: {
      who,
      why: ctx.readiness ? `${ctx.readiness}. ${obs.why}` : obs.why,
      decision_maker: dm,
      help,
      angle: obs.angle,
      unknown: ctx.unknown,
    },
    messages,
    call: {
      who: dm,
      why: obs.angle,
      point: obs.text,
      opener: `Hi ${hi}, this is Dylan with Lamb Ascension. I’ll be brief — ${obs.text} Would you be open to a short audit based on what we actually reviewed?`,
      next_question: "How are you currently getting customers?",
    },
  };
}

import type { DiscoveryAnswers, ValueFit } from "./types.ts";

function money(raw?: string): number | null {
  if (!raw) return null;
  const n = Number(String(raw).replace(/[^0-9.]/g, ""));
  return Number.isFinite(n) && n > 0 ? n : null;
}

export function qualifyValueOffer(a: DiscoveryAnswers): { fit: ValueFit; why: string[]; unknown: string[] } {
  const why: string[] = [];
  const unknown: string[] = [];
  const value = money(a.customer_value);
  const budget = money(a.monthly_ad_budget);
  const filled = Object.values(a).filter((v) => v && String(v).trim()).length;

  if (value != null) why.push(`CLIENT-PROVIDED average customer/client value: about $${value.toLocaleString()}.`);
  else unknown.push("Average customer/client value");
  if (budget != null) why.push(`CLIENT-PROVIDED monthly ad budget: about $${budget.toLocaleString()}.`);
  else unknown.push("Monthly advertising budget");
  if (a.capacity) why.push(`CLIENT-PROVIDED capacity: ${a.capacity}.`);
  else unknown.push("How many new customers they can handle");
  if (a.current_channels) why.push(`CLIENT-PROVIDED channels: ${a.current_channels}.`);
  else unknown.push("Current acquisition channels");
  if (a.close_rate) why.push(`CLIENT-PROVIDED close rate: ${a.close_rate}.`);
  else unknown.push("Close rate");
  if (a.lead_handling) why.push(`CLIENT-PROVIDED lead handling: ${a.lead_handling}.`);
  else unknown.push("What happens after a lead comes in");

  if (filled === 0) {
    return { fit: "NEED MORE INFORMATION", why: ["No discovery answers yet. Looking successful online is not enough."], unknown };
  }
  if (value != null && value < 500) {
    return { fit: "NOT A FIT", why: [...why, "Customer value is too low for a $2,500–$10,000/month retainer."], unknown };
  }
  if (value != null && value >= 8000 && (budget == null || budget >= 3000) && a.capacity) {
    return { fit: "HIGH-VALUE OFFER MAY MAKE SENSE", why: [...why, "This is still not a promise they will pay $10K. It only means the economics they described could support a high-ticket conversation."], unknown };
  }
  if (value != null && value >= 2000) {
    return { fit: "STANDARD OFFER MAY FIT BETTER", why: [...why, "Economics may support Acquire/Convert before a $10K system."], unknown };
  }
  return { fit: "NEED MORE INFORMATION", why: [...why, "Ask the remaining questions before labeling this a high-value retainer."], unknown };
}

export const DISCOVERY_QUESTIONS = [
  "How are you currently getting customers?",
  "What channels are working?",
  "What is your average customer/client value?",
  "What happens after a lead comes in?",
  "How many new customers can you realistically handle?",
  "Are you currently running Google or Meta Ads?",
  "What monthly advertising budget are you comfortable deploying?",
  "What would make a marketing partnership successful for you?",
];

import type { PackedContext } from "./pack.ts";

export type OutreachLetter = {
  subject: string;
  body: string;
  sentence: string;
  angle: string;
  why: string;
  evidence: string[];
};

type Voice = { work: string; people: string; ask: string };

function hash(seed: string): number {
  let h = 0;
  for (const c of seed) h = (h * 33 + c.charCodeAt(0)) >>> 0;
  return h;
}

function pick<T>(seed: string, items: T[]): T {
  return items[hash(seed) % items.length]!;
}

function absentFact(ctx: PackedContext, key: string): boolean {
  const fact = ctx.facts.find((f) => f.key === key);
  if (!fact) return false;
  return /^(no |missing)/i.test(fact.text);
}

function presentFact(ctx: PackedContext, key: string): boolean {
  const fact = ctx.facts.find((f) => f.key === key);
  if (!fact) return false;
  return !/^(no |missing)/i.test(fact.text) && !/unknown/i.test(fact.text);
}

export function industryVoice(vertical: string, kind = ""): Voice {
  const v = `${vertical} ${kind}`.toLowerCase();
  if (/roof/.test(v)) return { work: "roofing work", people: "homeowners", ask: "estimate requests" };
  if (/hvac|air condition|heating/.test(v)) return { work: "HVAC work", people: "homeowners", ask: "service calls" };
  if (/plumb/.test(v)) return { work: "plumbing work", people: "homeowners", ask: "service requests" };
  if (/law|attorney|legal/.test(v)) return { work: "legal work", people: "potential clients", ask: "consultation requests" };
  if (/financ|lend|loan|credit/.test(v)) return { work: "financing", people: "borrowers", ask: "funding applications" };
  if (/dental|dentist/.test(v)) return { work: "dental care", people: "patients", ask: "appointment requests" };
  if (/med spa|cosmetic|aesthetic/.test(v)) return { work: "treatment options", people: "patients", ask: "appointment requests" };
  if (/foundation/.test(v)) return { work: "foundation work", people: "homeowners", ask: "estimate requests" };
  if (/remodel|contractor|construction/.test(v)) return { work: "project work", people: "homeowners", ask: "estimate requests" };
  if (/saas|software/.test(v)) return { work: "the product", people: "businesses", ask: "qualified inquiries" };
  if (/consult|b2b/.test(v)) return { work: "the work", people: "businesses", ask: "qualified inquiries" };
  const named = (vertical || "").trim();
  if (!named || named.toLowerCase() === "unknown") {
    return { work: "what you offer", people: "visitors", ask: "inquiries" };
  }
  return { work: named.toLowerCase(), people: "visitors", ask: "inquiries" };
}

function adsLive(ctx: PackedContext): boolean {
  return (ctx.ads || []).some((ad) => ad.label === "ADVERTISING DETECTED");
}

type Finding = {
  code: string;
  evidence: string[];
  sentence: string;
  soWhat: string;
  position: string;
  angle: string;
  why: string;
  auditReady: boolean;
};

function positionFor(kind: "convert" | "ads" | "tracking" | "speed" | "trust" | "light", voice: Voice, seed: string): string {
  const lead = pick(seed + "pos", [
    "At Lamb Ascension, we build customer-acquisition systems",
    "At Lamb Ascension, we design customer-acquisition systems",
  ]);
  if (kind === "ads") {
    return `${lead} that connect targeted advertising with a page built to capture ${voice.ask}, so more of that attention can become a real opportunity.`;
  }
  if (kind === "tracking") {
    return `${lead} where inquiries and calls can be tied back to the marketing that produced them, instead of guessing which channel is working.`;
  }
  if (kind === "speed") {
    return `${lead} designed to turn more mobile traffic into ${voice.ask}, starting with a page people can actually use.`;
  }
  if (kind === "trust") {
    return `${lead} designed to turn existing reputation into ${voice.ask}, by putting proof where a new visitor decides whether to reach out.`;
  }
  if (kind === "convert") {
    return `${lead} designed to turn more website traffic into qualified inquiries through a clearer path, lead capture, and follow-up.`;
  }
  return `${lead} designed to turn attention into qualified inquiries. I would rather confirm the details than guess at a package.`;
}

function chooseFinding(ctx: PackedContext, voice: Voice): Finding {
  const name = ctx.name;
  const paid = adsLive(ctx);
  const phoneOnly = Boolean(ctx.phone && ctx.phone !== "UNKNOWN") || presentFact(ctx, "phone_visible") || presentFact(ctx, "click_to_call");

  if (ctx.opportunities.some((o) => o.code === "NO_HOMEPAGE_FORM")) {
    const inner = ctx.facts.some((f) => f.key === "contact_form_inner") && !absentFact(ctx, "contact_form_inner");
    const sentence = inner
      ? `I took a look at ${name} and didn’t see a contact form on the homepage. A form did show up on an inside page.`
      : `I took a look at ${name} and did not find a contact form on the homepage.`;
    const soWhat = phoneOnly
      ? `That leaves a gap where ${voice.people} can look through your ${voice.work} and still leave if they are not ready to call — so those ${voice.ask} never get captured.`
      : `That means someone can find you, look through your ${voice.work}, and leave without ever turning into ${voice.ask}.`;
    return {
      code: "NO_HOMEPAGE_FORM",
      evidence: inner ? ["NO_HOMEPAGE_FORM", "contact_form_inner"] : ["NO_HOMEPAGE_FORM"],
      sentence,
      soWhat: paid
        ? `${soWhat} If paid traffic is landing on that homepage, more of it can leave without a next step.`
        : soWhat,
      position: positionFor(paid ? "ads" : "convert", voice, name),
      angle: "Homepage inquire path is weaker than it needs to be",
      why: "Verified homepage form gap. We only mention the form we did or did not see.",
      auditReady: true,
    };
  }

  if (ctx.opportunities.some((o) => o.code === "NO_HOMEPAGE_CTA")) {
    return {
      code: "NO_HOMEPAGE_CTA",
      evidence: ["NO_HOMEPAGE_CTA"],
      sentence: `I took a look at ${name} and didn’t see a clear quote or estimate ask near the top of the homepage.`,
      soWhat: `When the next step is easy to miss, ${voice.people} can be interested in your ${voice.work} and still leave before they become ${voice.ask}.`,
      position: positionFor("convert", voice, name),
      angle: "The next step is not obvious on the first screen",
      why: "Verified: no common quote or estimate ask in the first content.",
      auditReady: true,
    };
  }

  if (ctx.opportunities.some((o) => o.code === "NO_TRACKING" || o.code === "NO_ADS_CONVERSION_TAG")) {
    const code = ctx.opportunities.some((o) => o.code === "NO_TRACKING") ? "NO_TRACKING" : "NO_ADS_CONVERSION_TAG";
    return {
      code,
      evidence: [code],
      sentence: code === "NO_TRACKING"
        ? `On the pages we checked for ${name}, I didn’t see the usual tracking snippets that would show which visits turn into inquiries.`
        : `On the pages we checked for ${name}, I didn’t see a Google Ads conversion tag.`,
      soWhat: code === "NO_TRACKING"
        ? "Without that, it is hard to know which marketing is actually producing customers. Missing tags are not proof that you never advertise."
        : "That does not prove ads are off. It does mean a checked page would not show which clicks became inquiries.",
      position: positionFor("tracking", voice, name),
      angle: "Tracking on the pages we checked would not show where inquiries come from",
      why: "We only report tags we did not see on the pages checked. We do not claim ad spend.",
      auditReady: true,
    };
  }

  const slow = ctx.opportunities.find((o) => o.code === "SLOW_MOBILE");
  if (slow) {
    return {
      code: "SLOW_MOBILE",
      evidence: ["SLOW_MOBILE"],
      sentence: `I checked ${name} on a phone. ${slow.plain}`,
      soWhat: `A slow page gives mobile visitors a reason to leave before they ask about ${voice.work}.`,
      position: positionFor("speed", voice, name),
      angle: "Mobile speed may be costing inquiries",
      why: "The phone speed score is a stored result, not a guess.",
      auditReady: true,
    };
  }

  if (absentFact(ctx, "testimonials") && ctx.reviews >= 15) {
    return {
      code: "testimonials",
      evidence: ["testimonials", "reviews"],
      sentence: `${name} has ${ctx.reviews} public reviews, and I didn’t see that proof used on the homepage.`,
      soWhat: `New ${voice.people} may not see the reputation that could help them send ${voice.ask}. That is a trust gap on the page, not a claim about revenue.`,
      position: positionFor("trust", voice, name),
      angle: "Public reviews are not carrying the homepage",
      why: "Review count is from the public listing. The homepage testimonial check is from the pages we opened.",
      auditReady: true,
    };
  }

  if (ctx.facts.some((f) => f.key === "case_studies" || /case-study|client-story/i.test(f.text))) {
    return {
      code: "case_studies",
      evidence: ["case_studies"],
      sentence: `${name} publishes case-study / client-story language. That reads as work sold to businesses, not a generic local-service page.`,
      soWhat: `The opportunity is getting more of the right ${voice.people} to start a conversation, not pretending this is a walk-in shop.`,
      position: positionFor("convert", voice, name),
      angle: "Client stories are on the site — the ask can match that",
      why: "Observed case-study wording on a page we opened. That is wording, not verified contract value.",
      auditReady: true,
    };
  }

  if (ctx.facts.some((f) => f.key === "enterprise_language" || /enterprise \/ b2b/i.test(f.text))) {
    return {
      code: "enterprise_language",
      evidence: ["enterprise_language"],
      sentence: `${name}’s site is written for businesses, not just local consumers.`,
      soWhat: `A first note should talk about ${voice.ask} from ${voice.people}, not a consumer review pitch.`,
      position: positionFor("light", voice, name),
      angle: "The site speaks to businesses",
      why: "Observed enterprise or B2B wording on a page we opened.",
      auditReady: true,
    };
  }

  if (ctx.research_status === "blocked" || ctx.research_status === "failed") {
    const bits = [`${name} is a ${ctx.vertical.toLowerCase() || "company"} company${ctx.city ? ` in ${ctx.city}` : ""}`];
    if (ctx.reviews) bits.push(`with ${ctx.reviews} public reviews`);
    if (ctx.rating !== "UNKNOWN") bits.push(`and a ${ctx.rating} public rating`);
    return {
      code: "listing_only",
      evidence: ctx.reviews ? ["reviews", "listing"] : ["listing"],
      sentence: `${bits.join(" ")}. I could not inspect the website, so I am not going to pretend I found a site problem.`,
      soWhat: "The only honest next step is a look at the site itself before recommending anything.",
      position: positionFor("light", voice, name),
      angle: "Public listing only — website still unknown",
      why: "Website research did not finish. We only use listing facts we already have. We do not invent site problems.",
      auditReady: false,
    };
  }

  if (ctx.reviews >= 80) {
    return {
      code: "reviews",
      evidence: ["reviews"],
      sentence: `${name} already has ${ctx.reviews} public reviews${ctx.city ? ` in ${ctx.city}` : ""}.`,
      soWhat: `That is a reputation signal, not a claim about revenue. I would not invent a website problem on top of it.`,
      position: positionFor("trust", voice, name),
      angle: "Known in public — keep the note on what we actually verified",
      why: "Verified public review count. That is not revenue and not an ad-budget claim.",
      auditReady: false,
    };
  }

  return {
    code: "identity",
    evidence: ["identity"],
    sentence: `${name} is a ${ctx.vertical.toLowerCase() || "company"} company${ctx.city ? ` in ${ctx.city}` : ""}. I don’t have a stronger verified finding yet, so this note stays on that.`,
    soWhat: "I would rather send a short, accurate note than invent a problem to make the email sound sharper.",
    position: positionFor("light", voice, name),
    angle: "Category and market only",
    why: "We don’t have a stronger verified hook yet, so the note stays factual and short.",
    auditReady: false,
  };
}

function auditLine(ctx: PackedContext, ready: boolean): string {
  if (ready) {
    return pick(ctx.name + "audit", [
      `I put together a short audit showing what I noticed and a few opportunities I’d recommend for ${ctx.name} specifically.`,
      `I put together a short audit of what I actually saw, and a few opportunities I’d recommend for ${ctx.name}.`,
    ]);
  }
  return `I can put together a short audit for ${ctx.name} specifically once there is a verified finding to stand on. I don’t want to invent one.`;
}

function cta(name: string): string {
  return pick(name + "cta", [
    "Would you be open to me sending it over?",
    "Want me to send it over?",
    "Would it be helpful if I sent it over?",
    "Open to taking a look?",
  ]);
}

export function composeOutreachEmail(ctx: PackedContext): OutreachLetter {
  const voice = industryVoice(ctx.vertical, ctx.kind);
  const finding = chooseFinding(ctx, voice);
  const hi = ctx.contact_name !== "UNKNOWN" ? (ctx.contact_name.split(" ")[0] || ctx.contact_name) : "Team";
  const subject = finding.auditReady
    ? `${ctx.name} — quick opportunity I noticed`
    : `${ctx.name} — a short note`;
  const body = [
    `Hi ${hi},`,
    "",
    finding.sentence,
    "",
    finding.soWhat,
    "",
    finding.position,
    "",
    auditLine(ctx, finding.auditReady),
    "",
    cta(ctx.name),
    "",
    "Dylan",
    "Lamb Ascension",
  ].join("\n");
  return {
    subject,
    body,
    sentence: finding.sentence,
    angle: finding.angle,
    why: finding.why,
    evidence: finding.evidence,
  };
}

import { packContext } from "./pack.ts";
