test("two devices can mint the same numeric id; actions still hit only the matching uid", () => {
  const a = p("device-a-uuid", 7, "Dallas Roof Co");
  const b = p("device-b-uuid", 7, "Fort Worth HVAC");
  const rows = [a, b];
