import type { Prospect } from "../review-brief.ts";
import { ensureUid } from "./ids.ts";

/** Canonical identity. Numeric `id` is display/legacy only. */
export function prospectUid(p: { uid?: string }): string {
  return p.uid || "";
}

export function findByUid(rows: Prospect[], uid: string | null | undefined): Prospect | undefined {
  if (!uid) return undefined;
  return rows.find((r) => r.uid === uid);
}

export function patchByUid(rows: Prospect[], next: Prospect): Prospect[] {
  const uid = next.uid;
  if (!uid) return [...rows, ensureUid(next)];
  let found = false;
  const out = rows.map((c) => {
    if (c.uid === uid) {
      found = true;
      return next;
    }
    return c;
  });
  return found ? out : [...out, ensureUid(next)];
}

/** Apply a change to one prospect by uid — never by colliding numeric id. */
export function applyByUid(rows: Prospect[], uid: string, fn: (p: Prospect) => Prospect): Prospect[] {
  return rows.map((c) => (c.uid === uid ? fn(c) : c));
}

export function withUids(rows: Prospect[]): Prospect[] {
  return rows.map(ensureUid);
}

import type { Prospect } from "../review-brief.ts";

export function newUid(): string {
  if (typeof crypto !== "undefined" && typeof crypto.randomUUID === "function") {
    return crypto.randomUUID();
  }
  return `p-${Date.now()}-${Math.random().toString(16).slice(2)}`;
}

export function ensureUid(p: Prospect): Prospect {
  return p.uid ? p : { ...p, uid: newUid() };
}

export function websiteDomain(website: string | undefined): string {
  if (!website || website === "UNKNOWN") return "";
  try {
    const raw = website.includes("://") ? website : `https://${website}`;
    return new URL(raw).hostname.replace(/^www\./, "").toLowerCase();
  } catch {
    return "";
  }
}

export function nextClientId(rows: { id: number }[]): number {
  return Math.max(0, ...rows.map((r) => r.id || 0)) + 1;
}

export function normalizeName(name: string): string {
  return (name || "").trim().toLowerCase().replace(/\s+/g, " ");
}

const LEGAL_SUFFIX_RE = /\b(llc|inc|incorporated|ltd|co|company|corp|corporation)\b/g;

export function nameKey(name: string): string {
  return normalizeName(name)
    .replace(LEGAL_SUFFIX_RE, " ")
    .replace(/[^a-z0-9 ]/g, " ")
    .replace(/\s+/g, " ")
    .trim();
}

/** Existing Owner Mode prospect profile: `/` with `?p=<uid>`. Not a new route. */
export function prospectProfileSearch(uid: string): string {
  const id = (uid || "").trim();
  if (!id) return "/";
  return `/?p=${encodeURIComponent(id)}`;
}

export function prospectProfileUrl(origin: string, uid: string): string {
  const base = (origin || "").replace(/\/$/, "") || "https://lamb-ascension-engine.vercel.app";
  return `${base}${prospectProfileSearch(uid)}`;
}

/** Last completed Find Clients result. View-only identity — never a new Places search. */

export type LastDiscovery = {
  query: string;
  vertical: string;
  location: string;
  requested: number;
  matched: number;
  prospectUids: string[];
  placeIds: string[];
  timestamp: string;
};

const STORE = "la_last_discovery_v1";

export function emptyLastDiscovery(): LastDiscovery {
  return {
    query: "",
    vertical: "",
    location: "",
    requested: 0,
    matched: 0,
    prospectUids: [],
    placeIds: [],
    timestamp: "",
  };
}

export function isLastDiscovery(v: unknown): v is LastDiscovery {
  if (!v || typeof v !== "object") return false;
  const d = v as LastDiscovery;
  return Array.isArray(d.prospectUids) && Array.isArray(d.placeIds);
}

export function loadLastDiscovery(): LastDiscovery | null {
  if (typeof localStorage === "undefined") return null;
  try {
    const raw = localStorage.getItem(STORE);
    if (!raw) return null;
    const parsed = JSON.parse(raw) as unknown;
    return isLastDiscovery(parsed) && parsed.prospectUids.length ? parsed : null;
  } catch {
    return null;
  }
}

export function saveLastDiscovery(d: LastDiscovery | null): void {
  if (typeof localStorage === "undefined") return;
  try {
    if (!d || !d.prospectUids.length) localStorage.removeItem(STORE);
    else localStorage.setItem(STORE, JSON.stringify(d));
  } catch {
    /* quota / private mode */
  }
}

export function lastDiscoveryFromMatch(opts: {
  vertical: string;
  location: string;
  requested: number;
  prospectUids: string[];
  placeIds: string[];
}): LastDiscovery {
  const vertical = (opts.vertical || "").trim();
  const location = (opts.location || "").trim();
  return {
    query: [vertical, location].filter(Boolean).join(" in ") || "Find Clients",
    vertical,
    location,
    requested: Math.max(0, Math.floor(opts.requested || 0)),
    matched: opts.prospectUids.length,
    prospectUids: opts.prospectUids.filter(Boolean),
    placeIds: opts.placeIds.filter(Boolean),
    timestamp: new Date().toISOString(),
  };
}

import { createServerFn } from "@tanstack/react-start";
import { authMiddleware } from "@/lib/auth/middleware";
import type { Prospect } from "@/lib/review-brief";
import {
  applyProspectInfoChanges,
  pickKnownChanges,
  sanitizeChanges,
  spokenAfterSave,
  type ProspectInfoChanges,
} from "./owner-edit";
import { reachKind } from "./reach";

export type UpdateProspectInformationInput = {
  prospectUid: string;
  changes: ProspectInfoChanges;
  confirmDestructive?: boolean;
  inputMethod?: "MANUAL" | "VOICE";
};

export const updateProspectInformationFn = createServerFn({ method: "POST" })
  .middleware([authMiddleware])
  .validator((data: UpdateProspectInformationInput) => data)
  .handler(async ({ data, context }) => {
    const { getProspectByUid, upsertProspects, logActivity } = await import("./repo.server");
    const uid = String(data.prospectUid || "").trim();
    if (!uid) {
      return { ok: false as const, reason: "Which prospect should I add that to?", emailSent: false };
    }
    const current = await getProspectByUid(context.userId, uid);
    if (!current) {
      return { ok: false as const, reason: "I couldn’t find that prospect, so nothing changed.", emailSent: false };
    }
    const picked = pickKnownChanges({ ...(data.changes || {}) });
    if (picked.unknown.length) {
      return {
        ok: false as const,
        reason: `I can only save known prospect fields. I ignored: ${picked.unknown.join(", ")}.`,
        emailSent: false,
      };
    }
    const san = sanitizeChanges(picked.changes);
    if (!san.ok) {
      return {
        ok: false as const,
        reason: san.errors.map((e) => e.message).join(" "),
        errors: san.errors,
        emailSent: false,
      };
    }
    if (!Object.keys(san.changes).length) {
      return { ok: false as const, reason: "Nothing to save.", emailSent: false };
    }
    const applied = applyProspectInfoChanges(current, san.changes, { actor: "owner" });
    const saved = await upsertProspects(context.userId, [applied.prospect]);
    const prospect: Prospect = saved.find((p) => p.uid === uid) || applied.prospect;
    const detail = applied.history.map((h) => h.detail).join(" ");
    await logActivity(
      context.userId,
      "PROSPECT_INFORMATION_UPDATED",
      detail.slice(0, 1800),
      uid,
      data.inputMethod || "MANUAL",
    );
    return {
      ok: true as const,
      prospect,
      audits: applied.audits,
      spoken: spokenAfterSave(applied.audits, prospect.name),
      reach: reachKind(prospect),
      emailSent: false,
      outreachAuthorized: false,
    };
  });

