};

export type FieldAudit = {
  field: ProspectInfoField;
  previous: string;
  next: string;
  source: "OWNER";
};

export type HistoryEntry = {
  at: string;
  action: string;
  detail: string;
  field?: string;
  previous?: string;
  next?: string;
