import { makeFinding } from "./ledger.ts";
import { evaluateInvariants } from "./invariants.ts";
import { workerStale } from "./health.ts";
import type { SentinelCode } from "./codes.ts";
import type { LiveProbeInput, SentinelCheckResult, SentinelFinding } from "./types.ts";

export function evaluateChecks(input: LiveProbeInput): SentinelCheckResult[] {
  const checks: SentinelCheckResult[] = [];

  checks.push(checkHttp(input));
  checks.push(checkDb(input));
  checks.push(checkWorker(input));
  checks.push(checkGmail(input));
  checks.push(checkCalendar(input));
  checks.push(checkParser(input));
  checks.push(checkPlaces(input));
  checks.push(checkInvariants(input));
  checks.push(checkTestMode(input));
  checks.push(checkVoice(input));

  return checks;
}

function checkHttp(input: LiveProbeInput): SentinelCheckResult {
  if (input.http.ok) {
    return ok("http", "sentinel", "Live site responded.", true, "cheap");
  }
  return fail("http", "sentinel", makeFinding(
    "HTTP_UNHEALTHY",
    "The live Lamb Ascension site did not return a healthy response.",
    { status: input.http.status || 0 },
  ), true, "cheap");
}

function checkDb(input: LiveProbeInput): SentinelCheckResult {
  if (input.db.ok) {
    return ok("db", "database", `Database responded (${input.db.source}).`, true, "cheap");
  }
  return fail("db", "database", makeFinding(
    "DATABASE_UNAVAILABLE",
    "Production database did not respond.",
    { error: input.db.error || "unavailable", source: input.db.source },
  ), false, "cheap");
}

function checkWorker(input: LiveProbeInput): SentinelCheckResult {
  if (!input.worker.secretPresent && input.worker.lastCompletedAt == null) {
    return fail("worker", "worker", makeFinding(
      "WORKER_NOT_CONFIGURED",
      "Outreach worker is not configured and has never been observed.",
      {},
    ), false, "none");
  }
  const stale = workerStale(input.worker.lastCompletedAt, input.now);
  if (stale || (input.worker.lastResult || "").startsWith("error")) {
    return fail("worker", "worker", makeFinding(
      "WORKER_STALE",
      "Outreach worker heartbeat is stale or the last run failed.",
      {
        lastCompletedAt: input.worker.lastCompletedAt,
        lastResult: input.worker.lastResult,
      },
    ), Boolean(input.worker.lastCompletedAt), "none");
  }
  return ok("worker", "worker", "Worker heartbeat is fresh.", true, "none");
}

function checkGmail(input: LiveProbeInput): SentinelCheckResult {
  if (!input.gmail.connected) {
    return fail("gmail", "gmail", makeFinding(
      "GMAIL_NOT_CONNECTED",
      "Gmail is not connected.",
      {},
    ), false, "none");
  }
  if (!input.gmail.tokenValid) {
    return fail("gmail", "gmail", makeFinding(
      "GMAIL_TOKEN_INVALID",
      "Gmail is connected, but the token is not valid.",
      { identity: input.gmail.identity },
    ), input.gmail.probed, "cheap");
  }
  return ok(
    "gmail",
    "gmail",
    input.gmail.identity ? `Gmail token valid (${input.gmail.identity}).` : "Gmail token valid.",
    input.gmail.probed || input.gmail.tokenValid,
    "cheap",
  );
}

function checkCalendar(input: LiveProbeInput): SentinelCheckResult {
  if (!input.calendar.connected) {
    return fail("calendar", "calendar", makeFinding(
      "CALENDAR_NOT_AUTHORIZED",
      "Google Calendar is not connected.",
      {},
    ), false, "none");
  }
  if (!input.calendar.tokenValid) {
    return fail("calendar", "calendar", makeFinding(
      "CALENDAR_TOKEN_REFRESH_FAILED",
      "Calendar is connected, but the token could not be used.",
      { listCode: input.calendar.listCode || "" },
    ), input.calendar.probed, "cheap");
  }
  if (input.calendar.probed && !input.calendar.listOk) {
    const code = input.calendar.listCode === "CALENDAR_LIST_PARSE_FAILED"
      ? "CALENDAR_LIST_PARSE_FAILED"
      : input.calendar.listCode === "CALENDAR_TOKEN_REFRESH_FAILED"
        ? "CALENDAR_TOKEN_REFRESH_FAILED"
        : "CALENDAR_LIST_AUTH_FAILED";
    return fail("calendar", "calendar", makeFinding(
      code,
      "Calendar event list did not succeed.",
      { listCode: input.calendar.listCode || "", skipped: input.calendar.skipped },
    ), true, "provider_read");
  }
  return ok(
    "calendar",
    "calendar",
    input.calendar.probed
      ? `Calendar list parsed (${input.calendar.parsedEvents} events).`
      : "Calendar token is present.",
    input.calendar.probed || input.calendar.tokenValid,
    input.calendar.probed ? "provider_read" : "cheap",
  );
}

function checkParser(input: LiveProbeInput): SentinelCheckResult {
  if (input.parser.threw || input.parser.kept === 0) {
    return fail("calendar-parser", "calendar", makeFinding(
      "CALENDAR_LIST_PARSE_FAILED",
      "The Calendar list parser failed a known malformed-event fixture.",
      { kept: input.parser.kept, skipped: input.parser.skipped, threw: input.parser.threw },
      { reproduction: "Parse a Google events.list body that includes a cancelled event, a missing start, and a conference payload. Readable events must still render." },
    ), true, "none");
  }
  return ok("calendar-parser", "calendar", `Parser kept ${input.parser.kept} readable events.`, true, "none");
}

function checkPlaces(input: LiveProbeInput): SentinelCheckResult {
  if (!input.places.keyConfigured) {
    return fail("places", "places", makeFinding(
      "PLACES_KEY_MISSING",
      "GOOGLE_PLACES_API_KEY is not configured. Find Clients stays fail-closed.",
      {},
    ), false, "none");
  }
  return ok("places", "places", "Google Places key is configured. No search was performed.", true, "none");
}

function checkInvariants(input: LiveProbeInput): SentinelCheckResult {
  const findings = evaluateInvariants(input.invariants);
  if (!findings.length) {
    return ok("invariants", "pipeline", "Pipeline, booking, and outreach invariants hold.", true, "cheap");
  }
  const feature = findings[0]?.feature || "pipeline";
  return {
    id: "invariants",
    feature,
    ok: false,
    observed: true,
    code: findings[0]!.code,
    detail: findings.map((f) => f.summary).join(" "),
    findings,
    cost: "cheap",
  };
}

function checkTestMode(input: LiveProbeInput): SentinelCheckResult {
  const leaks = input.invariants.testModeLeak;
  if (leaks.length) {
    return fail("test-mode", "test_mode", makeFinding(
      "TEST_MODE_INVARIANT_FAILED",
      "Test Mode is on, but a non-allowlisted send was recorded.",
      { count: leaks.length },
    ), true, "cheap");
  }
  return ok(
    "test-mode",
    "test_mode",
    input.testMode ? "Test Mode is on. Allowlist still enforced." : "Test Mode is off. Live outreach rules apply.",
    true,
    "none",
  );
}

export function checkVoice(input: Pick<LiveProbeInput, "voice">): SentinelCheckResult {
  const voice = input.voice;
  if (!voice || !voice.observed) {
    return ok("ara-voice", "ara_voice", "Ara voice has not been observed recently.", false, "none");
  }
  if (!voice.ok) {
    const raw = voice.code || "ARA_VOICE_SESSION_CREATE_FAILED";
    const code: SentinelCode =
      raw === "ARA_VOICE_PROVIDER_AUTH_FAILED"
      || raw === "ARA_VOICE_SESSION_CREATE_FAILED"
      || raw === "ARA_VOICE_PROVIDER_UNAVAILABLE"
      || raw === "ARA_VOICE_NETWORK_FAILED"
        ? raw
        : "ARA_VOICE_SESSION_CREATE_FAILED";
    return fail("ara-voice", "ara_voice", makeFinding(
      code,
      "Ara voice could not establish a realtime session.",
      { code: voice.code || "", detail: voice.detail || "" },
    ), true, "cheap");
  }
  return ok("ara-voice", "ara_voice", "Ara voice session mint was observed working.", true, "cheap");
}

function ok(
  id: string,
  feature: SentinelCheckResult["feature"],
  detail: string,
  observed: boolean,
  cost: SentinelCheckResult["cost"],
): SentinelCheckResult {
  return { id, feature, ok: true, observed, code: "SENTINEL_OK", detail, findings: [], cost };
}

function fail(
  id: string,
  feature: SentinelCheckResult["feature"],
  finding: SentinelFinding,
  observed: boolean,
  cost: SentinelCheckResult["cost"],
): SentinelCheckResult {
  return {
    id,
    feature,
    ok: false,
    observed,
    code: finding.code,
    detail: finding.summary,
    findings: [finding],
    cost,
  };
}

/** Stable Sentinel error codes. Never rely on human-readable text alone. */

export const SENTINEL_CODES = [
  "CALENDAR_LIST_PARSE_FAILED",
  "CALENDAR_TOKEN_REFRESH_FAILED",
  "CALENDAR_TOKEN_INVALID",
  "CALENDAR_NOT_AUTHORIZED",
  "CALENDAR_LIST_AUTH_FAILED",
  "PLACES_AUTH_FAILED",
  "PLACES_KEY_MISSING",
  "DATABASE_UNAVAILABLE",
  "WORKER_STALE",
  "WORKER_NOT_CONFIGURED",
  "GMAIL_SEND_FAILED",
  "GMAIL_TOKEN_INVALID",
  "GMAIL_NOT_CONNECTED",
  "UNKNOWN_DELIVERY",
  "BOOKING_PERSISTENCE_FAILED_AFTER_CALENDAR_CREATE",
  "ARA_ACTION_DUPLICATE",
  "ARA_ACTION_ROUTING_FAILED",
  "ARA_VOICE_PROVIDER_AUTH_FAILED",
  "ARA_VOICE_SESSION_CREATE_FAILED",
  "ARA_VOICE_PROVIDER_UNAVAILABLE",
  "ARA_VOICE_NETWORK_FAILED",
  "PIPELINE_STATE_MISMATCH",
  "TEST_MODE_INVARIANT_FAILED",
  "PROSPECT_DUPLICATE_IDENTITY",
  "FOLLOWUP_NOT_CANCELLED_AFTER_REPLY",
  "DNC_SEQUENCE_ACTIVE",
  "BOUNCE_FUTURE_SEND_SCHEDULED",
  "HTTP_UNHEALTHY",
  "CONTACTABILITY_MISMATCH",
  "CONTACTABLE_WITHOUT_EMAIL",
  "SENTINEL_OK",
] as const;

export type SentinelCode = (typeof SENTINEL_CODES)[number];

export const SEVERITIES = ["critical", "high", "medium", "low"] as const;
export type SentinelSeverity = (typeof SEVERITIES)[number];

export const FEATURES = [
  "gmail",
  "calendar",
  "places",
  "database",
  "worker",
  "booking",
  "outreach",
  "pipeline",
  "ara",
  "ara_voice",
  "auth",
  "test_mode",
  "sentinel",
] as const;
export type SentinelFeature = (typeof FEATURES)[number];

export const SENTINEL_MODES = ["light", "deep", "post_deploy", "owner", "fixture"] as const;
export type SentinelMode = (typeof SENTINEL_MODES)[number];

export function isSentinelCode(raw: string): raw is SentinelCode {
  return (SENTINEL_CODES as readonly string[]).includes(raw);
}

export function defaultSeverity(code: SentinelCode): SentinelSeverity {
  switch (code) {
    case "TEST_MODE_INVARIANT_FAILED":
    case "DNC_SEQUENCE_ACTIVE":
    case "BOUNCE_FUTURE_SEND_SCHEDULED":
    case "GMAIL_SEND_FAILED":
    case "ARA_ACTION_DUPLICATE":
    case "BOOKING_PERSISTENCE_FAILED_AFTER_CALENDAR_CREATE":
    case "UNKNOWN_DELIVERY":
      return "critical";
    case "CALENDAR_LIST_PARSE_FAILED":
    case "CALENDAR_TOKEN_REFRESH_FAILED":
    case "CALENDAR_TOKEN_INVALID":
    case "CALENDAR_LIST_AUTH_FAILED":
    case "PLACES_AUTH_FAILED":
    case "DATABASE_UNAVAILABLE":
    case "WORKER_STALE":
    case "GMAIL_TOKEN_INVALID":
    case "FOLLOWUP_NOT_CANCELLED_AFTER_REPLY":
    case "PROSPECT_DUPLICATE_IDENTITY":
    case "PIPELINE_STATE_MISMATCH":
    case "ARA_VOICE_PROVIDER_AUTH_FAILED":
    case "ARA_VOICE_SESSION_CREATE_FAILED":
    case "ARA_VOICE_PROVIDER_UNAVAILABLE":
    case "ARA_VOICE_NETWORK_FAILED":
    case "HTTP_UNHEALTHY":
    case "CONTACTABILITY_MISMATCH":
    case "CONTACTABLE_WITHOUT_EMAIL":
      return "high";
    case "CALENDAR_NOT_AUTHORIZED":
    case "GMAIL_NOT_CONNECTED":
    case "PLACES_KEY_MISSING":
    case "WORKER_NOT_CONFIGURED":
    case "ARA_ACTION_ROUTING_FAILED":
      return "medium";
    default:
      return "low";
  }
}

export function featureForCode(code: SentinelCode): SentinelFeature {
  if (code.startsWith("CALENDAR")) return "calendar";
  if (code.startsWith("PLACES")) return "places";
  if (code.startsWith("GMAIL") || code === "UNKNOWN_DELIVERY") return "gmail";
  if (code.startsWith("WORKER")) return "worker";
  if (code.startsWith("ARA_VOICE")) return "ara_voice";
  if (code.startsWith("ARA")) return "ara";
  if (code === "DATABASE_UNAVAILABLE") return "database";
  if (code === "HTTP_UNHEALTHY") return "sentinel";
  if (code === "TEST_MODE_INVARIANT_FAILED") return "test_mode";
  if (code === "BOOKING_PERSISTENCE_FAILED_AFTER_CALENDAR_CREATE") return "booking";
  if (
    code === "PIPELINE_STATE_MISMATCH"
    || code === "PROSPECT_DUPLICATE_IDENTITY"
    || code === "FOLLOWUP_NOT_CANCELLED_AFTER_REPLY"
    || code === "DNC_SEQUENCE_ACTIVE"
    || code === "BOUNCE_FUTURE_SEND_SCHEDULED"
    || code === "CONTACTABILITY_MISMATCH"
    || code === "CONTACTABLE_WITHOUT_EMAIL"
  ) return "pipeline";
  return "sentinel";
}

export function ownerLabel(code: SentinelCode): string {
  switch (code) {
    case "CALENDAR_LIST_PARSE_FAILED": return "Calendar list could not be read";
    case "CALENDAR_TOKEN_REFRESH_FAILED":
    case "CALENDAR_TOKEN_INVALID":
    case "CALENDAR_LIST_AUTH_FAILED": return "Calendar needs attention";
    case "CALENDAR_NOT_AUTHORIZED": return "Calendar isn’t connected";
