import { makeFinding } from "./ledger.ts";
import type { SentinelFinding } from "./types.ts";

export function evaluateContactabilityInvariants(prospects: Prospect[]): SentinelFinding[] {
  const out: SentinelFinding[] = [];
  for (const p of prospects) {
    const c = evaluateContactability(p);
    const reach = reachKind(p);
    const key = p.uid || p.name || "";
    const uid = p.uid || "";
    if (reach === "READY_TO_CONTACT" && !c.emailRoute) {
      out.push(makeFinding(
        "CONTACTABLE_WITHOUT_EMAIL",
        `${p.name} is marked ready to contact without a usable email route.`,
        { uid: p.uid, reach },
        { extraKey: key, affected: [{ uid }] },
      ));
    }
    const mapped = c.status === "CONTACTABLE" ? "READY_TO_CONTACT"
      : c.status === "NEEDS_CONTACT_INFORMATION" ? "NEEDS_CONTACT_INFO"
        : c.status === "NEEDS_RESEARCH" ? "NEEDS_RESEARCH"
          : c.status === "SUPPRESSED" ? "SUPPRESSED"
            : "BLOCKED";
    if (mapped !== reach && !(c.status === "CONTACTABLE" && reach === "READY_TO_CONTACT")) {
      out.push(makeFinding(
        "CONTACTABILITY_MISMATCH",
        `${p.name}: reach=${reach} vs contactability=${c.status}.`,
        { uid: p.uid, reach, status: c.status },
        { extraKey: key, affected: [{ uid }] },
      ));
    }
  }
  return out;
}

/**
 * Optional safe fix preparation. Auto-Fix is OFF and must stay OFF.
 * Sentinel may describe a patch. It must not merge, deploy, rotate secrets,
 * or change Test Mode.
 */

export const SENTINEL_AUTO_FIX = false as const;

export const AUTO_FIX_FORBIDDEN = [
  "auth",
  "oauth",
  "billing",
  "database_schema_destructive",
  "send_safety",
  "test_mode",
  "production_secrets",
  "dnc",
  "calendar_destructive",
  "email_delivery",
] as const;

export type FixPrepReport = {
  allowed: false;
  autoFix: false;
  reason: string;
  next: string;
};

export function mayAutoFix(_kind?: string): FixPrepReport {
  return {
    allowed: false,
    autoFix: false,
    reason: "Sentinel Auto-Fix is OFF.",
    next: "Detect → reproduce in test → smallest isolated branch → wait for Dylan to approve merge and deploy.",
  };
}

export function describeFixWorkflow(bugId: string): string {
  return [
    `Bug ${bugId} may be prepared as an isolated fix.`,
    "1. Reproduce with a regression test.",
    "2. Identify the smallest cause.",
    "3. Open an isolated branch. Do not touch main.",
    "4. Run typecheck, lint, src tests, and build.",
    "5. Wait for Dylan to approve merge and production deploy.",
    "Sentinel will not merge, roll back, rotate credentials, or disable Test Mode.",
  ].join(" ");
}

import { WORKER_STALE_MS } from "../mail/heartbeat.ts";
import type { HealthLight, SentinelBug, SentinelCheckResult, SentinelFinding, SubsystemHealth } from "./types.ts";
import type { SentinelCode, SentinelFeature } from "./codes.ts";

export const OBSERVED_FRESH_MS = 30 * 60 * 1000;

const DASHBOARD: SentinelFeature[] = [
  "gmail",
  "calendar",
  "places",
  "database",
  "worker",
  "booking",
  "outreach",
  "ara",
  "ara_voice",
];

export function lightFromFindings(findings: SentinelFinding[], observed: boolean): HealthLight {
  if (findings.some((f) => f.severity === "critical")) return "red";
  if (findings.some((f) => f.severity === "high")) return "red";
  if (!observed) return "yellow";
  if (findings.some((f) => f.severity === "medium")) return "yellow";
  return "green";
}

export function overallFromSubsystems(rows: SubsystemHealth[]): HealthLight {
  if (rows.some((r) => r.light === "red")) return "red";
  if (rows.some((r) => r.light === "yellow" || r.light === "unknown")) return "yellow";
  if (!rows.length) return "unknown";
  return "green";
}

/** Launch smoke ignores a stale Ara voice tile. A real voice failure (red) still counts. */
export function launchLight(rows: SubsystemHealth[]): HealthLight {
  const counted = rows.filter((r) => r.feature !== "ara_voice" || r.light === "red");
  return overallFromSubsystems(counted);
}

export function voiceObservation(rows: SubsystemHealth[]): "fresh" | "stale" | "failed" | "unknown" {
  const voice = rows.find((r) => r.feature === "ara_voice");
  if (!voice) return "unknown";
  if (voice.light === "red") return "failed";
  if (voice.light === "green") return "fresh";
  return "stale";
}

export function overallGrade(light: HealthLight): "healthy" | "degraded" | "critical" | "unknown" {
  if (light === "green") return "healthy";
  if (light === "red") return "critical";
  if (light === "yellow") return "degraded";
  return "unknown";
}

export function overallLabel(light: HealthLight, open: number): string {
  if (light === "green") return "Everything is healthy";
  if (light === "red") return open === 1 ? "1 regression detected" : `${open} problems detected`;
  if (light === "yellow") return "Something needs attention";
  return "Sentinel has not observed production yet";
}

export function workerStale(lastCompletedAt: number | null, now: number, staleMs = WORKER_STALE_MS): boolean {
  if (lastCompletedAt == null) return true;
  return now - lastCompletedAt > staleMs;
}

export function recentlyObserved(iso: string | null, now = Date.now(), freshMs = OBSERVED_FRESH_MS): boolean {
  if (!iso) return false;
  const t = Date.parse(iso);
  if (!Number.isFinite(t)) return false;
  return now - t <= freshMs;
}

/** Map a finding onto the owner-facing System Health tile it should light. */
export function dashboardFeatureOf(code: SentinelCode, feature: SentinelFeature): SentinelFeature {
  if (code === "PROSPECT_DUPLICATE_IDENTITY") return "places";
  if (
    code === "FOLLOWUP_NOT_CANCELLED_AFTER_REPLY"
    || code === "DNC_SEQUENCE_ACTIVE"
    || code === "BOUNCE_FUTURE_SEND_SCHEDULED"
    || code === "TEST_MODE_INVARIANT_FAILED"
  ) return "outreach";
  if (code === "PIPELINE_STATE_MISMATCH" || code === "BOOKING_PERSISTENCE_FAILED_AFTER_CALENDAR_CREATE") {
    return "booking";
  }
  if (feature === "pipeline") return "outreach";
  if (feature === "test_mode") return "outreach";
  return feature;
}

function relatedChecks(feature: SentinelFeature, checks: SentinelCheckResult[]): SentinelCheckResult[] {
  const direct = checks.filter((c) => c.feature === feature);
  if (feature === "booking" || feature === "outreach" || feature === "ara") {
    return [...direct, ...checks.filter((c) => c.id === "invariants" || (feature === "outreach" && c.id === "test-mode"))];
  }
  if (feature === "places") {
    return [...direct, ...checks.filter((c) => c.id === "invariants")];
  }
  return direct;
}

export function rollupSubsystems(
  checks: SentinelCheckResult[],
  bugs: SentinelBug[],
  observedAt: Record<string, string | null>,
  now = Date.now(),
): SubsystemHealth[] {
  return DASHBOARD.map((feature) => {
    const related = relatedChecks(feature, checks);
    const findings: SentinelFinding[] = [
      ...related.flatMap((c) => c.findings).filter((f) => dashboardFeatureOf(f.code, f.feature) === feature),
      ...bugs.filter((b) => b.status === "open" && dashboardFeatureOf(b.error_code, b.feature) === feature).map((b) => ({
        code: b.error_code,
        severity: b.severity,
        feature: b.feature,
        summary: b.summary,
        evidence: b.evidence,
        signature: b.signature,
      })),
    ];
    const observed = related.some((c) => c.observed) || recentlyObserved(observedAt[feature], now);
    const light = lightFromFindings(findings, observed);
    const worst = [...findings].sort((a, b) => severityRank(b.severity) - severityRank(a.severity))[0];
    const okCheck = related.find((c) => c.ok && c.observed);
    return {
      feature,
      light,
      label: featureLabel(feature),
      detail: worst?.summary || okCheck?.detail || (observed ? "Recently observed working." : "Not recently observed."),
      observedAt: observedAt[feature] || null,
    };
  });
}

function severityRank(s: string): number {
  if (s === "critical") return 4;
  if (s === "high") return 3;
  if (s === "medium") return 2;
  return 1;
}

export function featureLabel(feature: SentinelFeature): string {
  switch (feature) {
    case "gmail": return "Gmail";
    case "calendar": return "Calendar";
    case "places": return "Google Places";
    case "database": return "Database";
    case "worker": return "Worker";
    case "booking": return "Booking";
    case "outreach": return "Outreach safety";
    case "pipeline": return "Pipeline";
    case "ara": return "Ara actions";
    case "ara_voice": return "Ara voice";
    case "auth": return "Auth";
    case "test_mode": return "Test Mode";
    case "sentinel": return "Sentinel";
  }
}

import assert from "node:assert/strict";
import { describe, it } from "node:test";
import { EMPTY_INVARIANTS, evaluateInvariants } from "./invariants.ts";

describe("Sentinel invariants", () => {
  it("all healthy snapshot yields no findings", () => {
    assert.equal(evaluateInvariants(EMPTY_INVARIANTS).length, 0);
  });

  it("duplicate Place ID is PROSPECT_DUPLICATE_IDENTITY", () => {
    const findings = evaluateInvariants({
      ...EMPTY_INVARIANTS,
      duplicatePlaceIds: [{ placeId: "ChIJabc", uids: ["p1", "p2"] }],
    });
    assert.equal(findings[0]?.code, "PROSPECT_DUPLICATE_IDENTITY");
    assert.equal(findings[0]?.severity, "high");
  });

  it("reply with scheduled follow-up is FOLLOWUP_NOT_CANCELLED_AFTER_REPLY", () => {
    const findings = evaluateInvariants({
      ...EMPTY_INVARIANTS,
      replyButFollowupScheduled: [{ prospectUid: "p1", followupId: "fu-1" }],
    });
    assert.equal(findings[0]?.code, "FOLLOWUP_NOT_CANCELLED_AFTER_REPLY");
  });

  it("booked row missing google event id is BOOKING_PERSISTENCE_FAILED_AFTER_CALENDAR_CREATE", () => {
    const findings = evaluateInvariants({
      ...EMPTY_INVARIANTS,
      bookedMissingEventId: [{ id: "ce-1", prospectUid: "p1" }],
    });
    assert.equal(findings[0]?.code, "BOOKING_PERSISTENCE_FAILED_AFTER_CALENDAR_CREATE");
    assert.equal(findings[0]?.severity, "critical");
  });

  it("DNC with active sequence is critical", () => {
    const findings = evaluateInvariants({
      ...EMPTY_INVARIANTS,
      dncActiveSequence: [{ prospectUid: "p1", sequenceId: "seq-1" }],
    });
    assert.equal(findings[0]?.code, "DNC_SEQUENCE_ACTIVE");
    assert.equal(findings[0]?.severity, "critical");
  });

  it("test-mode leak is critical", () => {
    const findings = evaluateInvariants({
      ...EMPTY_INVARIANTS,
      testModeLeak: [{ messageId: "m1", recipient: "real@example.com" }],
    });
    assert.equal(findings[0]?.code, "TEST_MODE_INVARIANT_FAILED");
    assert.equal(findings[0]?.severity, "critical");
  });
});

import { makeFinding } from "./ledger.ts";
import type { InvariantSnapshot, SentinelFinding } from "./types.ts";
import { evaluateContactabilityInvariants } from "./contactability-check.ts";

export function evaluateInvariants(snap: InvariantSnapshot): SentinelFinding[] {
  const out: SentinelFinding[] = [];

  for (const row of snap.duplicatePlaceIds) {
    if (row.uids.length < 2) continue;
    out.push(makeFinding(
      "PROSPECT_DUPLICATE_IDENTITY",
      `Google Place ID ${row.placeId} appears on ${row.uids.length} prospect rows.`,
      { placeId: row.placeId, uids: row.uids },
      {
        extraKey: row.placeId,
        affected: row.uids.map((uid) => ({ uid })),
        reproduction: "Find Clients on an overlapping market should not insert a second row for the same Place ID.",
      },
    ));
  }

  for (const row of snap.bookedMissingEventId) {
    out.push(makeFinding(
      "BOOKING_PERSISTENCE_FAILED_AFTER_CALENDAR_CREATE",
      "A booked sales call is missing its Google Calendar event id.",
      { id: row.id, prospectUid: row.prospectUid },
      { extraKey: row.id, affected: [{ id: row.id, prospectUid: row.prospectUid }] },
    ));
  }

  for (const row of snap.bookedMissingPipeline) {
    const hasGoogle = Boolean((row.googleEventId || "").trim());
    out.push(makeFinding(
      "PIPELINE_STATE_MISMATCH",
      hasGoogle
        ? "A Google Calendar booking exists without a matching Call Booked pipeline state."
        : "A prospect is Call Booked without a booked Google Calendar event id. Repair will not invent a Calendar event.",
      { googleEventId: row.googleEventId, prospectUid: row.prospectUid },
      { extraKey: row.googleEventId || row.prospectUid, affected: [{ googleEventId: row.googleEventId, prospectUid: row.prospectUid }] },
    ));
  }

  for (const row of snap.replyButFollowupScheduled) {
    out.push(makeFinding(
      "FOLLOWUP_NOT_CANCELLED_AFTER_REPLY",
      "A prospect replied, but a follow-up is still scheduled.",
      { prospectUid: row.prospectUid, followupId: row.followupId },
      { extraKey: row.followupId, affected: [{ prospectUid: row.prospectUid, followupId: row.followupId }] },
    ));
  }

  for (const row of snap.dncActiveSequence) {
    out.push(makeFinding(
      "DNC_SEQUENCE_ACTIVE",
      "A Do Not Contact / skipped prospect still has an active outreach sequence.",
      { prospectUid: row.prospectUid, sequenceId: row.sequenceId },
      { extraKey: row.sequenceId, affected: [{ prospectUid: row.prospectUid }] },
    ));
  }

  for (const row of snap.bounceFutureSends) {
    out.push(makeFinding(
      "BOUNCE_FUTURE_SEND_SCHEDULED",
      "A hard bounce still has future sends scheduled.",
      { prospectUid: row.prospectUid, followupId: row.followupId },
      { extraKey: row.followupId, affected: [{ prospectUid: row.prospectUid }] },
    ));
  }

  for (const row of snap.testInRevenue) {
    out.push(makeFinding(
      "TEST_MODE_INVARIANT_FAILED",
      "A TEST workflow record is counted in real revenue / live pipeline totals.",
      { uid: row.uid },
      { extraKey: row.uid, affected: [{ uid: row.uid }] },
    ));
  }

  for (const row of snap.testModeLeak) {
    out.push(makeFinding(
      "TEST_MODE_INVARIANT_FAILED",
      "Test Mode is on, but a message was sent to an address that is not on the allowlist.",
      { messageId: row.messageId, recipient: row.recipient },
      { extraKey: row.messageId, affected: [{ messageId: row.messageId }] },
    ));
  }

  for (const row of snap.duplicateActivity) {
    if (row.count < 2) continue;
    out.push(makeFinding(
      "ARA_ACTION_DUPLICATE",
      `The same ${row.action} ran ${row.count} times from a repeated transcript.`,
      { action: row.action, detail: row.detail, count: row.count },
      { extraKey: `${row.action}|${row.detail}` },
    ));
  }

  if (snap.prospects?.length) out.push(...evaluateContactabilityInvariants(snap.prospects));
  return out;
}

export const EMPTY_INVARIANTS: InvariantSnapshot = {
  duplicatePlaceIds: [],
  bookedMissingEventId: [],
  bookedMissingPipeline: [],
  replyButFollowupScheduled: [],
  dncActiveSequence: [],
  bounceFutureSends: [],
  testInRevenue: [],
  testModeLeak: [],
  duplicateActivity: [],
};

import { createHash } from "node:crypto";
import { defaultSeverity, featureForCode, type SentinelCode, type SentinelSeverity } from "./codes.ts";
import type { SentinelEvidence, SentinelFinding } from "./types.ts";

export function findingSignature(code: SentinelCode, extra = ""): string {
  const raw = `${code}|${extra}`.slice(0, 400);
  return createHash("sha256").update(raw).digest("hex").slice(0, 24);
}

export function serialEvidence(evidence: Record<string, unknown> = {}): SentinelEvidence {
  const out: SentinelEvidence = {};
  for (const [k, v] of Object.entries(evidence)) {
    if (v == null) out[k] = null;
    else if (typeof v === "string" || typeof v === "number" || typeof v === "boolean") out[k] = v;
    else out[k] = JSON.stringify(v);
  }
  return out;
}

export function makeFinding(
  code: SentinelCode,
  summary: string,
  evidence: Record<string, unknown> = {},
  opts?: {
    severity?: SentinelSeverity;
    reproduction?: string;
    affected?: Array<Record<string, string>>;
    extraKey?: string;
  },
): SentinelFinding {
  return {
    code,
    severity: opts?.severity || defaultSeverity(code),
    feature: featureForCode(code),
    summary,
    evidence: serialEvidence(evidence),
    reproduction: opts?.reproduction,
    affected: opts?.affected,
    signature: findingSignature(code, opts?.extraKey || summary),
  };
}

export function mergeOccurrence(existingCount: number): number {
  return Math.max(1, existingCount) + 1;
}

import { asIsoTimestamp, compareEventStart, normalizeGoogleCalendarEvent } from "../google/calendar.ts";

/** In-process Calendar parser regression. Never calls Google. */
export const MALFORMED_CALENDAR_FIXTURE: unknown[] = [
  null,
  { id: "bad" },
  { status: "cancelled", id: "gone", start: { dateTime: "2026-09-21T19:00:00-05:00" } },
  {
    id: "evt-ok",
    summary: "Calendar Test",
    start: { dateTime: "2026-09-22T15:00:00-05:00" },
    end: { dateTime: "2026-09-22T15:30:00-05:00" },
  },
  { id: "evt-allday", summary: "Out", start: { date: "2026-09-23" }, end: { date: "2026-09-24" } },
  {
    id: "evt-conference",
    summary: "Meet",
    start: { dateTime: "2026-09-22T16:00:00-05:00" },
    end: { dateTime: "2026-09-22T16:30:00-05:00" },
    attendees: { "0": { email: "a@x.com" } },
    conferenceData: { entryPoints: [{ uri: "https://meet.google.com/abc" }] },
  },
];

export function runCalendarParserFixture(items: unknown[] = MALFORMED_CALENDAR_FIXTURE): {
  kept: number;
  skipped: number;
  threw: boolean;
  ids: string[];
} {
  const events: { id: string; start: string }[] = [];
  let skipped = 0;
  try {
    for (const item of items) {
      const event = normalizeGoogleCalendarEvent(item);
      if (event) events.push({ id: event.id, start: event.start });
      else if (item && typeof item === "object") {
        const status = String((item as { status?: unknown }).status || "").toLowerCase();
        if (status !== "cancelled") skipped += 1;
      }
    }
    const mixed = [
      ...events,
      { id: "sale-pg", start: asIsoTimestamp(new Date("2026-09-22T16:00:00.000Z")) },
    ];
    mixed.sort(compareEventStart);
    return { kept: events.length, skipped, threw: false, ids: events.map((e) => e.id) };
  } catch {
    return { kept: events.length, skipped, threw: true, ids: events.map((e) => e.id) };
  }
}

/**
 * Sentinel run orchestrator. Inspect / diagnose / record only.
 * Never sends mail, never creates or deletes Calendar events, never
 * writes OAuth, never disables Test Mode, never merges or deploys.
 */
import { env } from "@/lib/env.server";
import { evaluateChecks, checkVoice } from "./checks.ts";
import { launchLight, overallGrade, overallLabel, rollupSubsystems, recentlyObserved, voiceObservation } from "./health.ts";
import { runCalendarParserFixture } from "./parser.ts";
import { SENTINEL_WATCHING } from "./speech.ts";
import { SENTINEL_AUTO_FIX } from "./fix-prep.ts";
import { EMPTY_INVARIANTS } from "./invariants.ts";
import { placesKeyConfigured } from "@/lib/discovery/status";
import { secretPresent } from "@/lib/mail/test-mode";
import type { LiveProbeInput, SentinelFinding, SentinelSnapshot } from "./types.ts";
import type { SentinelMode } from "./codes.ts";

function productionSha(): string {
  return (env("VERCEL_GIT_COMMIT_SHA") || env("GITHUB_SHA") || "").trim();
}

function wantsProviderRead(mode: SentinelMode): boolean {
  return mode === "deep" || mode === "post_deploy";
}

export async function runSentinel(opts: {
  userId: string;
  mode: SentinelMode;
  environment?: string;
}): Promise<{ snapshot: SentinelSnapshot; findings: SentinelFinding[] }> {
  const {
    pingDatabase,
    loadInvariantSnapshot,
    insertRun,
    upsertFindings,
    resolveMissing,
    listOpenBugs,
    touchHeartbeat,
    loadHeartbeats,
    latestDeployment,
    recordDeployment,
    lastKnownGoodSha,
    latestRun,
  } = await import("./sql.server");
  const { loadIntegrationStatus } = await import("@/lib/mail/integration-status.server");
  const { loadWorkerHeartbeat } = await import("@/lib/mail/sql.server");

  const mode = opts.mode;
  const environment = opts.environment || (env("VERCEL_ENV") || "production");
  const sha = productionSha();
  const prev = (await latestRun())?.production_sha || "";
  const now = Date.now();

  const db = await pingDatabase();
  await touchHeartbeat("db", db.ok, db.ok ? "SENTINEL_OK" : "DATABASE_UNAVAILABLE", db.ok ? db.source : db.error || "db");

  const parser = runCalendarParserFixture();
  let invariants = EMPTY_INVARIANTS;
  if (db.ok) {
    try {
      invariants = await loadInvariantSnapshot(opts.userId);
    } catch {
      invariants = EMPTY_INVARIANTS;
    }
  }

  const beat = db.ok ? await loadWorkerHeartbeat().catch(() => ({ lastCompletedAt: null, lastResult: "", lastStartedAt: null, runId: null, source: "" })) : { lastCompletedAt: null, lastResult: "", lastStartedAt: null, runId: null, source: "" };
  const workerSecret = secretPresent(env("OUTREACH_JOB_SECRET") || env("CRON_SECRET"));

  let gmail = { connected: false, tokenValid: false, identity: "", probed: false };
  let calendar = {
    connected: false,
    tokenValid: false,
    listOk: false,
    listCode: "",
    freeBusyOk: false,
    parsedEvents: 0,
    skipped: 0,
    probed: false,
  };
  let testMode = true;

  if (db.ok) {
    try {
      const integration = await loadIntegrationStatus(opts.userId, { probeLive: wantsProviderRead(mode) });
      testMode = integration.test_mode;
      gmail = {
        connected: integration.gmail_connected,
        tokenValid: integration.gmail_token_valid,
        identity: integration.gmail_identity,
        probed: wantsProviderRead(mode),
      };
      calendar = {
        connected: integration.calendar_connected,
        tokenValid: integration.calendar_token_valid,
        listOk: false,
        listCode: integration.calendar_freebusy_code || "",
        freeBusyOk: integration.calendar_freebusy_valid,
        parsedEvents: 0,
        skipped: 0,
        probed: wantsProviderRead(mode),
      };
      if (wantsProviderRead(mode) && integration.calendar_connected) {
        const listed = await probeCalendarList(opts.userId);
        calendar.listOk = listed.ok;
        calendar.listCode = listed.code;
        calendar.parsedEvents = listed.count;
        calendar.skipped = listed.skipped;
        calendar.probed = true;
        if (!listed.ok && listed.code === "CALENDAR_TOKEN_REFRESH_FAILED") calendar.tokenValid = false;
      }
    } catch {
      /* fail closed into evaluateChecks */
    }
  }

  const priorBeats = db.ok ? await loadHeartbeats().catch(() => ({} as Awaited<ReturnType<typeof loadHeartbeats>>)) : {};
  const voiceBeat = priorBeats.ara_voice;
  const voiceObserved = Boolean(voiceBeat && recentlyObserved(voiceBeat.lastCheckAt || voiceBeat.lastOkAt || null, now));

  const input: LiveProbeInput = {
    now,
    mode,
    environment,
    productionSha: sha,
    previousSha: prev,
    db,
    http: { ok: true, status: 200 },
    worker: {
      lastCompletedAt: beat.lastCompletedAt,
      lastResult: beat.lastResult,
      secretPresent: workerSecret,
    },
    gmail,
    calendar,
    places: { keyConfigured: placesKeyConfigured() },
    testMode,
    parser,
    invariants,
    voice: {
      observed: voiceObserved,
      ok: Boolean(voiceBeat?.observedOk),
      code: voiceBeat?.lastCode || "",
      detail: voiceBeat?.observedOk ? "mint ok" : (voiceBeat?.lastCode || ""),
    },
  };

  const checks = evaluateChecks(input);
  const findings = checks.flatMap((c) => c.findings);

  await touchHeartbeat("gmail", gmail.connected && gmail.tokenValid, gmail.tokenValid ? "SENTINEL_OK" : "GMAIL_TOKEN_INVALID", gmail.identity || "");
  await touchHeartbeat("calendar", calendar.connected && calendar.tokenValid && (calendar.probed ? calendar.listOk : true) && !parser.threw, parser.threw ? "CALENDAR_LIST_PARSE_FAILED" : calendar.listOk || !calendar.probed ? "SENTINEL_OK" : (calendar.listCode || "CALENDAR_LIST_AUTH_FAILED"), calendar.listOk ? `${calendar.parsedEvents} events` : calendar.listCode);
  await touchHeartbeat("places", placesKeyConfigured() && !findings.some((f) => f.code === "PROSPECT_DUPLICATE_IDENTITY"), placesKeyConfigured() ? (findings.some((f) => f.code === "PROSPECT_DUPLICATE_IDENTITY") ? "PROSPECT_DUPLICATE_IDENTITY" : "SENTINEL_OK") : "PLACES_KEY_MISSING", placesKeyConfigured() ? "configured" : "missing");
  await touchHeartbeat("worker", !checks.find((c) => c.id === "worker")?.findings.length, checks.find((c) => c.id === "worker")?.code || "SENTINEL_OK", checks.find((c) => c.id === "worker")?.detail || "");
  const bookingOk = !findings.some((f) => f.feature === "booking" || f.code === "PIPELINE_STATE_MISMATCH" || f.code === "BOOKING_PERSISTENCE_FAILED_AFTER_CALENDAR_CREATE");
  const outreachOk = !findings.some((f) => f.feature === "outreach" || f.feature === "test_mode" || f.code === "FOLLOWUP_NOT_CANCELLED_AFTER_REPLY" || f.code === "DNC_SEQUENCE_ACTIVE" || f.code === "BOUNCE_FUTURE_SEND_SCHEDULED" || f.code === "TEST_MODE_INVARIANT_FAILED");
  const araOk = !findings.some((f) => f.feature === "ara");
  await touchHeartbeat("booking", bookingOk && db.ok, bookingOk ? "SENTINEL_OK" : (findings.find((f) => f.feature === "booking" || f.code === "PIPELINE_STATE_MISMATCH")?.code || "PIPELINE_STATE_MISMATCH"), bookingOk ? "invariants hold" : "invariant failed");
  await touchHeartbeat("outreach", outreachOk && db.ok, outreachOk ? "SENTINEL_OK" : (findings.find((f) => f.feature === "outreach" || f.feature === "test_mode")?.code || "PIPELINE_STATE_MISMATCH"), outreachOk ? "invariants hold" : "invariant failed");
  await touchHeartbeat("ara", araOk && db.ok, araOk ? "SENTINEL_OK" : "ARA_ACTION_DUPLICATE", araOk ? "no duplicate actions" : "duplicate action");
  await touchHeartbeat("sentinel", true, "SENTINEL_OK", mode);

  if (findings.length) await upsertFindings(findings, { environment, productionSha: sha });
  const resolvedCodes = await resolveMissing(findings.map((f) => f.signature), sha);
  const openBugs = await listOpenBugs();
  const beats = await loadHeartbeats();
  const observedAt: Record<string, string | null> = {
    gmail: beats.gmail?.lastOkAt || null,
    calendar: beats.calendar?.lastOkAt || null,
    places: beats.places?.lastOkAt || null,
    database: beats.db?.lastOkAt || null,
    worker: beats.worker?.lastOkAt || null,
    booking: beats.booking?.lastOkAt || beats.db?.lastOkAt || null,
    outreach: beats.outreach?.lastOkAt || beats.worker?.lastOkAt || null,
    ara: beats.ara?.lastOkAt || beats.sentinel?.lastOkAt || null,
    ara_voice: beats.ara_voice?.lastOkAt || beats.ara_voice?.lastCheckAt || null,
  };
  const subsystems = rollupSubsystems(checks, openBugs, observedAt);
  const overall = launchLight(subsystems);
  const voice = voiceObservation(subsystems);
  const grade = overallGrade(overall);
  const summary = overall === "green" && voice === "stale"
    ? "Outreach systems are healthy. Ara voice observation is stale."
    : overallLabel(overall, openBugs.length);

  await insertRun({
    userId: opts.userId,
    mode,
    environment,
    productionSha: sha,
    previousSha: prev,
    overall: grade,
    summary,
    checkCount: checks.length,
    findingCount: findings.length,
    payload: {
      checks: checks.map((c) => ({ id: c.id, ok: c.ok, code: c.code, cost: c.cost })),
      autoFix: SENTINEL_AUTO_FIX,
    },
  });

  if (mode === "post_deploy" && sha) {
    const knownGood = grade === "healthy" ? sha : await lastKnownGoodSha();
    const rollback = grade === "critical" && Boolean(knownGood) && knownGood !== sha;
    await recordDeployment({
      previousSha: prev,
      newSha: sha,
      testResult: "not_run_in_process",
      smokeResult: grade === "healthy" && voice === "stale" ? "healthy" : grade,
      newErrors: findings.map((f) => f.code),
      resolvedErrors: resolvedCodes,
      rollbackRecommended: rollback,
      rollbackReason: rollback
        ? `Critical regression began at SHA ${sha.slice(0, 7)}. Previous verified checkpoint ${knownGood.slice(0, 7)} was healthy. Rollback is available. Dylan decides.`
        : "",
      knownGoodSha: knownGood,
    });
  }

  const lastDeploy = await latestDeployment();
  const snapshot: SentinelSnapshot = {
    overall,
    overallLabel: summary,
    lastRunAt: new Date(now).toISOString(),
    lastRunMode: mode,
    productionSha: sha,
    previousSha: prev,
    openIssues: openBugs.length,
    criticalOpen: openBugs.filter((b) => b.severity === "critical").length,
    highOpen: openBugs.filter((b) => b.severity === "high").length,
    subsystems,
    alerts: openBugs.filter((b) => b.severity === "critical" || b.severity === "high"),
    bugs: openBugs,
    lastDeploy,
    rollback: lastDeploy?.rollback_recommended
      ? { recommended: true, reason: lastDeploy.rollback_reason, knownGoodSha: lastDeploy.known_good_sha }
      : null,
    watching: SENTINEL_WATCHING,
    autoFix: false,
  };
  return { snapshot, findings };
}

async function probeCalendarList(userId: string): Promise<{ ok: boolean; code: string; count: number; skipped: number }> {
  try {
    const { accessFor } = await import("@/lib/mail/live.server");
    const { listEvents } = await import("@/lib/google/calendar");
    const tokens = await accessFor(userId, "calendar");
    if (!tokens) return { ok: false, code: "CALENDAR_NOT_AUTHORIZED", count: 0, skipped: 0 };
    const from = new Date();
    const to = new Date(from.getTime() + 7 * 24 * 60 * 60 * 1000);
    const listed = await listEvents(tokens.access_token, from, to, fetch, tokens.email);
    if (!listed.ok) return { ok: false, code: listed.code, count: 0, skipped: 0 };
    return { ok: true, code: "SENTINEL_OK", count: listed.events.length, skipped: 0 };
  } catch {
    return { ok: false, code: "CALENDAR_LIST_UPSTREAM_5XX", count: 0, skipped: 0 };
  }
}

export async function loadSentinelSnapshot(): Promise<SentinelSnapshot> {
  const { listOpenBugs, latestRun, loadHeartbeats, latestDeployment } = await import("./sql.server");
  let openBugs: Awaited<ReturnType<typeof listOpenBugs>> = [];
  let run: Awaited<ReturnType<typeof latestRun>> = null;
  let beats: Awaited<ReturnType<typeof loadHeartbeats>> = {};
  let lastDeploy: Awaited<ReturnType<typeof latestDeployment>> = null;
  try {
    [openBugs, run, beats, lastDeploy] = await Promise.all([
      listOpenBugs(),
      latestRun(),
      loadHeartbeats(),
      latestDeployment(),
    ]);
  } catch {
    openBugs = [];
  }
  const observedAt: Record<string, string | null> = {
    gmail: beats.gmail?.lastOkAt || null,
    calendar: beats.calendar?.lastOkAt || null,
    places: beats.places?.lastOkAt || null,
    database: beats.db?.lastOkAt || null,
    worker: beats.worker?.lastOkAt || null,
    booking: beats.booking?.lastOkAt || beats.db?.lastOkAt || null,
    outreach: beats.outreach?.lastOkAt || beats.worker?.lastOkAt || null,
    ara: beats.ara?.lastOkAt || beats.sentinel?.lastOkAt || null,
    ara_voice: beats.ara_voice?.lastOkAt || beats.ara_voice?.lastCheckAt || null,
  };
  const voiceObserved = Boolean(beats.ara_voice && recentlyObserved(beats.ara_voice.lastCheckAt || beats.ara_voice.lastOkAt || null));
  const voiceCheck = checkVoice({
    voice: {
      observed: voiceObserved,
      ok: Boolean(beats.ara_voice?.observedOk),
      code: beats.ara_voice?.lastCode || "",
      detail: beats.ara_voice?.observedOk ? "mint ok" : (beats.ara_voice?.lastCode || ""),
    },
  });
  const subsystems = rollupSubsystems([voiceCheck], openBugs, observedAt);
  const overall = run
    ? (run.overall === "healthy" ? "green" : run.overall === "critical" ? "red" : run.overall === "degraded" ? "yellow" : "unknown")
    : launchLight(subsystems);
  return {
    overall,
    overallLabel: overallLabel(overall, openBugs.length),
    lastRunAt: run?.finished_at || run?.started_at || null,
    lastRunMode: run?.mode || "",
    productionSha: run?.production_sha || productionSha(),
    previousSha: run?.previous_sha || "",
    openIssues: openBugs.length,
    criticalOpen: openBugs.filter((b) => b.severity === "critical").length,
    highOpen: openBugs.filter((b) => b.severity === "high").length,
    subsystems,
    alerts: openBugs.filter((b) => b.severity === "critical" || b.severity === "high"),
    bugs: openBugs,
    lastDeploy,
    rollback: lastDeploy?.rollback_recommended
      ? { recommended: true, reason: lastDeploy.rollback_reason, knownGoodSha: lastDeploy.known_good_sha }
      : null,
    watching: SENTINEL_WATCHING,
    autoFix: false,
  };
}

import { featureLabel } from "./health.ts";
import type { SentinelSnapshot } from "./types.ts";

export type SentinelSpeech = {
  healthy: string;
  bugs: string;
  brokeToday: string;
  lastDeploy: string;
  worker: string;
  watching: string;
  spoken: string;
};

export function everythingWorkingSpeech(snap: SentinelSnapshot): string {
  const red = (snap.subsystems || []).filter((s) => s.light === "red");
  const voiceRed = red.some((s) => s.feature === "ara_voice");
  const voice = (snap.subsystems || []).find((s) => s.feature === "ara_voice");
  const voiceStale = voice && voice.light !== "green" && voice.light !== "red";
  if (snap.overall === "green" && voiceStale) {
    return "Outreach systems are healthy. Ara voice has not been observed recently. That is separate from sending email.";
  }
  if (snap.overall === "green" && !red.length) {
    return "Yes. Gmail, Calendar, Google Places, Database, Worker, Booking, Outreach safety, Ara actions, and Ara voice are all healthy.";
  }
  if (voiceRed && red.length === 1) {
    return "Most systems are healthy, but Ara voice is currently unavailable.";
  }
  if (snap.overall === "red") {
    return `No. Sentinel found ${snap.criticalOpen || snap.openIssues} production problem${(snap.criticalOpen || snap.openIssues) === 1 ? "" : "s"}.`;
  }
  if (snap.overall === "yellow") {
    return "Not fully. Sentinel sees something that needs attention, but no critical outage.";
  }
  return "I don’t have a completed Sentinel observation yet, so I won’t guess.";
}

export function sentinelSpeech(snap: SentinelSnapshot, topic?: string): SentinelSpeech {
  const healthy = everythingWorkingSpeech(snap);

  const open = snap.bugs.filter((b) => b.status === "open");
  const bugs = !open.length
    ? "Sentinel has no open bugs on the ledger."
    : open.slice(0, 5).map((b) => `${b.error_code}: ${b.summary}`).join(" ");

  const today = open.filter((b) => isToday(b.last_seen_at) || isToday(b.first_seen_at));
  const brokeToday = !today.length
    ? "Sentinel did not record a new production break today."
    : today.map((b) => `${b.error_code} on ${featureLabel(b.feature)}.`).join(" ");

  const deploy = snap.lastDeploy;
  const lastDeploy = !deploy
    ? "Sentinel does not have a deployment comparison yet."
    : deploy.rollback_recommended
      ? `The latest production SHA is ${shortSha(deploy.new_sha)}. Sentinel recommends rollback to ${shortSha(deploy.known_good_sha) || "the last known-good checkpoint"}. ${deploy.rollback_reason} Dylan decides — Sentinel will not roll back by itself.`
      : `The latest production SHA is ${shortSha(deploy.new_sha)}. Previous was ${shortSha(deploy.previous_sha) || "unknown"}. Smoke: ${deploy.smoke_result || "not recorded"}.`;

  const worker = snap.subsystems.find((s) => s.feature === "worker");
  const workerAnswer = !worker
    ? "I don’t have a worker observation yet."
    : worker.light === "green"
      ? `Yes. ${worker.detail}`
      : worker.detail;

  const watching = snap.watching.length
    ? `Sentinel watches ${snap.watching.join(", ")}. It inspects, diagnoses, and records. It does not merge, deploy, or change Test Mode by itself.`
    : "Sentinel watches Gmail, Calendar, Google Places, the database, the outreach worker, booking, outreach safety, and Ara actions.";

  const spoken = pickTopic(topic, { healthy, bugs, brokeToday, lastDeploy, worker: workerAnswer, watching });
  return { healthy, bugs, brokeToday, lastDeploy, worker: workerAnswer, watching, spoken };
}

function pickTopic(
  topic: string | undefined,
  parts: Omit<SentinelSpeech, "spoken">,
): string {
  const t = (topic || "").toLowerCase();
  if (/watch/.test(t)) return parts.watching;
  if (/worker/.test(t)) return parts.worker;
  if (/deploy|sha|last (ship|release)/.test(t)) return parts.lastDeploy;
  if (/broke|today|what happened/.test(t)) return `${parts.brokeToday} ${parts.bugs}`.trim();
  if (/bug/.test(t)) return parts.bugs;
  return `${parts.healthy} ${parts.bugs}`.trim();
}

function shortSha(sha: string): string {
  return (sha || "").slice(0, 7);
}

function isToday(iso: string): boolean {
  if (!iso) return false;
  const d = new Date(iso);
  if (!Number.isFinite(d.getTime())) return false;
  const now = new Date();
  return d.toDateString() === now.toDateString();
}

export const SENTINEL_WATCHING = [
  "Gmail",
  "Calendar",
  "Google Places",
  "the database",
  "the outreach worker",
  "booking",
  "outreach safety",
  "Pipeline invariants",
  "Ara actions",
  "Ara voice",
  "Test Mode",
];

export function parseSentinelAsk(text: string): { kind: "status" | "open" | "none"; topic?: string } {
  const t = (text || "").toLowerCase().replace(/[?!.,]/g, " ").replace(/\s+/g, " ").trim();
  if (/\b(open|show|go to)\b/.test(t) && /\b(system health|sentinel)\b/.test(t)) {
    return { kind: "open" };
  }
  if (
    /is lascengine healthy/.test(t)
    || /is (the )?(app|engine|production|lascengine) healthy/.test(t)
    || /are there any bugs/.test(t)
    || /what broke( today)?/.test(t)
    || /did the last (deploy|deployment) pass/.test(t)
    || /is the worker running/.test(t)
    || /what is sentinel watching/.test(t)
    || /any (production )?regressions/.test(t)
    || /is everything working/.test(t)
  ) {
    return { kind: "status", topic: t };
  }
  return { kind: "none" };
}

