    assert.equal(announceToAra({ type: "INFO", text: "  ", dedupeKey: "empty" }), null);
  });
});

export type AnnouncePriority =
  | "BLOCKER"
  | "ERROR"
  | "WARNING"
  | "INFO"
  | "SUCCESS"
  | "TASK"
  | "REPLY"
  | "NAVIGATION";

export type AnnounceEvent = {
  type: AnnouncePriority;
  text: string;
  spoken?: string;
  view?: string;
  action?: string;
  dedupeKey: string;
};

const recent = new Map<string, number>();
const DEDUPE_MS = 30_000;

export function resetAnnounceDedupe(): void {
  recent.clear();
}

export function shouldAnnounce(ev: Pick<AnnounceEvent, "dedupeKey" | "text">, now = Date.now()): boolean {
  const text = (ev.text || "").trim();
  if (!text) return false;
  const last = recent.get(ev.dedupeKey) || 0;
  if (last > 0 && now - last < DEDUPE_MS) return false;
  recent.set(ev.dedupeKey, now);
  return true;
}

/** Returns the event when it should be spoken; otherwise null (duplicate / empty). */
export function announceToAra(ev: AnnounceEvent, now = Date.now()): AnnounceEvent | null {
  const text = (ev.spoken || ev.text || "").trim();
  if (!text) return null;
  if (!shouldAnnounce({ dedupeKey: ev.dedupeKey, text }, now)) return null;
  return { ...ev, text, spoken: text };
}

export function announceSource(type: AnnouncePriority): "BLOCKER" | "ERROR" | "WARNING" | "TASK" | "NAVIGATION" | "SCREEN_READER" {
  if (type === "BLOCKER") return "BLOCKER";
  if (type === "ERROR") return "ERROR";
  if (type === "WARNING") return "WARNING";
  if (type === "TASK" || type === "REPLY") return "TASK";
  if (type === "NAVIGATION") return "NAVIGATION";
  return "SCREEN_READER";
}

import assert from "node:assert/strict";
import { describe, it } from "node:test";
import { realtimeErrorText } from "./voice-failure.ts";
import { shouldFailClosedOnRealtimeError } from "./lifecycle.ts";

describe("Conversation Mode realtime errors", () => {
  it("does not take Ara down for a benign response.cancel after a calendar intercept", () => {
    const cancel = {
      type: "error",
      error: { type: "invalid_request_error", code: "response_cancel_not_active", message: "Cancellation failed: no active response" },
    };
    assert.match(realtimeErrorText(cancel), /response_cancel_not_active|no active response/i);
    assert.equal(shouldFailClosedOnRealtimeError(cancel), false);

    const inProgress = {
      type: "error",
      error: { code: "conversation_already_has_active_response", message: "Already has an active response" },
    };
    assert.equal(shouldFailClosedOnRealtimeError(inProgress), false);

    const buffer = {
      type: "error",
      error: { message: "input_audio_buffer is too small" },
    };
    assert.equal(shouldFailClosedOnRealtimeError(buffer), false);
  });

  it("still fails closed on fatal auth / session errors", () => {
    const auth = { type: "error", error: { message: "invalid auth token" } };
    assert.equal(shouldFailClosedOnRealtimeError(auth), true);
    const session = { type: "error", error: { message: "invalid session configuration" } };
    assert.equal(shouldFailClosedOnRealtimeError(session), true);
  });

  it("does not leak Authorization headers from error text", () => {
    const ev = { type: "error", error: { message: "Cancellation failed: no active response" } };
    assert.doesNotMatch(realtimeErrorText(ev), /Authorization|Bearer |xai-/i);
  });
});

import { isAllowedTool, type AraDeskContext } from "./tools.ts";
import { sessionUpdatePayload } from "./ara-context.ts";
import { conversationItemEvent } from "./ara-memory.ts";
import { realtimeErrorText, voiceFailureReason } from "./voice-failure.ts";
import { shouldFailClosedOnRealtimeError } from "./lifecycle.ts";
import { araSpeech } from "./speech-controller.ts";
import { micStreamLive, stopMicStream } from "./mic.ts";

export type AraStatus = "ready" | "connecting" | "listening" | "speaking" | "unavailable" | "mic_needed";

export type AraHandlers = {
  onStatus: (s: AraStatus) => void;
  onUserTranscript: (text: string, isFinal: boolean, itemId?: string) => void;
  onAraTranscript: (text: string, isFinal?: boolean) => void;
  onToolCall: (name: string, args: Record<string, unknown>, callId: string) => Promise<Record<string, unknown>>;
  onError: (plain: string) => void;
  onMic?: (live: boolean, reason?: string) => void;
};

function floatTo16(f32: Float32Array): Int16Array {
  const out = new Int16Array(f32.length);
  for (let i = 0; i < f32.length; i++) {
    const s = Math.max(-1, Math.min(1, f32[i]));
    out[i] = s < 0 ? s * 0x8000 : s * 0x7fff;
  }
  return out;
}

function downsample(input: Float32Array, fromRate: number, toRate: number): Float32Array {
  if (fromRate === toRate) return input;
  const ratio = fromRate / toRate;
  const n = Math.floor(input.length / ratio);
  const out = new Float32Array(n);
  for (let i = 0; i < n; i++) out[i] = input[Math.floor(i * ratio)];
  return out;
}

function pcmToBase64(pcm: Int16Array): string {
  const bytes = new Uint8Array(pcm.buffer, pcm.byteOffset, pcm.byteLength);
  let s = "";
  const chunk = 0x8000;
  for (let i = 0; i < bytes.length; i += chunk) {
    s += String.fromCharCode(...bytes.subarray(i, chunk + i));
  }
  return btoa(s);
}

function base64ToPcm(b64: string): Int16Array {
  const bin = atob(b64);
  const bytes = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) bytes[i] = bin.charCodeAt(i);
  return new Int16Array(bytes.buffer);
}

export class AraRealtime {
  private ws: WebSocket | null = null;
  private recCtx: AudioContext | null = null;
  private stream: MediaStream | null = null;
  private processor: ScriptProcessorNode | null = null;
  private muted = false;
  private pendingCalls = 0;
  private closed = false;
  private handledCalls = new Set<string>();
  private micGated = false;
  private micLive = false;
  private sessionReady = false;
  private givenStream = false;
  private seededIds = new Set<string>();

  constructor(
    private readonly token: string,
    private readonly wsUrl: string,
    private readonly handlers: AraHandlers,
  ) {}

  get microphoneLive(): boolean {
    return this.micLive && micStreamLive(this.stream);
  }

  get sessionIsReady(): boolean {
    return this.sessionReady && this.ws?.readyState === WebSocket.OPEN;
  }

  setMuted(v: boolean) {
    this.muted = v;
    araSpeech().setMuted(v);
  }

  setMicGated(v: boolean) {
    this.micGated = v;
  }

  cancelResponse() {
    if (this.ws?.readyState === WebSocket.OPEN) {
      try { this.ws.send(JSON.stringify({ type: "response.cancel" })); } catch { /* ignore */ }
    }
    araSpeech().conversationEnded();
  }

  async start(ctx: AraDeskContext, opts?: { stream?: MediaStream | null; withMic?: boolean }): Promise<void> {
    this.handlers.onStatus("connecting");
    araSpeech().unlock();
    const withMic = opts?.withMic !== false;
    if (withMic) {
      const ok = await this.startMic(opts?.stream || null);
      if (!ok) {
        this.handlers.onStatus("mic_needed");
        return;
      }
    }
    const url = this.wsUrl;
    const proto = `xai-client-secret.${this.token}`;
    const ws = new WebSocket(url, [proto]);
    this.ws = ws;
    ws.onopen = () => {
      if (this.closed) {
        ws.close();
        return;
      }
      ws.send(JSON.stringify(sessionUpdatePayload(ctx)));
      this.seedSavedConversation(ctx);
      this.sessionReady = true;
      araSpeech().setSession(true);
      if (this.microphoneLive) this.handlers.onStatus("listening");
      else this.handlers.onStatus("ready");
    };
    ws.onerror = () => {
      if (!this.closed) this.handlers.onError(voiceFailureReason("WEBSOCKET_FAILED"));
      this.handlers.onStatus("unavailable");
      araSpeech().setSession(false);
    };
    ws.onclose = () => {
      this.sessionReady = false;
      araSpeech().setSession(false);
      if (!this.closed) {
        this.handlers.onStatus("unavailable");
        this.handlers.onError(voiceFailureReason("WEBSOCKET_FAILED"));
      }
    };
    ws.onmessage = (ev) => {
      if (typeof ev.data !== "string") return;
      try {
        void this.onEvent(JSON.parse(ev.data) as Record<string, unknown>);
      } catch {
        /* ignore malformed frames */
      }
    };
  }

  updateContext(ctx: AraDeskContext) {
    if (this.ws?.readyState === WebSocket.OPEN) {
      this.ws.send(JSON.stringify(sessionUpdatePayload(ctx)));
      this.seedSavedConversation(ctx);
    }
  }

  private seedSavedConversation(ctx: AraDeskContext) {
    if (this.ws?.readyState !== WebSocket.OPEN) return;
    for (const message of (ctx.conversationMessages || []).slice(-30)) {
      if (!message.id || !message.text || this.seededIds.has(message.id)) continue;
      this.seededIds.add(message.id);
      this.ws.send(JSON.stringify(conversationItemEvent(message)));
    }
  }

  stop() {
    this.closed = true;
    this.seededIds.clear();
    this.sessionReady = false;
    this.micLive = false;
    try { this.processor?.disconnect(); } catch { /* ignore */ }
    if (!this.givenStream) stopMicStream(this.stream);
    this.stream = null;
    void this.recCtx?.close();
    try { this.ws?.close(); } catch { /* ignore */ }
    this.ws = null;
    araSpeech().setSession(false);
    araSpeech().conversationEnded();
    this.handlers.onStatus("ready");
  }

  private async startMic(existing: MediaStream | null): Promise<boolean> {
    try {
      if (existing && micStreamLive(existing)) {
        this.stream = existing;
        this.givenStream = true;
      } else {
        this.stream = await navigator.mediaDevices.getUserMedia({ audio: { echoCancellation: true, noiseSuppression: true } });
        this.givenStream = false;
      }
      if (!micStreamLive(this.stream)) {
        this.handlers.onMic?.(false, "Microphone permission is needed to talk to Ara.");
        this.handlers.onError(voiceFailureReason("MIC_BLOCKED"));
        return false;
      }
      this.recCtx = new AudioContext();
      if (this.recCtx.state === "suspended") await this.recCtx.resume();
      const src = this.recCtx.createMediaStreamSource(this.stream);
      const proc = this.recCtx.createScriptProcessor(4096, 1, 1);
      this.processor = proc;
      proc.onaudioprocess = (e) => {
        if (!this.ws || this.ws.readyState !== WebSocket.OPEN || this.closed || this.micGated) return;
        const f32 = e.inputBuffer.getChannelData(0);
        const ds = downsample(f32, this.recCtx?.sampleRate || 48000, 24000);
        const pcm = floatTo16(ds);
        this.ws.send(JSON.stringify({ type: "input_audio_buffer.append", audio: pcmToBase64(pcm) }));
      };
      const mute = this.recCtx.createGain();
      mute.gain.value = 0;
      src.connect(proc);
      proc.connect(mute);
      mute.connect(this.recCtx.destination);
      this.micLive = true;
      this.handlers.onMic?.(true);
      araSpeech().onMicGate = (gated) => this.setMicGated(gated);
      return true;
    } catch {
      this.micLive = false;
      this.handlers.onMic?.(false, "Microphone permission is needed to talk to Ara.");
      this.handlers.onError("Microphone permission is needed to talk to Ara. Buttons still work.");
      return false;
    }
  }

  /** Kept for tests and conversation PCM → the one Ara speech controller. */
  playPcm(pcm: Int16Array) {
    if (this.muted || this.closed) return;
    araSpeech().playConversationPcm(pcm);
  }

  private async runTool(name: string, args: Record<string, unknown>, callId: string) {
    if (callId && this.handledCalls.has(callId)) return;
    if (callId) this.handledCalls.add(callId);
    this.pendingCalls += 1;
    let output: Record<string, unknown>;
    if (!isAllowedTool(name)) {
      output = { ok: false, reason: "That tool is not on the allowlist." };
    } else {
      try {
        output = await this.handlers.onToolCall(name, args, callId);
      } catch {
        output = { ok: false, reason: "That action did not finish." };
      }
    }
    this.pendingCalls -= 1;
    if (this.ws?.readyState === WebSocket.OPEN) {
      this.ws.send(JSON.stringify({
        type: "conversation.item.create",
        item: { type: "function_call_output", call_id: callId, output: JSON.stringify(output) },
      }));
      if (this.pendingCalls <= 0 && !output.already_spoken) {
        this.ws.send(JSON.stringify({ type: "response.create" }));
      }
    }
  }

  private async onEvent(ev: Record<string, unknown>) {
    const type = String(ev.type || "");
    if (type === "error") {
      if (!shouldFailClosedOnRealtimeError(ev)) {
        if (this.microphoneLive) this.handlers.onStatus("listening");
        else if (this.sessionReady) this.handlers.onStatus("ready");
        return;
      }
      const detail = realtimeErrorText(ev).toLowerCase();
      const code = /auth|token|unauthor|forbidden|invalid api key|not authenticated/.test(detail)
        ? "VOICE_AUTH_FAILED"
        : "PROVIDER_ERROR";
      this.handlers.onError(voiceFailureReason(code));
      this.handlers.onStatus("unavailable");
      return;
    }
    if (type === "input_audio_buffer.speech_started") {
      if (this.microphoneLive) this.handlers.onStatus("listening");
    }
    if (type === "response.output_audio.delta" && typeof ev.delta === "string") {
      this.handlers.onStatus("speaking");
      this.playPcm(base64ToPcm(ev.delta));
    }
    if (type === "response.output_audio_transcript.delta" && typeof ev.delta === "string") {
      this.handlers.onAraTranscript(ev.delta, false);
    }
    if (type === "response.output_audio_transcript.done" && typeof ev.transcript === "string") {
      this.handlers.onAraTranscript(ev.transcript, true);
    }
    if (type === "conversation.item.input_audio_transcription.updated" && typeof ev.transcript === "string") {
      this.handlers.onUserTranscript(ev.transcript, false, String(ev.item_id || ""));
    }
    if (type === "conversation.item.input_audio_transcription.completed") {
      const text = String(ev.transcript || ev.text || "");
      if (text) this.handlers.onUserTranscript(text, true, String(ev.item_id || ""));
    }
    if (type === "response.function_call_arguments.done") {
      const name = String(ev.name || "");
      const callId = String(ev.call_id || ev.callId || "");
      let args: Record<string, unknown> = {};
      try { args = JSON.parse(String(ev.arguments || "{}")) as Record<string, unknown>; } catch { args = {}; }
      await this.runTool(name, args, callId);
    }
    if (type === "response.output_item.done") {
      const item = ev.item as { type?: string; name?: string; call_id?: string; arguments?: string } | undefined;
      if (item?.type === "function_call" && item.name && item.call_id) {
        let args: Record<string, unknown> = {};
        try { args = JSON.parse(String(item.arguments || "{}")) as Record<string, unknown>; } catch { args = {}; }
        await this.runTool(item.name, args, item.call_id);
      }
    }
    if (type === "response.done") {
      araSpeech().conversationEnded();
      if (this.microphoneLive) this.handlers.onStatus("listening");
      else this.handlers.onStatus(this.sessionReady ? "ready" : "unavailable");
    }
  }
}

import assert from "node:assert/strict";
import { describe, it } from "node:test";
import { appendAraTurn, deleteAraThread, deleteAraTurn, emptyAraLog, searchAraLog, startAraThread } from "./ara-history.ts";

describe("Ara conversation log", () => {
  it("keeps a conversation and titles it from what you said", () => {
    let log = emptyAraLog();
    log = appendAraTurn(log, "you", "Book AWO Lending Thursday at 11", 1_000);
    log = appendAraTurn(log, "ara", "Done — I scheduled AWO Lending for Thursday at 11:00 AM.", 2_000);
    assert.equal(log.threads.length, 1);
    assert.match(log.threads[0].title, /AWO Lending/);
    assert.equal(log.threads[0].turns.length, 2);
  });

  it("does not save the same line twice in a row", () => {
    let log = appendAraTurn(emptyAraLog(), "ara", "Done — booked.", 1_000);
    log = appendAraTurn(log, "ara", "Done — booked.", 2_000);
    assert.equal(log.threads[0].turns.length, 1);
  });

  it("starts a new conversation after a long gap", () => {
    let log = appendAraTurn(emptyAraLog(), "you", "First thing", 1_000);
    log = appendAraTurn(log, "you", "Much later", 1_000 + 46 * 60 * 1000);
    assert.equal(log.threads.length, 2);
    assert.equal(log.threads[0].title, "Much later");
  });

  it("search finds a message inside a conversation", () => {
    let log = appendAraTurn(emptyAraLog(), "you", "What is on Thursday", 1_000);
    log = appendAraTurn(log, "ara", "AWO Lending at 11.", 2_000);
    const hits = searchAraLog(log, "awo");
    assert.equal(hits.length >= 1, true);
    assert.match(hits[0].snippet, /AWO/i);
  });

  it("deletes one saved message and drops an empty conversation", () => {
    let log = appendAraTurn(emptyAraLog(), "you", "Keep this", 1_000);
    log = appendAraTurn(log, "ara", "Throw this away", 2_000);
    const araId = log.threads[0].turns[1].id;
    log = deleteAraTurn(log, log.threads[0].id, araId);
    assert.equal(log.threads[0].turns.length, 1);
    assert.equal(log.threads[0].turns[0].text, "Keep this");
    const onlyId = log.threads[0].turns[0].id;
    log = deleteAraTurn(log, log.threads[0].id, onlyId);
    assert.equal(log.threads.length, 0);
    assert.equal(log.activeId, null);
  });

  it("deletes a whole saved conversation", () => {
    let log = appendAraTurn(emptyAraLog(), "you", "First", 1_000);
    log = appendAraTurn(log, "you", "Second", 1_000 + 46 * 60 * 1000);
    const drop = log.threads[1].id;
    log = deleteAraThread(log, drop);
    assert.equal(log.threads.length, 1);
    assert.equal(log.threads[0].title, "Second");
  });

  it("new conversation does not duplicate an empty one", () => {
    const started = startAraThread(emptyAraLog(), 5);
    const again = startAraThread(started, 6);
    assert.equal(again.threads.length, 1);
  });
});

export type AraTurn = {
  id: string;
  role: "you" | "ara";
  text: string;
  at: number;
};

export type AraThread = {
  id: string;
  title: string;
  updatedAt: number;
  turns: AraTurn[];
};

export type AraLog = {
  activeId: string | null;
  threads: AraThread[];
};

export type AraHit = {
  threadId: string;
  turnId: string;
  title: string;
  role: AraTurn["role"];
  snippet: string;
  at: number;
};

const GAP_MS = 45 * 60 * 1000;
const DEDUPE_MS = 12_000;
const MAX_THREADS = 40;
const MAX_TURNS = 200;

export function emptyAraLog(): AraLog {
  return { activeId: null, threads: [] };
}

function uid(): string {
  return `ara_${Date.now().toString(36)}_${Math.random().toString(36).slice(2, 8)}`;
}

export function titleFromTurn(text: string): string {
  const clean = text.replace(/\s+/g, " ").trim();
  if (clean.length <= 42) return clean;
  return `${clean.slice(0, 41).trim()}…`;
}

export function appendAraTurn(log: AraLog, role: AraTurn["role"], text: string, now = Date.now()): AraLog {
  const clean = text.replace(/\s+/g, " ").trim();
  if (!clean) return log;
  const threads = log.threads.map((t) => ({ ...t, turns: t.turns.slice() }));
  let active = threads.find((t) => t.id === log.activeId) || null;
  const last = active?.turns[active.turns.length - 1];
  if (last && last.role === role && last.text === clean && now - last.at < DEDUPE_MS) return log;
  const stale = !active || (role === "you" && active.turns.length > 0 && now - active.updatedAt > GAP_MS);
  if (stale || !active) {
    active = {
      id: uid(),
      title: role === "you" ? titleFromTurn(clean) : "Ara",
      updatedAt: now,
      turns: [],
    };
    threads.unshift(active);
  }
  if (role === "you" && (active.turns.length === 0 || active.title === "Ara")) {
    active.title = titleFromTurn(clean);
  }
  active.turns.push({ id: uid(), role, text: clean, at: now });
  if (active.turns.length > MAX_TURNS) active.turns = active.turns.slice(-MAX_TURNS);
  active.updatedAt = now;
  const next = threads
    .map((t) => (t.id === active!.id ? active! : t))
    .sort((a, b) => b.updatedAt - a.updatedAt)
    .slice(0, MAX_THREADS);
  return { activeId: active.id, threads: next };
}

export function deleteAraTurn(log: AraLog, threadId: string, turnId: string): AraLog {
  const threads = log.threads.flatMap((thread) => {
    if (thread.id !== threadId) return [thread];
    if (!thread.turns.some((turn) => turn.id === turnId)) return [thread];
    const turns = thread.turns.filter((turn) => turn.id !== turnId);
    if (!turns.length) return [];
    const firstYou = turns.find((turn) => turn.role === "you");
    return [{
      ...thread,
      turns,
      title: firstYou ? titleFromTurn(firstYou.text) : "Ara",
      updatedAt: turns[turns.length - 1].at,
    }];
  });
  const activeId = threads.some((thread) => thread.id === log.activeId) ? log.activeId : (threads[0]?.id ?? null);
  return { activeId, threads };
}

export function deleteAraThread(log: AraLog, threadId: string): AraLog {
  const threads = log.threads.filter((thread) => thread.id !== threadId);
  const activeId = log.activeId === threadId ? (threads[0]?.id ?? null) : log.activeId;
  return { activeId, threads };
}

export function startAraThread(log: AraLog, now = Date.now()): AraLog {
  const current = log.threads.find((t) => t.id === log.activeId);
  if (current && current.turns.length === 0) return log;
  const thread: AraThread = { id: uid(), title: "New conversation", updatedAt: now, turns: [] };
  return { activeId: thread.id, threads: [thread, ...log.threads].slice(0, MAX_THREADS) };
}

function snippet(text: string, term: string): string {
  const lower = text.toLowerCase();
  const at = lower.indexOf(term.toLowerCase());
  const start = Math.max(0, at < 0 ? 0 : at - 28);
  const slice = text.slice(start, start + 90).trim();
  return `${start > 0 ? "…" : ""}${slice}${start + 90 < text.length ? "…" : ""}`;
}

export function searchAraLog(log: AraLog, query: string): AraHit[] {
  const terms = query.trim().toLowerCase().split(/\s+/).filter(Boolean);
  if (!terms.length) return [];
  const hits: AraHit[] = [];
  for (const thread of log.threads) {
    const title = thread.title.toLowerCase();
    if (terms.every((term) => title.includes(term))) {
      const first = thread.turns[0];
      hits.push({
        threadId: thread.id,
        turnId: first?.id || thread.id,
        title: thread.title,
        role: "you",
        snippet: thread.title,
        at: thread.updatedAt,
      });
    }
    for (const turn of thread.turns) {
      const hay = turn.text.toLowerCase();
      if (!terms.every((term) => hay.includes(term))) continue;
      hits.push({
        threadId: thread.id,
        turnId: turn.id,
        title: thread.title,
        role: turn.role,
        snippet: snippet(turn.text, terms[0]),
        at: turn.at,
      });
    }
  }
  hits.sort((a, b) => b.at - a.at);
  return hits.slice(0, 40);
}

const KEY_PREFIX = "lasc.ara.chats.v1";

export function araLogKey(userId?: string | null): string {
  return `${KEY_PREFIX}:${userId || "local"}`;
}

export function loadAraLog(userId?: string | null): AraLog {
  if (typeof localStorage === "undefined") return emptyAraLog();
  try {
    const raw = localStorage.getItem(araLogKey(userId));
    if (!raw) return emptyAraLog();
    const parsed = JSON.parse(raw) as AraLog;
    if (!parsed || !Array.isArray(parsed.threads)) return emptyAraLog();
    return {
      activeId: typeof parsed.activeId === "string" ? parsed.activeId : null,
      threads: parsed.threads.filter((t) => t && typeof t.id === "string" && Array.isArray(t.turns)),
    };
  } catch {
    return emptyAraLog();
  }
}

export function saveAraLog(userId: string | null | undefined, log: AraLog): void {
  if (typeof localStorage === "undefined") return;
  try {
    localStorage.setItem(araLogKey(userId), JSON.stringify(log));
  } catch {
    /* full storage should not break the desk */
  }
}

