    state = r.state;
    assert.equal(state.view, "detail");
    assert.equal(state.openUid, "uid-fire");
    assert.equal(state.evidence, false);
    assert.match(state.lastSpoken, /Firefighter Roofing/);

    r = run(state, "Show me the evidence.");
