/** Home is Ara’s screen. These are the real Owner Mode blocks she can rearrange. */

export const HOME_WIDGETS = [
  "greeting",
  "hero",
  "status",
  "up_next",
  "needs_you",
  "sales",
  "connections",
  "pipeline",
] as const;

export type HomeWidget = (typeof HOME_WIDGETS)[number];

export type HomeLayout = {
  order: HomeWidget[];
  hidden: HomeWidget[];
  emphasis: HomeWidget | null;
  compact: boolean;
};

export const DEFAULT_HOME_LAYOUT: HomeLayout = {
  order: ["greeting", "hero", "status", "up_next", "needs_you"],
  hidden: ["sales", "connections", "pipeline"],
  emphasis: "hero",
  compact: true,
};

export type LayoutCommand =
  | { kind: "move"; widget: HomeWidget; place: "top" | "bottom" | "higher" | "lower"; index?: number }
  | { kind: "hide"; widget: HomeWidget }
  | { kind: "show"; widget: HomeWidget }
  | { kind: "emphasis"; widget: HomeWidget }
  | { kind: "clean" }
  | { kind: "nav_calendar" };


const ALIASES: Array<{ widget: HomeWidget; keys: string[] }> = [
  { widget: "hero", keys: ["start my tasks", "start tasks", "the big button", "hero", "main button"] },
  { widget: "sales", keys: ["sales", "sales status", "the sales card"] },
  { widget: "status", keys: ["status", "compact status", "the numbers"] },
  { widget: "up_next", keys: ["up next", "current task", "the current task"] },
  { widget: "needs_you", keys: ["needs you", "remaining tasks", "waiting on you"] },
  { widget: "greeting", keys: ["greeting", "hello", "good morning"] },
  { widget: "connections", keys: ["connections", "gmail", "connect gmail"] },
  { widget: "pipeline", keys: ["pipeline", "the pipeline"] },
];

export function widgetLabel(w: HomeWidget): string {
  switch (w) {
    case "hero": return "Start My Tasks";
    case "sales": return "Sales";
    case "status": return "status";
    case "up_next": return "Up next";
    case "needs_you": return "Needs you";
    case "greeting": return "the greeting";
    case "connections": return "Connections";
    case "pipeline": return "Pipeline";
  }
}

export function matchWidget(raw: string): HomeWidget | null {
  const t = (raw || "").toLowerCase().replace(/[_-]+/g, " ").trim();
  if ((HOME_WIDGETS as readonly string[]).includes(t)) return t as HomeWidget;
  if (t === "start my tasks" || t === "start tasks" || t === "hero") return "hero";
  for (const row of ALIASES) {
    if (row.keys.some((k) => t === k || t.includes(k))) return row.widget;
  }
  return null;
}

export function visibleOrder(layout: HomeLayout): HomeWidget[] {
  const hidden = new Set(layout.hidden);
  const seen = new Set<HomeWidget>();
  const out: HomeWidget[] = [];
  for (const w of layout.order) {
    if (hidden.has(w) || seen.has(w)) continue;
    seen.add(w);
    out.push(w);
  }
  return out;
}

function uniqueOrder(order: HomeWidget[]): HomeWidget[] {
  const seen = new Set<HomeWidget>();
  const out: HomeWidget[] = [];
  for (const w of order) {
    if (seen.has(w)) continue;
    seen.add(w);
    out.push(w);
  }
  return out;
}

export function applyLayoutCommand(layout: HomeLayout, cmd: LayoutCommand): { layout: HomeLayout; spoken: string } {
  if (cmd.kind === "nav_calendar") {
    return { layout, spoken: "Calendar is already in the top navigation." };
  }
  if (cmd.kind === "clean") {
    const next: HomeLayout = {
      order: ["greeting", "hero", "status", "up_next", "needs_you"],
      hidden: ["sales", "connections", "pipeline"],
      emphasis: "hero",
      compact: true,
    };
    return { layout: next, spoken: "Home is cleaner. Start My Tasks is at the top." };
  }
  if (cmd.kind === "hide") {
    if (cmd.widget === "hero" || cmd.widget === "greeting") {
      return { layout, spoken: "I need to keep that on Home so you can still run the desk." };
    }
    const hidden = [...new Set([...layout.hidden, cmd.widget])];
    return {
      layout: { ...layout, hidden },
      spoken: `Hid ${widgetLabel(cmd.widget)}.`,
    };
  }
  if (cmd.kind === "show") {
    const hidden = layout.hidden.filter((w) => w !== cmd.widget);
    const order = layout.order.includes(cmd.widget) ? layout.order : [...layout.order, cmd.widget];
    return {
      layout: { ...layout, hidden, order: uniqueOrder(order) },
      spoken: `Showing ${widgetLabel(cmd.widget)}.`,
    };
  }
  if (cmd.kind === "emphasis") {
    return {
      layout: { ...layout, emphasis: cmd.widget, compact: true },
      spoken: `Made ${widgetLabel(cmd.widget)} bigger.`,
    };
  }
  const hidden = layout.hidden.filter((w) => w !== cmd.widget);
  const vis = visibleOrder({ ...layout, hidden, order: layout.order.includes(cmd.widget) ? layout.order : [...layout.order, cmd.widget] });
  const from = vis.indexOf(cmd.widget);
  let nextVis = vis.filter((w) => w !== cmd.widget);
  const place = cmd.place || "top";
  if (place === "bottom") {
    nextVis = [...nextVis, cmd.widget];
  } else if (place === "higher") {
    const at = Math.max(0, (from < 0 ? 0 : from) - 1);
    nextVis.splice(at, 0, cmd.widget);
  } else if (place === "lower") {
    const at = Math.min(nextVis.length, (from < 0 ? nextVis.length : from) + 1);
    nextVis.splice(at, 0, cmd.widget);
  } else if (typeof cmd.index === "number") {
    nextVis.splice(Math.max(0, Math.min(nextVis.length, cmd.index)), 0, cmd.widget);
  } else {
    nextVis = [cmd.widget, ...nextVis];
  }
  return {
    layout: { ...layout, order: uniqueOrder(nextVis), hidden, emphasis: cmd.widget === "hero" ? "hero" : layout.emphasis },
    spoken: place === "top"
      ? `Moved ${widgetLabel(cmd.widget)} to the top.`
      : place === "bottom"
        ? `Moved ${widgetLabel(cmd.widget)} lower on Home.`
        : place === "higher"
          ? `Moved ${widgetLabel(cmd.widget)} up.`
          : `Moved ${widgetLabel(cmd.widget)} farther down.`,
  };
}

export function parseLayoutCommand(raw: string): LayoutCommand | null {
  const t = (raw || "")
    .toLowerCase()
    .replace(/^(hey |ok |okay |hi |yo )?ara[,:]?\s+/i, "")
    .replace(/[?.!,]/g, " ")
    .replace(/\s+/g, " ")
    .trim();
  if (!t) return null;

  if (/move calendar into (the )?nav|calendar (in|into) (the )?navigation/.test(t)) {
    return { kind: "nav_calendar" };
  }
  if (/make (home|this) clean|cleaner home|make home cleaner/.test(t)) {
    return { kind: "clean" };
  }
  if (/^(hide|remove) /.test(t) || /hide (sales|connections|pipeline|status)/.test(t)) {
    const widget = matchWidget(t);
    if (widget) return { kind: "hide", widget };
  }
  if (/^(show|unhide|bring back) /.test(t)) {
    const widget = matchWidget(t);
    if (widget) return { kind: "show", widget };
  }
  if (/make (this|it|start my tasks|sales) bigger|make this bigger/.test(t)) {
    const widget = matchWidget(t) || "hero";
    return { kind: "emphasis", widget };
  }
  if (/put pipeline (over here|on home|here)|show pipeline on home/.test(t)) {
    return { kind: "show", widget: "pipeline" };
  }
  if (/move .+ farther down|move .+ lower|sales farther down|put .+ lower/.test(t)) {
    const widget = matchWidget(t);
    if (widget) return { kind: "move", widget, place: "lower" };
  }
  if (/move .+ (up|higher)|put .+ higher/.test(t)) {
    const widget = matchWidget(t);
    if (widget) return { kind: "move", widget, place: "higher" };
  }
  if (/move .+ to the bottom|put .+ at the bottom/.test(t)) {
    const widget = matchWidget(t);
    if (widget) return { kind: "move", widget, place: "bottom" };
  }
  if (/move .+ to the top|move .+ above everything|put .+ (at|to) the top/.test(t)) {
    const widget = matchWidget(t);
    if (widget) return { kind: "move", widget, place: "top" };
  }
  return null;
}

export function loadHomeLayout(): HomeLayout {
  if (typeof window === "undefined") return DEFAULT_HOME_LAYOUT;
  try {
    const raw = window.localStorage.getItem("la_home_layout_v2");
    if (!raw) return DEFAULT_HOME_LAYOUT;
    const parsed = JSON.parse(raw) as Partial<HomeLayout>;
    const order = (parsed.order || DEFAULT_HOME_LAYOUT.order).filter((w): w is HomeWidget =>
      (HOME_WIDGETS as readonly string[]).includes(w),
    );
    const hidden = (parsed.hidden || DEFAULT_HOME_LAYOUT.hidden).filter((w): w is HomeWidget =>
      (HOME_WIDGETS as readonly string[]).includes(w),
    );
    return {
      order: uniqueOrder(order.length ? order : DEFAULT_HOME_LAYOUT.order),
      hidden,
      emphasis: parsed.emphasis && (HOME_WIDGETS as readonly string[]).includes(parsed.emphasis) ? parsed.emphasis : "hero",
      compact: parsed.compact !== false,
    };
  } catch {
    return DEFAULT_HOME_LAYOUT;
  }
}

export function saveHomeLayout(layout: HomeLayout) {
  if (typeof window === "undefined") return;
  try {
    window.localStorage.setItem("la_home_layout_v2", JSON.stringify(layout));
  } catch {
    /* ignore */
  }
}

import assert from "node:assert/strict";
import { describe, it } from "node:test";
import {
  acceptAudioChunk,
  bargeInTick,
  BARGE_FRAMES,
  beginChunkGate,
  canTransition,
  classifyVoiceError,
  frameRms,
  isBenignVoiceError,
  normalizeTranscript,
  RESPONSE_KICK_TIMEOUT_MS,
  RESPONSE_START_TIMEOUT_MS,
  sessionLooksConfigured,
  shouldFailClosedOnRealtimeError,
  uiStatus,
  VoiceMachine,
} from "./lifecycle.ts";

describe("Ara voice lifecycle", () => {
  it("TEST 1 normal: one turn produces one response and returns to listening", () => {
    assert.equal(canTransition("LISTENING", "USER_SPEAKING"), true);
    assert.equal(canTransition("USER_SPEAKING", "FINALIZING_USER_TURN"), true);
    assert.equal(canTransition("FINALIZING_USER_TURN", "THINKING"), true);
    assert.equal(canTransition("THINKING", "ARA_SPEAKING"), true);
    assert.equal(canTransition("ARA_SPEAKING", "LISTENING"), true);
    assert.equal(canTransition("IDLE", "ARA_SPEAKING"), false);
    assert.equal(canTransition("ARA_SPEAKING", "USER_SPEAKING"), false);
    const m = new VoiceMachine("conv_test");
    assert.equal(m.transition("LISTENING", "open"), true);
    assert.equal(m.transition("USER_SPEAKING", "speech_started"), true);
    const fin = m.finalizeUserTurn("What should I work on?");
    assert.equal(fin.accepted, true);
    assert.match(fin.turnId || "", /^user_turn_/);
    assert.equal(m.state, "THINKING");
    assert.equal(m.startResponse("response_1"), true);
    assert.equal(m.state, "ARA_SPEAKING");
    assert.equal(m.isActiveResponse("response_1"), true);
    assert.equal(m.isActiveResponse("response_old"), false);
    m.completeResponse("response_1");
    m.completeTurnAfterPlayback();
    assert.equal(m.state, "LISTENING");
    assert.equal(m.lastCompletedTurnId, fin.turnId);
    assert.equal(uiStatus("ARA_SPEAKING"), "speaking");
    assert.ok(m.logs.some((l) => l.line.includes("TURN") && l.line.includes("CREATED")));
    assert.ok(m.logs.some((l) => l.line.includes("RESPONSE response_1 STARTED")));
    assert.ok(m.logs.some((l) => l.line.includes("TURN") && l.line.includes("COMPLETE")));
  });

  it("deduplicates the same finalized transcript instead of opening a second turn", () => {
    const m = new VoiceMachine();
    m.transition("LISTENING", "open");
    m.transition("USER_SPEAKING", "speech");
    const a = m.finalizeUserTurn("What should I work on?");
    const b = m.finalizeUserTurn("What should I work on?");
    assert.equal(a.accepted, true);
    assert.equal(b.accepted, false);
    assert.equal(b.duplicate, true);
    assert.equal(m.duplicatesDropped, 1);
    assert.equal(m.activeUserTurnId, a.turnId);
  });

  it("TEST 2 long response: drops stale and duplicate audio chunks so playback never restarts from 1", () => {
    let gate = beginChunkGate("response_1042");
    const c1 = acceptAudioChunk(gate, "response_1042", 0);
    assert.equal(c1.ok, true);
    gate = c1.gate;
    const c2 = acceptAudioChunk(gate, "response_1042", 1);
    assert.equal(c2.ok, true);
    gate = c2.gate;
    const dup = acceptAudioChunk(gate, "response_1042", 1);
    assert.equal(dup.ok, false);
    assert.equal(dup.reason, "dup");
    gate = dup.gate;
    const stale = acceptAudioChunk(gate, "response_99", 2);
    assert.equal(stale.ok, false);
    assert.equal(stale.reason, "stale");
    gate = stale.gate;
    let next = gate;
    for (let i = 2; i < 40; i++) {
      const hit = acceptAudioChunk(next, "response_1042", i);
      assert.equal(hit.ok, true, `chunk ${i}`);
      next = hit.gate;
    }
    assert.equal(next.nextIndex, 40);
    const m = new VoiceMachine();
    m.transition("LISTENING", "open");
    m.finalizeUserTurn("Tell me a long briefing.");
    assert.equal(m.startResponse("response_1042"), true);
    assert.equal(m.startResponse("response_1042"), true);
    assert.equal(m.activeResponseId, "response_1042");
    assert.equal(m.state, "ARA_SPEAKING");
  });

  it("TEST 3 tool call: follow-up stays on the same user turn and does not listen mid-tool", () => {
    const m = new VoiceMachine();
    m.transition("LISTENING", "open");
    m.transition("USER_SPEAKING", "speech");
    const turn = m.finalizeUserTurn("Change my Home background.");
    m.startResponse("response_a");
    assert.equal(m.rememberCall("call_1"), true);
    assert.equal(m.rememberCall("call_1"), false);
    m.beginTool();
    m.completeTurnAfterPlayback();
    assert.equal(m.state, "THINKING");
    assert.equal(m.mic, "gated");
    m.endTool();
    assert.equal(m.markFollowupSent("response_a"), true);
    assert.equal(m.markFollowupSent("response_a"), false);
    m.startResponse("response_b");
    assert.equal(m.activeUserTurnId, turn.turnId);
    assert.equal(m.activeResponseId, "response_b");
    m.completeTurnAfterPlayback();
    assert.equal(m.state, "LISTENING");
    assert.equal(m.lastCompletedTurnId, turn.turnId);
  });

  it("rejects a second overlapping response unless it is the tool follow-up", () => {
    const m = new VoiceMachine();
    m.transition("LISTENING", "open");
    m.finalizeUserTurn("What should I work on?");
    m.startResponse("response_a");
    m.noteHeardAudio();
    assert.equal(m.startResponse("response_b"), false);
    assert.equal(m.activeResponseId, "response_a");
    m.markFollowupSent("response_a");
    assert.equal(m.startResponse("response_c"), true);
    assert.equal(m.activeResponseId, "response_c");
  });

  it("TEST 4 / 8 / 9: screen-context updates keep the same session and do not create a turn", () => {
    const m = new VoiceMachine("conv_nav");
    m.transition("LISTENING", "open");
    const before = m.activeUserTurnId;
    m.noteEvent("session.update");
    assert.equal(m.state, "LISTENING");
    assert.equal(m.activeUserTurnId, before);
    assert.equal(m.conversationSessionId, "conv_nav");
    m.noteEvent("ui.collapse_transcript");
    assert.equal(m.conversationSessionId, "conv_nav");
    assert.equal(m.state, "LISTENING");
  });

  it("TEST 5 barge-in cancels the active response; TEST 6 echo-level RMS does not", () => {
    const m = new VoiceMachine();
    m.transition("LISTENING", "open");
    m.transition("USER_SPEAKING", "s");
    m.finalizeUserTurn("Tell me about the pipeline.");
    m.startResponse("response_long");
    const echo = bargeInTick(0, 0.01);
    assert.equal(echo.triggered, false);
    let consec = 0;
    let fired = false;
    for (let i = 0; i < BARGE_FRAMES; i++) {
      const t = bargeInTick(consec, 0.09);
      consec = t.consecutive;
      fired = t.triggered;
    }
    assert.equal(fired, true);
    assert.equal(m.bargeIn(), true);
    assert.equal(m.state, "USER_SPEAKING");
    assert.equal(m.activeResponseId, null);
    assert.equal(m.bargeInEvents, 1);
    const quiet = new Float32Array(32);
    assert.ok(frameRms(quiet) < 0.01);
    m.startResponse("response_echo");
    const ignored = m.finalizeUserTurn("Firefighter Roofing looks interesting because");
    assert.equal(ignored.accepted, false);
    assert.equal(m.activeResponseId, "response_echo");
  });

  it("TEST 7 rapid turns each get exactly one response", () => {
    const m = new VoiceMachine();
    m.transition("LISTENING", "open");
    const t1 = m.finalizeUserTurn("What should I work on?");
    m.startResponse("r1");
    m.completeTurnAfterPlayback();
    const t2 = m.finalizeUserTurn("Open Pipeline.");
    m.startResponse("r2");
    m.completeTurnAfterPlayback();
    const t3 = m.finalizeUserTurn("What’s next?");
    m.startResponse("r3");
    m.completeTurnAfterPlayback();
    assert.notEqual(t1.turnId, t2.turnId);
    assert.notEqual(t2.turnId, t3.turnId);
    assert.equal(m.lastCompletedTurnId, t3.turnId);
    assert.equal(m.state, "LISTENING");
  });

  it("TEST 10 reconnect keeps last completed turn and does not replay", () => {
    const m = new VoiceMachine("conv_keep");
    m.transition("LISTENING", "open");
    m.transition("USER_SPEAKING", "s");
    const turn = m.finalizeUserTurn("Open Pipeline.");
    m.startResponse("response_nav");
    m.completeTurnAfterPlayback();
    m.resetForReconnectKeepTurns();
    assert.equal(m.lastCompletedTurnId, turn.turnId);
    assert.equal(m.activeResponseId, null);
    assert.equal(m.conversationSessionId, "conv_keep");
    assert.ok(m.logs.some((l) => /RECONNECT without replay/.test(l.line)));
  });

  it("response.created can arrive while still finalizing the user turn", () => {
    const m = new VoiceMachine();
    m.transition("LISTENING", "open");
    m.transition("USER_SPEAKING", "speech");
    m.transition("FINALIZING_USER_TURN", "speech_stopped");
    assert.equal(m.startResponse("response_fast"), true);
    assert.equal(m.state, "ARA_SPEAKING");
    assert.equal(m.mic, "gated");
  });

  it("normalizes transcripts so punctuation does not bypass dedupe", () => {
    assert.equal(normalizeTranscript("Open Pipeline!"), normalizeTranscript("open pipeline"));
  });

  it("ignores benign realtime errors instead of tearing down the session", () => {
    assert.equal(isBenignVoiceError("Cancellation failed: no active response"), true);
    assert.equal(isBenignVoiceError("conversation_already_has_active_response"), true);
    assert.equal(isBenignVoiceError("invalid auth token"), false);
    assert.equal(classifyVoiceError("Cancellation failed: no active response"), "benign");
    assert.equal(classifyVoiceError("invalid auth token"), "fatal");
    assert.equal(classifyVoiceError("Unknown parameter: turn_detection.foo"), "fatal");
    assert.equal(classifyVoiceError("invalid session configuration"), "fatal");
    assert.equal(classifyVoiceError("response generation failed"), "recoverable");
    const cancel = {
      type: "error",
      error: { code: "response_cancel_not_active", message: "Cancellation failed: no active response" },
    };
    assert.equal(shouldFailClosedOnRealtimeError(cancel), false);
    assert.equal(shouldFailClosedOnRealtimeError({ type: "error", error: { message: "invalid auth token" } }), true);
  });
});

describe("Ara thinking watchdog / session ack", () => {
  it("TEST 2 — no response.created kicks once then recovers to listening", () => {
    const m = new VoiceMachine("conv_hello");
    m.acknowledgeSession();
    m.transition("LISTENING", "open");
    const t0 = 1_000_000;
    const fin = m.finalizeUserTurn("Hello.", t0);
    assert.equal(fin.accepted, true);
    assert.equal(m.state, "THINKING");
    assert.equal(m.thinkingReason, "WAITING_FOR_RESPONSE_START");
    assert.equal(m.consumeWatchdog(t0 + 100).type, "none");
    const kick = m.consumeWatchdog(t0 + RESPONSE_START_TIMEOUT_MS + 1);
    assert.equal(kick.type, "kick");
    if (kick.type !== "kick") return;
    assert.equal(kick.turnId, fin.turnId);
    assert.equal(m.markRecoveryKick(kick.turnId, t0 + RESPONSE_START_TIMEOUT_MS + 1), true);
    assert.equal(m.markRecoveryKick(kick.turnId, t0 + RESPONSE_START_TIMEOUT_MS + 2), false);
    const snap = m.snapshot(t0 + RESPONSE_START_TIMEOUT_MS + 2);
    assert.equal(snap.recoveryKickSent, true);
    const stage2 = m.consumeWatchdog(t0 + RESPONSE_START_TIMEOUT_MS + RESPONSE_KICK_TIMEOUT_MS + 5);
    assert.equal(stage2.type, "stage2");
    m.failTurnAndListen("watchdog_stage2");
    assert.equal(m.state, "LISTENING");
    assert.equal(m.thinkingReason, null);
    assert.equal(m.activeResponseId, null);
    assert.equal(m.sendingMic, true);
    assert.equal(m.mic, "live");
    assert.equal(m.awaitingFollowup, false);
    assert.equal(m.toolsInFlight, 0);
  });

  it("TEST 3 — delayed response.created cancels the watchdog with no extra kick", () => {
    const m = new VoiceMachine();
    m.acknowledgeSession();
    m.transition("LISTENING", "open");
    const t0 = 2_000_000;
    const fin = m.finalizeUserTurn("Hello.", t0);
    assert.equal(m.consumeWatchdog(t0 + RESPONSE_START_TIMEOUT_MS - 10).type, "none");
    assert.equal(m.startResponse("response_late"), true);
    assert.equal(m.state, "ARA_SPEAKING");
    assert.equal(m.consumeWatchdog(t0 + RESPONSE_START_TIMEOUT_MS + 50).type, "none");
    assert.equal(m.recoveryKickSentForTurn.has(fin.turnId || ""), false);
    assert.equal(m.activeResponseId, "response_late");
  });

  it("TEST 4 — recovery kick then delayed normal response keeps one pipeline", () => {
    const m = new VoiceMachine();
    m.acknowledgeSession();
    m.transition("LISTENING", "open");
    const t0 = 3_000_000;
    const fin = m.finalizeUserTurn("Hello.", t0);
    const kick = m.consumeWatchdog(t0 + RESPONSE_START_TIMEOUT_MS + 1);
    assert.equal(kick.type, "kick");
    assert.equal(m.markRecoveryKick(fin.turnId || "", t0 + RESPONSE_START_TIMEOUT_MS + 1), true);
    assert.equal(m.startResponse("response_auto"), true);
    assert.equal(m.startResponse("response_kick"), false);
    assert.equal(m.activeResponseId, "response_auto");
    assert.equal(m.consumeWatchdog(t0 + 30_000).type, "none");
    m.noteHeardAudio();
    m.completeTurnAfterPlayback();
    assert.equal(m.state, "LISTENING");
  });

  it("TEST 5 — recoverable provider error cannot stay in THINKING", () => {
    const m = new VoiceMachine();
    m.acknowledgeSession();
    m.transition("LISTENING", "open");
    m.finalizeUserTurn("Hello.");
    assert.equal(m.state, "THINKING");
    m.noteProviderError("response generation failed");
    m.failTurnAndListen("recoverable_error");
    assert.equal(m.state, "LISTENING");
    assert.equal(m.thinkingReason, null);
    assert.equal(uiStatus(m.state), "listening");
  });

  it("TEST 6 — session.update is not ready until server_vad is acknowledged", () => {
    assert.equal(sessionLooksConfigured({ turn_detection: { type: null } }), false);
    assert.equal(sessionLooksConfigured({}), false);
    assert.equal(sessionLooksConfigured({ turn_detection: { type: "server_vad", create_response: true } }), true);
    const m = new VoiceMachine();
    m.transition("LISTENING", "premature");
    assert.equal(m.shouldSendMic(), false);
    m.acknowledgeSession();
    assert.equal(m.shouldSendMic(), true);
    assert.equal(m.sessionConfigAcknowledged, true);
  });

  it("TEST 8 — long-running tool uses tool watchdog not the short response watchdog", () => {
    const m = new VoiceMachine();
    m.acknowledgeSession();
    m.transition("LISTENING", "open");
    const t0 = 4_000_000;
    m.finalizeUserTurn("Generate a new background.", t0);
    m.startResponse("response_tool");
    m.beginTool(t0 + 10);
    assert.equal(m.thinkingReason, "TOOL_IN_FLIGHT");
    assert.equal(m.watchdogKind, "tool");
    assert.equal(m.consumeWatchdog(t0 + RESPONSE_START_TIMEOUT_MS + 20).type, "none");
    m.endTool();
    assert.equal(m.markFollowupSent("response_tool", t0 + 50), true);
    assert.equal(m.thinkingReason, "WAITING_FOR_TOOL_FOLLOWUP");
    assert.equal(m.watchdogKind, "followup");
  });

  it("old watchdog cannot fire against a newer user turn or conversation session", () => {
    const m = new VoiceMachine("conv_a");
    m.acknowledgeSession();
    m.transition("LISTENING", "open");
    const t0 = 5_000_000;
    const first = m.finalizeUserTurn("Hello.", t0);
    m.startResponse("r1");
    m.completeTurnAfterPlayback();
    const second = m.finalizeUserTurn("How are you?", t0 + 100);
    assert.equal(m.activeUserTurnId, second.turnId);
    assert.notEqual(first.turnId, second.turnId);
    assert.equal(m.consumeWatchdog(t0 + RESPONSE_START_TIMEOUT_MS + 1).type, "none");
    m.watchdogSessionId = "conv_stale";
    assert.equal(m.consumeWatchdog(t0 + RESPONSE_START_TIMEOUT_MS + 200).type, "none");
    assert.equal(m.state, "THINKING");
    assert.equal(m.activeUserTurnId, second.turnId);
  });

  it("TEST 2/6 — cancelling speech returns to LISTENING and drops stale audio", () => {
    const m = new VoiceMachine();
    m.acknowledgeSession();
    m.transition("LISTENING", "open");
    m.finalizeUserTurn("Tell me a story.");
    assert.equal(m.startResponse("response_long"), true);
    assert.equal(m.state, "ARA_SPEAKING");
    const gen = m.playbackGeneration;
    m.cancelSpeechAndListen("stop_speech");
    assert.equal(m.state, "LISTENING");
    assert.equal(m.activeResponseId, null);
    assert.equal(m.currentTtsId, null);
    assert.equal(m.thinkingReason, null);
    assert.equal(uiStatus(m.state), "listening");
    assert.ok(m.playbackGeneration > gen);
    assert.equal(m.isCancelledResponse("response_long"), true);
    assert.equal(m.startResponse("response_long"), false);
    assert.equal(m.state, "LISTENING");
    assert.equal(m.startResponse("response_after_cancel"), false, "suppressed until next owner turn");
  });

  it("TEST 7 — after cancellation the next turn is a new listening turn", () => {
    const m = new VoiceMachine();
    m.acknowledgeSession();
    m.transition("LISTENING", "open");
    m.finalizeUserTurn("Hello.");
    m.startResponse("r1");
    m.cancelSpeechAndListen("stop_speech");
    const next = m.finalizeUserTurn("What should I work on?");
    assert.equal(next.accepted, true);
    assert.equal(m.startResponse("r2"), true);
    assert.equal(m.activeResponseId, "r2");
    m.completeTurnAfterPlayback();
    assert.equal(m.state, "LISTENING");
  });

  it("ARA_SPEAKING without a TTS owner recovers to LISTENING", () => {
    const m = new VoiceMachine();
    m.acknowledgeSession();
    m.transition("LISTENING", "open");
    m.finalizeUserTurn("Hello.");
    m.startResponse("r1");
    m.activeResponseId = null;
    m.currentTtsId = null;
    assert.equal(m.recoverInvalidSpeaking(), true);
    assert.equal(m.state, "LISTENING");
    assert.equal(uiStatus("USER_SPEAKING"), "hearing");
  });

  it("stuck Speaking with no queued audio recovers to LISTENING", () => {
    const m = new VoiceMachine();
    m.acknowledgeSession();
    m.transition("LISTENING", "open");
    m.finalizeUserTurn("Ara, can you hear me?");
    m.startResponse("r_stop");
    m.noteHeardAudio();
    m.lastAudioAt = Date.now() - 2000;
    assert.equal(m.recoverStaleSpeaking(0), true);
    assert.equal(m.state, "LISTENING");
    assert.equal(m.activeResponseId, null);
    assert.equal(uiStatus(m.state), "listening");
  });

  it("false-stop suppression lifts on the next owner turn", () => {
    const m = new VoiceMachine();
    m.acknowledgeSession();
    m.transition("LISTENING", "open");
    m.finalizeUserTurn("Ara, can you hear me?");
    m.startResponse("r1");
    m.cancelSpeechAndListen("hallucinated_stop_ack");
    assert.equal(m.suppressModelSpeech, true);
    assert.equal(m.startResponse("r2"), false);
    const next = m.finalizeUserTurn("What should I work on?");
    assert.equal(next.accepted, true);
    assert.equal(m.suppressModelSpeech, false);
    assert.equal(m.startResponse("r3"), true);
    m.completeTurnAfterPlayback(true);
    assert.equal(m.state, "LISTENING");
  });

  it("opening greeting arms the start watchdog without a fake Hello transcript", () => {
    const m = new VoiceMachine("conv_greet");
    m.acknowledgeSession();
    m.transition("LISTENING", "open");
    const t0 = 9_000_000;
    const turnId = m.beginSessionGreeting(t0);
    assert.match(turnId, /^user_turn_/);
    assert.equal(m.state, "THINKING");
    assert.equal(m.thinkingReason, "WAITING_FOR_RESPONSE_START");
    assert.equal(m.activeUserTurnId, turnId);
    assert.equal(m.lastFinalTranscript, null);
    assert.equal(m.consumeWatchdog(t0 + 100).type, "none");
    const kick = m.consumeWatchdog(t0 + RESPONSE_START_TIMEOUT_MS + 1);
    assert.equal(kick.type, "kick");
    if (kick.type !== "kick") return;
    assert.equal(kick.turnId, turnId);
    assert.equal(m.markRecoveryKick(turnId, t0 + RESPONSE_START_TIMEOUT_MS + 1), true);
    m.failTurnAndListen("watchdog_stage2");
    assert.equal(m.state, "LISTENING");
    assert.equal(m.sendingMic, true);
  });

  it("typed owner text can interrupt an opening greeting", () => {
    const m = new VoiceMachine("conv_type");
    m.acknowledgeSession();
    m.transition("LISTENING", "open");
    m.beginSessionGreeting(1_000);
    assert.equal(m.state, "THINKING");
    m.cancelSpeechAndListen("owner_typed");
    assert.equal(m.state, "LISTENING");
    m.allowNextModelSpeech();
    const fin = m.finalizeUserTurn("What should I work on?", 2_000);
    assert.equal(fin.accepted, true);
    assert.equal(m.state, "THINKING");
    assert.equal(m.suppressModelSpeech, false);
  });
});

import { realtimeErrorText } from "./voice-failure.ts";

export type VoiceState =
  | "IDLE"
  | "LISTENING"
  | "USER_SPEAKING"
  | "FINALIZING_USER_TURN"
  | "THINKING"
  | "ARA_SPEAKING"
  | "INTERRUPTING"
  | "ERROR";

export type ThinkingReason =
  | "WAITING_FOR_RESPONSE_START"
  | "TOOL_IN_FLIGHT"
  | "WAITING_FOR_TOOL_FOLLOWUP"
  | null;

export type VoiceErrorClass = "benign" | "recoverable" | "fatal";

export type WatchdogKind = "start" | "kick" | "followup" | "tool" | "drain" | null;

export type WatchdogAction =
  | { type: "none" }
  | { type: "kick"; turnId: string }
  | { type: "stage2"; turnId: string }
  | { type: "drain"; turnId: string };

export type VoiceLog = { at: number; line: string };

export type VoiceSnapshot = {
  conversationSessionId: string;
  voiceState: VoiceState;
  activeUserTurnId: string | null;
  activeResponseId: string | null;
  lastCompletedTurnId: string | null;
  currentTtsId: string | null;
  mic: "stopped" | "starting" | "live" | "gated";
  vad: "idle" | "speech" | "echo_gate";
  queuedChunks: number;
  lastEvent: string;
  duplicatesDropped: number;
  staleDropped: number;
  bargeInEvents: number;
  logs: string[];
  sessionConfigAcknowledged: boolean;
  thinkingReason: ThinkingReason;
  thinkingSince: number | null;
  responseWatchdogTurnId: string | null;
  responseWatchdogElapsed: number;
  recoveryKickSent: boolean;
  lastProviderError: string | null;
  lastProviderEvent: string | null;
  stopIntentDetected: boolean;
  stopIntentSource: string;
  stopIntentConfidence: string;
  stopIntentPhrase: string;
  stopIntentTurnId: string | null;
  lastInterimTranscript: string | null;
  lastFinalTranscript: string | null;
  lastNormalizedTranscript: string | null;
  playbackGeneration: number;
  suppressModelSpeech: boolean;
};

const ALLOWED: Record<VoiceState, VoiceState[]> = {
  IDLE: ["LISTENING", "ERROR", "IDLE"],
  LISTENING: ["USER_SPEAKING", "FINALIZING_USER_TURN", "THINKING", "ARA_SPEAKING", "IDLE", "ERROR", "LISTENING"],
  USER_SPEAKING: ["FINALIZING_USER_TURN", "THINKING", "LISTENING", "IDLE", "ERROR", "USER_SPEAKING"],
  FINALIZING_USER_TURN: ["THINKING", "ARA_SPEAKING", "LISTENING", "IDLE", "ERROR", "FINALIZING_USER_TURN"],
  THINKING: ["ARA_SPEAKING", "LISTENING", "IDLE", "ERROR", "THINKING", "INTERRUPTING"],
  ARA_SPEAKING: ["LISTENING", "INTERRUPTING", "THINKING", "IDLE", "ERROR", "ARA_SPEAKING"],
  INTERRUPTING: ["FINALIZING_USER_TURN", "LISTENING", "THINKING", "IDLE", "ERROR", "USER_SPEAKING", "INTERRUPTING"],
  ERROR: ["IDLE", "LISTENING", "ERROR"],
};

export const BARGE_RMS_MIN = 0.08;
export const BARGE_FRAMES = 5;
export const FINAL_DEDUP_MS = 5000;
export const ECHO_SETTLE_MS = 350;
export const RESPONSE_START_TIMEOUT_MS = 8000;
export const RESPONSE_KICK_TIMEOUT_MS = 8000;
export const TOOL_FOLLOWUP_TIMEOUT_MS = 25000;
export const TOOL_IN_FLIGHT_TIMEOUT_MS = 90000;
export const SESSION_ACK_TIMEOUT_MS = 8000;
export const SPEAKING_DRAIN_TIMEOUT_MS = 4000;
export const SPEAKING_NO_AUDIO_TIMEOUT_MS = 8000;

let turnSeq = 0;
let responseSeq = 0;

export function nextTurnId(): string {
  turnSeq += 1;
  return `user_turn_${turnSeq}`;
}

export function nextResponseId(turnId: string | null): string {
  responseSeq += 1;
  return turnId ? `response_${turnSeq}_${responseSeq}` : `response_${responseSeq}`;
}

export function normalizeTranscript(raw: string): string {
  return (raw || "")
    .toLowerCase()
    .replace(/[?.!,]/g, " ")
    .replace(/\s+/g, " ")
    .trim();
}

export function frameRms(samples: ArrayLike<number>): number {
  if (!samples.length) return 0;
  let s = 0;
  for (let i = 0; i < samples.length; i++) s += Number(samples[i]) * Number(samples[i]);
  return Math.sqrt(s / samples.length);
}

export function bargeInTick(consecutive: number, rms: number): { consecutive: number; triggered: boolean } {
  const next = rms >= BARGE_RMS_MIN ? consecutive + 1 : 0;
  return { consecutive: next, triggered: next >= BARGE_FRAMES };
}

export function isBenignVoiceError(message: string): boolean {
  const m = (message || "").toLowerCase();
  return (
    m.includes("cancel") ||
    m.includes("already has an active response") ||
    m.includes("already has a response") ||
    m.includes("no active response") ||
    m.includes("response not found") ||
    m.includes("already in progress") ||
    m.includes("buffer too small") ||
    m.includes("input_audio_buffer") ||
    m.includes("conversation_already_has_active_response") ||
    m.includes("response_cancel_not_active")
  );
}

export function classifyVoiceError(message: string): VoiceErrorClass {
  if (isBenignVoiceError(message)) return "benign";
  const m = (message || "").toLowerCase();
  if (/auth|token|unauthor|forbidden|permission|invalid api key|not authenticated/.test(m)) return "fatal";
  if (/unsupported session|invalid session|unknown parameter|session update/.test(m) && /unsupported|invalid|unknown/.test(m)) {
    return "fatal";
  }
  return "recoverable";
}

/** Cancel / no-active-response errors must not take Conversation Mode down. */
export function shouldFailClosedOnRealtimeError(ev: Record<string, unknown>): boolean {
  return classifyVoiceError(realtimeErrorText(ev)) === "fatal";
}

export type ChunkGate = {
  activeResponseId: string | null;
  nextIndex: number;
  dropped: number;
};

export function beginChunkGate(responseId: string): ChunkGate {
  return { activeResponseId: responseId, nextIndex: 0, dropped: 0 };
}

export function acceptAudioChunk(
  gate: ChunkGate,
  responseId: string,
  chunkIndex?: number,
): { ok: boolean; reason?: "stale" | "dup" | "no_active"; index: number; gate: ChunkGate } {
  if (!gate.activeResponseId) {
    return { ok: false, reason: "no_active", index: -1, gate: { ...gate, dropped: gate.dropped + 1 } };
  }
  if (responseId !== gate.activeResponseId) {
    return { ok: false, reason: "stale", index: -1, gate: { ...gate, dropped: gate.dropped + 1 } };
  }
  const index = chunkIndex ?? gate.nextIndex;
  if (index < gate.nextIndex) {
    return { ok: false, reason: "dup", index, gate: { ...gate, dropped: gate.dropped + 1 } };
  }
  return { ok: true, index, gate: { ...gate, nextIndex: index + 1 } };
}

export function canTransition(from: VoiceState, to: VoiceState): boolean {
  return ALLOWED[from].includes(to);
}

export class VoiceMachine {
  state: VoiceState = "IDLE";
  conversationSessionId: string;
  activeUserTurnId: string | null = null;
  activeResponseId: string | null = null;
  lastCompletedTurnId: string | null = null;
  currentTtsId: string | null = null;
  mic: VoiceSnapshot["mic"] = "stopped";
  vad: VoiceSnapshot["vad"] = "idle";
  queuedChunks = 0;
  lastEvent = "init";
  duplicatesDropped = 0;
  staleDropped = 0;
  bargeInEvents = 0;
  logs: VoiceLog[] = [];
  bargeConsecutive = 0;
  sendingMic = false;
  followupSentFor = new Set<string>();
  handledCalls = new Set<string>();
  toolsInFlight = 0;
  awaitingFollowup = false;
  heardAudio = false;
  echoSettleUntil = 0;
  sessionConfigAcknowledged = false;
  thinkingReason: ThinkingReason = null;
  thinkingSince: number | null = null;
  watchdogTurnId: string | null = null;
  watchdogSessionId: string | null = null;
  watchdogKind: WatchdogKind = null;
  watchdogDeadline: number | null = null;
  recoveryKickSentForTurn = new Set<string>();
  lastProviderError: string | null = null;
  lastProviderEvent: string | null = null;
  cancelledResponseIds = new Set<string>();
  playbackGeneration = 0;
  stopIntentDetected = false;
  stopIntentSource = "none";
  stopIntentConfidence = "none";
  stopIntentPhrase = "";
  stopIntentTurnId: string | null = null;
  lastInterimTranscript: string | null = null;
  lastFinalTranscript: string | null = null;
  lastNormalizedTranscript: string | null = null;
  suppressModelSpeech = false;
  falseStopRetrySent = false;
  lastAudioAt = 0;
  speakingStartedAt = 0;
  private lastFinalNorm = "";
  private lastFinalAt = 0;

  constructor(sessionId?: string) {
    this.conversationSessionId = sessionId || `conv_${Date.now().toString(36)}_${Math.random().toString(36).slice(2, 6)}`;
  }

  log(line: string) {
    this.logs = [...this.logs.slice(-39), { at: Date.now(), line }];
  }

  snapshot(now = Date.now()): VoiceSnapshot {
    const watchdogTurn = this.watchdogTurnId;
    const elapsed = this.thinkingSince ? Math.max(0, now - this.thinkingSince) : 0;
    return {
      conversationSessionId: this.conversationSessionId,
      voiceState: this.state,
      activeUserTurnId: this.activeUserTurnId,
      activeResponseId: this.activeResponseId,
      lastCompletedTurnId: this.lastCompletedTurnId,
      currentTtsId: this.currentTtsId,
      mic: this.mic,
      vad: this.vad,
      queuedChunks: this.queuedChunks,
      lastEvent: this.lastEvent,
      duplicatesDropped: this.duplicatesDropped,
      staleDropped: this.staleDropped,
      bargeInEvents: this.bargeInEvents,
      logs: this.logs.map((l) => l.line),
      sessionConfigAcknowledged: this.sessionConfigAcknowledged,
      thinkingReason: this.thinkingReason,
      thinkingSince: this.thinkingSince,
      responseWatchdogTurnId: watchdogTurn,
      responseWatchdogElapsed: elapsed,
      recoveryKickSent: this.activeUserTurnId ? this.recoveryKickSentForTurn.has(this.activeUserTurnId) : false,
      lastProviderError: this.lastProviderError,
      lastProviderEvent: this.lastProviderEvent,
      stopIntentDetected: this.stopIntentDetected,
      stopIntentSource: this.stopIntentSource,
      stopIntentConfidence: this.stopIntentConfidence,
      stopIntentPhrase: this.stopIntentPhrase,
      stopIntentTurnId: this.stopIntentTurnId,
      lastInterimTranscript: this.lastInterimTranscript,
      lastFinalTranscript: this.lastFinalTranscript,
      lastNormalizedTranscript: this.lastNormalizedTranscript,
      playbackGeneration: this.playbackGeneration,
      suppressModelSpeech: this.suppressModelSpeech,
    };
  }

  transition(to: VoiceState, event: string): boolean {
    if (!canTransition(this.state, to)) {
      this.log(`BLOCKED ${this.state} → ${to} (${event})`);
      return false;
    }
    if (this.state !== to) this.log(`${this.state} → ${to} (${event})`);
    this.state = to;
    this.lastEvent = event;
    if (to === "LISTENING" || to === "USER_SPEAKING" || to === "FINALIZING_USER_TURN") {
      this.sendingMic = true;
      this.mic = "live";
      if (to === "LISTENING") {
        this.vad = "idle";
        this.thinkingReason = null;
        this.thinkingSince = null;
      }
    }
    if (to === "THINKING" || to === "ARA_SPEAKING") {
      this.sendingMic = false;
      this.mic = "gated";
      this.vad = to === "ARA_SPEAKING" ? "echo_gate" : "idle";
      this.bargeConsecutive = 0;
    }
    if (to === "ARA_SPEAKING") {
      this.thinkingReason = null;
      this.speakingStartedAt = Date.now();
    }
    if (to === "IDLE" || to === "ERROR") {
      this.sendingMic = false;
      this.mic = "stopped";
      this.thinkingReason = null;
      this.thinkingSince = null;
      this.clearWatchdog();
    }
    return true;
  }

  noteEvent(name: string) {
    this.lastEvent = name;
    this.lastProviderEvent = name;
  }

  noteHeardAudio() {
    this.heardAudio = true;
    this.lastAudioAt = Date.now();
    if (this.watchdogKind === "start" || this.watchdogKind === "kick" || this.watchdogKind === "followup") {
      this.clearWatchdog();
    }
  }

  noteInterimTranscript(text: string) {
    this.lastInterimTranscript = (text || "").slice(0, 120);
  }

  noteFinalTranscript(text: string, normalized: string) {
    this.lastFinalTranscript = (text || "").slice(0, 120);
    this.lastNormalizedTranscript = (normalized || "").slice(0, 120);
  }

  noteStopIntent(hit: {
    detected: boolean;
    kind: string;
    source: string;
    confidence: string;
    phrase: string;
    turnId: string | null;
    reason: string;
  }) {
    this.stopIntentDetected = hit.detected;
    this.stopIntentSource = hit.source;
    this.stopIntentConfidence = hit.confidence;
    this.stopIntentPhrase = hit.phrase;
    this.stopIntentTurnId = hit.turnId;
    this.log(
      `STOP INTENT detected=${hit.detected} kind=${hit.kind} source=${hit.source} confidence=${hit.confidence} phrase=${JSON.stringify(hit.phrase)} reason=${hit.reason} turn=${hit.turnId || "none"}`,
    );
  }

  bumpPlaybackGeneration() {
    this.playbackGeneration += 1;
    return this.playbackGeneration;
  }

  markResponseCancelled(responseId: string | null) {
    if (responseId) this.cancelledResponseIds.add(responseId);
  }

  isCancelledResponse(responseId: string | null | undefined): boolean {
    if (!responseId) return false;
    return this.cancelledResponseIds.has(responseId);
  }

  recoverInvalidSpeaking(): boolean {
    if (this.state !== "ARA_SPEAKING") return false;
    if (this.suppressModelSpeech) {
      this.log("SUPPRESSED ARA_SPEAKING — recover LISTENING");
      this.failTurnAndListen("speech_suppressed");
      return true;
    }
    if (this.activeResponseId && this.currentTtsId) return false;
    this.log("INVALID ARA_SPEAKING without TTS owner — recover LISTENING");
    this.failTurnAndListen("speaking_without_owner");
    return true;
  }

  recoverStaleSpeaking(queuedChunks: number, now = Date.now()): boolean {
    if (this.state !== "ARA_SPEAKING") return false;
    if (this.suppressModelSpeech) {
      this.failTurnAndListen("speech_suppressed");
      return true;
    }
    if (!this.activeResponseId || !this.currentTtsId) {
      return this.recoverInvalidSpeaking();
    }
    if (!this.heardAudio) return false;
    if (queuedChunks > 0) return false;
    const last = this.lastAudioAt || this.speakingStartedAt;
    if (!last || now - last < 1500) return false;
    this.log("STALE ARA_SPEAKING — audio drained but state stuck; recover LISTENING");
    this.completeTurnAfterPlayback(true);
    return true;
  }

  cancelSpeechAndListen(reason = "stop_speech") {
    this.markResponseCancelled(this.activeResponseId);
    this.bumpPlaybackGeneration();
    this.activeResponseId = null;
    this.currentTtsId = null;
    this.queuedChunks = 0;
    this.heardAudio = false;
    this.awaitingFollowup = false;
    this.toolsInFlight = 0;
    this.pendingCallsSafeClear();
    this.clearWatchdog();
    this.thinkingReason = null;
    this.thinkingSince = null;
    this.sendingMic = true;
    this.mic = "live";
    this.vad = "idle";
    this.bargeConsecutive = 0;
    this.suppressModelSpeech = true;
    this.log(`SPEECH CANCELLED (${reason}) → LISTENING`);
    if (this.state === "IDLE" || this.state === "ERROR") return;
    if (this.state === "LISTENING") return;
    this.transition("LISTENING", reason);
  }

  private pendingCallsSafeClear() {
    this.handledCalls.clear();
  }

  acknowledgeSession() {
    this.sessionConfigAcknowledged = true;
    this.log("session.updated acknowledged");
  }

  noteProviderError(message: string) {
    this.lastProviderError = (message || "").slice(0, 240);
  }

  enterThinking(reason: Exclude<ThinkingReason, null>, now = Date.now()) {
    this.thinkingReason = reason;
    if (this.thinkingSince == null) this.thinkingSince = now;
    this.transition("THINKING", reason);
    this.gateMic();
  }

  armWatchdog(kind: Exclude<WatchdogKind, null>, turnId: string | null, timeoutMs: number, now = Date.now()) {
    const id = turnId || this.activeUserTurnId || this.conversationSessionId;
    if (!id) return;
    this.watchdogKind = kind;
    this.watchdogTurnId = id;
    this.watchdogSessionId = this.conversationSessionId;
    this.watchdogDeadline = now + timeoutMs;
    this.log(`WATCHDOG ${kind} ${id} ${timeoutMs}ms`);
  }

  clearWatchdog() {
    this.watchdogKind = null;
    this.watchdogTurnId = null;
    this.watchdogSessionId = null;
    this.watchdogDeadline = null;
  }

  gateMic() {
    this.sendingMic = false;
    this.mic = "gated";
    this.bargeConsecutive = 0;
  }

  finalizeUserTurn(transcript: string, now = Date.now()): { accepted: boolean; turnId: string | null; duplicate: boolean } {
    const norm = normalizeTranscript(transcript);
    if (!norm) return { accepted: false, turnId: null, duplicate: false };
    if (this.state === "THINKING" || this.state === "ARA_SPEAKING") {
      this.duplicatesDropped += 1;
      this.log(`TURN ignored in ${this.state} (echo/stale final)`);
      return { accepted: false, turnId: this.activeUserTurnId, duplicate: true };
    }
    if (norm === this.lastFinalNorm && now - this.lastFinalAt < FINAL_DEDUP_MS) {
      this.duplicatesDropped += 1;
      this.log(`TURN DUP dropped "${norm.slice(0, 48)}"`);
      return { accepted: false, turnId: this.activeUserTurnId, duplicate: true };
    }
    this.lastFinalNorm = norm;
    this.lastFinalAt = now;
    this.suppressModelSpeech = false;
    this.falseStopRetrySent = false;
    const turnId = nextTurnId();
    this.activeUserTurnId = turnId;
    this.followupSentFor.clear();
    this.awaitingFollowup = false;
    this.toolsInFlight = 0;
    this.heardAudio = false;
    this.transition("FINALIZING_USER_TURN", "user_final");
    this.log(`TURN ${turnId} CREATED`);
    this.log(`TURN ${turnId} FINALIZED`);
    this.enterThinking("WAITING_FOR_RESPONSE_START", now);
    this.armWatchdog("start", turnId, RESPONSE_START_TIMEOUT_MS, now);
    this.log("WAITING FOR response.created");
    return { accepted: true, turnId, duplicate: false };
  }

  startResponse(responseId: string): boolean {
    if (!responseId) return false;
    if (this.suppressModelSpeech) {
      this.staleDropped += 1;
      this.log(`RESPONSE ${responseId} REJECTED (speech suppressed until next owner turn)`);
      return false;
    }
    if (this.isCancelledResponse(responseId)) {
      this.staleDropped += 1;
      this.log(`RESPONSE ${responseId} REJECTED (cancelled)`);
      return false;
    }
    if (this.activeResponseId === responseId && (this.state === "ARA_SPEAKING" || this.state === "THINKING")) {
      this.duplicatesDropped += 1;
      this.log(`RESPONSE ${responseId} duplicate created ignored`);
      this.clearWatchdog();
      return true;
    }
    if (
      this.activeResponseId &&
      this.activeResponseId !== responseId &&
      (this.state === "ARA_SPEAKING" || this.heardAudio) &&
      !this.awaitingFollowup
    ) {
      this.staleDropped += 1;
      this.log(`RESPONSE ${responseId} REJECTED (already speaking ${this.activeResponseId})`);
      return false;
    }
    if (this.activeResponseId && this.activeResponseId !== responseId) {
      this.log(`RESPONSE ${this.activeResponseId} SUPERSEDED by ${responseId}`);
    }
    if (this.state === "LISTENING" || this.state === "USER_SPEAKING" || this.state === "FINALIZING_USER_TURN") {
      this.transition("THINKING", "response.created");
    }
    this.awaitingFollowup = false;
    this.heardAudio = false;
    this.activeResponseId = responseId;
    this.currentTtsId = responseId;
    this.echoSettleUntil = Date.now() + ECHO_SETTLE_MS;
    this.clearWatchdog();
    this.log(`RESPONSE ${responseId} STARTED`);
    this.transition("ARA_SPEAKING", "response.created");
    this.armWatchdog("drain", this.activeUserTurnId, SPEAKING_NO_AUDIO_TIMEOUT_MS);
    return true;
  }

  isActiveResponse(responseId: string | null | undefined): boolean {
    if (!responseId || !this.activeResponseId) return false;
    if (this.isCancelledResponse(responseId)) return false;
    return responseId === this.activeResponseId;
  }

  dropStale(kind: string) {
    this.staleDropped += 1;
    this.log(`STALE ${kind} dropped (active=${this.activeResponseId || "none"})`);
  }

  completeResponse(responseId: string) {
    if (!this.isActiveResponse(responseId)) {
      this.dropStale("response.done");
      return;
    }
    this.log(`TTS ${responseId} COMPLETED`);
    if (this.watchdogKind !== "drain") this.clearWatchdog();
  }

  completeTurnAfterPlayback(force = false) {
    if (!force && (this.toolsInFlight > 0 || this.awaitingFollowup)) {
      this.enterThinking(this.toolsInFlight > 0 ? "TOOL_IN_FLIGHT" : "WAITING_FOR_TOOL_FOLLOWUP");
      this.log("hold LISTENING — tool/follow-up still in flight");
      return;
    }
    if (this.activeUserTurnId) {
      this.lastCompletedTurnId = this.activeUserTurnId;
      this.log(`TURN ${this.activeUserTurnId} COMPLETE`);
    }
    this.activeResponseId = null;
    this.currentTtsId = null;
    this.queuedChunks = 0;
    this.heardAudio = false;
    this.clearWatchdog();
    this.transition("LISTENING", "playback_drained");
  }

  consumeWatchdog(now = Date.now()): WatchdogAction {
    if (!this.watchdogDeadline || !this.watchdogTurnId || !this.watchdogKind) return { type: "none" };
    if (this.watchdogSessionId && this.watchdogSessionId !== this.conversationSessionId) {
      this.log("WATCHDOG ignored — conversation session changed");
      this.clearWatchdog();
      return { type: "none" };
    }
    if (now < this.watchdogDeadline) return { type: "none" };
    const turnId = this.watchdogTurnId;
    if (this.watchdogKind !== "drain" && this.activeUserTurnId && this.activeUserTurnId !== turnId) {
      this.log(`WATCHDOG ignored — turn ${turnId} no longer active`);
      this.clearWatchdog();
      return { type: "none" };
    }
    if (this.watchdogKind !== "drain" && this.activeResponseId && (this.state === "ARA_SPEAKING" || this.heardAudio)) {
      this.clearWatchdog();
      return { type: "none" };
    }
    if (this.watchdogKind === "drain") {
      this.log(`WATCHDOG speaking drain ${turnId}`);
      return { type: "drain", turnId };
    }
    if (this.watchdogKind === "start" || this.watchdogKind === "followup") {
      if (this.recoveryKickSentForTurn.has(turnId)) {
        this.log(`WATCHDOG no response.created for ${turnId} after kick`);
        return { type: "stage2", turnId };
      }
      if (this.toolsInFlight > 0 && this.watchdogKind === "start") {
        this.armWatchdog("tool", turnId, TOOL_IN_FLIGHT_TIMEOUT_MS, now);
        return { type: "none" };
      }
      this.log(`WATCHDOG no response.created for ${turnId}`);
      return { type: "kick", turnId };
    }
    if (this.watchdogKind === "kick" || this.watchdogKind === "tool") {
      this.log(`WATCHDOG stage2 ${turnId}`);
      return { type: "stage2", turnId };
    }
    return { type: "none" };
  }

  markRecoveryKick(turnId: string, now = Date.now()): boolean {
    if (!turnId) return false;
    if (this.recoveryKickSentForTurn.has(turnId)) return false;
    if (this.activeResponseId) return false;
    if (this.activeUserTurnId && this.activeUserTurnId !== turnId) return false;
    this.recoveryKickSentForTurn.add(turnId);
    this.armWatchdog("kick", turnId, RESPONSE_KICK_TIMEOUT_MS, now);
    this.log(`WATCHDOG recovery kick sent for ${turnId}`);
    return true;
  }

  failTurnAndListen(reason: string) {
    this.log(`TURN ${this.activeUserTurnId || "none"} FAILED (${reason})`);
    this.activeResponseId = null;
    this.currentTtsId = null;
    this.queuedChunks = 0;
    this.heardAudio = false;
    this.awaitingFollowup = false;
    this.toolsInFlight = 0;
    this.handledCalls.clear();
    this.followupSentFor.clear();
    this.clearWatchdog();
    this.thinkingReason = null;
    this.thinkingSince = null;
    this.sendingMic = true;
    this.mic = "live";
    this.vad = "idle";
    this.bargeConsecutive = 0;
    this.transition("LISTENING", reason);
  }

  /** Opening greeting: one model response, no fake owner "Hello" transcript. */
  beginSessionGreeting(now = Date.now()): string {
    const turnId = nextTurnId();
    this.activeUserTurnId = turnId;
    this.suppressModelSpeech = false;
    this.falseStopRetrySent = false;
    this.heardAudio = false;
    this.followupSentFor.clear();
    this.awaitingFollowup = false;
    this.toolsInFlight = 0;
    this.log(`TURN ${turnId} GREETING`);
    this.enterThinking("WAITING_FOR_RESPONSE_START", now);
    this.armWatchdog("start", turnId, RESPONSE_START_TIMEOUT_MS, now);
    return turnId;
  }

  allowNextModelSpeech() {
    this.suppressModelSpeech = false;
  }

  bargeIn(): boolean {
    if (this.state !== "ARA_SPEAKING" && this.state !== "THINKING") return false;
    this.bargeInEvents += 1;
    const old = this.activeResponseId;
    this.log(`BARGE-IN cancel ${old || "none"}`);
    this.markResponseCancelled(old);
    this.bumpPlaybackGeneration();
    this.transition("INTERRUPTING", "barge_in");
    this.activeResponseId = null;
    this.currentTtsId = null;
    this.queuedChunks = 0;
    this.heardAudio = false;
    this.awaitingFollowup = false;
    this.toolsInFlight = 0;
    this.clearWatchdog();
    this.sendingMic = true;
    this.mic = "live";
    this.vad = "speech";
    this.suppressModelSpeech = false;
    this.transition("USER_SPEAKING", "barge_in");
    return true;
  }

  shouldSendMic(): boolean {
    return this.sendingMic && this.state !== "ERROR" && this.state !== "IDLE" && this.sessionConfigAcknowledged;
  }

  echoSettled(now = Date.now()): boolean {
    return now >= this.echoSettleUntil;
  }

  expectFollowup(parentId: string, now = Date.now()): boolean {
    if (this.followupSentFor.has(parentId)) return false;
    this.followupSentFor.add(parentId);
    this.awaitingFollowup = true;
    this.gateMic();
    this.enterThinking("WAITING_FOR_TOOL_FOLLOWUP", now);
    this.armWatchdog("followup", this.activeUserTurnId, TOOL_FOLLOWUP_TIMEOUT_MS, now);
    this.log(`EXPECT follow-up for ${parentId}`);
    return true;
  }

  markFollowupSent(parentId: string, now = Date.now()): boolean {
    return this.expectFollowup(parentId, now);
  }

  beginTool(now = Date.now()) {
    this.toolsInFlight += 1;
    this.enterThinking("TOOL_IN_FLIGHT", now);
    this.armWatchdog("tool", this.activeUserTurnId, TOOL_IN_FLIGHT_TIMEOUT_MS, now);
  }

  endTool() {
    this.toolsInFlight = Math.max(0, this.toolsInFlight - 1);
  }

  rememberCall(callId: string): boolean {
    const id = (callId || "").trim();
    if (!id) return true;
    if (this.handledCalls.has(id)) return false;
    this.handledCalls.add(id);
    return true;
  }

  resetForReconnectKeepTurns() {
    this.activeResponseId = null;
    this.currentTtsId = null;
    this.queuedChunks = 0;
    this.sendingMic = false;
    this.mic = "stopped";
    this.bargeConsecutive = 0;
    this.heardAudio = false;
    this.awaitingFollowup = false;
    this.toolsInFlight = 0;
    this.sessionConfigAcknowledged = false;
    this.handledCalls.clear();
    this.followupSentFor.clear();
    this.recoveryKickSentForTurn.clear();
    this.clearWatchdog();
    this.thinkingReason = null;
    this.thinkingSince = null;
    this.transition("IDLE", "reconnect");
    this.log("RECONNECT without replay");
  }
}

export function uiStatus(state: VoiceState): "ready" | "connecting" | "listening" | "hearing" | "thinking" | "speaking" | "unavailable" {
  if (state === "ERROR") return "unavailable";
  if (state === "IDLE") return "ready";
  if (state === "ARA_SPEAKING") return "speaking";
  if (state === "THINKING" || state === "INTERRUPTING") return "thinking";
  if (state === "USER_SPEAKING") return "hearing";
  return "listening";
}

export function sessionLooksConfigured(session: Record<string, unknown> | undefined | null): boolean {
  if (!session || typeof session !== "object") return false;
  const td = session.turn_detection;
  if (!td || typeof td !== "object") return false;
  return (td as { type?: unknown }).type === "server_vad";
}

import assert from "node:assert/strict";
import { describe, it } from "node:test";
import { listeningAllowed, micStatusLabel, micStreamLive } from "./mic.ts";

describe("microphone permission truth", () => {
  it("Listening is only allowed when conversation, mic, stream, session, and sending are all live", () => {
    const ready = {
      conversationOn: true,
      micPermission: "GRANTED" as const,
      micStreamActive: true,
      voiceSessionReady: true,
      micSending: true,
    };
    assert.equal(listeningAllowed(ready), true);
    assert.equal(listeningAllowed({ ...ready, conversationOn: false }), false);
    assert.equal(listeningAllowed({ ...ready, micPermission: "BLOCKED" }), false);
    assert.equal(listeningAllowed({ ...ready, micPermission: "DENIED" }), false);
    assert.equal(listeningAllowed({ ...ready, micStreamActive: false }), false);
    assert.equal(listeningAllowed({ ...ready, voiceSessionReady: false }), false);
    assert.equal(listeningAllowed({ ...ready, micSending: false }), false);
  });

  it("status labels never say Listening when mic is missing", () => {
    assert.equal(micStatusLabel("BLOCKED"), "Mic needed");
    assert.equal(micStatusLabel("DENIED"), "Mic needed");
    assert.equal(micStatusLabel("UNAVAILABLE"), "Voice input unavailable");
    assert.doesNotMatch(micStatusLabel("BLOCKED"), /Listening/);
  });

  it("micStreamLive requires a live enabled track", () => {
    assert.equal(micStreamLive(null), false);
    assert.equal(micStreamLive(undefined), false);
  });
});

export type MicPermission =
  | "UNKNOWN"
  | "REQUESTING"
  | "GRANTED"
  | "DENIED"
  | "BLOCKED"
  | "UNAVAILABLE";

export function micStreamLive(stream: MediaStream | null | undefined): boolean {
  if (!stream) return false;
  return stream.getAudioTracks().some((t) => t.readyState === "live" && t.enabled !== false);
}

export function stopMicStream(stream: MediaStream | null | undefined): void {
  try {
    stream?.getTracks().forEach((t) => t.stop());
  } catch {
    /* ignore */
  }
}

export async function queryMicPermission(): Promise<MicPermission> {
  if (typeof navigator === "undefined" || !navigator.mediaDevices?.getUserMedia) return "UNAVAILABLE";
  try {
    const perms = navigator.permissions;
    if (perms?.query) {
      const status = await perms.query({ name: "microphone" as PermissionName });
      if (status.state === "granted") return "GRANTED";
      if (status.state === "denied") return "BLOCKED";
      return "UNKNOWN";
    }
  } catch {
    /* Safari / embedded browsers often omit microphone from permissions.query */
  }
  return "UNKNOWN";
}

export async function requestMicrophone(): Promise<{
  state: MicPermission;
  stream: MediaStream | null;
  reason?: string;
}> {
  if (typeof navigator === "undefined" || !navigator.mediaDevices?.getUserMedia) {
    return { state: "UNAVAILABLE", stream: null, reason: "This browser cannot use a microphone." };
  }
  try {
    const stream = await navigator.mediaDevices.getUserMedia({
      audio: { echoCancellation: true, noiseSuppression: true },
    });
    if (!micStreamLive(stream)) {
      stopMicStream(stream);
      return { state: "UNAVAILABLE", stream: null, reason: "No live microphone track." };
    }
    return { state: "GRANTED", stream };
  } catch (err) {
    const name = err && typeof err === "object" && "name" in err ? String((err as { name: string }).name) : "";
    if (name === "NotAllowedError" || name === "PermissionDeniedError") {
      return {
        state: "BLOCKED",
        stream: null,
        reason: "Microphone access is blocked. Enable it in your browser permissions to talk to Ara.",
      };
    }
    if (name === "NotFoundError" || name === "DevicesNotFoundError") {
      return { state: "UNAVAILABLE", stream: null, reason: "No microphone is available." };
    }
    return { state: "DENIED", stream: null, reason: "Microphone permission is needed to talk to Ara." };
  }
}

export function listeningAllowed(opts: {
  conversationOn: boolean;
  micPermission: MicPermission;
  micStreamActive: boolean;
  voiceSessionReady: boolean;
  micSending: boolean;
}): boolean {
  return (
    opts.conversationOn
    && opts.micPermission === "GRANTED"
    && opts.micStreamActive
    && opts.voiceSessionReady
    && opts.micSending
  );
}

export function micStatusLabel(permission: MicPermission): string {
  if (permission === "BLOCKED" || permission === "DENIED") return "Mic needed";
  if (permission === "UNAVAILABLE") return "Voice input unavailable";
  if (permission === "REQUESTING") return "Asking for mic…";
  return "Mic needed";
}

