  });

  it("daily cap refuses extra research after the limit", () => {
    _resetResearchLimitsForTests();
    process.env.DAILY_ARA_RESEARCH_CAP = "2";
    process.env.GLOBAL_DAILY_ARA_RESEARCH_CAP = "2";
    const user = `cap-test-${Date.now()}`;
